window.MH_TR["\u05e4\u05e8\u05e700_\u05de\u05e4\u05ea_\u05e2\u05d5\u05dc\u05dd_\u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd"]={"t":"\u05de\u05e4\u05ea \u05e2\u05d5\u05dc\u05dd \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd","l":[[1.0,"\u05dc\u05e4\u05e0\u05d9\u05db\u05dd \u05ea\u05d5\u05e9\u05d1\u05ea \u05e4\u05e9\u05d5\u05d8\u05d4. \u05d0\u05d5\u05ea\u05d4 \u05e6\u05d5\u05e8\u05d4, \u05d0\u05d5\u05ea\u05df \u05de\u05d9\u05d3\u05d5\u05ea, \u05d0\u05d5\u05ea\u05d5 \u05e9\u05e8\u05d8\u05d5\u05d8."],[6.0,"\u05e2\u05db\u05e9\u05d9\u05d5 \u05e0\u05d9\u05d9\u05e6\u05e8 \u05d0\u05d5\u05ea\u05d4 \u05e9\u05dc\u05d5\u05e9 \u05e4\u05e2\u05de\u05d9\u05dd: \u05de\u05e4\u05dc\u05d3\u05d4, \u05de\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05de\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd."],[12.0,"\u05ea\u05d5\u05e9\u05d1\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4 \u05e9\u05d5\u05e7\u05dc\u05ea \u05e7\u05d9\u05dc\u05d5\u05d2\u05e8\u05dd \u05d0\u05d7\u05d3."],[15.0,"\u05d0\u05d5\u05ea\u05d4 \u05ea\u05d5\u05e9\u05d1\u05ea \u05de\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05e9\u05d5\u05e7\u05dc\u05ea \u05d1\u05e2\u05e8\u05da \u05e9\u05dc\u05d9\u05e9, \u05d5\u05de\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05e7\u05e6\u05ea \u05d9\u05d5\u05ea\u05e8 \u05de\u05d7\u05e6\u05d9."],[21.0,"\u05d0\u05d1\u05dc \u05d4\u05de\u05e9\u05e7\u05dc \u05d4\u05d5\u05d0 \u05e8\u05e7 \u05d4\u05d4\u05ea\u05d7\u05dc\u05d4."],[23.0,"\u05d0\u05d7\u05e8\u05ea \u05dc\u05d7\u05d5\u05dd \u05d5\u05dc\u05e1\u05d1\u05d9\u05d1\u05d4, \u05d9\u05e2\u05dc\u05d5 \u05de\u05d7\u05d9\u05e8 \u05e9\u05d5\u05e0\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d5\u05d9\u05e2\u05d1\u05e8\u05d5 \u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4 \u05d3\u05e8\u05da \u05e9\u05d5\u05e0\u05d4 \u05dc\u05d2\u05de\u05e8\u05d9."],[34.0,"\u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d6\u05d4\u05d4. \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05e9\u05e0\u05d4 \u05d4\u05db\u05dc. \u05e2\u05dc \u05d6\u05d4 \u05d4\u05e7\u05d5\u05e8\u05e1 \u05d4\u05d6\u05d4."],[40.0,"\u05db\u05dc \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d4\u05d4\u05e0\u05d3\u05e1\u05d9\u05d9\u05dd \u05de\u05ea\u05d7\u05dc\u05e7\u05d9\u05dd \u05dc\u05d0\u05e8\u05d1\u05e2 \u05de\u05e9\u05e4\u05d7\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea: \u05de\u05ea\u05db\u05d5\u05ea, \u05e4\u05d5\u05dc\u05d9\u05de\u05e8\u05d9\u05dd, \u05e7\u05e8\u05de\u05d9\u05e7\u05d4 \u05d5\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05de\u05e8\u05d5\u05db\u05d1\u05d9\u05dd."],[48.0,"\u05d1\u05e7\u05d5\u05e8\u05e1 \u05d4\u05d6\u05d4 \u05e0\u05ea\u05de\u05e7\u05d3 \u05d1\u05de\u05ea\u05db\u05d5\u05ea, \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e9\u05e8\u05d5\u05d1 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d4\u05de\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05e2\u05e9\u05d5\u05d9\u05d9\u05dd \u05de\u05d4\u05dd."],[54.0,"\u05e9\u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d5\u05d0 \u05d4\u05d9\u05e1\u05d5\u05d3 \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9 \u05d1\u05d4\u05df: \u05e4\u05dc\u05d3\u05d5\u05ea \u05dc\u05de\u05d9\u05e0\u05d9\u05d4\u05df \u05d5\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7."],[63.0,"\u05d5\u05de\u05ea\u05db\u05d5\u05ea \u05dc\u05d0 \u05d1\u05e8\u05d6\u05dc\u05d9\u05d5\u05ea: \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05e0\u05d7\u05d5\u05e9\u05ea, \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd, \u05e0\u05d9\u05e7\u05dc \u05d5\u05e2\u05d5\u05d3."],[70.0,"\u05d4\u05e4\u05dc\u05d3\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05de\u05ea\u05db\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4, \u05d1\u05e4\u05e2\u05e8 \u05e2\u05e6\u05d5\u05dd \u05de\u05e9\u05d0\u05e8 \u05d4\u05de\u05ea\u05db\u05d5\u05ea."],[76.0,"\u05d4\u05d9\u05d0 \u05d6\u05d5\u05dc\u05d4, \u05d7\u05d6\u05e7\u05d4, \u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc\u05d4 \u05d1\u05d8\u05d5\u05d5\u05d7 \u05e8\u05d7\u05d1 \u05de\u05d0\u05d5\u05d3 \u05d1\u05e2\u05d6\u05e8\u05ea \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc\u05d9 \u05d7\u05d5\u05dd."],[84.0,"\u05d0\u05d9\u05da \u05de\u05e9\u05d5\u05d5\u05d9\u05dd \u05d1\u05d9\u05df \u05d7\u05d5\u05de\u05e8\u05d9\u05dd? \u05d1\u05e2\u05d6\u05e8\u05ea \u05ea\u05db\u05d5\u05e0\u05d5\u05ea. \u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05de\u05db\u05e0\u05d9\u05d5\u05ea, \u05d0\u05dc\u05d4 \u05e9\u05e7\u05d5\u05d1\u05e2\u05d5\u05ea \u05d0\u05d9\u05da \u05d4\u05d7\u05dc\u05e7 \u05de\u05ea\u05e0\u05d4\u05d2 \u05ea\u05d7\u05ea \u05e2\u05d5\u05de\u05e1."],[93.0,"\u05d7\u05d5\u05d6\u05e7 \u05db\u05e0\u05d9\u05e2\u05d4 \u05d4\u05d5\u05d0 \u05d4\u05de\u05d0\u05de\u05e5 \u05e9\u05d1\u05d5 \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05ea\u05d7\u05d9\u05dc \u05dc\u05d4\u05ea\u05e2\u05d5\u05d5\u05ea \u05dc\u05e6\u05de\u05d9\u05ea\u05d5\u05ea."],[97.0,"\u05e2\u05d3 \u05e9\u05dd, \u05db\u05e9\u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e1, \u05d4\u05d7\u05dc\u05e7 \u05d7\u05d5\u05d6\u05e8 \u05dc\u05e6\u05d5\u05e8\u05ea\u05d5. \u05de\u05e2\u05d1\u05e8 \u05dc\u05d6\u05d4 \u05d4\u05d5\u05d0 \u05e0\u05e9\u05d0\u05e8 \u05de\u05e2\u05d5\u05d5\u05ea."],[104.0,"\u05d7\u05d5\u05d6\u05e7 \u05de\u05ea\u05d9\u05d7\u05d4 \u05d4\u05d5\u05d0 \u05d4\u05de\u05d0\u05de\u05e5 \u05d4\u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9 \u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05d7\u05d6\u05d9\u05e7 \u05dc\u05e1\u05e0\u05d9 \u05e9\u05d4\u05d5\u05d0 \u05e0\u05e9\u05d1\u05e8."],[110.0,"\u05d1\u05ea\u05db\u05e0\u05d5\u05df \u05e8\u05d5\u05d1 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05d7\u05d5\u05d6\u05e7 \u05d4\u05db\u05e0\u05d9\u05e2\u05d4 \u05d4\u05d5\u05d0 \u05d4\u05e0\u05ea\u05d5\u05df \u05d4\u05d7\u05e9\u05d5\u05d1 \u05d9\u05d5\u05ea\u05e8, \u05db\u05d9 \u05d7\u05dc\u05e7 \u05e9\u05d4\u05ea\u05e2\u05d5\u05d5\u05ea \u05db\u05d1\u05e8 \u05dc\u05d0 \u05e2\u05d5\u05d1\u05d3."],[117.0,"\u05e9\u05d1\u05e8. \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05d0\u05d7\u05d5\u05d6 \u05d4\u05d4\u05ea\u05d0\u05e8\u05db\u05d5\u05ea \u05e9\u05dc \u05d3\u05d2\u05dd \u05d4\u05de\u05ea\u05d9\u05d7\u05d4."],[125.0,"\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05d9\u05d0 \u05d4\u05d4\u05ea\u05e0\u05d2\u05d3\u05d5\u05ea \u05e9\u05dc \u05e4\u05e0\u05d9 \u05d4\u05d7\u05d5\u05de\u05e8 \u05dc\u05d7\u05d3\u05d9\u05e8\u05d4 \u05d5\u05dc\u05e9\u05d7\u05d9\u05e7\u05d4."],[129.0,"\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05dc\u05d7\u05d9\u05e6\u05d4 \u05e9\u05dc \u05d7\u05d5\u05d3\u05df \u05dc\u05ea\u05d5\u05da \u05d4\u05d7\u05d5\u05de\u05e8, \u05d1\u05e9\u05d9\u05d8\u05d5\u05ea \u05d1\u05e8\u05d9\u05e0\u05dc, \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc \u05d5\u05d5\u05d9\u05e7\u05e8\u05e1."],[136.0,"\u05d5\u05d4\u05ea\u05db\u05d5\u05e0\u05d4 \u05e9\u05e0\u05d5\u05d8\u05d9\u05dd \u05dc\u05e9\u05db\u05d5\u05d7: \u05e7\u05e9\u05d9\u05d7\u05d5\u05ea, stiffness \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea, \u05e9\u05e0\u05de\u05d3\u05d3\u05ea \u05d1\u05de\u05d5\u05d3\u05d5\u05dc \u05d4\u05d0\u05dc\u05e1\u05d8\u05d9\u05d5\u05ea."],[143.0,"\u05d4\u05d9\u05d0 \u05d0\u05d5\u05de\u05e8\u05ea \u05db\u05de\u05d4 \u05d4\u05d7\u05dc\u05e7 \u05de\u05ea\u05db\u05d5\u05e4\u05e3 \u05ea\u05d7\u05ea \u05e2\u05d5\u05de\u05e1, \u05e2\u05d5\u05d3 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05d2\u05d9\u05e2 \u05dc\u05db\u05e0\u05d9\u05e2\u05d4."],[148.0,"\u05de\u05d5\u05d3\u05d5\u05dc \u05d4\u05d0\u05dc\u05e1\u05d8\u05d9\u05d5\u05ea \u05e9\u05dc \u05e4\u05dc\u05d3\u05d4 \u05d4\u05d5\u05d0 \u05d1\u05e2\u05e8\u05da 200 \u05d2'\u05d9\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc, \u05e9\u05dc \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d1\u05e2\u05e8\u05da 110, \u05d5\u05e9\u05dc \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d1\u05e2\u05e8\u05da 70."],[157.0,"\u05d1\u05d9\u05d5\u05ea\u05e8 \u05d5\u05e2\u05d3 \u05e4\u05dc\u05d3\u05ea \u05d4\u05db\u05dc\u05d9\u05dd \u05d4\u05de\u05d5\u05e7\u05e9\u05d9\u05ea \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d4\u05df \u05db\u05de\u05e2\u05d8 \u05d1\u05d0\u05d5\u05ea\u05d4 \u05e7\u05e9\u05d9\u05d7\u05d5\u05ea."],[166.0,"\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05de\u05e7\u05d8\u05d9\u05df \u05d0\u05ea \u05d4\u05db\u05d9\u05e4\u05d5\u05e3 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05ea\u05d7\u05ea \u05e2\u05d5\u05de\u05e1."],[172.0,"\u05d0\u05dd \u05ea\u05d5\u05e9\u05d1\u05ea \u05de\u05ea\u05db\u05d5\u05e4\u05e4\u05dc\u05ea \u05d9\u05d5\u05ea\u05e8 \u05de\u05d3\u05d9, \u05d4\u05d7\u05dc\u05e4\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d1\u05e4\u05dc\u05d3\u05d4 \u05d7\u05d6\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05d0 \u05ea\u05e2\u05d6\u05d5\u05e8."],[178.0,"\u05e6\u05e8\u05d9\u05da \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4, \u05d0\u05d5 \u05dc\u05e2\u05d1\u05d5\u05e8 \u05dc\u05d7\u05d5\u05de\u05e8 \u05e2\u05dd \u05de\u05d5\u05d3\u05d5\u05dc \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8."],[183.0,"\u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05d5\u05dc\u05d4\u05ea\u05e0\u05d2\u05d3 \u05dc\u05e9\u05d1\u05e8, \u05dc\u05de\u05e9\u05dc \u05d1\u05de\u05db\u05d4. \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05de\u05d1\u05d7\u05df \u05e9\u05e8\u05e4\u05d9."],[193.0,"\u05db\u05d0\u05df \u05e0\u05de\u05e6\u05d0\u05ea \u05d0\u05d7\u05ea \u05d4\u05e4\u05e9\u05e8\u05d5\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9\u05d5\u05ea \u05e9\u05dc \u05d4\u05de\u05d8\u05dc\u05d5\u05e8\u05d2\u05d9\u05d4: \u05db\u05db\u05dc \u05e9\u05de\u05e7\u05e9\u05d9\u05dd \u05d7\u05d5\u05de\u05e8, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d4\u05d5\u05d0 \u05e0\u05e2\u05e9\u05d4 \u05e4\u05e8\u05d9\u05da \u05d9\u05d5\u05ea\u05e8."],[201.0,"\u05dc\u05d4\u05d9\u05e1\u05d3\u05e7 \u05d1\u05de\u05db\u05d4. \u05e4\u05dc\u05d3\u05d4 \u05e8\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05ea\u05ea\u05e2\u05e7\u05dd, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05ea\u05d9\u05e9\u05d1\u05e8."],[210.0,"\u05d0\u05d9\u05e0\u05d4 \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05d2\u05d1\u05d5\u05d4\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d0\u05dc\u05d0 \u05d4\u05e9\u05d9\u05dc\u05d5\u05d1 \u05d4\u05e0\u05db\u05d5\u05df \u05dc\u05ea\u05e4\u05e7\u05d9\u05d3 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7."],[220.0,"\u05de\u05e2\u05d1\u05e8 \u05dc\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05de\u05db\u05e0\u05d9\u05d5\u05ea \u05d9\u05e9 \u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e4\u05d9\u05d6\u05d9\u05e7\u05dc\u05d9\u05d5\u05ea, \u05e9\u05d7\u05e9\u05d5\u05d1\u05d5\u05ea \u05dc\u05d1\u05d7\u05d9\u05e8\u05d4 \u05dc\u05d0 \u05e4\u05d7\u05d5\u05ea."],[225.0,"\u05e6\u05e4\u05d9\u05e4\u05d5\u05ea: \u05e4\u05dc\u05d3\u05d4 \u05d1\u05e2\u05e8\u05da 7.85 \u05d2\u05e8\u05dd \u05dc\u05e1\u05e0\u05d8\u05d9\u05de\u05d8\u05e8 \u05de\u05e2\u05d5\u05e7\u05d1, \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d1\u05e2\u05e8\u05da 4.4, \u05d5\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d1\u05e2\u05e8\u05da 2.7."],[237.0,"\u05d4\u05e1\u05d2\u05d5\u05dc\u05d9, \u05d5\u05db\u05d0\u05df \u05d4\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d4\u05d7\u05d6\u05e7\u05d5\u05ea \u05de\u05e0\u05e6\u05d7\u05d9\u05dd. \u05dc\u05db\u05df \u05d4\u05dd \u05e9\u05d5\u05dc\u05d8\u05d9\u05dd \u05d1\u05ea\u05e2\u05d5\u05e4\u05d4."],[248.0,"\u05d4\u05ea\u05e4\u05e9\u05d8\u05d5\u05ea \u05ea\u05e8\u05de\u05d9\u05ea: \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05ea\u05d0\u05e8\u05da \u05d1\u05e2\u05e8\u05da \u05e1\u05d9 \u05e9\u05e0\u05d9\u05d9\u05dd \u05de\u05e4\u05dc\u05d3\u05d4 \u05d1\u05d0\u05d5\u05ea\u05d5 \u05e9\u05d9\u05e0\u05d5\u05d9 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4."],[254.0,"\u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05d4\u05d4\u05d1\u05d3\u05dc \u05d1\u05d9\u05df \u05de\u05db\u05dc\u05d5\u05dc \u05e9\u05e2\u05d5\u05d1\u05d3 \u05dc\u05d1\u05d9\u05df \u05de\u05db\u05dc\u05d5\u05dc \u05e9\u05e0\u05ea\u05e7\u05e2."],[263.0,"\u05de\u05d5\u05dc\u05d9\u05db\u05d5\u05ea \u05d7\u05d5\u05dd \u05d5\u05d7\u05e9\u05de\u05dc: \u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05d5\u05dc\u05d9\u05db\u05d9\u05dd \u05de\u05e6\u05d5\u05d9\u05df, \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d5\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05d5\u05ea."],[270.0,"\u05d6\u05d4 \u05de\u05e9\u05e4\u05d9\u05e2 \u05e2\u05dc \u05e4\u05d9\u05d6\u05d5\u05e8 \u05d4\u05d7\u05d5\u05dd \u05d1\u05d7\u05dc\u05e7, \u05d5\u05d2\u05dd \u05e2\u05dc \u05d4\u05d7\u05d5\u05dd \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05d6\u05de\u05df \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3."],[276.0,"\u05d5\u05dc\u05d1\u05e1\u05d5\u05e3, \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e1\u05d1\u05d9\u05d1\u05d4: \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d5\u05ea \u05d5\u05de\u05d2\u05e2 \u05e2\u05dd \u05db\u05d9\u05de\u05d9\u05e7\u05dc\u05d9\u05dd."],[282.0,"\u05d7\u05dc\u05e7 \u05e9\u05d7\u05d6\u05e7 \u05de\u05e1\u05e4\u05d9\u05e7 \u05d1\u05d9\u05d5\u05dd \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d0\u05d1\u05dc \u05de\u05d7\u05dc\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05e9\u05e0\u05d4, \u05d4\u05d5\u05d0 \u05d1\u05d7\u05d9\u05e8\u05ea \u05d7\u05d5\u05de\u05e8 \u05dc\u05d0 \u05e0\u05db\u05d5\u05e0\u05d4."],[289.0,"\u05d5\u05db\u05d0\u05df \u05e0\u05db\u05e0\u05e1\u05ea \u05d4\u05de\u05d8\u05dc\u05d5\u05e8\u05d2\u05d9\u05d4. \u05d4\u05d9\u05d0 \u05e2\u05d5\u05e0\u05d4 \u05e2\u05dc \u05d4\u05e9\u05d0\u05dc\u05d4: \u05de\u05d0\u05d9\u05e4\u05d4 \u05de\u05d2\u05d9\u05e2\u05d5\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc \u05d4\u05de\u05ea\u05db\u05ea?"],[295.0,"\u05d4\u05ea\u05e9\u05d5\u05d1\u05d4 \u05d4\u05d9\u05d0 \u05e9\u05e8\u05e9\u05e8\u05ea \u05e9\u05dc \u05e9\u05dc\u05d5\u05e9 \u05d7\u05d5\u05dc\u05d9\u05d5\u05ea: \u05d4\u05d4\u05e8\u05db\u05d1 \u05d4\u05db\u05d9\u05de\u05d9, \u05d4\u05de\u05d1\u05e0\u05d4 \u05d4\u05e4\u05e0\u05d9\u05de\u05d9, \u05d5\u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05d0\u05e0\u05d7\u05e0\u05d5 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd."],[303.0,"\u05d5\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05d0\u05d9\u05d6\u05d4 \u05de\u05d1\u05e0\u05d4 \u05e4\u05e0\u05d9\u05de\u05d9 \u05d9\u05d9\u05d5\u05d5\u05e6\u05e8 \u05d1\u05e4\u05d5\u05e2\u05dc, \u05d5\u05d4\u05de\u05d1\u05e0\u05d4 \u05d4\u05d5\u05d0 \u05e9\u05e7\u05d5\u05d1\u05e2 \u05d0\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea."],[314.0,"\u05d3\u05d5\u05d2\u05de\u05d4: \u05e4\u05dc\u05d3\u05ea 4140. \u05d0\u05d5\u05ea\u05d5 \u05de\u05d5\u05d8, \u05d0\u05d5\u05ea\u05d5 \u05d4\u05e8\u05db\u05d1 \u05d1\u05d3\u05d9\u05d5\u05e7."],[320.0,"\u05d1\u05de\u05e6\u05d1 \u05e8\u05da \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc\u05d4 \u05d1\u05e2\u05e8\u05da 200 \u05d1\u05e8\u05d9\u05e0\u05dc, \u05d5\u05e7\u05dc \u05dc\u05e2\u05d1\u05d3 \u05d0\u05d5\u05ea\u05d4."],[325.0,"\u05d0\u05d7\u05e8\u05d9 \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05d9\u05d5\u05ea\u05e8 \u05de-50 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc \u05e1, \u05d5\u05d0\u05d6 \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05dc\u05e2\u05d1\u05d3 \u05d0\u05d5\u05ea\u05d4 \u05d1\u05db\u05dc\u05d9\u05dd \u05e8\u05d2\u05d9\u05dc\u05d9\u05dd."],[332.0,"\u05d4\u05d4\u05e8\u05db\u05d1 \u05dc\u05d0 \u05d4\u05e9\u05d5\u05ea\u05e0\u05d4. \u05d4\u05e9\u05ea\u05e0\u05d4 \u05d4\u05de\u05d1\u05e0\u05d4 \u05d1\u05ea\u05d5\u05da \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd."],[336.0,"\u05d1\u05dc\u05d9 \u05de\u05e6\u05d1 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d4\u05d9\u05d0 \u05d4\u05d2\u05d3\u05e8\u05d4 \u05d7\u05e1\u05e8\u05d4, \u05d5\u05db\u05da \u05d2\u05dd \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd 6061 \u05d1\u05dc\u05d9 \u05d4-\u05d3 \u05e9\u05d0\u05d7\u05e8\u05d9\u05d5."],[351.0,"\u05d5\u05e2\u05db\u05e9\u05d9\u05d5 \u05dc\u05e9\u05d0\u05dc\u05d4 \u05e9\u05db\u05dc \u05de\u05ea\u05de\u05d7\u05e8 \u05e9\u05d5\u05d0\u05dc: \u05db\u05de\u05d4 \u05d6\u05d4 \u05e2\u05d5\u05dc\u05d4?"],[355.0,"\u05d4\u05de\u05d7\u05d9\u05e8 \u05dc\u05e7\u05d9\u05dc\u05d5 \u05d4\u05d5\u05d0 \u05d4\u05d7\u05dc\u05e7 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df. \u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05d4\u05d9\u05d0 \u05d4\u05d6\u05d5\u05dc\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8. \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d9\u05e7\u05e8\u05d9\u05dd \u05de\u05de\u05e0\u05d4 \u05e4\u05d9 \u05db\u05de\u05d4."],[364.0,"\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e0\u05d9\u05e7\u05dc \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05e4\u05d9 \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d9\u05d5\u05ea\u05e8 \u05dc\u05e7\u05d9\u05dc\u05d5."],[368.0,"\u05d0\u05d1\u05dc \u05d1\u05d7\u05dc\u05e7 \u05de\u05e2\u05d5\u05d1\u05d3, \u05d4\u05de\u05d7\u05d9\u05e8 \u05dc\u05e7\u05d9\u05dc\u05d5 \u05dc\u05d0 \u05de\u05e1\u05e4\u05e8 \u05d0\u05ea \u05db\u05dc \u05d4\u05e1\u05d9\u05e4\u05d5\u05e8."],[373.0,"\u05e8\u05d0\u05e9\u05d9\u05ea, \u05de\u05d5\u05d8 \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05e9\u05d5\u05e7\u05dc \u05e9\u05dc\u05d9\u05e9 \u05de\u05de\u05d5\u05d8 \u05e4\u05dc\u05d3\u05d4 \u05d1\u05d0\u05d5\u05ea\u05df \u05de\u05d9\u05d3\u05d5\u05ea, \u05db\u05da \u05e9\u05d4\u05d4\u05e4\u05e8\u05e9\u05d5 \u05d1\u05de\u05d7\u05d9\u05e8 \u05d4\u05d7\u05d5\u05de\u05e8 \u05e7\u05d8\u05df \u05de\u05de\u05d4 \u05e9\u05e0\u05e8\u05d0\u05d4."],[381.0,"\u05e9\u05e0\u05d9\u05ea, \u05d5\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d6\u05d4 \u05d4\u05d2\u05d5\u05e8\u05dd \u05d4\u05db\u05d1\u05d3 \u05d9\u05d5\u05ea\u05e8: \u05d6\u05de\u05df \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3."],[386.0,"\u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e0\u05d9\u05e7\u05dc \u05e0\u05d7\u05ea\u05db\u05d9\u05dd \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05d9\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d5\u05ea \u05e4\u05d9 \u05db\u05de\u05d4, \u05d5\u05e9\u05d5\u05d7\u05e7\u05d9\u05dd \u05db\u05dc\u05d9\u05dd \u05de\u05d4\u05e8."],[396.0,"\u05de\u05d9\u05e0\u05d9\u05de\u05d5\u05dd \u05dc\u05d4\u05d6\u05de\u05e0\u05d4, \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d5\u05e6\u05d9\u05e4\u05d5\u05d9 \u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05d3\u05d5\u05e8\u05e9, \u05d5\u05ea\u05e2\u05d5\u05d3\u05d5\u05ea \u05d7\u05d5\u05de\u05e8 \u05e9\u05d4\u05dc\u05e7\u05d5\u05d7 \u05de\u05d7\u05d9\u05d9\u05d1."],[407.0,"\u05d1\u05d7\u05d9\u05e8\u05ea \u05d7\u05d5\u05de\u05e8 \u05d8\u05d5\u05d1\u05d4 \u05de\u05ea\u05d7\u05e9\u05d5\u05d1\u05ea \u05d1\u05db\u05dc \u05d0\u05dc\u05d4 \u05d1\u05d9\u05d7\u05d3, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05d1\u05de\u05d7\u05d9\u05e8 \u05dc\u05e7\u05d9\u05dc\u05d5."],[412.0,"\u05d0\u05d6 \u05d0\u05d9\u05da \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d7\u05d5\u05de\u05e8 \u05d1\u05e4\u05d5\u05e2\u05dc? \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05db\u05de\u05d5 \u05de\u05e9\u05e4\u05da."],[416.0,"\u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05de\u05d4\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7: \u05e2\u05d5\u05de\u05e1\u05d9\u05dd, \u05de\u05e9\u05e7\u05dc, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05e2\u05d1\u05d5\u05d3\u05d4, \u05e1\u05d1\u05d9\u05d1\u05d4 \u05d5\u05ea\u05e7\u05e0\u05d9\u05dd \u05e9\u05d4\u05dc\u05e7\u05d5\u05d7 \u05de\u05d7\u05d9\u05d9\u05d1."],[424.0,"\u05de\u05d4\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05e0\u05d2\u05d6\u05e8\u05ea \u05e8\u05e9\u05d9\u05de\u05d4 \u05e7\u05e6\u05e8\u05d4 \u05e9\u05dc \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05de\u05d5\u05e2\u05de\u05d3\u05d9\u05dd, \u05e9\u05db\u05d5\u05dc\u05dd \u05de\u05e1\u05d5\u05d2\u05dc\u05d9\u05dd \u05dc\u05e2\u05e9\u05d5\u05ea \u05d0\u05ea \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4."],[430.0,"\u05d4\u05d0\u05dd \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05ea\u05da \u05d0\u05d5\u05ea\u05d5, \u05d5\u05d0\u05d9\u05d6\u05d4 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d5\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d4\u05d5\u05d0 \u05e6\u05e8\u05d9\u05da."],[439.0,"\u05d5\u05d1\u05e1\u05d5\u05e3 \u05de\u05db\u05e8\u05d9\u05e2\u05d9\u05dd \u05dc\u05e4\u05d9 \u05e2\u05dc\u05d5\u05ea \u05d5\u05d6\u05de\u05d9\u05e0\u05d5\u05ea."],[442.0,"\u05d4\u05d7\u05d6\u05e7 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d0\u05dc\u05d0 \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05e4\u05e9\u05d5\u05d8 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e9\u05e2\u05d5\u05e0\u05d4 \u05e2\u05dc \u05db\u05dc \u05d4\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea."],[452.0,"\u05d5\u05d4\u05e0\u05d4 \u05d4\u05de\u05e4\u05d4 \u05e9\u05dc \u05d4\u05e7\u05d5\u05e8\u05e1."],[454.0,"\u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05de\u05d8\u05dc\u05d5\u05e8\u05d2\u05d9\u05d4: \u05d4\u05de\u05d1\u05e0\u05d4 \u05d4\u05d2\u05d1\u05d9\u05e9\u05d9, \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d5\u05d4\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea, \u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d5\u05ea \u05e4\u05d0\u05d6\u05d4, \u05d5\u05d4\u05d3\u05e8\u05db\u05d9\u05dd \u05dc\u05d7\u05d6\u05e7 \u05de\u05ea\u05db\u05ea."],[463.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05e0\u05e2\u05d1\u05d5\u05e8 \u05e2\u05dc \u05d4\u05e4\u05dc\u05d3\u05d5\u05ea \u05dc\u05e1\u05d5\u05d2\u05d9\u05d4\u05df \u05d5\u05e2\u05dc \u05d8\u05d9\u05e4\u05d5\u05dc\u05d9 \u05d4\u05d7\u05d5\u05dd \u05e9\u05dc\u05d4\u05df, \u05d5\u05e2\u05dc \u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d9\u05e6\u05d5\u05e7."],[469.0,"\u05de\u05e9\u05dd \u05e0\u05de\u05e9\u05d9\u05da \u05dc\u05de\u05ea\u05db\u05d5\u05ea \u05d4\u05dc\u05d0 \u05d1\u05e8\u05d6\u05dc\u05d9\u05d5\u05ea: \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05e0\u05d7\u05d5\u05e9\u05ea, \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e2\u05dc."],[476.0,"\u05d5\u05d0\u05d9\u05da \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05e9\u05e4\u05d9\u05e2 \u05e2\u05dc \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3, \u05e2\u05dc \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d5\u05e2\u05dc \u05e6\u05d5\u05e8\u05ea \u05d4\u05d0\u05e1\u05e4\u05e7\u05d4."],[484.0,"\u05d5\u05e0\u05e1\u05d9\u05d9\u05dd \u05d1\u05ea\u05e7\u05e0\u05d9\u05dd, \u05d1\u05ea\u05e2\u05d5\u05d3\u05d5\u05ea \u05d7\u05d5\u05de\u05e8 \u05d5\u05d1\u05d1\u05d7\u05d9\u05e8\u05ea \u05d7\u05d5\u05de\u05e8 \u05d1\u05e4\u05d5\u05e2\u05dc, \u05e2\u05dd \u05d3\u05d5\u05d2\u05de\u05d0\u05d5\u05ea \u05e9\u05dc \u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05de\u05d9\u05ea\u05d9\u05d9\u05dd."],[491.0,"\u05db\u05d9 \u05d1\u05e1\u05d5\u05e3, \u05db\u05dc \u05d7\u05dc\u05e7 \u05d8\u05d5\u05d1 \u05de\u05ea\u05d7\u05d9\u05dc \u05d1\u05d7\u05d5\u05de\u05e8 \u05d4\u05e0\u05db\u05d5\u05df."]]};
window.MH_TR["\u05e4\u05e8\u05e701_\u05de\u05d1\u05e0\u05d4_\u05d2\u05d1\u05d9\u05e9\u05d9_\u05d5\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd"]={"t":"\u05de\u05d1\u05e0\u05d4 \u05d2\u05d1\u05d9\u05e9\u05d9 \u05d5\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd","l":[[1.0,"\u05db\u05e9\u05de\u05e1\u05ea\u05db\u05dc\u05d9\u05dd \u05e2\u05dc \u05d7\u05dc\u05e7 \u05de\u05ea\u05db\u05ea, \u05d4\u05d5\u05d0 \u05e0\u05e8\u05d0\u05d4 \u05d0\u05d7\u05d9\u05d3 \u05d5\u05de\u05dc\u05d0."],[5.0,"\u05d0\u05d1\u05dc \u05d0\u05dd \u05e0\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e4\u05d9 \u05de\u05d0\u05d4, \u05e0\u05e8\u05d0\u05d4 \u05e9\u05d4\u05d5\u05d0 \u05d1\u05e0\u05d5\u05d9 \u05de\u05d0\u05dc\u05e4\u05d9 \u05d2\u05d1\u05d9\u05e9\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd, \u05e6\u05de\u05d5\u05d3\u05d9\u05dd \u05d6\u05d4 \u05dc\u05d6\u05d4. \u05d0\u05dc\u05d4 \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd."],[13.0,"\u05e9\u05d4\u05d0\u05d8\u05d5\u05de\u05d9\u05dd \u05d1\u05ea\u05d5\u05db\u05d5 \u05de\u05e1\u05d5\u05d3\u05e8\u05d9\u05dd \u05d1\u05e9\u05d5\u05e8\u05d5\u05ea \u05d9\u05e9\u05e8\u05d5\u05ea, \u05d1\u05d3\u05e4\u05d5\u05e1 \u05e9\u05d7\u05d5\u05d6\u05e8 \u05e2\u05dc \u05e2\u05e6\u05de\u05d5 \u05e9\u05d5\u05d1 \u05d5\u05e9\u05d5\u05d1."],[23.0,"\u05d4\u05e1\u05d3\u05e8 \u05d4\u05d6\u05d4, \u05d4\u05e1\u05e8\u05d9\u05d2 \u05d4\u05d2\u05d1\u05d9\u05e9\u05d9, \u05d4\u05d5\u05d0 \u05d4\u05d1\u05e1\u05d9\u05e1 \u05dc\u05db\u05dc \u05de\u05d4 \u05e9\u05e0\u05dc\u05de\u05d3 \u05d1\u05e7\u05d5\u05e8\u05e1."],[29.0,"\u05d7\u05d5\u05dd \u05de\u05e9\u05e0\u05d4 \u05d0\u05d5\u05ea\u05d4, \u05d5\u05dc\u05de\u05d4 \u05e4\u05dc\u05d3\u05d4 \u05d0\u05d7\u05ea \u05e0\u05e9\u05d1\u05e8\u05ea \u05d1\u05e7\u05d5\u05e8 \u05d5\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05dc\u05d0."],[39.0,"\u05de\u05d4 \u05de\u05d7\u05d6\u05d9\u05e7 \u05d0\u05ea \u05d4\u05d0\u05d8\u05d5\u05de\u05d9\u05dd \u05d9\u05d7\u05d3?"],[41.0,"\u05e9\u05dc\u05d4\u05dd, \u05d5\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05e0\u05e2\u05d9\u05dd \u05d1\u05d7\u05d5\u05e4\u05e9\u05d9\u05d5\u05ea \u05d1\u05d9\u05df \u05db\u05dc \u05d4\u05d0\u05d8\u05d5\u05de\u05d9\u05dd, \u05db\u05de\u05d5 \u05e2\u05e0\u05df \u05de\u05e9\u05d5\u05ea\u05e3. \u05d6\u05d4 \u05d4\u05e7\u05e9\u05e8 \u05d4\u05de\u05ea\u05db\u05ea\u05d9."],[53.0,"\u05d0\u05d7\u05e8\u05d9\u05dd. \u05e8\u05d0\u05e9\u05d9\u05ea, \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05d4\u05d7\u05d5\u05e4\u05e9\u05d9\u05d9\u05dd \u05de\u05d5\u05dc\u05d9\u05db\u05d9\u05dd \u05d7\u05e9\u05de\u05dc \u05d5\u05d7\u05d5\u05dd."],[61.0,"\u05d0\u05d8\u05d5\u05de\u05d9\u05dd \u05de\u05d7\u05dc\u05d9\u05e7\u05d4 \u05dc\u05de\u05e7\u05d5\u05dd \u05d7\u05d3\u05e9, \u05d4\u05d9\u05d0 \u05e0\u05e7\u05e9\u05e8\u05ea \u05de\u05d7\u05d3\u05e2\u05d5 \u05dc\u05e9\u05db\u05e0\u05d9\u05dd \u05d4\u05d7\u05d3\u05e9\u05d9\u05dd, \u05d5\u05d4\u05d7\u05d5\u05de\u05e8 \u05dc\u05d0 \u05e0\u05e9\u05d1\u05e8."],[72.0,"\u05dc\u05db\u05df \u05de\u05ea\u05db\u05ea \u05d0\u05e4\u05e9\u05e8 \u05dc\u05db\u05d5\u05e4\u05e3, \u05dc\u05d7\u05e9\u05dc \u05d5\u05dc\u05de\u05e9\u05d5\u05da, \u05d5\u05d0\u05d9\u05dc\u05d5 \u05d6\u05db\u05d5\u05db\u05d9\u05ea \u05d0\u05d5 \u05e7\u05e8\u05de\u05d9\u05e7\u05d4 \u05e0\u05e1\u05d3\u05e7\u05d5\u05ea."],[80.0,"\u05e8\u05d5\u05d1 \u05d4\u05de\u05ea\u05db\u05d5\u05ea \u05d4\u05d4\u05e0\u05d3\u05e1\u05d9\u05d5\u05ea \u05de\u05e1\u05ea\u05d3\u05e8\u05d5\u05ea \u05d1\u05d0\u05d7\u05d3 \u05de\u05e9\u05dc\u05d5\u05e9\u05d4 \u05de\u05d1\u05e0\u05d9\u05dd."],[84.0,"\u05d0\u05d7\u05d3 \u05d1\u05de\u05e8\u05db\u05d6. \u05d1\u05d5 \u05e0\u05de\u05e6\u05d0\u05d9\u05dd \u05d4\u05d1\u05e8\u05d6\u05dc \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8, \u05d4\u05db\u05e8\u05d5\u05dd, \u05d4\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05d5\u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df."],[96.0,"\u05e4\u05d0\u05d4. \u05d1\u05d5 \u05e0\u05de\u05e6\u05d0\u05d9\u05dd \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05d4\u05e0\u05d7\u05d5\u05e9\u05ea, \u05d4\u05e0\u05d9\u05e7\u05dc, \u05d5\u05d4\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05ea."],[108.0,"\u05d4\u05e9\u05dc\u05d9\u05e9\u05d9 \u05d4\u05d5\u05d0 \u05e1\u05e1\u05d7, \u05de\u05d1\u05e0\u05d4 \u05de\u05e9\u05d5\u05e9\u05d4 \u05e6\u05e4\u05d5\u05e3. \u05d1\u05d5 \u05e0\u05de\u05e6\u05d0\u05d9\u05dd \u05d4\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8, \u05d4\u05de\u05d2\u05e0\u05d6\u05d9\u05d5\u05dd \u05d5\u05d4\u05d0\u05d1\u05e5."],[117.0,"\u05d5\u05dc\u05de\u05d1\u05e0\u05d4\u05d9\u05e9 \u05d4\u05e9\u05dc\u05db\u05d5\u05ea \u05de\u05e2\u05e9\u05d9\u05d5\u05ea."],[119.0,"\u05e2\u05dc\u05d9\u05d4\u05dd, \u05d5\u05dc\u05db\u05df \u05d4\u05de\u05ea\u05db\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05de\u05e9\u05d9\u05db\u05d5\u05ea \u05de\u05d0\u05d5\u05d3, \u05d5\u05e0\u05e9\u05d0\u05e8\u05d5\u05ea \u05de\u05e9\u05d9\u05db\u05d5\u05ea \u05d2\u05dd \u05d1\u05e7\u05d5\u05e8 \u05e2\u05de\u05d5\u05e7."],[130.0,"\u05e0\u05e2\u05e9\u05d9\u05ea \u05e7\u05e9\u05d4. \u05dc\u05db\u05df \u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05d7\u05de\u05df \u05e8\u05d2\u05d9\u05dc\u05d5\u05ea \u05e2\u05dc\u05d5\u05dc\u05d5\u05ea \u05dc\u05d4\u05e4\u05d5\u05da \u05dc\u05e4\u05e8\u05d9\u05db\u05d5\u05ea \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d5\u05ea."],[141.0,"\u05e7\u05e9\u05d9\u05dd \u05dc\u05e2\u05d9\u05e6\u05d5\u05d1 \u05d1\u05e7\u05d5\u05e8, \u05d5\u05d2\u05dd \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05e4\u05d7\u05d5\u05ea \u05e0\u05d5\u05d7 \u05dc\u05e2\u05d9\u05e6\u05d5\u05d1 \u05de\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd."],[151.0,"\u05d4\u05d7\u05d5\u05dd \u05e9\u05dc \u05d4\u05e4\u05dc\u05d3\u05d4: \u05d4\u05d5\u05d0 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05d4\u05d2\u05d1\u05d9\u05e9\u05d9 \u05e9\u05dc\u05d5 \u05dc\u05e4\u05d9 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4."],[160.0,"\u05e2\u05d3 912 \u05de\u05e2\u05dc\u05d5\u05ea \u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d5\u05d0 00\u05dd."],[165.0,"\u05de\u05e2\u05dc 912 \u05de\u05e2\u05dc\u05d5\u05ea \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d1\u05e8 FCC-7, \u05d5\u05de\u05d1\u05e0\u05d4 \u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."],[171.0,"\u05de\u05e2\u05dc 1,394 \u05de\u05e2\u05dc\u05d5\u05ea \u05d4\u05d5\u05d0 \u05d7\u05d5\u05d6\u05e8 \u05dc-806, \u05d5\u05e2\u05d3 \u05d4\u05d4\u05ea\u05db\u05d4 \u05d1-1,538 \u05de\u05e2\u05dc\u05d5\u05ea."],[179.0,"\u05d4\u05e9\u05d9\u05e0\u05d5\u05d9 \u05d4\u05d6\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05d1\u05de\u05e6\u05d1 \u05de\u05d5\u05e6\u05e7, \u05d1\u05dc\u05d9 \u05dc\u05d4\u05ea\u05d9\u05da \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7."],[183.0,"\u05d5\u05db\u05e9\u05de\u05d1\u05e0\u05d4 \u05de\u05e9\u05ea\u05e0\u05d4, \u05de\u05e9\u05ea\u05e0\u05d4 \u05d2\u05dd \u05d4\u05db\u05de\u05d5\u05ea \u05e9\u05dc \u05e4\u05d7\u05de\u05df \u05e9\u05d4\u05d1\u05e8\u05d6\u05dc \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05db\u05d9\u05dc \u05d1\u05ea\u05d5\u05db\u05d5."],[189.0,"\u05d1\u05d3\u05d9\u05d5\u05e7 \u05d0\u05ea \u05d4\u05de\u05e2\u05d1\u05e8 \u05d4\u05d6\u05d4 \u05de\u05e0\u05e6\u05dc\u05d9\u05dd \u05d1\u05d4\u05e7\u05e9\u05d9\u05d4, \u05db\u05e4\u05d9 \u05e9\u05e0\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 6."],[194.0,"\u05e2\u05db\u05e9\u05d9\u05d5 \u05dc\u05e9\u05d0\u05dc\u05d4 \u05d4\u05d7\u05e9\u05d5\u05d1\u05d4: \u05d0\u05d9\u05da \u05de\u05ea\u05db\u05ea \u05de\u05ea\u05e2\u05d5\u05d5\u05ea\u05ea?"],[198.0,"\u05d4\u05d3\u05d1\u05e8 \u05d4\u05d8\u05d1\u05e2\u05d9 \u05d4\u05d5\u05d0 \u05dc\u05d7\u05e9\u05d5\u05d1 \u05e9\u05de\u05d9\u05e9\u05d5\u05e8 \u05e9\u05dc\u05dd \u05e9\u05dc \u05d0\u05d8\u05d5\u05de\u05d9\u05dd \u05de\u05d7\u05dc\u05d9\u05e7 \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea \u05e2\u05dc \u05d4\u05de\u05d9\u05e9\u05d5\u05e8 \u05e9\u05de\u05ea\u05d7\u05ea\u05d9\u05d5."],[204.0,"\u05d0\u05d1\u05dc \u05d0\u05dd \u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05db\u05d5\u05d7 \u05e9\u05e0\u05d3\u05e8\u05e9 \u05dc\u05d6\u05d4, \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d7\u05d5\u05d6\u05e7 \u05d2\u05d1\u05d5\u05d4 \u05e4\u05d9 \u05de\u05d0\u05d4 \u05d5\u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d1\u05de\u05e6\u05d9\u05d0\u05d5\u05ea."],[212.0,"\u05d4\u05e1\u05d9\u05d1\u05d4 \u05d4\u05d9\u05d0 \u05e4\u05d2\u05de\u05d9\u05dd \u05d1\u05e1\u05e8\u05d9\u05d2 \u05e9\u05e0\u05e7\u05e8\u05d0\u05d9\u05dd \u05e0\u05e7\u05e2\u05d9\u05dd, 5 \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea."],[218.0,"\u05e0\u05e7\u05e2 \u05d4\u05d5\u05d0 \u05e9\u05d5\u05e8\u05d4 \u05e9\u05dc \u05d0\u05d8\u05d5\u05de\u05d9\u05dd \u05e9\u05d7\u05e1\u05e8\u05d4, \u05d0\u05d5 \u05e0\u05d3\u05d7\u05e7\u05d4, \u05d1\u05ea\u05d5\u05da \u05d4\u05e1\u05e8\u05d9\u05d2."],[223.0,"\u05d7\u05e9\u05d1\u05d5 \u05e2\u05dc \u05e9\u05d8\u05d9\u05d7 \u05db\u05d1\u05d3 \u05e9\u05e8\u05d5\u05e6\u05d9\u05dd \u05dc\u05d4\u05d6\u05d9\u05d6. \u05dc\u05de\u05e9\u05d5\u05da \u05d0\u05ea \u05db\u05d5\u05dc\u05d5 \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3."],[228.0,"\u05d0\u05d1\u05dc \u05d0\u05dd \u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05d1\u05d5 \u05e7\u05de\u05d8 \u05d5\u05d3\u05d5\u05d7\u05e4\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05de\u05d8 \u05dc\u05d0\u05d5\u05e8\u05db\u05d5, \u05d4\u05e9\u05d8\u05d9\u05d7 \u05d6\u05d6 \u05d1\u05e7\u05dc\u05d5\u05ea, \u05e7\u05e6\u05ea \u05d1\u05db\u05dc \u05e4\u05e2\u05dd."],[235.0,"\u05db\u05da \u05d1\u05d3\u05d9\u05d5\u05e7 \u05e0\u05e2 \u05e0\u05e7\u05e2: \u05d4\u05d5\u05d0 \u05de\u05d6\u05d9\u05d6 \u05e8\u05e7 \u05e9\u05d5\u05e8\u05d4 \u05d0\u05d7\u05ea \u05e9\u05dc \u05e7\u05e9\u05d5\u05e8\u05d9\u05dd \u05d1\u05db\u05dc \u05e8\u05d2\u05e2, \u05d5\u05dc\u05db\u05df \u05d4\u05db\u05d5\u05d7 \u05d4\u05e0\u05d3\u05e8\u05e9 \u05e7\u05d8\u05df \u05d1\u05d4\u05e8\u05d1\u05d4."],[243.0,"\u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05d4\u05e4\u05dc\u05e1\u05d8\u05d9 \u05e9\u05dc \u05de\u05ea\u05db\u05ea, \u05db\u05dc \u05db\u05d9\u05e4\u05d5\u05e3, \u05db\u05dc \u05d7\u05d9\u05e9\u05d5\u05dc\u05d5\u05db\u05dc \u05e9\u05d1\u05d1, \u05d4\u05d5\u05d0 \u05ea\u05e0\u05d5\u05e2\u05d4 \u05e9\u05dc \u05de\u05d9\u05dc\u05d9\u05d0\u05e8\u05d3\u05d9 \u05e0\u05e7\u05e2\u05d9\u05dd."],[251.0,"\u05de\u05db\u05d0\u05df \u05e0\u05d5\u05d1\u05e2 \u05d4\u05e8\u05e2\u05d9\u05d5\u05df \u05d4\u05de\u05e8\u05db\u05d6\u05d9 \u05e9\u05dc \u05d7\u05d5\u05d6\u05e7 \u05d4\u05de\u05ea\u05db\u05d5\u05ea: \u05db\u05d3\u05d9 \u05dc\u05d7\u05d6\u05e7 \u05de\u05ea\u05db\u05ea, \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e7\u05e9\u05d5\u05d5\u05ea \u05e2\u05dc \u05d4\u05e0\u05e7\u05e2\u05d9\u05dd \u05dc\u05e0\u05d5\u05e2."],[259.0,"\u05d3\u05e8\u05da \u05d0\u05d7\u05ea \u05dc\u05e2\u05e9\u05d5\u05d5\u05ea \u05d0\u05ea \u05d6\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05e2\u05e6\u05de\u05d5."],[262.0,"\u05d1\u05d6\u05d4 \u05d5\u05de\u05e1\u05ea\u05d1\u05db\u05d9\u05dd, \u05d5\u05db\u05dc \u05e0\u05e7\u05e2 \u05d7\u05d3\u05e9 \u05de\u05ea\u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05d6\u05d5\u05d6. \u05d6\u05d5 \u05d4\u05ea\u05e7\u05e9\u05d5\u05ea \u05de\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8."],[274.0,"\u05db\u05d5\u05dc\u05e0\u05d5 \u05de\u05db\u05d9\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4: \u05de\u05db\u05d5\u05e4\u05e4\u05d9\u05dd \u05d0\u05d8\u05d1 \u05de\u05e9\u05e8\u05d3\u05d9 \u05d4\u05dc\u05d5\u05da \u05d5\u05e9\u05d5\u05d1, \u05d4\u05d5\u05d0 \u05e0\u05e2\u05e9\u05d4 \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3, \u05d5\u05d1\u05e1\u05d5\u05e3 \u05e0\u05e9\u05d1\u05e8 \u05e9\u05dd."],[282.0,"\u05dc\u05db\u05dc\u05d9 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da, \u05d5\u05dc\u05de\u05d4 \u05e4\u05d7 \u05e9\u05e2\u05d1\u05e8 \u05db\u05d9\u05e4\u05d5\u05e3 \u05e0\u05e2\u05e9\u05d4 \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05e7\u05d5 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3."],[291.0,"\u05d5\u05d0\u05ea \u05d4\u05d4\u05ea\u05e7\u05e9\u05d5\u05ea \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d1\u05d8\u05dc \u05d1\u05d7\u05d9\u05de\u05d5\u05dd, \u05e9\u05de\u05e1\u05d3\u05e8 \u05de\u05d7\u05d3\u05e2\u05d5 \u05d0\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd."],[297.0,"\u05e2\u05db\u05e9\u05d9\u05d5 \u05e0\u05d7\u05d6\u05d5\u05e8 \u05dc\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd."],[298.0,"\u05d1\u05d4\u05e8\u05d1\u05d4 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea. \u05db\u05dc \u05d2\u05d1\u05d9\u05e9 \u05d2\u05d3\u05dc \u05d1\u05db\u05d9\u05d5\u05d5\u05df \u05de\u05e9\u05dc\u05d5, \u05e2\u05d3 \u05e9\u05d4\u05d5\u05d0 \u05e4\u05d5\u05d2\u05e9 \u05d0\u05ea \u05e9\u05db\u05e0\u05d9\u05d5."],[309.0,"\u05db\u05dc \u05d2\u05d1\u05d9\u05e9 \u05db\u05d6\u05d4 \u05d4\u05d5\u05d0 \u05d2\u05e8\u05e2\u05d9\u05df, \u05d5\u05d4\u05e7\u05d5 \u05e9\u05d1\u05d5 \u05e0\u05e4\u05d2\u05e9\u05d9\u05dd \u05e9\u05e0\u05d9 \u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d4\u05d5\u05d0 \u05d2\u05d1\u05d5\u05dc \u05d2\u05e8\u05e2\u05d9\u05df."],[315.0,"\u05d1\u05ea\u05d5\u05da \u05db\u05dc \u05d2\u05e8\u05e2\u05d9\u05df \u05d4\u05e9\u05d5\u05e8\u05d5\u05ea \u05d9\u05e9\u05e8\u05d5\u05ea \u05d5\u05de\u05e1\u05d5\u05d3\u05e8\u05d5\u05ea, \u05d0\u05d1\u05dc \u05de\u05d2\u05e8\u05e2\u05d9\u05df \u05dc\u05d2\u05e8\u05e2\u05d9\u05df \u05d4\u05db\u05d9\u05d5\u05d5\u05df \u05de\u05e9\u05ea\u05e0\u05d4."],[322.0,"\u05d4\u05e9\u05d5\u05e8\u05d5\u05ea \u05e4\u05ea\u05d0\u05d5\u05dd \u05e4\u05d5\u05e0\u05d5\u05ea \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d0\u05d7\u05e8. \u05d4\u05e0\u05e7\u05e2 \u05dc\u05d0 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05de\u05e9\u05d9\u05da \u05d9\u05e9\u05e8, \u05d5\u05d4\u05d5\u05d0 \u05e0\u05e2\u05e6\u05e8."],[333.0,"\u05db\u05dc\u05d5\u05de\u05e8, \u05db\u05dc \u05d2\u05d1\u05d5\u05dc \u05d2\u05e8\u05e2\u05d9\u05df \u05d4\u05d5\u05d0 \u05de\u05d7\u05e1\u05d5\u05dd."],[336.0,"\u05de\u05db\u05d0\u05df \u05e9\u05d2\u05d5\u05d3\u05dc \u05d4\u05d2\u05e8\u05e2\u05d9\u05df \u05de\u05e9\u05e4\u05d9\u05e2 \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea \u05e2\u05dc \u05d4\u05d7\u05d5\u05d6\u05e7."],[340.0,"\u05db\u05db\u05dc \u05e9\u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8, \u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea, \u05d9\u05d5\u05ea\u05e8 \u05de\u05d7\u05e1\u05d5\u05de\u05d9\u05dd, \u05d5\u05d4\u05de\u05ea\u05db\u05ea \u05d7\u05d6\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8."],[347.0,"5 toughness. \u05d6\u05d5 \u05db\u05de\u05e2\u05d8 \u05d4\u05d3\u05e8\u05da \u05d4\u05d9\u05d7\u05d9\u05d3\u05d4 \u05dc\u05d7\u05d6\u05e7 \u05de\u05ea\u05db\u05ea \u05d1\u05dc\u05d9 \u05dc\u05e9\u05dc\u05dd \u05d1\u05e4\u05e8\u05d9\u05db\u05d5\u05ea."],[357.0,"\u05d0\u05ea \u05d2\u05d5\u05d3\u05dc \u05d4\u05d2\u05e8\u05e2\u05d9\u05df \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d1\u05de\u05d9\u05e7\u05e8\u05d5\u05e1\u05e7\u05d5\u05e4 \u05d5\u05de\u05d1\u05d8\u05d0\u05d9\u05dd \u05d1\u05de\u05e1\u05e4\u05e8 \u05d2\u05e8\u05e2\u05d9\u05df \u05dc\u05e4\u05d9 \u05d4\u05ea\u05e7\u05df E112 \u05d5\u05d0 ASTM"],[365.0,"\u05e9\u05d9\u05de\u05d5 \u05dc\u05d1, \u05d4\u05de\u05e1\u05e4\u05e8 \u05d4\u05e4\u05d5\u05da: \u05de\u05e1\u05e4\u05e8 \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05d2\u05e8\u05e2\u05d9\u05df \u05e2\u05d3\u05d9\u05df \u05d9\u05d5\u05ea\u05e8."],[371.0,"\u05d5\u05d2\u05d5\u05d3\u05dc \u05d4\u05d2\u05e8\u05e2\u05d9\u05df \u05dc\u05d0 \u05e7\u05d1\u05d5\u05e2. \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05de\u05d5\u05e9\u05da \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd."],[377.0,"\u05d6\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05dc\u05de\u05e9\u05dc \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05e9\u05e0\u05e2\u05e9\u05d4 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d3\u05d9, \u05d0\u05d5 \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e1\u05de\u05d5\u05da \u05dc\u05e8\u05d9\u05ea\u05d5\u05da."],[384.0,"\u05db\u05e9\u05de\u05d2\u05dc\u05d2\u05dc\u05d9\u05dd \u05e4\u05d7 \u05d0\u05d5 \u05de\u05d5\u05d8, \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d5\u05d4\u05ea\u05db\u05dc\u05d9\u05dc\u05d9\u05dd \u05e9\u05d1\u05ea\u05d5\u05da \u05d4\u05d7\u05d5\u05de\u05e8 \u05e0\u05de\u05ea\u05d7\u05d9\u05dd \u05dc\u05d0\u05d5\u05e8\u05da \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d2\u05dc\u05d2\u05d5\u05dc."],[391.0,"\u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d6\u05d4 \u05d4\u05de\u05e9\u05d5\u05d9\u05db\u05d5\u05ea \u2026 \u05d8\u05d5\u05d1\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8, \u05d5\u05dc\u05e8\u05d5\u05d7\u05d1\u05d5 \u05d4\u05df \u05e0\u05de\u05d5\u05db\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8."],[402.0,"\u05d1\u05db\u05d9\u05e4\u05d5\u05e3 \u05e4\u05d7, \u05dc\u05db\u05df, \u05e2\u05d3\u05d9\u05e3 \u05e9\u05e7\u05d5 \u05d4\u05db\u05d9\u05e4\u05d5\u05e3 \u05d9\u05d4\u05d9\u05d4 \u05e0\u05d9\u05e6\u05d1 \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d2\u05dc\u05d2\u05d5\u05dc."],[407.0,"\u05db\u05d9\u05e4\u05d5\u05e3 \u05e9\u05e7\u05d5 \u05e9\u05dc\u05d5 \u05de\u05e7\u05d1\u05d9\u05dc \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d2\u05dc\u05d2\u05d5\u05dc \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05e8\u05d3\u05d9\u05d5\u05e1 \u05e7\u05d8\u05df \u05d5\u05d1\u05d7\u05d5\u05de\u05e8 \u05e7\u05e9\u05d4."],[414.0,"\u05d0\u05d5\u05ea\u05d5 \u05e2\u05d9\u05e7\u05e8\u05d5\u05df \u05e4\u05d5\u05e2\u05dc \u05d1\u05d7\u05d9\u05e9\u05d5\u05dc. \u05d1\u05d7\u05dc\u05e7 \u05de\u05d7\u05d5\u05e9\u05dc, \u05e7\u05d5\u05d5\u05d9 \u05d4\u05d6\u05e8\u05d9\u05de\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8 \u05e2\u05d5\u05e7\u05d1\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e6\u05d5\u05e8\u05d4 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7."],[422.0,"\u05d1\u05d7\u05dc\u05e7 \u05e9\u05e2\u05d5\u05d1\u05d3 \u05de\u05de\u05d5\u05d8, \u05d4\u05e9\u05d1\u05d1\u05d9\u05dd \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05d5\u05d5\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4."],[426.0,"\u05d0\u05e8\u05db\u05d5\u05d1\u05d4, \u05de\u05d7\u05d5\u05e9\u05dc\u05d9\u05dd. \u05db\u05e9\u05d4\u05db\u05d9\u05d5\u05d5\u05df \u05d7\u05e9\u05d5\u05d1, \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."],[435.0,"\u05de\u05d4 \u05db\u05dc\u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4?"],[437.0,"\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05d0\u05d5 \u05e4\u05dc\u05d3\u05d4 \u05e9\u05e0\u05d1\u05d3\u05e7\u05d4 \u05d1\u05de\u05d1\u05d7\u05df \u05d4\u05dc\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4."],[451.0,"\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d2\u05e1\u05d9\u05dd \u2026 \u05e0\u05de\u05d5\u05db\u05d4, \u05d2\u05dd \u05db\u05e9\u05d4\u05e7\u05e2\u05d5\u05d9\u05d5\u05ea \u05e9\u05dc\u05d5 \u05ea\u05e7\u05d9\u05e0\u05d4."],[459.0,"\u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05d3\u05e8\u05d9\u05e9\u05d4 \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d2\u05e8\u05e2\u05d9\u05df \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05d2\u05d1\u05d9\u05dc\u05d4 \u05d0\u05ea \u05d7\u05d9\u05ea\u05d5\u05da \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d4\u05e4\u05d7, \u05d5\u05dc\u05db\u05df \u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d7\u05ea."],[467.0,"\u05d7\u05dc\u05e7 \u05de\u05d7\u05d5\u05e9\u05dc \u05d3\u05d5\u05e8\u05e9\u05d5 \u05ea\u05d1\u05e0\u05d9\u05ea, \u05d5\u05d6\u05d4 \u05de\u05e9\u05ea\u05dc\u05dd \u05e8\u05e7 \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea."],[471.0,"\u05d5\u05d3\u05e8\u05d9\u05e9\u05d4 \u05dc\u05d2\u05e8\u05e2\u05d9\u05df \u05e2\u05d3\u05d9\u05df \u05d0\u05d5 \u05dc\u05de\u05d1\u05d7\u05df \u05d4\u05dc\u05dd \u05d1\u05e7\u05d5\u05e8 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d5\u05ea\u05e2\u05d5\u05d3\u05d5\u05ea."],[477.0,"\u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4: \u05de\u05d1\u05d7\u05e0\u05d9 \u05d4\u05de\u05ea\u05d9\u05d7\u05d4, \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea, \u05d4\u05d4\u05dc\u05dd \u05d5\u05d4\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."]]};
window.MH_TR["\u05e4\u05e8\u05e702_\u05ea\u05db\u05d5\u05e0\u05d5\u05ea_\u05de\u05db\u05e0\u05d9\u05d5\u05ea_\u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea"]={"t":"\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05de\u05db\u05e0\u05d9\u05d5\u05ea \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea","l":[[1.0,"\u05de\u05e1\u05e4\u05e8\u05d9\u05dd: \u05d7\u05d5\u05d6\u05e7 \u05db\u05e0\u05d9\u05e2\u05d4 \u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9, \u05d8\u05d5\u05d5\u05d7 \u05e7\u05e9\u05d9\u05d5\u05ea, \u05d0\u05e0\u05e8\u05d2\u05d9\u05d9\u05ea \u05d4\u05dc\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05de\u05e1\u05d5\u05d9\u05de\u05ea."],[11.0,"\u05db\u05dc \u05d0\u05d7\u05d3 \u05de\u05d4\u05dd \u05e0\u05de\u05d3\u05d3 \u05d1\u05de\u05d1\u05d7\u05df \u05de\u05d5\u05d2\u05d3\u05e8, \u05dc\u05e4\u05d9 \u05ea\u05e7\u05df, \u05e2\u05dc \u05d3\u05d2\u05dd \u05d1\u05d2\u05d5\u05d3\u05dc \u05de\u05d5\u05d2\u05d3\u05e8."],[17.0,"\u05db\u05d3\u05d9 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05d5\u05ea\u05dd \u05e0\u05db\u05d5\u05df, \u05d5\u05dc\u05d3\u05e2\u05ea \u05de\u05d4 \u05d4\u05dd \u05de\u05d1\u05d8\u05d9\u05d7\u05d9\u05dd \u05d5\u05de\u05d4 \u05dc\u05d0, \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d1\u05d9\u05df \u05d0\u05d9\u05da \u05db\u05dc \u05de\u05d1\u05d7\u05df \u05e2\u05d5\u05d1\u05d3."],[24.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05e2\u05dc \u05d4\u05de\u05d1\u05d7\u05e0\u05d9\u05dd \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd: \u05de\u05ea\u05d9\u05d7\u05d4, \u05e7\u05e9\u05d9\u05d5\u05ea, \u05d4\u05dc\u05dd, \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05d5\u05d6\u05d7\u05d9\u05dc\u05d4."],[32.0,"\u05e9\u05d8\u05d5\u05d7, \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05e2\u05dc\u05d9\u05d5 \u05d0\u05d5\u05e8\u05da \u05de\u05d3\u05d9\u05d3\u05d4, \u05d5\u05de\u05d5\u05ea\u05d7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05dc\u05d0\u05d8 \u05e2\u05d3 \u05e9\u05d4\u05d5\u05d0 \u05e0\u05e9\u05d1\u05e8, \u05ea\u05d5\u05da \u05de\u05d3\u05d9\u05d3\u05d4 \u05e9\u05dc \u05d4\u05db\u05d5\u05d7 \u05d5\u05e9\u05dc \u05d4\u05d4\u05ea\u05d0\u05e8\u05db\u05d5\u05ea."],[45.0,"\u05de\u05d0\u05de\u05e5, \u05d1\u05d9\u05d7\u05d9\u05d3\u05d5\u05ea \u05e9\u05dc \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc, \u05db\u05dc\u05d5\u05de\u05e8 \u05e0\u05d9\u05d5\u05d8\u05d5\u05df \u05dc\u05db\u05dc \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e8\u05d1\u05d5\u05e2."],[54.0,"\u05d1\u05d4\u05ea\u05d7\u05dc\u05d4 \u05d4\u05e7\u05d5 \u05d9\u05e9\u05e8: \u05d6\u05d4 \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d0\u05dc\u05e1\u05d8\u05d9."],[58.0,"\u05d0\u05e6\u05dc \u05e8\u05d5\u05d1 \u05d4\u05de\u05ea\u05db\u05d5\u05ea \u05d0\u05d9\u05df \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d7\u05d3\u05d4 \u05e9\u05d1\u05d4 \u05d4\u05e7\u05d5 \u05de\u05ea\u05e2\u05e7\u05dd, \u05d5\u05dc\u05db\u05df \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d7\u05d5\u05d6\u05e7 \u05d4\u05db\u05e0\u05d9\u05e2\u05d4 \u05d1\u05d4\u05e1\u05db\u05de\u05d4."],[65.0,"\u05d4\u05ea\u05d0\u05e8\u05db\u05d5\u05ea, \u05d5\u05d4\u05de\u05d0\u05de\u05e5 \u05e9\u05d1\u05d5 \u05d4\u05e7\u05e8\u05e4\u05d5\u05d2\u05e9 \u05d0\u05ea \u05d4\u05e2\u05e7\u05d5\u05de\u05d4 \u05d4\u05d5\u05d0 \u05d7\u05d7\u05e7 \u05d4\u05db\u05e0\u05d9\u05e2\u05d4."],[75.0,"\u05d1\u05ea\u05e2\u05d5\u05d3\u05d5\u05ea \u05d4\u05d5\u05d0 \u05de\u05e1\u05d5\u05de\u05df RpO0.2. \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d1\u05e0\u05d4 \u05e8\u05db\u05d5\u05ea \u05d9\u05e9\u05e9 \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05db\u05e0\u05d9\u05e2\u05d4 \u05d7\u05d3\u05d4, \u05d5\u05d4\u05d9\u05d0 \u05de\u05e1\u05d5\u05de\u05e0\u05ea \u05e8\u05d586."],[85.0,"\u05d0\u05d7\u05e8\u05d9\u05d4 \u05d4\u05d3\u05d2\u05dd \u05de\u05ea\u05d7\u05d9\u05dc \u05dc\u05d4\u05d9\u05e6\u05e8 \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d0\u05d7\u05d3, \u05d5\u05d6\u05de\u05df \u05e7\u05e6\u05e8 \u05d0\u05d7\u05e8 \u05db\u05da \u05e0\u05e9\u05d1\u05e8."],[95.0,"\u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05d0\u05ea \u05e9\u05e0\u05d9 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05ea \u05d0\u05d5\u05e8\u05da \u05d4\u05de\u05d3\u05d9\u05d3\u05d4, \u05d5\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05d4\u05ea\u05d0\u05e8\u05db\u05d5\u05ea \u05d1\u05d0\u05d7\u05d5\u05d6\u05d9\u05dd, A"],[102.0,"\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d2\u05dd \u05d0\u05ea \u05d4\u05e6\u05de\u05e6\u05d5\u05dd \u05d1\u05e9\u05d8\u05d7 \u05d4\u05d7\u05ea\u05da \u05d1\u05de\u05e7\u05d5\u05dd \u05d4\u05e9\u05d1\u05e8, 7. \u05e9\u05e0\u05d9 \u05d4\u05de\u05e1\u05e4\u05e8\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05de\u05ea\u05d0\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05e9\u05d9\u05db\u05d5\u05ea."],[110.0,"\u05e2\u05db\u05e9\u05d9\u05d5 \u05e0\u05e9\u05d9\u05dd \u05db\u05de\u05d4 \u05e2\u05e7\u05d5\u05de\u05d5\u05ea \u05d6\u05d5 \u05e2\u05dc \u05d6\u05d5."],[113.0,"\u05e4\u05e1\u05e7\u05dc, \u05d5\u05d6\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05de\u05d4 \u05e9\u05d4\u05de\u05e1\u05e4\u05e8 \u05d1\u05e9\u05dd \u05e9\u05dc\u05d4 \u05d0\u05d5\u05de\u05e8. \u05d0\u05d7\u05e8\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05de\u05de\u05e9\u05d9\u05db\u05d4 \u05dc\u05d4\u05ea\u05d0\u05e8\u05da \u05d4\u05e8\u05d1\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d1\u05e8."],[127.0,"\u05e4\u05dc\u05d3\u05d4 \u05de\u05d5\u05e7\u05e9\u05d9\u05ea: \u05d4\u05e2\u05e7\u05d5\u05de\u05d4 \u05e2\u05d5\u05dc\u05d4 \u05d2\u05d1\u05d5\u05d4 \u05d1\u05d4\u05e8\u05d1\u05d4, \u05dc\u05e2\u05ea\u05d9\u05dd \u05de\u05e2\u05dc 0 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc, \u05d0\u05d1\u05dc \u05e0\u05e9\u05d1\u05e8\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d4\u05ea\u05d0\u05e8\u05db\u05d5\u05ea \u05e7\u05d8\u05e0\u05d4."],[137.0,"\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d7\u05d6\u05e7\u05d4: \u05d7\u05d5\u05d6\u05e7 \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9, \u05d5\u05e9\u05d9\u05e4\u05d5\u05e2 \u05de\u05ea\u05d5\u05df \u05d9\u05d5\u05ea\u05e8 \u05d1\u05d2\u05dc\u05dc \u05d4\u05de\u05d5\u05d3\u05d5\u05dc \u05d4\u05e0\u05de\u05d5\u05da."],[143.0,"\u05d5\u05e2\u05d5\u05d3 \u05d3\u05d1\u05e8 \u05d7\u05e9\u05d5\u05d1: \u05d4\u05de\u05e1\u05e4\u05e8\u05d9\u05dd \u05d1\u05ea\u05e2\u05d5\u05d3\u05d4 \u05d4\u05dd \u05e2\u05e8\u05db\u05d9 \u05de\u05d9\u05e0\u05d9\u05de\u05d5\u05dd, \u05d5\u05d4\u05dd \u05e0\u05de\u05d3\u05d3\u05d5 \u05e2\u05dc \u05d3\u05d2\u05dd \u05de\u05d0\u05d5\u05ea\u05d4 \u05de\u05e0\u05d4."],[150.0,"\u05d4\u05d7\u05dc\u05e7 \u05e9\u05dc\u05db\u05dd, \u05d0\u05d7\u05e8\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3, \u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05d5 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05d4\u05d5\u05d0 \u05db\u05d1\u05e8 \u05e1\u05d9\u05e4\u05d5\u05e8 \u05d0\u05d7\u05e8."],[156.0,"\u05de\u05d1\u05d7\u05df \u05e7\u05e9\u05d9\u05d5\u05ea \u05de\u05d4\u05d9\u05e8, \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05e4\u05d5\u05d2\u05e2 \u05d1\u05d7\u05dc\u05e7, \u05d5\u05e0\u05e2\u05e9\u05d4 \u05e2\u05dc \u05d4\u05d7\u05dc\u05e7 \u05e2\u05e6\u05de\u05d5."],[161.0,"\u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df \u05e4\u05e9\u05d5\u05d8: \u05dc\u05d5\u05d7\u05e6\u05d9\u05dd \u05d7\u05d5\u05d3\u05df \u05e7\u05e9\u05d4 \u05dc\u05ea\u05d5\u05da \u05d4\u05d7\u05d5\u05de\u05e8 \u05d1\u05db\u05d5\u05d7 \u05d9\u05d3\u05d5\u05e2, \u05d5\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05e9\u05e7\u05e2 \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d1\u05d7\u05d5\u05de\u05e8."],[169.0,"\u05d1\u05e9\u05d9\u05d8\u05ea \u05d1\u05e8\u05d9\u05e0\u05dc \u05dc\u05d5\u05d7\u05e6\u05d9\u05dd \u05db\u05d3\u05d5\u05e8, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e7\u05d5\u05d8\u05e8 \u05e2\u05e9\u05e8\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05d5\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05ea \u05e7\u05d5\u05d8\u05e8 \u05d4\u05e9\u05e7\u05e2."],[176.0,"\u05d9\u05e6\u05d9\u05e7\u05d5\u05ea \u05d5\u05d7\u05d9\u05e9\u05d5\u05dc\u05d9\u05dd, \u05d5\u05e0\u05d5\u05ea\u05e0\u05ea \u05de\u05de\u05d5\u05e6\u05e2 \u05d8\u05d5\u05d1 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05db\u05de\u05d4 \u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd. \u05d4\u05e2\u05e8\u05da \u05e0\u05db\u05ea\u05d1 HB, \u05d0\u05d5 \\\\\u05e4\u05d7."],[188.0,"\u05e2\u05d5\u05de\u05e7 \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4, \u05d5\u05d4\u05de\u05db\u05e9\u05d9\u05e8 \u05de\u05e6\u05d9\u05d2 \u05d0\u05ea \u05d4\u05de\u05e1\u05e4\u05e8 \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea. \u05d6\u05d5 \u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05e8\u05e6\u05e4\u05ea \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8."],[199.0,"\u05d9\u05e9 \u05dc\u05d4 \u05db\u05de\u05d4 \u05e1\u05e7\u05d0\u05dc\u05d5\u05ea: HRC, \u05e2\u05dd \u05d7\u05e8\u05d5\u05d8 \u05d9\u05d4\u05dc\u05d5\u05dd, \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d5\u05e7\u05e9\u05d5\u05ea, HRB-1, \u05e2\u05dd \u05db\u05d3\u05d5\u05e8 \u05e7\u05d8\u05df, \u05dc\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e8\u05db\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."],[209.0,"\u05d1\u05e9\u05d9\u05d8\u05ea \u05d5\u05d9\u05e7\u05e8\u05e1 \u05dc\u05d5\u05d7\u05e6\u05d9\u05dd \u05e4\u05d9\u05e8\u05de\u05d9\u05d3\u05ea \u05d9\u05d4\u05dc\u05d5\u05dd \u05d5\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05dc\u05db\u05e1\u05d5\u05e0\u05d9\u05dd \u05e9\u05dc \u05d4\u05e9\u05e7\u05e2 \u05d1\u05de\u05d9\u05e7\u05e8\u05d5\u05e1\u05e7\u05d5\u05dd."],[215.0,"\u05e7\u05d8\u05e0\u05d9\u05dd \u05d4\u05d9\u05d0 \u05de\u05d0\u05e4\u05e9\u05e8\u05ea \u05dc\u05de\u05d3\u05d5\u05d3 \u05e9\u05db\u05d1\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea. \u05d4\u05e2\u05e8\u05da \u05e0\u05db\u05ea\u05d1 \u00abHV"],[225.0,"\u05db\u05de\u05d4 \u05db\u05dc\u05dc\u05d9\u05dd \u05de\u05e2\u05e9\u05d9\u05d9\u05dd."],[227.0,"\u05d5\u05dc\u05e1\u05d9 \u05d8\u05d1\u05dc\u05d0\u05d5\u05ea \u05d4\u05de\u05e8\u05d4 \u05e9\u05dc \u05ea\u05e7\u05df \u05db\u05de\u05d5 E140 \u05d5\u05d0 ASTM \u05d4\u05d8\u05d1\u05dc\u05d0\u05d5\u05ea \u05e0\u05db\u05d5\u05e0\u05d5\u05ea \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea, \u05d5\u05dc\u05d0 \u05dc\u05db\u05dc \u05d7\u05d5\u05de\u05e8."],[240.0,"\u05d4\u05de\u05ea\u05d9\u05d7\u05d4 \u05d1\u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc \u05d4\u05d5\u05d0 \u05d1\u05e2\u05e8\u05da \u05e4\u05d9 3.479 \u05de\u05e2\u05e8\u05da \u05d4\u05d1\u05e8\u05d9\u05e0\u05dc, \u05d5\u05dc\u05db\u05df \u05d1\u05d3\u05d9\u05e7\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05de\u05d5\u05d5\u05d3\u05d0\u05ea \u05de\u05d4\u05e8 \u05e9\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d4\u05e6\u05dc\u05d9\u05d7."],[255.0,"\u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05dc\u05e4\u05d7\u05d5\u05ea \u05e4\u05d9 \u05e2\u05e9\u05e8\u05d4 \u05de\u05e2\u05d5\u05de\u05e7 \u05d4\u05e9\u05e7\u05e2, \u05d0\u05d7\u05e8\u05ea \u05d4\u05e9\u05d5\u05dc\u05d7\u05df \u05e9\u05de\u05ea\u05d7\u05ea \u05de\u05e9\u05e4\u05d9\u05e2 \u05e2\u05dc \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4."],[267.0,"\u05d5\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d1\u05de\u05e8\u05d7\u05e7 \u05de\u05e1\u05e4\u05d9\u05e7 \u05de\u05d4\u05e9\u05e4\u05d4, \u05e2\u05dc \u05de\u05e9\u05d8\u05d7 \u05e0\u05e7\u05d9 \u05d5\u05d7\u05dc\u05e7."],[271.0,"\u05d5\u05e8\u05d1\u05d9\u05e2\u05d9\u05ea, \u05d1\u05d7\u05dc\u05e7 \u05e9\u05e2\u05d1\u05e8 \u05d4\u05e7\u05e9\u05d9\u05d9\u05ea \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7, \u05de\u05d3\u05d9\u05d3\u05d4 \u05e2\u05dc \u05d4\u05e4\u05e0\u05d9\u05dd \u05e0\u05d5\u05ea\u05e0\u05ea \u05e8\u05e7 \u05d0\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05e9\u05db\u05d1\u05d4."],[278.0,"\u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e7 \u05e9\u05dc\u05d4 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d1\u05d7\u05ea\u05da, \u05d1\u05e1\u05d3\u05e8\u05ea \u05de\u05d3\u05d9\u05d3\u05d5\u05ea \u05d5\u05d9\u05e7\u05e8\u05e1 \u05de\u05d4\u05e4\u05e0\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d4."],[285.0,"\u05de\u05d1\u05d7\u05df \u05d4\u05d4\u05dc\u05dd \u05d1\u05d5\u05d3\u05e7 \u05de\u05e9\u05d5\u05d4\u05d5 \u05e9\u05de\u05d1\u05d7\u05df \u05d4\u05de\u05ea\u05d9\u05d7\u05d4 \u05dc\u05d0 \u05e8\u05d5\u05d0\u05d4: \u05d0\u05d9\u05da \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05ea\u05e0\u05d4\u05d2 \u05d1\u05de\u05db\u05d4, \u05db\u05e9\u05d9\u05e9 \u05d1\u05d5 \u05d7\u05e8\u05d9\u05e5."],[292.0,"\u05e2\u05e9\u05e8\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05d1\u05d0\u05d5\u05e8\u05da 55 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05e2\u05dd \u05d7\u05e8\u05d9\u05e5 \u05d1\u05e6\u05d5\u05e8\u05ea \\ \u05d1\u05d0\u05de\u05e6\u05e2."],[302.0,"\u05de\u05d8\u05d5\u05d8\u05dc\u05ea \u05db\u05d1\u05d3\u05d4 \u05de\u05e9\u05d5\u05ea\u05d7\u05e8\u05e8\u05ea \u05de\u05d2\u05d5\u05d1\u05d4 \u05d9\u05d3\u05d5\u05e2 \u05d5\u05e9\u05d5\u05d1\u05e8\u05ea \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea."],[307.0,"\u05de\u05d4\u05d2\u05d5\u05d1\u05d4 \u05e9\u05d4\u05de\u05d8\u05d5\u05d8\u05dc\u05ea \u05de\u05d0\u05d1\u05d3\u05ea \u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05e9\u05d4\u05d3\u05d2\u05dd \u05e1\u05e4\u05d2, \u05d1\u05d2'\u05d0\u05d5\u05dc."],[313.0,"\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05ea\u05dc\u05d5\u05d9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4, \u05d5\u05dc\u05db\u05df \u05ea\u05de\u05d9\u05d3 \u05de\u05e6\u05d9\u05d9\u05e0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4."],[317.0,"\u05e0\u05e9\u05d0\u05e8\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05e2\u05d3 \u05d0\u05d6\u05d5\u05e8 \u05de\u05e1\u05d5\u05d9\u05dd, \u05d5\u05e9\u05dd \u05d4\u05d9\u05d0 \u05e6\u05d5\u05e0\u05d7\u05ea. \u05d6\u05d4 \u05d0\u05d6\u05d5\u05e8 \u05d4\u05de\u05e2\u05d1\u05e8 \u05de\u05d4\u05ea\u05e0\u05d4\u05d2\u05d5\u05ea \u05de\u05e9\u05d9\u05db\u05d4 \u05dc\u05e4\u05e8\u05d9\u05db\u05d4, \u05e9\u05d4\u05db\u05e8\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 1."],[331.0,"\u05d4\u05d4\u05d1\u05d3\u05dc \u05e8\u05d5\u05d0\u05d9\u05dd \u05d2\u05dd \u05d1\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d1\u05e8: \u05e9\u05d1\u05e8 \u05de\u05e9\u05d9\u05da \u05e2\u05de\u05d5\u05dd \u05d5\u05e1\u05d9\u05d1\u05d9, \u05e9\u05d1\u05e8 \u05e4\u05e8\u05d9\u05da \u05de\u05d1\u05e8\u05d9\u05e7 \u05d5\u05d2\u05d1\u05d9\u05e9\u05d9."],[339.0,"\u05d3\u05d5\u05d2\u05de\u05d4 \u05de\u05d5\u05db\u05e8\u05ea: \u05d1\u05e4\u05dc\u05d3\u05ea S355J2, \u05d4\u05d0\u05d5\u05ea J \u05d5\u05d4\u05e1\u05e4\u05e8\u05d4 2 \u05d0\u05d5\u05de\u05e8\u05d5\u05ea \u05e9\u05d4\u05d5\u05d1\u05d8\u05d7\u05d5 \u05dc\u05e4\u05d7\u05d5\u05ea 27 \u05d2'\u05d0\u05d5\u05dc \u05d1\u05de\u05d9\u05e0\u05d5\u05e1 20 \u05de\u05e2\u05dc\u05d5\u05ea."],[351.0,"\u05e2\u05db\u05e9\u05d9\u05d5 \u05dc\u05db\u05e9\u05dc \u05d4\u05e9\u05db\u05d9\u05d7 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05d7\u05dc\u05e7\u05d9 \u05de\u05db\u05d5\u05e0\u05d5\u05ea: \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."],[356.0,"\u05de\u05e1\u05ea\u05d5\u05d1\u05d1, \u05e7\u05e4\u05d9\u05e5 \u05d0\u05d5 \u05d1\u05d5\u05e8\u05d2 \u05d1\u05de\u05e0\u05d5\u05e2, \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05e9\u05d1\u05e8 \u05d1\u05de\u05d0\u05de\u05e5 \u05e0\u05de\u05d5\u05da \u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05d7\u05d5\u05d6\u05e7 \u05d4\u05db\u05e0\u05d9\u05e2\u05d4."],[366.0,"\u05de\u05ea\u05e7\u05d3\u05dd \u05de\u05e2\u05d8 \u05d1\u05db\u05dc \u05de\u05d7\u05d6\u05d5\u05e8 \u05e2\u05d5\u05de\u05e1, \u05d5\u05d1\u05e1\u05d5\u05e3 \u05d4\u05d7\u05ea\u05da \u05e9\u05e0\u05d5\u05ea\u05e8 \u05db\u05d1\u05e8 \u05dc\u05d0 \u05de\u05d7\u05d6\u05d9\u05e7, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05e0\u05e9\u05d1\u05e8."],[378.0,"\u05e9\u05de\u05ea\u05e8\u05d7\u05e7\u05d9\u05dd \u05de\u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05d4\u05ea\u05d7\u05dc\u05d4, \u05d5\u05d0\u05d6\u05d5\u05e8 \u05d0\u05d7\u05e8\u05d5\u05df \u05de\u05d7\u05d5\u05e1\u05e4\u05e1 \u05e9\u05dc \u05d4\u05e9\u05d1\u05e8 \u05d4\u05e1\u05d5\u05e4\u05d9."],[387.0,"\u05d1\u05de\u05d1\u05d7\u05df \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05e1\u05d5\u05e4\u05e8\u05d9\u05dd \u05db\u05de\u05d4 \u05de\u05d7\u05d6\u05d5\u05e8\u05d9\u05dd \u05de\u05d7\u05d6\u05d9\u05e7 \u05db\u05dc \u05d3\u05d2\u05dd \u05d1\u05db\u05dc \u05e2\u05d5\u05de\u05e1, \u05d5\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e2\u05e7\u05d5\u05de\u05ea \u05d0-5."],[395.0,"\u05d4\u05de\u05ea\u05d9\u05d7\u05d4 \u05d1\u05d3\u05d2\u05dd \u05de\u05dc\u05d5\u05d8\u05e2\u05d5, \u05d5\u05de\u05ea\u05d7\u05ea\u05d9\u05d5 \u05d4\u05d7\u05dc\u05e7 \u05de\u05d7\u05d6\u05d9\u05e7 \u05db\u05de\u05e2\u05d8 \u05d1\u05dc\u05d9 \u05e1\u05d5\u05e3."],[404.0,"\u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d0\u05d9\u05df \u05d2\u05d1\u05d5\u05dc \u05db\u05d6\u05d4, \u05d5\u05dc\u05db\u05df \u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05dc\u05e4\u05d9 \u05de\u05e1\u05e4\u05e8 \u05de\u05d7\u05d6\u05d5\u05e8\u05d9\u05dd \u05de\u05d5\u05d2\u05d3\u05e8."],[410.0,"\u05db\u05de\u05d5 \u05e4\u05d9\u05e0\u05d4 \u05d7\u05d3\u05d4, \u05d7\u05e8\u05d9\u05e5, \u05ea\u05d7\u05d9\u05dc\u05ea \u05d4\u05d1\u05e8\u05d2\u05d4, \u05d0\u05d5 \u05e1\u05d9\u05de\u05df \u05e2\u05de\u05d5\u05e7 \u05e9\u05dc \u05db\u05dc\u05d9."],[423.0,"shot peening \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea, \u05de\u05d0\u05e8\u05d9\u05db\u05d9\u05dd \u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u05d7\u05d9\u05d9 \u05d4\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."],[434.0,"\u05d4\u05de\u05d1\u05d7\u05df \u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05d4\u05d5\u05d0 \u05d6\u05d7\u05d9\u05dc\u05d4."],[436.0,"\u05de\u05de\u05e9\u05d9\u05db\u05d4 \u05dc\u05d4\u05ea\u05d0\u05e8\u05da \u05dc\u05d0\u05d8 \u05dc\u05d0\u05d5\u05e8\u05da \u05d6\u05de\u05df, \u05d2\u05dd \u05db\u05e9\u05d4\u05de\u05d0\u05de\u05e5 \u05e0\u05de\u05d5\u05da \u05de\u05d7\u05d5\u05d6\u05e7 \u05d4\u05db\u05e0\u05d9\u05e2\u05d4."],[446.0,"\u05d1\u05e1\u05d1\u05d9\u05d1\u05ea 400 \u05de\u05e2\u05dc\u05d5\u05ea \u05d5\u05de\u05e2\u05dc\u05d4, \u05d5\u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05db\u05d1\u05e8 \u05d1\u05db\u05de\u05d4 \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea \u05e4\u05d7\u05d5\u05ea, \u05d6\u05d4 \u05d4\u05d5\u05e4\u05da \u05dc\u05e9\u05d9\u05e7\u05d5\u05dc \u05ea\u05db\u05e0\u05d5\u05e0\u05d9."],[457.0,"\u05de\u05d0\u05d5\u05ea \u05d5\u05d0\u05dc\u05e4\u05d9 \u05e9\u05e2\u05d5\u05ea, \u05d5\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05ea \u05e7\u05e6\u05d1 \u05d4\u05d4\u05ea\u05d0\u05e8\u05db\u05d5\u05ea \u05d5\u05d0\u05ea \u05d4\u05d6\u05de\u05df \u05e2\u05d3 \u05d4\u05e9\u05d1\u05e8."],[467.0,"\u05e7\u05d9\u05d8\u05d5\u05e8 \u05d5\u05d1\u05d5\u05e8\u05d2\u05d9 \u05d0\u05d5\u05d2\u05e0\u05d9\u05dd \u05d7\u05de\u05d9\u05dd. \u05dc\u05e9\u05dd \u05d1\u05d3\u05d9\u05d5\u05e7 \u05de\u05ea\u05d0\u05d9\u05de\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d4\u05e0\u05d9\u05e7\u05dc, \u05e9\u05e0\u05db\u05d9\u05e8 \u05d1\u05e4\u05e8\u05e7 15."],[479.0,"\u05d0\u05d1\u05dc \u05d1\u05d3\u05d9\u05e7\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05de\u05d4\u05d9\u05e8\u05d4 \u05d1\u05e7\u05d1\u05dc\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05d3\u05e8\u05da \u05d4\u05d6\u05d5\u05dc\u05d4 \u05dc\u05d5\u05d5\u05d3\u05d0 \u05e9\u05e7\u05d9\u05d1\u05dc\u05ea\u05dd \u05d0\u05ea \u05de\u05d4 \u05e9\u05d4\u05d5\u05d6\u05de\u05df."],[488.0,"\u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05dc\u05e9\u05dd \u05db\u05da \u05de\u05e9\u05d8\u05d7 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d9\u05d9\u05e2\u05d5\u05d3\u05d9 \u05e9\u05dc\u05d0 \u05d9\u05e2\u05d1\u05d5\u05e8 \u05e2\u05d9\u05d1\u05d5\u05d3."],[497.0,"\u05d5\u05d1\u05d7\u05dc\u05e7 \u05e9\u05e2\u05d5\u05d1\u05d3 \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea, \u05d4\u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd \u05d5\u05d2\u05d9\u05de\u05d5\u05e8 \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e9\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05dd \u05dc\u05d0 \u05e7\u05d5\u05e1\u05de\u05d8\u05d9\u05e7\u05d4, \u05d4\u05dd \u05d7\u05dc\u05e7 \u05de\u05d4\u05d7\u05d5\u05d6\u05e7."],[505.0,"\u05d3\u05d5\u05e8\u05e9\u05e9\u05d5\u05d9\u05dd \u05d3\u05d2\u05de\u05d9\u05dd, \u05de\u05e2\u05d1\u05d3\u05d4 \u05d5\u05d6\u05de\u05df, \u05d5\u05d1\u05d3\u05d9\u05e7\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05e2\u05dc \u05db\u05dc \u05d7\u05dc\u05e7 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05d6\u05de\u05df \u05dc\u05db\u05dc\u05d9\u05d7\u05d9\u05d3\u05d4."],[517.0,"\u05d5\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05de\u05d1\u05d9\u05d0\u05d5\u05ea \u05d0\u05d9\u05ea\u05df \u05d2\u05d9\u05de\u05d5\u05e8 \u05e2\u05d3\u05d9\u05df \u05d9\u05d5\u05ea\u05d4 \u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd, \u05d4\u05ea\u05d6\u05ea \u05db\u05d3\u05d5\u05e8\u05d9\u05d5\u05ea \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e1\u05d3\u05e7\u05d9\u05dd."],[525.0,"\u05de\u05d4\u05d9\u05e8\u05d4, \u05d4\u05dc\u05dd \u05dc\u05de\u05db\u05d4 \u05d5\u05dc\u05e7\u05d5\u05e8, \u05d5\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05d5\u05d6\u05d7\u05d9\u05dc\u05d4 \u05dc\u05de\u05d4 \u05e9\u05e7\u05d5\u05e8\u05d4 \u05dc\u05d0\u05d5\u05e8\u05da \u05d6\u05de\u05df."],[536.0,"\u05e9\u05de\u05e1\u05d1\u05d9\u05e8\u05d4 \u05de\u05d0\u05d9\u05e4\u05d4 \u05de\u05d2\u05d9\u05e2\u05d5\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4: \u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d5\u05ea \u05d4\u05e4\u05d0\u05d6\u05d4."]]};
window.MH_TR["\u05e4\u05e8\u05e703_\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea_\u05d5\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d5\u05ea_\u05e4\u05d0\u05d6\u05d4"]={"t":"\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d5\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d5\u05ea \u05e4\u05d0\u05d6\u05d4","l":[[1.0,"\u05db\u05de\u05e2\u05d8 \u05d0\u05e3 \u05de\u05ea\u05db\u05ea \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4 \u05d0\u05d9\u05e0\u05d4 \u05d8\u05d4\u05d5\u05e8\u05d4."],[4.0,"\u05d0\u05d1\u05dc \u05d0\u05dd \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05d5 \u05e4\u05d7\u05d5\u05ea \u05de\u05d0\u05d7\u05d5\u05d6 \u05d0\u05d7\u05d3 \u05e9\u05dc \u05e4\u05d7\u05de\u05df, \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e4\u05dc\u05d3\u05d4, \u05e9\u05d7\u05d6\u05e7\u05d4 \u05de\u05de\u05e0\u05d5 \u05e4\u05d9 \u05db\u05de\u05d4."],[16.0,"\u05de\u05ea\u05db\u05ea \u05e9\u05de\u05e2\u05e8\u05d1\u05d1\u05d9\u05dd \u05d1\u05d4 \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9\u05dd \u05db\u05d3\u05d9 \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc\u05d4 \u05e0\u05e7\u05e8\u05d0\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea."],[22.0,"\u05d5\u05e0\u05dc\u05de\u05d3 \u05dc\u05e7\u05e8\u05d5\u05d0 \u05d0\u05ea \u05d4\u05de\u05e4\u05d4 \u05e9\u05de\u05e8\u05d0\u05d4 \u05d0\u05d9\u05d6\u05d4 \u05de\u05d1\u05e0\u05d4 \u05d9\u05d9\u05d5\u05d5\u05e6\u05e8 \u05d1\u05db\u05dc \u05d4\u05e8\u05db\u05d1 \u05d5\u05d1\u05db\u05dc \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4: \u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05ea \u05d4\u05e4\u05d0\u05d6\u05d4."],[34.0,"\u05db\u05e9\u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d9\u05e1\u05d5\u05d3 \u05dc\u05de\u05ea\u05db\u05ea, \u05d4\u05d3\u05e8\u05da \u05d4\u05e4\u05e9\u05d5\u05d5\u05d8\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e9\u05d1\u05d4 \u05d4\u05d5\u05d0 \u05e0\u05db\u05e0\u05e1 \u05d4\u05d9\u05d0 \u05ea\u05de\u05d9\u05e1\u05d4 \u05de\u05d5\u05e6\u05e7\u05d4. \u05d9\u05e9 \u05dc\u05d4 \u05e9\u05e0\u05d9 \u05e1\u05d5\u05d2\u05d9\u05dd."],[42.0,"\u05de\u05ea\u05db\u05ea \u05d1\u05e1\u05e8\u05d9\u05d2. \u05d6\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05db\u05e9\u05d4\u05d0\u05d8\u05d5\u05de\u05d9\u05dd \u05d3\u05d5\u05de\u05d9\u05dd \u05d1\u05d2\u05d5\u05d3\u05dc\u05dd, \u05dc\u05de\u05e9\u05dc \u05e0\u05d9\u05e7\u05dc \u05d1\u05e0\u05d7\u05d5\u05e9\u05ea, \u05d0\u05d5 \u05db\u05e8\u05d5\u05dd \u05d5\u05e0\u05d9\u05e7\u05dc \u05d1\u05d1\u05e8\u05d6\u05dc."],[54.0,"\u05e9\u05d1\u05d9\u05df \u05d0\u05d8\u05d5\u05de\u05d9 \u05d4\u05de\u05ea\u05db\u05ea. \u05db\u05da \u05e0\u05db\u05e0\u05e1\u05d9\u05dd \u05d4\u05e4\u05d7\u05de\u05df, \u05d4\u05d7\u05e0\u05e7\u05df \u05d5\u05d4\u05de\u05d9\u05de\u05df \u05dc\u05d1\u05e8\u05d6\u05dc."],[65.0,"\u05d1\u05e9\u05e0\u05d9 \u05d4\u05de\u05e7\u05e8\u05d9\u05dd \u05d4\u05d0\u05d8\u05d5\u05dd \u05d4\u05d6\u05e8 \u05de\u05e2\u05d5\u05d5\u05ea \u05d0\u05ea \u05d4\u05e1\u05e8\u05d9\u05d2 \u05e1\u05d1\u05d9\u05d1\u05d5. \u05d5\u05db\u05de\u05d5 \u05e9\u05dc\u05de\u05d3\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 1, \u05db\u05dc \u05e2\u05d9\u05d5\u05d5\u05ea \u05db\u05d6\u05d4 \u05de\u05e7\u05e9\u05d4 \u05e2\u05dc \u05d4\u05e0\u05e7\u05e2\u05d9\u05dd \u05dc\u05e0\u05d5\u05e2."],[74.0,"\u05d6\u05d5 \u05d4\u05e7\u05e9\u05d7\u05d4 \u05d1\u05ea\u05de\u05d9\u05e1\u05d4 \u05de\u05d5\u05e6\u05e7\u05d4, \u05d5\u05d4\u05d9\u05d0 \u05d4\u05e1\u05d9\u05d1\u05d4 \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05dc\u05db\u05da \u05e9\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d7\u05d6\u05e7\u05d4 \u05de\u05d4\u05de\u05ea\u05db\u05ea \u05d4\u05d8\u05d4\u05d5\u05e8\u05d4."],[82.0,"\u05d0\u05d1\u05dc \u05dc\u05db\u05dc \u05de\u05ea\u05db\u05ea \u05d9\u05e9 \u05d2\u05d1\u05d5\u05dc \u05dc\u05db\u05de\u05d4 \u05d0\u05d8\u05d5\u05de\u05d9\u05dd \u05d6\u05e8\u05d9\u05dd \u05d4\u05d9\u05d0 \u05de\u05e1\u05d5\u05d2\u05dc\u05ea \u05dc\u05d4\u05db\u05d9\u05dc \u05d1\u05ea\u05de\u05d9\u05e1\u05d4."],[87.0,"\u05d1\u05d1\u05e8\u05d6\u05dc \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8 \u05d4\u05d2\u05d1\u05d5\u05dc \u05d4\u05d6\u05d4 \u05d6\u05e2\u05d9\u05e8: \u05e4\u05d7\u05d5\u05ea \u05de\u05e9\u05dc\u05d5\u05e9 \u05de\u05d0\u05d9\u05d5\u05ea \u05d4\u05d0\u05d7\u05d5\u05d6 \u05e4\u05d7\u05de\u05df."],[93.0,"\u05d5\u05e1\u05e8\u05d9\u05d2 \u05de\u05e9\u05dc\u05d5: \u05ea\u05e8\u05db\u05d5\u05d1\u05ea \u05e9\u05dc \u05d1\u05e8\u05d6\u05dc \u05d5\u05e4\u05d7\u05de\u05df \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea \u05e6\u05de\u05e0\u05d8\u05d9\u05d8. \u05e6\u05de\u05e0\u05d8\u05d9\u05d8 \u05e7\u05e9\u05d5\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d5\u05e4\u05e8\u05d9\u05da \u05de\u05d0\u05d5\u05d3."],[106.0,"\u05d0\u05d6\u05d5\u05e8 \u05d1\u05d7\u05d5\u05de\u05e8 \u05e9\u05d9\u05e9 \u05d1\u05d5 \u05de\u05d1\u05e0\u05d4 \u05d0\u05d7\u05d9\u05d3 \u05d5\u05d4\u05e8\u05db\u05d1 \u05d0\u05d7\u05d9\u05d3 \u05e0\u05e7\u05e8\u05d0 \u05e4\u05d0\u05d6\u05d4."],[111.0,"\u05d1\u05e8\u05d5\u05d1 \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e4\u05d0\u05d6\u05d4 \u05d0\u05d7\u05ea, \u05d5\u05db\u05de\u05d5\u05ea \u05d4\u05e4\u05d0\u05d6\u05d5\u05ea, \u05d4\u05e6\u05d5\u05e8\u05d4 \u05e9\u05dc\u05d4\u05df \u05d5\u05d4\u05e4\u05d9\u05d6\u05d5\u05e8 \u05e9\u05dc\u05d4\u05df \u05d4\u05dd \u05e9\u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea."],[120.0,"\u05db\u05d3\u05d9 \u05dc\u05d3\u05e2\u05ea \u05d0\u05d9\u05dc\u05d5 \u05e4\u05d0\u05d6\u05d5\u05ea \u05d9\u05d9\u05d5\u05d5\u05e6\u05e8\u05d5, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05ea \u05e4\u05d0\u05d6\u05d4. \u05d1\u05e6\u05d9\u05e8 \u05d4\u05d0\u05d5\u05e4\u05e7\u05d9 \u05d4\u05d4\u05e8\u05db\u05d1, \u05d5\u05d1\u05e6\u05d9\u05e8 \u05d4\u05d0\u05e0\u05db\u05d9 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4."],[129.0,"\u05db\u05dc \u05d0\u05d6\u05d5\u05e8 \u05d1\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d4 \u05de\u05e8\u05d0\u05d4 \u05d0\u05d9\u05dc\u05d5 \u05e4\u05d0\u05d6\u05d5\u05ea \u05d9\u05e6\u05d9\u05d1\u05d5\u05ea \u05d1\u05d4\u05e8\u05db\u05d1 \u05d5\u05d1\u05e0\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05d0\u05dc\u05d4, \u05db\u05e9\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05de\u05e1\u05e4\u05d9\u05e7."],[137.0,"\u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05d3\u05d5\u05d2\u05de\u05d4 \u05d4\u05e4\u05e9\u05d5\u05d8\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8: \u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05e0\u05d9\u05e7\u05dc, \u05e9\u05de\u05ea\u05de\u05d5\u05e1\u05e1\u05d9\u05dd \u05d6\u05d4 \u05d1\u05d6\u05d4 \u05d1\u05db\u05dc \u05d9\u05d7\u05e1."],[143.0,"\u05dc\u05de\u05e2\u05dc\u05d4 \u05d4\u05db\u05dc \u05e0\u05d5\u05d6\u05dc, \u05d5\u05dc\u05de\u05d8\u05d4 \u05d4\u05db\u05dc \u05df. \u05de\u05d5\u05e6\u05e7. \u05d1\u05d9\u05df \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 | \u05d4\u05e7\u05d5\u05d5\u05d9\u05dd \u05d9\u05e9 \u05d0\u05d6\u05d5\u05e8 \u05e9\u05d1\u05d5 \u05e0\u05d5\u05d6\u05dc \u05d5\u05de\u05d5\u05e6\u05e7 \u05e7\u05d9\u05d9\u05de\u05d9\u05dd \u05d9\u05d7\u05d3."],[152.0,"\u05dc\u05d4\u05ea\u05de\u05e6\u05e7 \u05dc\u05e9\u05d4\u05d9\u05d0 \u05d7\u05d5\u05e6\u05d4 \u05d0\u05ea \u05d4\u05e7\u05d5 \u05d4\u05e2\u05dc\u05d9\u05d5\u05df, \u05d5\u05de\u05e1\u05d9\u05d9\u05de\u05ea \u05e8\u05e7 \u05db\u05e9\u05d4\u05d9\u05d0 \u05d7\u05d5\u05e6\u05d4 \u05d0\u05ea \u05d4\u05e7\u05d5 \u05d4\u05ea\u05d7\u05ea\u05d5\u05df."],[161.0,"\u05db\u05dc\u05d5\u05de\u05e8, \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05dc\u05d0 \u05de\u05ea\u05de\u05e6\u05e7\u05ea \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d0\u05d7\u05ea, \u05db\u05de\u05d5 \u05de\u05ea\u05db\u05ea \u05d8\u05d4\u05d5\u05e8\u05d4, \u05d0\u05dc\u05d0 \u05d1\u05d8\u05d5\u05d5\u05d7 \u05e9\u05dc \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea."],[169.0,"\u05d1\u05d4\u05e8\u05d1\u05d4 \u05d6\u05d5\u05d2\u05d5\u05ea \u05e9\u05dc \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d4 \u05e0\u05e8\u05d0\u05d9\u05ea \u05d0\u05d7\u05e8\u05ea. \u05e0\u05e1\u05ea\u05db\u05dc \u05e2\u05dc \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df."],[176.0,"\u05d9\u05d5\u05e8\u05d3\u05ea, \u05e2\u05d3 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d0\u05d7\u05ea \u05e9\u05d1\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05e0\u05de\u05d5\u05db\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8: 12.6 \u05d0\u05d7\u05d5\u05d6 \u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df, \u05d5-577 \u05de\u05e2\u05dc\u05d5\u05ea."],[188.0,"\u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05de\u05ea\u05de\u05e6\u05e7\u05ea \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d0\u05d7\u05ea, \u05db\u05de\u05d5 \u05de\u05ea\u05db\u05ea \u05d8\u05d4\u05d5\u05e8\u05d4, \u05d4\u05d5\u05e8\u05de\u05ea \u05d8\u05d5\u05d1 \u05de\u05d0\u05d5\u05d3."],[199.0,"\u05dc\u05db\u05df \u05e8\u05d5\u05d1 \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d4\u05d9\u05e6\u05d9\u05e7\u05d4 \u05e9\u05dc \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05e0\u05de\u05e6\u05d0\u05d5\u05ea \u05d1\u05e1\u05d1\u05d9\u05d1\u05ea\u05d4."],[204.0,"\u05d5\u05d0\u05d5\u05ea\u05d5 \u05e8\u05e2\u05d9\u05d5\u05df \u05e2\u05d5\u05de\u05d3 \u05de\u05d0\u05d7\u05d5\u05e8\u05d9 \u05d7\u05d5\u05de\u05e8\u05d9 \u05d4\u05dc\u05d7\u05de\u05d4 \u05e8\u05db\u05d4, \u05e9\u05e0\u05d1\u05d7\u05e8\u05d5 \u05d1\u05d4\u05e8\u05db\u05d1 \u05e9\u05e0\u05de\u05e1 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05e0\u05de\u05d5\u05db\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8."],[211.0,"\u05d5\u05e2\u05db\u05e9\u05d9\u05d5 \u05dc\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d4 \u05d4\u05d7\u05e9\u05d5\u05d5\u05d1\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05e7\u05d5\u05e8\u05e1: \u05d1\u05e8\u05d6\u05dc \u05e4\u05d7\u05de\u05df. \u05d1\u05e6\u05d9\u05e8 \u05d4\u05d0\u05d5\u05e4\u05e7\u05d9\u05d0\u05d7\u05d7 \u05d4\u05e4\u05d7\u05de\u05df, \u05d5\u05d1\u05e6\u05d9\u05e8 \u05d4\u05d0\u05e0\u05db\u05d9 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4."],[222.0,"\u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d4\u05d1\u05e8\u05d6\u05dc \u05d1\u05de\u05d1\u05e0\u05d4 FCC \u05e9\u05d4\u05db\u05e8\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 1, \u05e9\u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05db\u05d9\u05dc \u05e2\u05d3 2.1 \u05d0\u05d7\u05d5\u05d6 \u05e4\u05d7\u05de\u05df."],[235.0,"\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d5\u05ea \u05e0\u05de\u05e6\u05d0 \u05d4\u05e4\u05e8\u05d9\u05d8, \u05d4\u05d1\u05e8\u05d6\u05dc \u05d1\u05de\u05d1\u05e0\u05d4 806, \u05e9\u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05db\u05d9\u05dc \u05e4\u05d7\u05de\u05df, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05e8\u05da \u05d5\u05de\u05e9\u05d9\u05da."],[244.0,"\u05e7\u05d5 \u05d0\u05d5\u05e4\u05e7\u05d9 \u05d7\u05e9\u05d5\u05d1 \u05e2\u05d5\u05d1\u05e8 \u05d1-727 \u05de\u05e2\u05dc\u05d5\u05ea: \u05de\u05ea\u05d7\u05ea\u05d9\u05d5 \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05db\u05d1\u05e8 \u05dc\u05d0 \u05d9\u05e6\u05d9\u05d1."],[251.0,"\u05d5\u05d1\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d0\u05d7\u05ea \u05e2\u05dc \u05d4\u05e7\u05d5 \u05d4\u05d6\u05d4, 0.77 \u05d0\u05d7\u05d5\u05d6 \u05e4\u05d7\u05de\u05df, \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05d5\u05e4\u05da \u05db\u05d5\u05dc\u05d5 \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea \u05dc\u05de\u05d1\u05e0\u05d4 \u05d7\u05d3\u05e2\u05d5."],[260.0,"\u05d5\u05dc\u05d1\u05e1\u05d5\u05e3, \u05d4\u05d2\u05d1\u05d5\u05dc \u05e9\u05dc 2.1 \u05d0\u05d7\u05d5\u05d6 \u05e4\u05d7\u05de\u05df \u05de\u05d7\u05dc\u05e7 \u05d0\u05ea \u05d4\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d4 \u05dc\u05e9\u05e0\u05d9\u05d9\u05dd: \u05de\u05e9\u05de\u05d0\u05dc \u05d4\u05e4\u05dc\u05d3\u05d5\u05ea, \u05d5\u05de\u05d9\u05de\u05d9\u05df \u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d9\u05e6\u05d5\u05e7."],[270.0,"\u05e8\u05d5\u05d1 \u05d4\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05d4\u05e0\u05d3\u05e1\u05d9\u05d5\u05ea \u05e0\u05de\u05e6\u05d0\u05d5\u05ea \u05d1\u05e4\u05d9\u05e0\u05d4 \u05e7\u05d8\u05e0\u05d4 \u05d1\u05e6\u05d3 \u05e9\u05de\u05d0\u05dc, \u05d1\u05d9\u05df \u05d0\u05e4\u05e1 \u05dc\u05d0\u05d7\u05d5\u05d6 \u05d0\u05d7\u05d3 \u05e9\u05dc \u05e4\u05d7\u05de\u05df."],[277.0,"\u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05db\u05e9\u05e4\u05dc\u05d3\u05d4 \u05de\u05ea\u05e7\u05e8\u05e8\u05ea \u05dc\u05d0\u05d8 \u05de\u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8?"],[281.0,"\u05d1-0.77 \u05d0\u05d7\u05d5\u05d6 \u05e4\u05d7\u05de\u05df, \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05de\u05ea\u05e4\u05e8\u05e7 \u05dc\u05e9\u05db\u05d1\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05e9\u05de\u05ea\u05d7\u05dc\u05e4\u05d5\u05ea \u05d6\u05d5 \u05d1\u05d6\u05d5: \u05e4\u05e8\u05d9\u05d8 \u05e8\u05da \u05d5\u05e6\u05de\u05e0\u05d8\u05d9\u05d8 \u05e7\u05e9\u05d4."],[290.0,"\u05d4\u05de\u05d1\u05e0\u05d4 \u05d4\u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 \u05e4\u05e8\u05dc\u05d9\u05d8, \u05db\u05d9 \u05d1\u05de\u05d9\u05e7\u05e8\u05d5\u05e1\u05e7\u05d5\u05e4 \u05d4\u05d5\u05d0 \u05de\u05d1\u05e8\u05d9\u05e7 \u05db\u05de\u05d5 \u05d0\u05dd \u05d4\u05e4\u05e0\u05d9\u05e0\u05d4."],[295.0,"\u05d7\u05dc\u05e7 \u05de\u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05d5\u05e4\u05da \u05e7\u05d5\u05d3\u05dd \u05dc\u05e4\u05e8\u05d9\u05d8, \u05d5\u05e8\u05e7 \u05d4\u05e9\u05d0\u05e8 \u05d4\u05d5\u05e4\u05da \u05dc\u05e4\u05e8\u05dc\u05d9\u05d8."],[306.0,"\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05d4\u05d9\u05d0 \u05ea\u05e2\u05e8\u05d5\u05d1\u05ea: \u05d1\u05e2\u05e8\u05da \u05de\u05d7\u05e6\u05d9\u05ea \u05e4\u05e8\u05d9\u05d8 \u05d5\u05de\u05d7\u05e6\u05d9\u05ea \u05e4\u05e8\u05dc\u05d9\u05d8."],[311.0,"\u05db\u05db\u05dc \u05e9\u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d7\u05de\u05df, \u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05e4\u05e8\u05dc\u05d9\u05d8, \u05d5\u05d4\u05e4\u05dc\u05d3\u05d4 \u05d7\u05d6\u05e7\u05d4 \u05d5\u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05e4\u05d7\u05d5\u05ea \u05de\u05e9\u05d9\u05db\u05d4."],[318.0,"\u05d5\u05d7\u05dc\u05e7 \u05de\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05db\u05dc\u05d9\u05dd, \u05d4\u05e4\u05d7\u05de\u05df \u05d4\u05e2\u05d5\u05d3\u05e3 \u05d9\u05d5\u05e6\u05e8 \u05e6\u05de\u05e0\u05d8\u05d9\u05d8 \u05d1\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd."],[330.0,"\u05d0\u05d1\u05dc \u05de\u05d4 \u05d0\u05dd \u05dc\u05d0 \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05dc\u05e4\u05dc\u05d3\u05d4 \u05d6\u05de\u05df?"],[332.0,"\u05d1\u05d8\u05d1\u05d9\u05dc\u05d4 \u05d1\u05de\u05d9\u05dd \u05d0\u05d5 \u05d1\u05e9\u05de\u05df, \u05dc\u05e4\u05d7\u05de\u05df \u05d0\u05d9\u05df \u05d6\u05de\u05df \u05dc\u05e6\u05d0\u05ea \u05de\u05d4\u05e1\u05e8\u05d9\u05d2 \u05d5\u05dc\u05d9\u05e6\u05d5\u05e8 \u05e6\u05de\u05e0\u05d8\u05d9\u05d8."],[342.0,"\u05d5\u05de\u05ea\u05d5\u05d7. \u05d4\u05de\u05d1\u05e0\u05d4 \u05d4\u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05d5\u05d4\u05d5\u05d0 \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d5\u05e4\u05e8\u05d9\u05da \u05de\u05d0\u05d5\u05d3."],[352.0,"\u05d4\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d4 \u05de\u05ea\u05d0\u05e8\u05ea \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05d5\u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05e0\u05d5\u05e6\u05e8 \u05d3\u05d5\u05d5\u05e7\u05d0 \u05db\u05e9\u05d0\u05d9\u05df\u05d6\u05de\u05df."],[361.0,"\u05e4\u05d7\u05de\u05df \u05d4\u05d9\u05d0 \u05e2\u05d5\u05dc\u05d4, \u05e2\u05d3 \u05d1\u05e2\u05e8\u05da 0.6 \u05d0\u05d7\u05d5\u05d6, \u05d5\u05de\u05e9\u05dd \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4."],[375.0,"\u05d0\u05d7\u05d5\u05d6 \u05e4\u05d7\u05de\u05df \u05de\u05d5\u05e7\u05e9\u05d9\u05ea \u05d4\u05d9\u05d8\u05d1, \u05d5\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd 0.2 \u05d0\u05d7\u05d5\u05d6 \u05db\u05de\u05e2\u05d8 \u05dc\u05d0."],[387.0,"\u05de\u05d4 \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4? \u05d0\u05d7\u05d5\u05d6 \u05d4\u05e4\u05d7\u05de\u05df \u05d4\u05d5\u05d0 \u05d4\u05e0\u05ea\u05d5\u05df \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05e9\u05de\u05e1\u05e4\u05e8 \u05de\u05d4 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05e9\u05d5\u05ea \u05e2\u05dd \u05e4\u05dc\u05d3\u05d4."],[394.0,"\u05e6\u05e8\u05d9\u05da \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05e7\u05e9\u05d5\u05d9\u05dd, \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05dc\u05d4\u05e7\u05e9\u05d5\u05d9\u05d9\u05ea \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7, \u05e9\u05e0\u05db\u05d9\u05e8 \u05d1\u05e4\u05e8\u05e7 7."],[404.0,"\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05de\u05e2\u05dc \u05d4\u05e7\u05d5 \u05e9\u05d1\u05d5 \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d4\u05d5\u05e4\u05db\u05ea \u05db\u05d5\u05dc\u05d4 \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d5\u05e9\u05dd \u05de\u05ea\u05d7\u05d9\u05dc \u05db\u05dc \u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05e7\u05e9\u05d9\u05d4."],[414.0,"\u05d5\u05d1\u05e8\u05d9\u05ea\u05d5\u05da, \u05db\u05db\u05dc \u05e9\u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d7\u05de\u05df, \u05d4\u05d0\u05d6\u05d5\u05e8 \u05e9\u05dc\u05d9\u05d3 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05ea\u05e7\u05e8\u05e8 \u05de\u05d4\u05e8 \u05d5\u05dc\u05d4\u05e4\u05d5\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05e4\u05e8\u05d9\u05da, \u05d5\u05dc\u05d4\u05d9\u05e1\u05d3\u05e7."],[423.0,"\u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05d4\u05d1\u05e8\u05d6\u05dc. \u05d3\u05e8\u05d9\u05e9\u05d4 \u05dc\u05d4\u05e8\u05db\u05d1 \u05db\u05d9\u05de\u05d9 \u05d1\u05d8\u05d5\u05d5\u05d7 \u05e6\u05e8 \u05de\u05d2\u05d1\u05d9\u05dc\u05d4 \u05d0\u05ea \u05d4\u05e1\u05e4\u05e7\u05d9\u05dd \u05d5\u05d0\u05ea \u05d4\u05de\u05e0\u05d5\u05ea."],[435.0,"\u05d5\u05db\u05dc \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05e9\u05de\u05e0\u05e6\u05dc \u05d0\u05ea \u05d4\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d4 \u05de\u05d5\u05e1\u05d9\u05e3 \u05e9\u05dc\u05d1, \u05d6\u05de\u05df \u05d5\u05d1\u05d3\u05d9\u05e7\u05d4."],[440.0,"\u05de\u05d5\u05e6\u05e7\u05d4 \u05d5\u05e4\u05d0\u05d6\u05d5\u05ea \u05e0\u05d5\u05e1\u05e4\u05d5\u05ea. \u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05ea \u05d4\u05e4\u05d0\u05d6\u05d4 \u05de\u05e8\u05d0\u05d4 \u05de\u05d4 \u05d9\u05d9\u05d5\u05d5\u05e6\u05e8 \u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9."],[451.0,"\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05e4\u05dc\u05d3\u05d4 \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05e4\u05e8\u05d9\u05d8 \u05d5\u05dc\u05e4\u05e8\u05dc\u05d9\u05d8, \u05d5\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8."],[458.0,"\u05e7\u05e8, \u05d2\u05e8\u05e2\u05d9\u05df \u05e2\u05d3\u05d9\u05df, \u05d4\u05e7\u05e9\u05d7\u05ea \u05de\u05e9\u05e7\u05e2 \u05d5\u05d8\u05e8\u05e0\u05e1\u05e4\u05d5\u05e8\u05de\u05e6\u05d9\u05d4 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8\u05d9\u05ea."]]};
window.MH_TR["\u05e4\u05e8\u05e704_\u05de\u05e0\u05d2\u05e0\u05d5\u05e0\u05d9_\u05d7\u05d9\u05d6\u05d5\u05e7"]={"t":"\u05de\u05e0\u05d2\u05e0\u05d5\u05e0\u05d9 \u05d7\u05d9\u05d6\u05d5\u05e7","l":[[1.0,"\u05d1\u05e4\u05e8\u05e7 1 \u05e8\u05d0\u05d9\u05e0\u05d5 \u05e9\u05de\u05ea\u05db\u05ea \u05de\u05ea\u05e2\u05d5\u05d5\u05ea\u05ea \u05db\u05e9\u05e0\u05e7\u05e2\u05d9\u05dd \u05e0\u05e2\u05d9\u05dd \u05d1\u05ea\u05d5\u05db\u05d4."],[6.0,"\u05de\u05db\u05d0\u05df \u05e0\u05d5\u05d1\u05e2 \u05e2\u05d9\u05e7\u05e8\u05d5\u05df \u05d0\u05d7\u05d3 \u05e9\u05de\u05e1\u05d1\u05d9\u05e8 \u05d0\u05ea \u05db\u05dc \u05d4\u05e9\u05d9\u05d8\u05d5\u05ea \u05dc\u05d7\u05d6\u05e7 \u05de\u05ea\u05db\u05ea: \u05dc\u05e9\u05d9\u05dd \u05de\u05db\u05e9\u05d5\u05dc\u05d9\u05dd \u05d1\u05d3\u05e8\u05db\u05dd \u05e9\u05dc \u05d4\u05e0\u05e7\u05e2\u05d9\u05dd."],[13.0,"\u05e9\u05de\u05e1\u05ea\u05d1\u05db\u05d9\u05dd \u05d6\u05d4 \u05d1\u05d6\u05d4. \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd. \u05d5\u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd \u05e9\u05dc \u05e4\u05d0\u05d6\u05d4 \u05e9\u05e0\u05d9\u05d9\u05d4."],[27.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05e2\u05dc \u05db\u05dc \u05d0\u05d7\u05d3 \u05de\u05d4\u05dd, \u05d5\u05e0\u05d1\u05d9\u05df \u05d2\u05dd \u05de\u05d4 \u05de\u05d1\u05d8\u05dc \u05d0\u05d5\u05ea\u05d5."],[33.0,"\u05d4\u05d3\u05e8\u05da \u05d4\u05e4\u05e2\u05d5\u05d5\u05d8\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05d7\u05d6\u05e7 \u05de\u05ea\u05db\u05ea \u05d4\u05d9\u05d0 \u05dc\u05e2\u05d5\u05d5\u05ea \u05d0\u05d5\u05ea\u05d4 \u05d1\u05e7\u05d5\u05e8."],[37.0,"\u05de\u05ea\u05e8\u05d1\u05d9\u05dd \u05d5\u05de\u05e1\u05ea\u05d1\u05db\u05d9\u05dd, \u05d5\u05d4\u05de\u05ea\u05db\u05ea \u05e0\u05e2\u05e9\u05d9\u05ea \u05d7\u05d6\u05e7\u05d4 \u05d5\u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8. \u05d6\u05d5 \u05d4\u05ea\u05e7\u05e9\u05d5\u05ea \u05de\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8."],[49.0,"\u05db\u05da \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05de\u05d5\u05d8\u05d5\u05ea \u05de\u05e9\u05d5\u05db\u05d9\u05dd \u05d1\u05e7\u05d5\u05e8, \u05e4\u05d7\u05d9 \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05e7\u05e9\u05d9\u05dd, \u05d5\u05e7\u05e4\u05d9\u05e6\u05d9\u05dd."],[54.0,"\u05d0\u05d1\u05dc \u05d9\u05e9 \u05dc\u05d6\u05d4 \u05de\u05d7\u05d9\u05e8: \u05db\u05db\u05dc \u05e9\u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e7\u05e8 \u05d2\u05d3\u05dc, \u05d4\u05de\u05e9\u05d9\u05db\u05d5\u05ea \u05d9\u05d5\u05e8\u05d3\u05ea."],[59.0,"\u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05d4\u05d0\u05d5\u05ea \u05d5\u05d7 \u05d1\u05e9\u05dd \u05d4\u05d8\u05de\u05e4\u05e8 \u05de\u05e1\u05de\u05e0\u05ea \u05d4\u05ea\u05e7\u05e2\u05d5\u05d5\u05ea \u05de\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8. H14 \u05d4\u05d5\u05d0 \u05d7\u05e6\u05d9 \u05e7\u05e9\u05d4, \u2026 \u05d4\u05d5\u05d0 \u05e7\u05e9\u05d4 \u05de\u05dc\u05d0."],[70.0,"\u05dc\u05d4\u05ea\u05e7\u05e9\u05d5\u05ea \u05de\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8 \u05d9\u05e9 \u05e9\u05e0\u05d9 \u05e6\u05d3\u05d3\u05d9\u05dd \u05e0\u05d5\u05e1\u05e4\u05d9\u05dd \u05e9\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d4\u05db\u05d9\u05e8."],[75.0,"\u05de\u05ea\u05d0\u05d9\u05de\u05d4, \u05de\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d7\u05d3\u05e9\u05d9\u05dd \u05d5\u05e8\u05db\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05d5\u05e6\u05e8 \u05d1\u05de\u05e7\u05d5\u05dd \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d4\u05de\u05e2\u05d5\u05d5\u05ea\u05d9\u05dd."],[86.0,"\u05d6\u05d5 \u05d4\u05ea\u05d2\u05d1\u05e9\u05d5\u05d5\u05ea \u05de\u05d7\u05d3\u05e2\u05d5, \u05d5\u05d4\u05de\u05ea\u05db\u05ea \u05d7\u05d5\u05d6\u05e8\u05ea \u05dc\u05de\u05e6\u05d1 \u05e8\u05da."],[90.0,"\u05db\u05e9\u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d7\u05d5\u05de\u05e8 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9, \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05de\u05e9\u05d5\u05ea\u05d7\u05e8\u05e8\u05d9\u05dd \u05d1\u05e6\u05d5\u05e8\u05d4 \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3\u05d4, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05ea\u05e2\u05e7\u05dd."],[101.0,"\u05dc\u05db\u05df \u05d7\u05dc\u05e7 \u05d0\u05e8\u05d5\u05da \u05d5\u05d3\u05e7 \u05e9\u05e2\u05d5\u05d1\u05d3 \u05de\u05de\u05d5\u05d8 \u05de\u05e9\u05d5\u05da \u05d1\u05e7\u05d5\u05e8 \u05e6\u05e8\u05d9\u05da \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d8\u05d9\u05e4\u05e1\u05d5\u05dc \u05dc\u05d4\u05e4\u05d2\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d0\u05d5 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d1\u05e9\u05dc\u05d1\u05d9\u05dd."],[111.0,"\u05d2\u05d1\u05d5\u05dc \u05d2\u05e8\u05e2\u05d9\u05df \u05e2\u05d5\u05e6\u05e8 \u05e0\u05e7\u05e2\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d2\u05e8\u05e2\u05d9\u05df \u05e2\u05d3\u05d9\u05df \u05d9\u05d5\u05ea\u05e8 \u05e0\u05d5\u05ea\u05df \u05d7\u05d5\u05d6\u05e7 \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8."],[121.0,"\u05d5\u05d1\u05e0\u05d9\u05d2\u05d5\u05d3 \u05dc\u05e9\u05d0\u05e8 \u05d4\u05d3\u05e8\u05db\u05d9\u05dd, \u05d4\u05d5\u05d0 \u05de\u05e9\u05e4\u05e8 \u05d2\u05dd \u05d0\u05ea \u05d4- toughness 5"],[125.0,"\u05d6\u05e2\u05d9\u05e8\u05d5\u05ea, \u05e9\u05dc \u05de\u05d0\u05d9\u05d5\u05ea \u05d4\u05d0\u05d7\u05d5\u05d6, \u05e9\u05dc \u05e0\u05d9\u05d5\u05d1\u05d9\u05d5\u05dd, \u05d5\u05e0\u05d3\u05d9\u05d5\u05dd \u05d0\u05d5 \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd, \u05d9\u05d7\u05d3 \u05e2\u05dd \u05d2\u05dc\u05d2\u05d5\u05dc \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05de\u05d1\u05d5\u05e7\u05e8\u05ea."],[137.0,"\u05db\u05da \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d1\u05e0\u05d4 \u05d7\u05d6\u05e7\u05d5\u05ea \u05e9\u05e2\u05d3\u05d9\u05d9\u05df \u05e0\u05d5\u05d7\u05d5\u05ea \u05dc\u05e8\u05d9\u05ea\u05d5\u05da."],[142.0,"\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d4\u05d7\u05d6\u05e7\u05d5\u05ea. \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d1\u05e0\u05d5\u05d9 \u05de\u05e9\u05dc\u05d5\u05e9\u05d4 \u05e9\u05dc\u05d1\u05d9\u05dd."],[150.0,"\u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05e9\u05d1\u05d4 \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05de\u05ea\u05de\u05d5\u05e1\u05e1\u05d9\u05dd \u05dc\u05d2\u05de\u05e8\u05d9 \u05d1\u05ea\u05d5\u05da \u05d4\u05de\u05ea\u05db\u05ea."],[160.0,"\u05d1\u05e9\u05dc\u05d1 \u05d4\u05e9\u05e0\u05d9 \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05de\u05d4\u05e8, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05de\u05d9\u05dd, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d9\u05d9\u05e9\u05d0\u05e8\u05d5 \u05db\u05dc\u05d5\u05d0\u05d9\u05dd \u05d1\u05ea\u05de\u05d9\u05e1\u05d4."],[167.0,"\u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05ea, \u05dc\u05db\u05de\u05d4 \u05e9\u05e2\u05d5\u05ea, \u05d5\u05de\u05e9\u05e7\u05e2\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05d5\u05e6\u05e8."],[175.0,"\u05d4\u05de\u05e9\u05e7\u05e2\u05d9\u05dd \u05d4\u05d6\u05e2\u05d9\u05e8\u05d9\u05dd \u05de\u05e4\u05d5\u05d6\u05e8\u05d9\u05dd \u05d1\u05ea\u05d5\u05da \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd, \u05d5\u05db\u05dc \u05d0\u05d7\u05d3 \u05de\u05d4\u05dd \u05d4\u05d5\u05d0 \u05de\u05d7\u05e1\u05d5\u05dd \u05dc\u05e0\u05e7\u05e2\u05d9\u05dd."],[181.0,"\u05d4\u05d7\u05d5\u05d6\u05e7 \u05e2\u05d5\u05dc\u05d4 \u05e2\u05dd \u05d6\u05de\u05df \u05d4\u05d4\u05d6\u05d3\u05e7\u05e0\u05d5\u05ea \u05e2\u05d3 \u05e9\u05d9\u05d0."],[185.0,"\u05d0\u05dd \u05de\u05de\u05e9\u05d9\u05db\u05d9\u05dd \u05dc\u05d7\u05de\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05d3\u05d9 \u05d6\u05de\u05df, \u05d4\u05de\u05e9\u05e7\u05e2\u05d9\u05dd \u05d2\u05d3\u05dc\u05d9\u05dd, \u05d5\u05d9\u05e9 \u05e4\u05d7\u05d5\u05ea \u05de\u05d4\u05dd, \u2026 \u05d9\u05d5\u05e8\u05d3. \u05d6\u05d5 \u05d4\u05d6\u05d3\u05e7\u05e0\u05d5\u05ea \u05d9\u05ea\u05e8."],[193.0,"\u05d4\u05d6\u05d3\u05e7\u05e0\u05d5\u05ea \u05de\u05dc\u05d0\u05db\u05d5\u05ea\u05d9\u05ea. 14 \u05d0\u05d5\u05de\u05e8 \u05d4\u05d6\u05d3\u05e7\u05e0\u05d5\u05ea \u05d8\u05d1\u05e2\u05d9\u05ea, \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8."],[204.0,"\u05dc\u05db\u05e0\u05d5\u05e2 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 55 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc. \u05d1\u05de\u05e6\u05d1 16 \u05d4\u05d5\u05d0 \u05de\u05d2\u05d9\u05e2 \u05dc-276."],[218.0,"\u05db\u05da \u05e2\u05d5\u05d1\u05d3\u05d5\u05ea \u05d2\u05dd \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d5\u05d4\u05e117-4, \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea 718 Inconel \u05d5\u05e4\u05dc\u05d3\u05d5\u05ea Maraging."],[226.0,"\u05d4\u05d3\u05e8\u05da \u05d4\u05e8\u05d1\u05d9\u05e2\u05d9\u05ea, \u05d5\u05d4\u05d7\u05d6\u05e7\u05d4 \u05de\u05db\u05d5\u05dc\u05df, \u05d4\u05d9\u05d0 \u05d8\u05e8\u05e0\u05e1\u05e4\u05d5\u05e8\u05de\u05e6\u05d9\u05d4 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8\u05d9\u05ea, \u05e9\u05d4\u05db\u05e8\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 3."],[232.0,"\u05d0\u05ea \u05d4\u05e1\u05e8\u05d9\u05d2 \u05db\u05dc \u05db\u05da, \u05e9\u05d4\u05e0\u05e7\u05e2\u05d9\u05dd \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d6\u05d5\u05d6. \u05db\u05da \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05dc\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc 2,000 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc \u05d5\u05d9\u05d5\u05ea\u05e8."],[244.0,"\u05d0\u05d5\u05ea\u05d5: \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e9\u05d5\u05d1 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05ea, \u05d5\u05de\u05d5\u05d5\u05ea\u05e8\u05d9\u05dd \u05e2\u05dc \u05d7\u05dc\u05e7 \u05de\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05ea\u05de\u05d5\u05e8\u05ea toughness"],[255.0,"\u05de\u05d5\u05e7\u05e9\u05d9\u05ea \u05d5\u05de\u05d5\u05e8\u05e4\u05d9\u05ea, \u05d1\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc \u05db-30 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc 6, \u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05d1\u05d3 \u05d0\u05d5\u05ea\u05d4 \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea."],[267.0,"\u05d5\u05e2\u05db\u05e9\u05d9\u05d5 \u05dc\u05e9\u05d0\u05dc\u05d4 \u05d4\u05de\u05e2\u05e9\u05d9\u05ea: \u05de\u05d4 \u05de\u05d1\u05d8\u05dc \u05db\u05dc \u05de\u05e0\u05d2\u05e0\u05d5\u05df?"],[271.0,"\u05e2\u05d9\u05d3\u05d5\u05df \u05d2\u05e8\u05e2\u05d9\u05df \u05e0\u05e4\u05d2\u05e2 \u05d1\u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05de\u05d5\u05e9\u05da \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05e9\u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd."],[282.0,"\u05d9\u05ea\u05e8, \u05d0\u05d5 \u05de\u05de\u05d9\u05e1 \u05d0\u05ea \u05d4\u05de\u05e9\u05e7\u05e2\u05d9\u05dd \u05de\u05d7\u05d3\u05e9. \u05dc\u05db\u05df \u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e9\u05dc 1, \u05d4\u05d0\u05d6\u05d5\u05e8 \u05e9\u05dc\u05d9\u05d3 \u05d4\u05ea\u05e4\u05e8 \u05de\u05d0\u05d1\u05d3 \u05d7\u05dc\u05e7 \u05d2\u05d3\u05d5\u05dc \u05de\u05d4\u05d7\u05d5\u05d6\u05e7."],[296.0,"\u05d5\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05de\u05ea\u05e8\u05db\u05dc\u05da \u05d1\u05db\u05dc \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e2\u05dc \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4 \u05e9\u05dc\u05d5."],[301.0,"\u05db\u05dc\u05d5\u05de\u05e8, \u05db\u05dc \u05d7\u05d9\u05de\u05d5\u05dd \u05e9\u05d4\u05d7\u05dc\u05e7 \u05e2\u05d5\u05d1\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05d9\u05db\u05d5\u05dc \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc\u05d5."],[307.0,"\u05e6\u05d9\u05e4\u05d5\u05d9 \u05d1\u05d7\u05d5\u05dd, \u05db\u05d3\u05d0\u05d9 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d0\u05d9\u05da \u05d4\u05d7\u05d5\u05de\u05e8 \u05e7\u05d9\u05d1\u05dc \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc\u05d5."],[316.0,"\u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05ea\u05e0\u05d5\u05e8\u05d9\u05dd \u05de\u05d1\u05d5\u05e7\u05e8\u05d9\u05dd \u05d5\u05d1\u05e7\u05e8\u05d4 \u05e6\u05de\u05d5\u05d3\u05d4 \u05e9\u05dc \u05d6\u05de\u05e0\u05d9\u05dd \u05d5\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea."],[326.0,"\u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05d7\u05d5\u05de\u05e8 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05de\u05d5."],[330.0,"\u05d1\u05d7\u05d5\u05dd, \u05d0\u05d1\u05dc \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05d1\u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8 \u05d5\u05d1\u05d2\u05d9\u05de\u05d5\u05e8 \u05d8\u05d5\u05d1 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05dc\u05db\u05df \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d7\u05d5\u05e1\u05db\u05d9\u05dd \u05e2\u05d9\u05d1\u05d5\u05d3."],[341.0,"\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d0\u05e8\u05d1\u05e2\u05d4 \u05de\u05e0\u05d2\u05e0\u05d5\u05e0\u05d9\u05dd, \u05d5\u05e2\u05d9\u05e7\u05e8\u05d5\u05df \u05d0\u05d7\u05d3, \u05dc\u05e2\u05e6\u05d5\u05e8 \u05e0\u05e7\u05e2\u05d9\u05dd."],[347.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05ea\u05d7\u05d9\u05dc \u05dc\u05e2\u05d1\u05d5\u05e8 \u05e2\u05dc \u05de\u05e9\u05e4\u05d7\u05d5\u05ea \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd, \u05e2\u05dd \u05d4\u05d7\u05e9\u05d5\u05d1\u05d4 \u05de\u05db\u05d5\u05dc\u05df: \u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05e4\u05d7\u05de\u05df."]]};
window.MH_TR["\u05e4\u05e8\u05e705_\u05e4\u05dc\u05d3\u05d5\u05ea_\u05e4\u05d7\u05de\u05df"]={"t":"\u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05d7\u05de\u05df","l":[[1.0,"\u05e4\u05d7\u05de\u05df, \u05d5\u05de\u05e2\u05d8 \u05de\u05e0\u05d2\u05df. \u05de\u05e0\u05d2\u05df \u05e7\u05d5\u05e9\u05e8 \u05d0\u05ea \u05d4\u05d2\u05d5\u05e4\u05e8\u05d9\u05ea \u05d5\u05de\u05e9\u05e4\u05e8 \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7."],[12.0,"\u05d1\u05e0\u05d5\u05e1\u05e3 \u05d9\u05e9 \u05d1\u05d4 \u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea \u05e9\u05dc \u05d6\u05e8\u05d7\u05df \u05d5\u05d2\u05d5\u05e4\u05e8\u05d9\u05ea, \u05e9\u05e0\u05e9\u05d0\u05e8\u05d5 \u05de\u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d5\u05de\u05d5\u05d2\u05d1\u05dc\u05d5\u05ea \u05d1\u05ea\u05e7\u05df."],[19.0,"\u05d0\u05d9\u05df \u05d1\u05d4 \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05de\u05db\u05d5\u05d5\u05e0\u05d9\u05dd \u05db\u05de\u05d5 \u05db\u05e8\u05d5\u05dd, \u05e0\u05d9\u05e7\u05dc \u05d0\u05d5 \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df."],[24.0,"\u05d1\u05d2\u05dc\u05dc \u05d6\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05d6\u05d5\u05dc\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d5\u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc\u05d4 \u05e0\u05e7\u05d1\u05e2\u05d5\u05ea \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05e4\u05d9 \u05db\u05de\u05d5\u05ea \u05d4\u05e4\u05d7\u05de\u05df \u05d5\u05dc\u05e4\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd."],[31.0,"\u05de\u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05ea \u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05e4\u05d7\u05de\u05df \u05dc\u05e9\u05dc\u05d5\u05e9 \u05de\u05e9\u05e4\u05d7\u05d5\u05ea, \u05dc\u05e4\u05d9 \u05d0\u05d7\u05d5\u05d6 \u05d4\u05e4\u05d7\u05de\u05df."],[36.0,"6 \u05d0\u05d7\u05d5\u05d6. \u05d5\u05e4\u05d7\u05de\u05df \u05d2\u05d1\u05d5\u05d4: \u05de\u05e2\u05dc 0.6 \u05d0\u05d7\u05d5\u05d6, \u05d5\u05e2\u05d3 \u05d1\u05e2\u05e8\u05da \u05d0\u05d7\u05d5\u05d6 \u05d0\u05d7\u05d3."],[51.0,"\u05d7\u05d6\u05e7\u05d4 \u05d5\u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05de\u05ea\u05e7\u05e9\u05d4 \u05d8\u05d5\u05d1 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05d4\u05e7\u05e9\u05d9\u05d4, \u05d0\u05d1\u05dc \u05d2\u05dd \u05e4\u05d7\u05d5\u05ea \u05de\u05e9\u05d9\u05db\u05d4 \u05d5\u05e4\u05d7\u05d5\u05ea \u05e8\u05ea\u05d9\u05db\u05d4."],[63.0,"\u05e4\u05dc\u05d3\u05d4 \u05d3\u05dc\u05ea \u05e4\u05d7\u05de\u05df, \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea \u05d2\u05dd \u05e4\u05dc\u05d3\u05d4 \u05e8\u05db\u05d4, \u05d4\u05d9\u05d0 \u05e1\u05d5\u05e1 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05e9\u05dc \u05d4\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4."],[69.0,"\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05e4\u05e9\u05d5\u05d8\u05d9\u05dd. \u05d3\u05d5\u05d2\u05de\u05d0\u05d5\u05ea \u05de\u05d5\u05db\u05e8\u05d5\u05ea \u05d4\u05df 1018 \u05d5-1020, \u05d5\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 5235 \u05d5-5355."],[84.0,"\u05d4\u05d9\u05d0 \u05e0\u05d5\u05d7\u05d4 \u05dc\u05e8\u05d9\u05ea\u05d5\u05da, \u05dc\u05db\u05d9\u05e4\u05d5\u05e3 \u05d5\u05dc\u05e2\u05d9\u05d1\u05d5\u05d3, \u05d0\u05d1\u05dc \u05d4\u05d9\u05d0 \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05ea\u05e7\u05e9\u05d4 \u05d1\u05d4\u05e7\u05e9\u05d9\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4."],[90.0,"\u05db\u05e9\u05e6\u05e8\u05d9\u05da \u05d1\u05d4 \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05e7\u05e9\u05d9\u05dd, \u05de\u05e7\u05e9\u05d9\u05dd \u05e8\u05e7 \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05db\u05de\u05d5 \u05e9\u05e0\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 7."],[96.0,"\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05e4\u05d7\u05de\u05df \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9 \u05d4\u05d9\u05d0 \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05dc\u05d7\u05dc\u05e7\u05d9 \u05de\u05db\u05d5\u05e0\u05d5\u05ea: \u05e6\u05d9\u05e8\u05d9\u05dd, \u05d2\u05dc\u05d9\u05dd, \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d5\u05d1\u05d5\u05e8\u05d2\u05d9 \u05e2\u05d9\u05d2\u05d5\u05df."],[104.0,"\u05d4\u05e0\u05e6\u05d9\u05d2\u05d4 \u05d4\u05d9\u05d3\u05d5\u05e2\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d9\u05d0 1045, \u05e9\u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05d9\u05e8\u05d5\u05e4\u05d9 \u05e0\u05e7\u05e8\u05d0\u05ea C45."],[112.0,"\u05d4\u05d7\u05dc\u05e7, \u05d0\u05d5 \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05e8\u05e7 \u05d0\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8 \u05e9\u05e0\u05e9\u05d7\u05e7, \u05dc\u05de\u05e9\u05dc \u05de\u05e9\u05d8\u05d7 \u05de\u05d9\u05e1\u05d1 \u05e2\u05dc \u05d2\u05dc."],[122.0,"\u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05ea\u05e7\u05e9\u05d5\u05ea \u05d5\u05dc\u05d4\u05d9\u05e1\u05d3\u05e7, \u05d5\u05dc\u05db\u05df \u05dc\u05e8\u05d5\u05d1 \u05e6\u05e8\u05d9\u05da \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05d5\u05e7\u05d3\u05dd."],[132.0,"\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05e4\u05d7\u05de\u05df \u05d2\u05d1\u05d5\u05d4, \u05db\u05de\u05d5 1060 \u05d5-1095, \u05de\u05e9\u05de\u05e9\u05d5\u05ea \u05dc\u05e7\u05e4\u05d9\u05e6\u05d9\u05dd, \u05dc\u05dc\u05d4\u05d1\u05d9\u05dd \u05d5\u05dc\u05ea\u05d9\u05dc \u05d7\u05d6\u05e7."],[140.0,"\u05d0\u05d7\u05e8\u05d9 \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d5\u05e2\u05de\u05d9\u05d3\u05d4 \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4."],[144.0,"\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d4\u05d9\u05d0 \u05e4\u05e8\u05d9\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d1\u05de\u05e6\u05d1 \u05de\u05d5\u05e7\u05e9\u05d4, \u05d5\u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4."],[151.0,"\u05e2\u05db\u05e9\u05d9\u05d5 \u05dc\u05e9\u05de\u05d5\u05ea. \u05d1\u05e9\u05d9\u05d8\u05d4 \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9\u05ea, \u05d5\u05e4\u05d5) SSAE-1 \u05dc\u05e4\u05dc\u05d3\u05d4\u05d9\u05e9 \u05de\u05e1\u05e4\u05e8 \u05e9\u05dc \u05d0\u05e8\u05d1\u05e2 \u05e1\u05e4\u05e8\u05d5\u05ea."],[159.0,"\u05d4\u05d9\u05d0 \u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05e8\u05d2\u05d9\u05dc\u05d4, 11 \u05d5-12 \u05d4\u05df \u05e4\u05dc\u05d3\u05d5\u05ea \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05dc, \u05e2\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05d2\u05d5\u05e4\u05e8\u05d9\u05ea."],[170.0,"\u05e9\u05ea\u05d9 \u05d4\u05e1\u05e4\u05e8\u05d5\u05ea \u05d4\u05d0\u05d7\u05e8\u05d5\u05e0\u05d5\u05ea \u05d4\u05df \u05d0\u05d7\u05d5\u05d6 \u05d4\u05e4\u05d7\u05de\u05df \u05d1\u05de\u05d0\u05d9\u05d5\u05ea. \u05dc\u05db\u05df 5 \u05d4\u05d9\u05d0 \u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05e8\u05d2\u05d9\u05dc\u05d4 \u05e2\u05dd 0.45 \u05d0\u05d7\u05d5\u05d6 \u05e4\u05d7\u05de\u05df."],[181.0,"\u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05d9\u05e8\u05d5\u05e4\u05d9, C45 \u05d4\u05d9\u05d0 \u05d0\u05d5\u05ea\u05d4 \u05e4\u05dc\u05d3\u05d4, \u05d5-6455 \u05d4\u05d9\u05d0 \u05d4\u05d2\u05e8\u05e1\u05d4 \u05e2\u05dd \u05d2\u05d5\u05e4\u05e8\u05d9\u05ea \u05de\u05d1\u05d5\u05e7\u05e8\u05ea, \u05e9\u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05d4\u05e7\u05e9\u05d9\u05d4."],[191.0,"\u05d1\u05e2\u05d1\u05e8, \u05dc\u05e4\u05d9 DIN, \u05e7\u05e8\u05d0\u05d5 \u05dc\u05d4 6%45. \u05d1\u05d9\u05e4\u05df \u05d4\u05d9\u05d0 \u05e0\u05e7\u05e8\u05d0\u05ea 5450."],[200.0,"\u05dc\u05db\u05dc \u05e4\u05dc\u05d3\u05d4 \u05d9\u05e9 \u05d2\u05dd \u05de\u05e1\u05e4\u05e8 \u05d7\u05d5\u05de\u05e8 \u05d0\u05d9\u05e8\u05d5\u05e4\u05d9, \u05dc-645 \u05d4\u05d5\u05d0 3."],[208.0,"\u05e4\u05d9\u05e8\u05d5\u05e9\u05d4 \u05e4\u05dc\u05d3\u05ea \u05de\u05d1\u05e0\u05d4, 355 \u05d4\u05d5\u05d0 \u05d7\u05d5\u05d6\u05e7 \u05d4\u05db\u05e0\u05d9\u05e2\u05d4 \u05d4\u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9 \u05d1\u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc, \u05d5-42 \u05d4\u05d9\u05d0 \u05d3\u05e8\u05d9\u05e9\u05ea \u05d4\u05d4\u05dc\u05dd \u05e9\u05d4\u05db\u05e8\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 2."],[226.0,"\u05d1\u05e9\u05de\u05d5\u05ea \u05d4\u05d9\u05e9\u05e0\u05d9\u05dd, \u05dc\u05e4\u05d9 \u05d0\u05d5\u05e1, \u05e7\u05e8\u05d0\u05d5 \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 5137 \u05d5- 2, \u05d5\u05d0\u05ea \u05d4\u05e9\u05de\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05e2\u05d3\u05d9\u05d9\u05df \u05e9\u05d5\u05de\u05e2\u05d9\u05dd \u05d1\u05e9\u05d8\u05d7."],[237.0,"\u05de\u05d4\u05d9\u05e8, \u05db\u05de\u05d5 12114 \u05d5-1215. \u05d4\u05df \u05de\u05db\u05d9\u05dc\u05d5\u05ea \u05ea\u05d5\u05e1\u05e4\u05ea \u05d2\u05d5\u05e4\u05e8\u05d9\u05ea, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e2\u05d5\u05e4\u05e8\u05ea."],[249.0,"\u05d0\u05ea \u05d4\u05d7\u05d9\u05db\u05d5\u05da, \u05d5\u05db\u05da \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05ea\u05d5\u05da \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05e9\u05d7\u05d9\u05e7\u05ea \u05db\u05dc\u05d9\u05dd \u05d5\u05d2\u05d9\u05de\u05d5\u05e8 \u05d8\u05d5\u05d1."],[259.0,"\u05d4\u05df; \u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05de\u05d0\u05d5\u05d3 \u05d1\u05de\u05d7\u05e8\u05d8\u05d5\u05ea \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9\u05d5\u05ea."],[262.0,"\u05d5\u05dc\u05db\u05df \u05d4\u05df \u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d5\u05ea \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e2\u05d5\u05de\u05d3\u05d9\u05dd \u05d1\u05e2\u05d5\u05de\u05e1 \u05db\u05d1\u05d3. \u05e0\u05e8\u05d7\u05d9\u05d1 \u05e2\u05dc \u05db\u05da \u05d1\u05e4\u05e8\u05e7 19."],[272.0,"\u05de\u05d4 \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4? \u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05de\u05d7\u05dc\u05d9\u05d3\u05d4, \u05d5\u05dc\u05db\u05df \u05db\u05de\u05e2\u05d8 \u05ea\u05de\u05d9\u05d3 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4 \u05e6\u05d9\u05e4\u05d5\u05d9 \u05d0\u05d5 \u05e6\u05d1\u05e2."],[280.0,"\u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05d2\u05d9\u05e2 \u05de\u05d2\u05d5\u05dc\u05d2\u05dc \u05d1\u05d7\u05d5\u05dd, \u05e2\u05dd \u05e9\u05db\u05d1\u05ea \u05ea\u05d7\u05de\u05d5\u05e6\u05ea, \u05d0\u05d5 \u05de\u05e9\u05d5\u05da \u05d1\u05e7\u05d5\u05d4 \u05d1\u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea."],[287.0,"\u05e9\u05de\u05d5\u05e1\u05d9\u05e3 \u05e2\u05dc\u05d5\u05ea \u05d4\u05d5\u05d0 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05d3\u05e8\u05d9\u05e9\u05ea \u05d4\u05dc\u05dd \u05d1\u05e7\u05d5\u05e8 \u05e2\u05dd \u05ea\u05e2\u05d5\u05d3\u05d4, \u05d5\u05d7\u05d5\u05de\u05e8 \u05de\u05e9\u05d5\u05da \u05d1\u05e7\u05d5\u05e8 \u05d0\u05d5 \u05de\u05d5\u05e9\u05d7\u05d6 \u05d1\u05de\u05d9\u05d3\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea."],[301.0,"\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d3\u05d5\u05d5\u05e7\u05d0 \u05e4\u05dc\u05d3\u05d4 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05dc, \u05d9\u05e7\u05e8\u05d4 \u05de\u05e2\u05d8 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05e7\u05d9\u05dc\u05d5, \u05d4\u05d9\u05d0 \u05e9\u05d7\u05d5\u05e1\u05db\u05ea \u05d4\u05db\u05d9 \u05d4\u05e8\u05d1\u05d4 \u05d1\u05d6\u05de\u05df \u05de\u05db\u05d5\u05e0\u05d4."],[308.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05dc\u05de\u05d3 \u05d0\u05ea \u05d8\u05d9\u05e4\u05d5\u05dc\u05d9 \u05d4\u05d7\u05d5\u05dd \u05e9\u05dc \u05d4\u05e4\u05dc\u05d3\u05d4: \u05dc\u05d9\u05d1\u05d5\u05df, \u05e0\u05e8\u05de\u05d5\u05dc, \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4."]]};
window.MH_TR["\u05e4\u05e8\u05e706_\u05d8\u05d9\u05e4\u05d5\u05dc\u05d9_\u05d7\u05d5\u05dd_\u05d1\u05e4\u05dc\u05d3\u05d4"]={"t":"\u05d8\u05d9\u05e4\u05d5\u05dc\u05d9 \u05d7\u05d5\u05dd \u05d1\u05e4\u05dc\u05d3\u05d4","l":[[1.0,"\u05e9\u05d1\u05d4 \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4. \u05e2\u05dc \u05d6\u05d4 \u05d1\u05e0\u05d5\u05d9\u05d9\u05dd \u05d8\u05d9\u05e4\u05d5\u05dc\u05d9 \u05d4\u05d7\u05d5\u05dd."],[10.0,"\u05d0\u05e8\u05d1\u05e2\u05ea \u05d8\u05d9\u05e4\u05d5\u05dc\u05d9 \u05d4\u05d7\u05d5\u05dd \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9\u05d9\u05dd \u05e9\u05dc \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d4\u05dd \u05e8\u05d9\u05db\u05d5\u05da, \u05e0\u05e8\u05de\u05d5\u05dc, \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4."],[17.0,"\u05d4\u05d7\u05d6\u05e7\u05d4 \u05d1\u05d4, \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05e7\u05e6\u05d1 \u05de\u05e1\u05d5\u05d9\u05dd. \u05d5\u05d4\u05d4\u05d1\u05d3\u05dc \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd \u05d4\u05d5\u05d0 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05e7\u05e6\u05d1 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8."],[28.0,"\u05d4\u05e7\u05d5 \u05e9\u05d1\u05d5 \u05d4\u05d9\u05d0 \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd, \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05dc\u05d0\u05d8 \u05de\u05d0\u05d5\u05d3, \u05d1\u05ea\u05d5\u05da \u05d4\u05ea\u05e0\u05d5\u05e8."],[38.0,"\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05de\u05e6\u05d1 \u05d4\u05e8\u05da \u05d1\u05d9\u05d5\u05ea\u05e8: \u05e4\u05e8\u05dc\u05d9\u05d8 \u05d2\u05e1 \u05d5\u05e4\u05e8\u05d9\u05d8."],[44.0,"\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e8\u05d9\u05db\u05d5\u05da \u05db\u05d3\u05d9 \u05dc\u05d4\u05e7\u05dc \u05e2\u05dc \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9 \u05d0\u05d5 \u05e2\u05d9\u05e6\u05d5\u05d1 \u05d1\u05e7\u05d5\u05e8, \u05d5\u05dc\u05d1\u05d8\u05dc \u05d4\u05ea\u05e7\u05e9\u05d5\u05ea \u05de\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8."],[51.0,"\u05d4\u05e6\u05de\u05e0\u05d8\u05d9\u05d8 \u05dc\u05db\u05d3\u05d5\u05e8\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea, \u05d5\u05d6\u05d4 \u05d4\u05de\u05e6\u05d1 \u05d4\u05e0\u05d5\u05d7 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05dc\u05d4\u05df."],[60.0,"\u05d4\u05de\u05e2\u05d1\u05e8, \u05e9\u05dc\u05d0 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4, \u05d0\u05dc\u05d0 \u05e8\u05e7 \u05de\u05d5\u05e8\u05d9\u05d3 \u05d0\u05ea \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd, \u05dc\u05de\u05e9\u05dc \u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05d5 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05db\u05d1\u05d3."],[73.0,"\u05e0\u05e8\u05de\u05d5\u05dc \u05d3\u05d5\u05de\u05d4 \u05dc\u05e8\u05d9\u05db\u05d5\u05da, \u05d0\u05d1\u05dc \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e0\u05e2\u05e9\u05d4 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05e9\u05e7\u05d8, \u05de\u05d7\u05d5\u05e5 \u05dc\u05ea\u05e0\u05d5\u05e8."],[78.0,"\u05d5\u05d0\u05d7\u05d9\u05d3. \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d9\u05d5\u05e6\u05d0\u05ea \u05de\u05e2\u05d8 \u05d7\u05d6\u05e7\u05d4 \u05d5\u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d0\u05e9\u05e8 \u05d0\u05d7\u05e8\u05d9\u05e8\u05d9\u05db\u05d5\u05df."],[89.0,"\u05e0\u05e8\u05de\u05d5\u05dc \u05e0\u05e2\u05e9\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d0\u05d7\u05e8\u05d9 \u05d7\u05d9\u05e9\u05d5\u05dc \u05d0\u05d5 \u05d2\u05dc\u05d2\u05d5\u05dc \u05d1\u05d7\u05d5\u05dd, \u05db\u05d3\u05d9 \u05dc\u05d9\u05d9\u05e9\u05e8 \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d0\u05d5 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4."],[97.0,"\u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05de\u05d4\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d1\u05d8\u05d1\u05d9\u05dc\u05d4. \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 3, \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05de\u05d4\u05d9\u05e8 \u05d9\u05d5\u05e6\u05e8 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8."],[109.0,"\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05d1\u05d8\u05d1\u05d9\u05dc\u05d4 \u05d1\u05de\u05d9\u05dd, \u05d1\u05e9\u05de\u05df, \u05d1\u05e4\u05d5\u05dc\u05d9\u05de\u05e8 \u05d0\u05d5 \u05d1\u05d2\u05d6."],[114.0,"\u05d1\u05d9\u05d5\u05ea\u05e8, \u05d0\u05d1\u05dc \u05d2\u05dd \u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05d4\u05d2\u05d1\u05d5\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05dc\u05e1\u05d3\u05e7\u05d9\u05dd. \u05e9\u05de\u05df \u05de\u05e7\u05e8\u05e8 \u05dc\u05d0\u05d8 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d1\u05d8\u05d5\u05d7 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d5\u05e8\u05db\u05d1\u05d9\u05dd."],[127.0,"\u05e7\u05d4\u05e9\u05d8\u05d7 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05db\u05d9 \u05de\u05d4\u05d9\u05e8, \u05d5\u05d1\u05de\u05e8\u05db\u05d6 \u05e9\u05dc \u05d7\u05ea\u05da \u05e2\u05d1\u05d4 \u05d4\u05d5\u05d0 \u05d0\u05d9\u05d8\u05d9\u05d9\u05d5\u05ea\u05d5\u05e8."],[137.0,"\u05d1\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05db\u05de\u05d5 1045, \u05d1\u05de\u05d5\u05d8 \u05e2\u05d1\u05d4, \u05e8\u05e7 \u05e9\u05db\u05d1\u05d4 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea \u05de\u05ea\u05e7\u05e9\u05d4, \u05d5\u05d4\u05dc\u05d9\u05d1\u05d4 \u05e0\u05e9\u05d0\u05e8\u05ea \u05e8\u05db\u05d4."],[145.0,"\u05d4\u05e7\u05e9\u05d9\u05d4, \u05d5\u05d0\u05d5\u05ea\u05d4 \u05de\u05e9\u05e4\u05e8\u05d9\u05dd \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea, \u05db\u05de\u05d5 \u05e9\u05e0\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 8."],[154.0,"\u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05de\u05e8\u05e4\u05d9\u05dd: \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e9\u05d5\u05d1 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05de\u05ea\u05d7\u05ea \u05dc\u05e7\u05d5 \u05d4\u05de\u05e2\u05d1\u05e8 \u05d5\u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd."],[165.0,"\u05db\u05db\u05dc \u05e9\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d9\u05d5\u05e8\u05d3\u05ea, \u2026 \u05e2\u05d5\u05dc\u05d4."],[171.0,"\u05d4\u05e8\u05e4\u05d9\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 200 \u05de\u05e2\u05dc\u05d5\u05ea, \u05de\u05e9\u05d0\u05d9\u05e8\u05d4 \u05e7\u05e9\u05d9\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d5\u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05db\u05dc\u05d9\u05dd \u05d5\u05dc\u05de\u05e1\u05d1\u05d9\u05dd."],[178.0,"\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 550 \u05e2\u05d3 650 \u05de\u05e2\u05dc\u05d5\u05ea, \u05e0\u05d5\u05ea\u05e0\u05ea \u05d7\u05d5\u05d6\u05e7 \u05d8\u05d5\u05d1, \u05d5\u05d2\u05dd toughness \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d5\u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05d2\u05dc\u05d9\u05dd \u05d5\u05dc\u05d1\u05e8\u05d2\u05d9\u05dd."],[189.0,"\u05d4\u05e9\u05d1\u05d7\u05d4. \u05d5\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d4\u05e8\u05e4\u05d5\u05ea \u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4, \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05e0\u05e1\u05d3\u05e7 \u05de\u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd."],[201.0,"\u05de\u05ea\u05e0\u05e4\u05d7\u05ea \u05db\u05e9\u05d4\u05d9\u05d0 \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05ea\u05e2\u05d5\u05d5\u05ea \u05d0\u05d5 \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7."],[210.0,"\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3\u05d9\u05dd. \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05d2\u05d1\u05d5\u05d4 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05d7\u05ea\u05db\u05d9\u05dd \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3\u05d9\u05dd, \u05d1\u05e4\u05d9\u05e0\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea \u05d5\u05d1\u05e7\u05d3\u05d7\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d9\u05dd \u05dc\u05e9\u05e4\u05d4."],[222.0,"\u05d1\u05e2\u05d9\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea: \u05d1\u05d7\u05d9\u05de\u05d5\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05d4 \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05d0\u05d1\u05d3\u05d9\u05dd \u05e4\u05d7\u05de\u05df \u05d5\u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05e8\u05db\u05d9\u05dd."],[228.0,"\u05dc\u05db\u05df \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05d7\u05d5\u05de\u05e8 \u05dc\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd, \u05d0\u05d5 \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d2\u05d9\u05e0\u05d4 \u05d0\u05d5 \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd."],[236.0,"\u05de\u05d4 \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4? \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d8\u05d5\u05d5\u05d7 \u05e7\u05e9\u05d9\u05d5\u05ea, \u05dc\u05de\u05e9\u05dc 40 \u05e2\u05d3 45 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc 6, \u05d5\u05dc\u05d0 \u05e1\u05ea\u05dd \u05de\u05d5\u05e7\u05e9\u05d4."],[245.0,"\u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d7\u05ea\u05db\u05d9\u05dd \u05d0\u05d7\u05d9\u05d3\u05d9\u05dd \u05d5\u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd \u05d1\u05e4\u05d9\u05e0\u05d5\u05ea, \u05d5\u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05de\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd."],[252.0,"\u05d5\u05d4\u05d5\u05d1\u05dc\u05d4 \u05dc\u05e7\u05d1\u05dc\u05df. \u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d2\u05d9\u05e0\u05d4 \u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d9\u05e7\u05e8\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05ea\u05e0\u05d5\u05e8 \u05e8\u05d2\u05d9\u05dc."],[262.0,"\u05d5\u05d9\u05d9\u05e9\u05d5\u05d4 \u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05e2\u05d5\u05d3."],[267.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d3\u05e8\u05da \u05dc\u05d4\u05e7\u05e9\u05d5\u05d5\u05ea \u05e8\u05e7 \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7: \u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4, \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d5\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4."]]};
window.MH_TR["\u05e4\u05e8\u05e707_\u05d4\u05e7\u05e9\u05d9\u05d9\u05ea_\u05e4\u05e0\u05d9_\u05e9\u05d8\u05d7"]={"t":"\u05d4\u05e7\u05e9\u05d9\u05d9\u05ea \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7","l":[[1.0,"\u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e8\u05d1\u05d9\u05dd \u05d9\u05e9 \u05e9\u05ea\u05d9 \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05e9\u05e0\u05e8\u05d0\u05d5\u05ea \u05e1\u05d5\u05ea\u05e8\u05d5\u05ea."],[5.0,"\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05ea \u05e7\u05e9\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05db\u05d3\u05d9 \u05dc\u05e2\u05de\u05d5\u05d3 \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4 \u05d5\u05d1\u05de\u05d2\u05e2, \u05dc\u05de\u05e9\u05dc \u05d1\u05e9\u05d9\u05e0\u05d9 \u05d2\u05dc\u05d2\u05dc \u05d0\u05d5 \u05d1\u05de\u05e9\u05d8\u05d7 \u05de\u05d9\u05e1\u05d1."],[13.0,"\u05d0\u05d1\u05dc \u05d4\u05d7\u05dc\u05e7 \u05db\u05d5\u05dc\u05d5 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05e7\u05e9\u05d5\u05d7, \u05db\u05d3\u05d9 \u05dc\u05d0 \u05dc\u05d4\u05d9\u05e9\u05d1\u05e8 \u05d1\u05de\u05db\u05d4."],[17.0,"\u05d4\u05e4\u05ea\u05e8\u05d5\u05df \u05d4\u05d5\u05d0 \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05e8\u05e7 \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05dc\u05d9\u05d1\u05d4 \u05e7\u05e9\u05d5\u05d7\u05d4."],[22.0,"\u05d5\u05d9\u05e9 \u05d1\u05d5\u05e0\u05d5\u05e1: \u05d4\u05e7\u05dc\u05d9\u05e4\u05d4 \u05d4\u05de\u05d5\u05e7\u05e9\u05d9\u05ea \u05e0\u05e9\u05d0\u05e8\u05ea \u05d1\u05dc\u05d7\u05d9\u05e6\u05d4, \u05d5\u05d6\u05d4 \u05de\u05e9\u05e4\u05e8 \u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."],[29.0,"\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d9\u05d0 \u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4."],[32.0,"\u05d1\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e4\u05dc\u05d3\u05d4 \u05d3\u05dc\u05ea \u05e4\u05d7\u05de\u05df \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05e2\u05e9\u05d9\u05e8\u05d4 \u05d1\u05e4\u05d7\u05de\u05df, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 900 \u05e2\u05d3 950 \u05de\u05e2\u05dc\u05d5\u05ea."],[41.0,"\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05d6\u05d5 \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d4\u05d9\u05d0 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d5\u05d4\u05e4\u05d7\u05de\u05df \u05d7\u05d5\u05d3\u05e8 \u05dc\u05d0\u05d8 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05e2\u05d3 \u05d1\u05e2\u05e8\u05da 0.8 \u05d0\u05d7\u05d5\u05d6."],[50.0,"\u05db\u05db\u05dc | \u05e9\u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d6\u05de\u05df \u05e8\u05d1 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05e9\u05db\u05d1\u05d4 | \u05e2\u05de\u05d5\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d1\u05d3\u05e8 \u05db\u05dc\u05dc \u05d7\u05e6\u05d9 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e2\u05d3 \u05e9\u05e0\u05d9 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."],[57.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05e7\u05e9\u05d9\u05dd \u05d1\u05d8\u05d1\u05d9\u05dc\u05d4 \u05d5\u05de\u05e8\u05e4\u05d9\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4."],[61.0,"\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4: \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05e9\u05dc \u05db-60 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc 6, \u05d5\u05dc\u05d9\u05d1\u05d4 \u05e8\u05db\u05d4 \u05d5\u05e7\u05e9\u05d5\u05d7\u05d4. \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05de\u05d5 8620 \u2026."],[73.0,"\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05dc\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05dc\u05e4\u05d9\u05e0\u05d9\u05dd \u05d5\u05dc\u05de\u05e1\u05dc\u05d5\u05dc\u05d9 \u05de\u05d9\u05e1\u05d1\u05d9\u05dd."],[79.0,"\u05de\u05db\u05e1\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05e9\u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05d4\u05d9\u05e9\u05d0\u05e8 \u05e8\u05db\u05d9\u05dd, \u05dc\u05de\u05e9\u05dc \u05d1\u05e6\u05d9\u05e4\u05d5\u05d9 \u05e0\u05d7\u05d5\u05e9\u05ea \u05d0\u05d5 \u05d1\u05de\u05e9\u05d7\u05d4 \u05de\u05d9\u05d5\u05d7\u05d3\u05ea."],[89.0,"\u05de\u05db\u05d9\u05d5\u05d5\u05df \u05e9\u05d9\u05e9 \u05d8\u05d1\u05d9\u05dc\u05d4, \u05d9\u05e9 \u05d2\u05dd \u05e2\u05d9\u05d5\u05d5\u05ea. \u05dc\u05db\u05df \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05dc\u05d4\u05e9\u05d7\u05d6\u05d4, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d3\u05d9."],[96.0,"\u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05de\u05d5\u05e7\u05e9\u05d9\u05ea \u05d3\u05e7\u05d4, \u05d5\u05d0\u05dd \u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05de\u05de\u05e0\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d3\u05d9, \u05de\u05d0\u05d1\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4."],[102.0,"\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05e2\u05d5\u05d1\u05d3\u05ea \u05d0\u05d7\u05e8\u05ea."],[104.0,"0 \u05e2\u05d3 570 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05e2\u05dd \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05db\u05de\u05d5 \u05db\u05e8\u05d5\u05dd, \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df."],[116.0,"\u05d0\u05d9\u05df \u05d8\u05d1\u05d9\u05dc\u05d4, \u05d5\u05dc\u05db\u05df \u05db\u05de\u05e2\u05d8 \u05d0\u05d9\u05df \u05e2\u05d9\u05d5\u05d5\u05ea, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d9\u05d5\u05e6\u05d0 \u05db\u05de\u05e2\u05d8 \u05d1\u05de\u05d9\u05d3\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea."],[122.0,"\u05d4\u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4, \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d1\u05d5\u05d3\u05d3\u05d5\u05ea, \u05d0\u05d1\u05dc \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d6."],[126.0,"\u05d4\u05d7\u05dc\u05e7 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d5\u05e7\u05e9\u05d4 \u05d5\u05de\u05d5\u05e8\u05e4\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05db\u05df, \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05e8\u05e4\u05d9\u05d4 \u05e9\u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4."],[134.0,"\u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e0\u05d5\u05e6\u05e8\u05ea \u05e9\u05db\u05d1\u05d4 \u05dc\u05d1\u05e0\u05d4, \u05e7\u05e9\u05d4 \u05d5\u05e4\u05e8\u05d9\u05db\u05d4. \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e8\u05d5\u05e6\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4."],[141.0,"\u05d4\u05d7\u05d9\u05e1\u05e8\u05d5\u05df: \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05e8\u05d5\u05da, \u05dc\u05e2\u05ea\u05d9\u05dd \u05e2\u05e9\u05d5\u05e8\u05d5\u05ea \u05e9\u05e2\u05d5\u05ea."],[146.0,"\u05d1\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4, \u05e1\u05dc\u05d9\u05dc \u05de\u05d7\u05de\u05dd \u05e8\u05e7 \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d1\u05ea\u05d5\u05da \u05e9\u05e0\u05d9\u05d5\u05ea, \u05d5\u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d6\u05d4 \u05de\u05ea\u05d9\u05d6\u05d9\u05dd \u05de\u05d9\u05dd."],[154.0,"\u05de\u05ea\u05d0\u05d9\u05de\u05d5\u05ea \u05dc\u05d4 \u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05e4\u05d7\u05de\u05df \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9, \u05db\u05de\u05d5 1045 \u05d5-4140, \u05e9\u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05dc\u05d1\u05d3 \u05d1\u05dc\u05d9 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05e4\u05d7\u05de\u05df."],[163.0,"\u05de\u05d9\u05e1\u05d1 \u05d0\u05d5 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d5\u05d0\u05ea \u05e2\u05d5\u05de\u05e7 \u05d4\u05e9\u05db\u05d1\u05d4 \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05dc\u05e4\u05d9 \u05ea\u05d3\u05d9\u05e8\u05d5\u05ea \u05d4\u05d6\u05e8\u05dd."],[172.0,"\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05dc\u05d4\u05d1\u05d4 \u05e2\u05d5\u05d1\u05d3\u05ea \u05e2\u05dc \u05d0\u05d5\u05ea\u05d5 \u05e2\u05d9\u05e7\u05e8\u05d5\u05df, \u05e2\u05dd \u05de\u05d1\u05e2\u05e8, \u05d5\u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd."],[178.0,"\u05d0\u05d6 \u05de\u05d4 \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd?"],[179.0,"\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05e0\u05d5\u05ea\u05e0\u05ea \u05e9\u05db\u05d1\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05d5\u05d7\u05d6\u05e7\u05d4 \u05d1\u05e4\u05dc\u05d3\u05d4 \u05d3\u05dc\u05ea \u05e4\u05d7\u05de\u05df, \u05d0\u05d1\u05dc \u05e2\u05dd \u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05d4\u05e9\u05d7\u05d6\u05d4."],[186.0,"\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05e0\u05d5\u05ea\u05e0\u05ea \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05d5\u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3, \u05db\u05de\u05e2\u05d8 \u05d1\u05dc\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea, \u05d0\u05d1\u05dc \u05d1\u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05e8\u05d5\u05da."],[192.0,"\u05d5\u05d7\u05e9\u05ea\u05dc\u05de\u05ea \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05db\u05dc\u05de\u05d5\u05d9\u05d5\u05ea, \u05db\u05d9 \u05dc\u05db\u05dc \u05d7\u05dc\u05e7 \u05e6\u05e8\u05d9\u05da \u05e1\u05dc\u05d9\u05dc \u05de\u05e9\u05dc\u05d5."],[201.0,"\u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05e2\u05d3 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d5\u05de\u05d0\u05ea\u05d9\u05d9\u05dd, \u05d1-58 \u05e2\u05d3 62 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc \u05e1, \u05d5\u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05d0\u05d9\u05e4\u05d4 \u05de\u05d5\u05ea\u05e8 \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea."],[218.0,"\u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e7\u05e9\u05d9\u05d9\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05d4."],[222.0,"\u05e9\u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05d4\u05d9\u05e9\u05d0\u05e8 \u05e8\u05db\u05d9\u05dd, \u05d4\u05e9\u05d7\u05d6\u05d4 \u05e9\u05dc \u05d7\u05dc\u05e7 \u05e7\u05e9\u05d4, \u05d5\u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05e1\u05dc\u05d9\u05dc \u05d9\u05d9\u05e2\u05d5\u05d3\u05d9 \u05dc\u05db\u05dc \u05d7\u05dc\u05e7."],[234.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea, \u05d5\u05d0\u05ea \u05d4\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05e9\u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05dc\u05d4\u05df \u05d0\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea."]]};
window.MH_TR["\u05e4\u05e8\u05e708_\u05e4\u05dc\u05d3\u05d5\u05ea_\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea"]={"t":"\u05e4\u05dc\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea","l":[[1.0,"\u05d1\u05e4\u05e8\u05e7\u05d9\u05dd 5 \u05e2\u05d3 7 \u05e8\u05d0\u05d9\u05e0\u05d5 \u05de\u05d4 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e9\u05d9\u05d2 \u05de\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df: \u05d4\u05d9\u05d0 \u05d6\u05d5\u05dc\u05d4, \u05e0\u05d5\u05d7\u05d4, \u05d5\u05de\u05ea\u05e7\u05e9\u05d4 \u05d4\u05d9\u05d8\u05d1 \u05db\u05e9\u05d9\u05e9 \u05d1\u05d4 \u05de\u05e1\u05e4\u05d9\u05e7 \u05e4\u05d7\u05de\u05df."],[10.0,"\u05d0\u05d1\u05dc \u05d9\u05e9 \u05dc\u05d4 \u05d0\u05e8\u05d1\u05e2 \u05de\u05d2\u05d1\u05dc\u05d5\u05ea. \u05d4\u05d9\u05d0 \u05de\u05ea\u05e7\u05e9\u05d4 \u05e8\u05e7 \u05dc\u05e2\u05d5\u05de\u05e7 \u05e8\u05d3\u05d5\u05d3, \u05d5\u05dc\u05db\u05df \u05d1\u05d7\u05ea\u05da \u05e2\u05d1\u05d4 \u05d4\u05dc\u05d9\u05d1\u05d4 \u05e0\u05e9\u05d0\u05e8\u05ea \u05e8\u05db\u05d4."],[18.0,"\u05db\u05d3\u05d9 \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05d0\u05d5\u05ea\u05d4 \u05e6\u05e8\u05d9\u05da \u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d1\u05de\u05d9\u05dd, \u05d5\u05d6\u05d4 \u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05dc\u05e1\u05d3\u05e7\u05d9\u05dd."],[26.0,"\u05d1\u05e7\u05d5\u05e8 \u05d4\u05d9\u05d0 \u05e0\u05e2\u05e9\u05d9\u05ea \u05e4\u05e8\u05d9\u05db\u05d4. \u05d5\u05d1\u05d7\u05d5\u05dd \u05d4\u05d9\u05d0 \u05de\u05ea\u05e8\u05db\u05db\u05ea \u05de\u05d4\u05e8."],[30.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e2\u05e1\u05d5\u05e7 \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05e0\u05de\u05d5\u05db\u05d4, \u05e9\u05d1\u05d4\u05df \u05e1\u05da \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d4\u05d5\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05d3 \u05db\u05d7\u05de\u05d9\u05e9\u05d4 \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd."],[43.0,"\u05db\u05d3\u05d9 \u05dc\u05d4\u05d1\u05d9\u05df \u05d0\u05ea \u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea, \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e4\u05e8\u05d9\u05d3 \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05de\u05d5\u05e9\u05d2\u05d9\u05dd \u05e9\u05de\u05ea\u05d1\u05dc\u05d1\u05dc\u05d9\u05dd \u05d1\u05e7\u05dc\u05d5\u05ea."],[49.0,"\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05d9\u05d0 \u05db\u05de\u05d4 \u05e7\u05e9\u05d5\u05d4 \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05d5\u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 3, \u05d4\u05d9\u05d0 \u05e0\u05e7\u05d1\u05e2\u05ea \u05db\u05de\u05e2\u05d8 \u05e8\u05e7 \u05dc\u05e4\u05d9 \u05d4\u05e4\u05d7\u05de\u05df."],[56.0,"\u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05dc\u05d0\u05d9\u05d6\u05d4 \u05e2\u05d5\u05de\u05e7 \u05d4\u05d7\u05dc\u05e7 \u05de\u05ea\u05e7\u05e9\u05d4, \u05d5\u05d6\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05de\u05d4 \u05e9\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05de\u05e9\u05e4\u05e8\u05d9\u05dd."],[63.0,"\u05e0\u05d9\u05e7\u05d7 \u05e9\u05e0\u05d9\u05de\u05d5\u05d8\u05d5\u05ea \u05e2\u05d1\u05d9\u05dd, \u05e2\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d0\u05d7\u05d7 \u05e4\u05d7\u05de\u05df, \u05d0\u05d7\u05d3 \u05de\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05d5\u05d0\u05d7\u05d3 \u05de\u05e4\u05dc\u05d3\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea, \u05d5\u05e0\u05e7\u05e9\u05d4 \u05d0\u05ea \u05e9\u05e0\u05d9\u05d4\u05dd."],[71.0,"\u05d1\u05e4\u05dc\u05d3\u05ea \u05d4\u05e4\u05d7\u05de\u05df \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05ea\u05e6\u05e0\u05d7 \u05db\u05de\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd \u05e4\u05e1\u05e0\u05d9\u05de\u05d4, \u05d5\u05d1\u05e4\u05dc\u05d3\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d4\u05d9\u05d0 \u05ea\u05d9\u05e9\u05d0\u05e8 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05e2\u05de\u05d5\u05e7 \u05dc\u05ea\u05d5\u05da \u05d4\u05d7\u05ea\u05da."],[84.0,"\u05d0\u05ea \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d1\u05de\u05d1\u05d7\u05df Jominy"],[87.0,"\u05dc\u05d5\u05e7\u05d7\u05d9\u05dd \u05de\u05d5\u05d8 \u05d1\u05e7\u05d5\u05d8\u05e8 25 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05e2\u05d3 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d5\u05de\u05ea\u05d9\u05d6\u05d9\u05dd \u05e1\u05d9\u05dc\u05d5\u05df \u05de\u05d9\u05dd \u05e2\u05dc \u05e7\u05e6\u05d4 \u05d0\u05d7\u05d3 \u05d1\u05dc\u05d1\u05d3."],[96.0,"\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05d9\u05d5\u05ea\u05e8. \u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05e7\u05e9\u05d9\u05d5\u05ea \u05d1\u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05de\u05d5\u05d8, \u05d5\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e2\u05e7\u05d5\u05de\u05d4."],[107.0,"\u05d1\u05e4\u05dc\u05d3\u05ea 1045 \u05d4\u05e2\u05e7\u05d5\u05de\u05d4 \u05e6\u05d5\u05e0\u05d7\u05ea \u05d0\u05d7\u05e8\u05d9 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd \u05d1\u05d5\u05d3\u05d3\u05d9\u05dd. \u05d1\u05e4\u05dc\u05d3\u05ea 4140 \u05d4\u05d9\u05d0 \u05e0\u05e9\u05d0\u05e8\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8."],[117.0,"\u05d4\u05e2\u05e7\u05d5\u05de\u05d4 \u05d4\u05d6\u05d5 \u05d0\u05d5\u05de\u05e8\u05ea \u05dc\u05de\u05ea\u05db\u05e0\u05df \u05d0\u05d9\u05d6\u05d4 \u05e7\u05d5\u05d8\u05e8 \u05d0\u05e4\u05e9\u05d5\u05e8 \u05dc\u05d4\u05e7\u05e9\u05d5\u05d5\u05ea \u05e2\u05d3 \u05d4\u05dc\u05d9\u05d1\u05d4, \u05d5\u05d1\u05d0\u05d9\u05d6\u05d4 \u05d0\u05de\u05e6\u05e2\u05d9 \u05e7\u05d9\u05e8\u05d5\u05e8."],[124.0,"\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8, \u2026 \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea. \u05d4\u05d9\u05d0 \u05de\u05e8\u05d0\u05d4 \u05d0\u05d9\u05d6\u05d4 \u05de\u05d1\u05e0\u05d4 \u05d9\u05d9\u05d5\u05d5\u05e6\u05e8 \u05d1\u05db\u05dc \u05e7\u05e6\u05d1 \u05e7\u05d9\u05e8\u05d5\u05e8."],[134.0,"\u05d1\u05e6\u05d9\u05e8 \u05d4\u05d0\u05d5\u05e4\u05e7\u05d9 \u05d4\u05d6\u05de\u05df, \u05d5\u05d1\u05e6\u05d9\u05e8 \u05d4\u05d0\u05e0\u05db\u05d9 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4."],[139.0,"\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d7\u05d5\u05e6\u05d4 \u05d0\u05d5\u05ea\u05d5, \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05e4\u05e8\u05dc\u05d9\u05d8 \u05d0\u05d5 \u05de\u05d1\u05e0\u05d9\u05dd \u05e8\u05db\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd."],[148.0,"\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8. \u05d1\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05d4\u05d0\u05e3 \u05e7\u05e8\u05d5\u05d1 \u05de\u05d0\u05d5\u05d3 \u05dc\u05e6\u05d9\u05e8, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05de\u05d0\u05d5\u05d3."],[158.0,"\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05de\u05e2\u05db\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05e4\u05e8\u05e7\u05d5\u05ea \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d5\u05d3\u05d5\u05d7\u05e4\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05e3 \u05d9\u05de\u05d9\u05e0\u05d4, \u05dc\u05d6\u05de\u05e0\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."],[165.0,"\u05dc\u05db\u05df \u05d2\u05dd \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05d9\u05d5\u05ea\u05e8, \u05d1\u05e9\u05de\u05df \u05d0\u05d5 \u05d0\u05e4\u05d9\u05dc\u05d5 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8, \u05de\u05e1\u05e4\u05d9\u05e7 \u05db\u05d3\u05d9 \u05dc\u05e7\u05d1\u05dc \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05d5\u05d2\u05dd \u05d1\u05de\u05e8\u05db\u05d6 \u05e9\u05dc \u05d7\u05ea\u05da \u05e2\u05d1\u05d4."],[174.0,"\u05e2\u05db\u05e9\u05d9\u05d5 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea, \u05d0\u05d7\u05d3 \u05d0\u05d7\u05d3. \u05de\u05e0\u05d2\u05df \u05de\u05e9\u05e4\u05e8 \u05d0\u05ea \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4, \u05d5\u05e7\u05d5\u05e9\u05e8 \u05d0\u05ea \u05d4\u05d2\u05d5\u05e4\u05e8\u05d9\u05ea."],[183.0,"\u05e9\u05e2\u05de\u05d9\u05d3\u05d9\u05dd \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4. \u05de\u05e2\u05dc 12 \u05d0\u05d7\u05d5\u05d6 \u05d4\u05d5\u05d0 \u05db\u05d1\u05e8 \u05d4\u05d5\u05e4\u05da \u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4 \u05dc\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4, \u05db\u05de\u05d5 \u05e9\u05e0\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 10."],[194.0,"\u05e0\u05d9\u05e7\u05dc \u05de\u05e9\u05e4\u05e8 \u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u2026, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05e7\u05d5\u05e8."],[198.0,"\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05de\u05e9\u05e4\u05e8 \u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05d4\u05e7\u05e9\u05d5\u05d9\u05d4, \u05de\u05e7\u05d8\u05d9\u05df \u05d0\u05ea \u05d4\u05e8\u05d2\u05d9\u05e9\u05d5\u05ea \u05dc\u05e9\u05d1\u05d9\u05e8\u05d5\u05ea \u05d4\u05e8\u05e4\u05d9\u05d4, \u05d5\u05de\u05e9\u05e4\u05e8 \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7 \u05d1\u05d7\u05d5\u05dd."],[206.0,"\u05d5\u05e0\u05d3\u05d9\u05d5\u05dd \u05de\u05e2\u05d3\u05df \u05d0\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05df \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05de\u05d0\u05d5\u05d3. \u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df \u05de\u05d7\u05d6\u05e7 \u05d0\u05ea \u05d4\u05e4\u05e8\u05d9\u05d8, \u05d5\u05e0\u05e4\u05d5\u05e5 \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e7\u05e4\u05d9\u05e6\u05d9\u05dd."],[215.0,"\u05d0\u05ea \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05d4\u05e7\u05e9\u05d5\u05d9\u05d4, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d5 \u05d1\u05d1\u05e8\u05d2\u05d9\u05dd \u05de\u05d5\u05e7\u05e9\u05d9\u05dd."],[225.0,"\u05d1\u05e9\u05d9\u05d8\u05d4 \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9\u05ea, \u05e9\u05ea\u05d9 \u05d4\u05e1\u05e4\u05e8\u05d5\u05ea \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d5\u05ea \u05d0\u05d5\u05de\u05e8\u05d5\u05ea \u05d0\u05d9\u05dc\u05d5 \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d9\u05e9 \u05d1\u05e4\u05dc\u05d3\u05d4."],[230.0,"\u05d4\u05d9\u05d0 \u05e0\u05d9\u05e7\u05dc \u05db\u05e8\u05d5\u05dd \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8. 51 \u05d4\u05d9\u05d0 \u05db\u05e8\u05d5\u05dd."],[243.0,"\u05d5\u05e9\u05ea\u05d9 \u05d4\u05e1\u05e4\u05e8\u05d5\u05ea \u05d4\u05d0\u05d7\u05e8\u05d5\u05e0\u05d5\u05ea \u05d4\u05df, \u05db\u05de\u05d5 \u05d1\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df, \u05d0\u05d7\u05d5\u05d6 \u05d4\u05e4\u05d7\u05de\u05df \u05d1\u05de\u05d0\u05d9\u05d5\u05ea."],[249.0,"\u05d1\u05e9\u05d9\u05d8\u05d4 \u05d4\u05d0\u05d9\u05e8\u05d5\u05e4\u05d9\u05ea \u05d4\u05e9\u05dd \u05de\u05ea\u05d7\u05d9\u05dc \u05d1\u05d0\u05d7\u05d5\u05d6 \u05d4\u05e4\u05d7\u05de\u05df \u05db\u05e4\u05d5\u05dc \u05de\u05d0\u05d4, \u05d5\u05d0\u05d7\u05e8\u05d9\u05d5 \u05e1\u05de\u05dc\u05d9 \u05d4\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea."],[255.0,"\u05d1\u05e9\u05dd 4\u05e1\u05d5\u05d04207, \u05d4\u05de\u05e1\u05e4\u05e8 42 \u05d0\u05d5\u05de\u05e8 0.42 \u05d0\u05d7\u05d5\u05d6 \u05e4\u05d7\u05de\u05df."],[265.0,"\u05d1\u05d0\u05e8\u05d1\u05e2, \u05db\u05dc\u05d5\u05de\u05e8 \u05d0\u05d7\u05d5\u05d6 \u05d0\u05d7\u05d3 \u05db\u05e8\u05d5\u05dd. \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05e9\u05dd, \u05d0\u05d1\u05dc \u05d1\u05dc\u05d9 \u05de\u05e1\u05e4\u05e8 \u05de\u05e9\u05dc\u05d5."],[276.0,"\u05d4\u05de\u05e7\u05d3\u05dd \u05dc\u05db\u05e8\u05d5\u05dd, \u05dc\u05de\u05e0\u05d2\u05df \u05d5\u05dc\u05e0\u05d9\u05e7\u05dc \u05d4\u05d5\u05d0 \u05d0\u05e8\u05d1\u05e2, \u05d5\u05dc\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05d5\u05dc\u05d5\u05e0\u05d3\u05d9\u05d5\u05dd \u05d4\u05d5\u05d0 \u05e2\u05e9\u05e8."],[283.0,"\u05e9\u05ea\u05d9 \u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4 \u05d4\u05df 0 \u05d5-4340."],[291.0,"0, \u05e9\u05d1\u05d0\u05d9\u05e8\u05d5\u05e4\u05d4 \u05e0\u05e7\u05e8\u05d0\u05ea 42CrMo4, \u05d4\u05d9\u05d0 \u05e1\u05d5\u05e1 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4: \u05e6\u05d9\u05e8\u05d9\u05dd, \u05d2\u05dc\u05d9\u05dd, \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d5\u05de\u05d7\u05d6\u05d9\u05e7\u05d9 \u05db\u05dc\u05d9\u05dd."],[303.0,"\u05d4\u05d9\u05d0 \u05de\u05d2\u05d9\u05e2\u05d4 \u05d2\u05dd \u05d1\u05de\u05e6\u05d1 \u2026, \u05de\u05d5\u05e9\u05d1\u05d7\u05ea \u05dc\u05db-30 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 4."],[309.0,"0 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05db-1.8 \u05d0\u05d7\u05d5\u05d6 \u05e0\u05d9\u05e7\u05dc. \u05d4\u05e0\u05d9\u05e7\u05dc \u05e0\u05d5\u05ea\u05df toughness \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d5\u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8."],[319.0,"\u05d0\u05e8\u05db\u05d5\u05d1\u05d4, \u05d2\u05dc\u05d9\u05dd \u05db\u05d1\u05d3\u05d9\u05dd, \u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05ea \u05d4\u05ea\u05e2\u05d5\u05e4\u05d4. \u05d1\u05d0\u05d9\u05e8\u05d5\u05e4\u05d4 \u05d4\u05de\u05e7\u05d1\u05d9\u05dc\u05d4 \u05d4\u05e7\u05e8\u05d5\u05d1\u05d4 \u05dc\u05d4 \u05d4\u05d9\u05d0 6\u05e1\u05d5\u05d0\u05d5\u05d0\u05d6340."],[334.0,"\u05e4\u05d7\u05de\u05df \u05d5\u05d0\u05d7\u05d5\u05d6 \u05d5\u05d7\u05e6\u05d9 \u05db\u05e8\u05d5\u05dd, \u05e9\u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc \u05de\u05e2\u05dc 60 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc 6."],[350.0,"\u05e9\u05e0\u05d9 \u05d3\u05d1\u05e8\u05d9\u05dd \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05d3\u05e2\u05ea \u05e2\u05dc \u05d4\u05e8\u05e4\u05d9\u05d4 \u05d5\u05e2\u05dc \u05e8\u05d9\u05ea\u05d5\u05da \u05e9\u05dc \u05e4\u05dc\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea."],[355.0,"\u2026 \u05d1\u05d8\u05d5\u05d5\u05d7\u05d9 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05de\u05e1\u05d5\u05d9\u05de\u05d9\u05dd \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d3\u05d5\u05d5\u05e7\u05d0 \u05de\u05d5\u05e8\u05d9\u05d3\u05d4 \u05d0\u05ea \u2026. \u05d6\u05d5 \u05e9\u05d1\u05d9\u05e8\u05d5\u05ea \u05d4\u05e8\u05e4\u05d9\u05d4."],[363.0,"\u05dc\u05db\u05df \u05e0\u05de\u05e0\u05e2\u05d9\u05dd \u05de\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d1\u05d8\u05d5\u05d5\u05d7\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4, \u05d5\u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05db\u05e9\u05d4\u05d7\u05dc\u05e7 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05d7\u05e9\u05d5\u05e3 \u05d0\u05dc\u05d9\u05d4\u05dd."],[370.0,"\u05e4\u05d5\u05e2\u05dc\u05d9\u05dd \u05d2\u05dd \u05d1\u05e8\u05d9\u05ea\u05d5\u05da. \u05d4\u05d0\u05d6\u05d5\u05e8 \u05e9\u05dc\u05d9\u05d3 \u05d4\u05ea\u05e4\u05e8 \u05de\u05ea\u05e7\u05e8\u05e8 \u05de\u05d4\u05e8, \u05d4\u05d5\u05e4\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05d5\u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7."],[382.0,"\u05db\u05d3\u05d9 \u05dc\u05d4\u05e2\u05e8\u05d9\u05da \u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05de\u05d7\u05e9\u05d1\u05d9\u05dd \u05e4\u05d7\u05de\u05df \u05d0\u05e7\u05d5\u05d5\u05d9\u05d5\u05d5\u05dc\u05e0\u05d8\u05d9: \u05d0\u05d7\u05d5\u05d6 \u05d4\u05e4\u05d7\u05de\u05df, \u05d5\u05e2\u05d5\u05d3 \u05d7\u05dc\u05e7 \u05de\u05d4\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05d0\u05d7\u05e8\u05d9\u05dd \u05dc\u05e4\u05d9 \u05de\u05e9\u05e7\u05dc."],[390.0,"\u05db\u05db\u05dc \u05e9\u05d4\u05e4\u05d7\u05de\u05df \u05d4\u05d0\u05e7\u05d5\u05d5\u05d9\u05d5\u05d5\u05dc\u05e0\u05d8\u05d9 \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05e6\u05e8\u05d9\u05da \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05d5\u05e7\u05d3\u05dd \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d1\u05d5\u05e7\u05e8."],[398.0,"\u05d1-4140 \u05d4\u05d5\u05d0 \u05d2\u05d1\u05d5\u05d4, \u05d5\u05dc\u05db\u05df \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e9\u05dc\u05d4 \u05d3\u05d5\u05e8\u05e9 \u05d4\u05dc\u05d9\u05da \u05de\u05e1\u05d5\u05d3\u05e8. \u05e0\u05e8\u05d7\u05d9\u05d1 \u05e2\u05dc \u05db\u05da \u05d1\u05e4\u05e8\u05e7 20."],[406.0,"\u05dc\u05d4\u05d7\u05dc\u05d9\u05e3 4140 \u05d1-1045 \u05e8\u05e7 \u05db\u05d9 \u05d4\u05d9\u05d0 \u05d6\u05d5\u05dc\u05d4. \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d4\u05dc\u05d9\u05d1\u05d4 \u05ea\u05d9\u05e9\u05d0\u05e8 \u05e8\u05db\u05d4."],[418.0,"\u05d2\u05dd \u05d0\u05ea \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05d0\u05ea \u05d4\u05d4\u05e9\u05d7\u05d6\u05d4. \u05d0\u05d1\u05dc \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05dc\u05d4 \u05d0\u05d9\u05d8\u05d9 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d4\u05db\u05dc\u05d9\u05dd \u05e0\u05e9\u05d7\u05e7\u05d9\u05dd \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8."],[429.0,"\u05de\u05e9\u05ea\u05e0\u05d4. \u05e4\u05dc\u05d3\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d9\u05e7\u05e8\u05d4 \u05de\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df, \u05d5\u05e4\u05dc\u05d3\u05ea \u05e0\u05d9\u05e7\u05dc \u05db\u05de\u05d5 4340 \u05d9\u05e7\u05e8\u05d4 \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8."],[442.0,"\u05e8\u05d9\u05ea\u05d5\u05da \u05e2\u05dd \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05d5\u05e7\u05d3\u05dd, \u05d5\u05d3\u05e8\u05d9\u05e9\u05d4 \u05dc\u05ea\u05e2\u05d5\u05d3\u05d4 \u05e2\u05dd \u05d4\u05e8\u05db\u05d1 \u05d5\u05de\u05d1\u05d7\u05df \u05d4\u05dc\u05dd, \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05e2\u05dc\u05d5\u05ea."],[449.0,"\u05d5\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05dc\u05d0\u05d9\u05d6\u05d4 \u05e2\u05d5\u05de\u05e7, \u05d1\u05d0\u05d9\u05d6\u05d4 \u05e7\u05d9\u05e8\u05d5\u05e8, \u05d5\u05db\u05de\u05d4 toughness \u05ea\u05d9\u05e9\u05d0\u05e8 \u05dc\u05d4."],[460.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05de\u05e9\u05e4\u05d7\u05d4 \u05e9\u05d1\u05d4 \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05dc\u05e7\u05d9\u05e6\u05d5\u05df: \u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05db\u05dc\u05d9\u05dd."]]};
window.MH_TR["\u05e4\u05e8\u05e709_\u05e4\u05dc\u05d3\u05d5\u05ea_\u05db\u05dc\u05d9\u05dd"]={"t":"\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd","l":[[1.0,"\u05d5\u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d0\u05ea \u05db\u05dc \u05e9\u05d0\u05e8 \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd: \u05de\u05d1\u05dc\u05d8\u05d9\u05dd, \u05d0\u05d2\u05e8\u05d5\u05e4\u05d9\u05dd, \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05d9\u05e6\u05d9\u05e7\u05d4 \u05d5\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05e4\u05dc\u05e1\u05d8\u05d9\u05e7, \u05de\u05e7\u05d3\u05d7\u05d9\u05dd \u05d5\u05de\u05d1\u05e8\u05d6\u05d9\u05dd."],[14.0,"\u05d2\u05d1\u05d5\u05d4\u05d4, \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4, \u05d5-655\u05d7\u05d70\u05d810 \u05de\u05e1\u05e4\u05d9\u05e7\u05d4 \u05db\u05d3\u05d9 \u05dc\u05d0 \u05dc\u05d4\u05d9\u05e9\u05d1\u05e8."],[23.0,"\u05db\u05de\u05d5 \u05db\u05e8\u05d5\u05dd, \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d5\u05d5\u05e0\u05d3\u05d9\u05d5\u05dd, \u05e9\u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05de\u05d0\u05d5\u05d3."],[34.0,"\u05db\u05dc \u05e1\u05d3\u05e8\u05d4 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd \u05de\u05d0\u05d6\u05e0\u05ea \u05d1\u05d9\u05df \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05d1\u05e6\u05d5\u05e8\u05d4 \u05d0\u05d7\u05e8\u05ea, \u05dc\u05e4\u05d9 \u05d4\u05e9\u05d9\u05de\u05d5\u05e9."],[40.0,"\u05d1\u05e9\u05d9\u05d8\u05d4 \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9\u05ea, \u05db\u05dc \u05e1\u05d3\u05e8\u05d4 \u05de\u05e1\u05d5\u05de\u05e0\u05ea \u05d1\u05d0\u05d5\u05ea."],[44.0,"\u05de\u05ea\u05e7\u05e9\u05d4 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8. \u05d5-\u05dd \u05e2\u05ea\u05d9\u05e8\u05ea \u05e4\u05d7\u05de\u05df \u05d5\u05db\u05e8\u05d5\u05dd. \u05d0\u05e8\u05d1\u05e2 \u05d4\u05e1\u05d3\u05e8\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05d4\u05df \u05e4\u05dc\u05d3\u05d5\u05ea \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05e7\u05d5\u05e8."],[58.0,"5\u05e4\u05d6\u05d9\u05d5\u05e2\u05d3\u05ea \u05dc\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05d4\u05dc\u05dd. \u05d5\u05d7 \u05d4\u05d9\u05d0 \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05d7\u05d5\u05dd. \u05d5\u05d0 \u05d5-\u05d3 \u05d4\u05df \u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05dc\u05db\u05dc\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da. \u05d5-\u05dd \u05dc\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05e4\u05dc\u05e1\u05d8\u05d9\u05e7."],[69.0,"\u05d4\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05d1\u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05e1\u05d3\u05e8\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 01, \u05d5-020. S7, H13, M2"],[80.0,"\u05d4\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05d1\u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05e1\u05d3\u05e8\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05d4\u05df,02 A2, ,01 M2 ,13 ,57 \u2026."],[81.0,"\u05de\u05ea\u05e7\u05e9\u05d4 \u05d1\u05e9\u05de\u05df, \u05e0\u05d5\u05d7\u05d4 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3, \u05d5\u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05db\u05dc\u05d9\u05dd \u05e4\u05e9\u05d5\u05d8\u05d9\u05dd \u05d5\u05dc\u05de\u05d3\u05d9\u05d3\u05d9\u05dd."],[91.0,"\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05d0\u05d9\u05d8\u05d9 \u05e0\u05d5\u05ea\u05df \u05e2\u05d9\u05d5\u05d5\u05ea \u05e7\u05d8\u05df \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05db\u05df \u05d4\u05d9\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05db\u05dc\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd."],[101.0,"\u05d4\u05e4\u05d7\u05de\u05df \u05d5\u05d4\u05db\u05e8\u05d5\u05dd \u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05db\u05de\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d4 \u05e9\u05dc \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9 \u05db\u05e8\u05d5\u05dd \u05d2\u05e1\u05d9\u05dd, \u05d5\u05d7\u05d4 \u05e0\u05d5\u05ea\u05df \u05dc\u05d4 \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05e6\u05d5\u05d9\u05e0\u05ea \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4."],[113.0,"\u05dc\u05db\u05df \u05d4\u05d9\u05d0 \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05dc\u05de\u05d1\u05dc\u05d8\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da \u05d5\u05dc\u05e1\u05db\u05d9\u05e0\u05d9 \u05d2\u05d9\u05dc\u05d9\u05d5\u05d8\u05d9\u05e0\u05d4. \u05d4\u05de\u05d7\u05d9\u05e8 \u05d4\u05d5\u05d0 toughness \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d4\u05e9\u05d7\u05d6\u05d4 \u05e7\u05e9\u05d4."],[122.0,"\u05e4\u05dc\u05d3\u05d5\u05ea 5, \u05db\u05de\u05d5 57, \u05e0\u05d1\u05e0\u05d5 \u05d1\u05db\u05d5\u05d5\u05e0\u05d4 \u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05e4\u05d7\u05de\u05df."],[127.0,"\u05d0\u05d1\u05dc \u05e2\u05d5\u05de\u05d3\u05d5\u05ea \u05d1\u05de\u05db\u05d5\u05ea \u05d7\u05d5\u05d6\u05e8\u05d5\u05ea \u05d1\u05dc\u05d9 \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7. \u05dc\u05db\u05df \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05de\u05d4\u05df \u05d0\u05d2\u05e8\u05d5\u05e4\u05d9\u05dd, \u05d0\u05d6\u05de\u05dc\u05d9\u05dd \u05d5\u05de\u05e7\u05d1\u05d5\u05ea."],[139.0,"\u05d6\u05d5 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d4\u05e4\u05e9\u05d5\u05e8\u05d4 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 0, \u05d1\u05d9\u05df \u05e7\u05e9\u05d9\u05d5\u05ea \u05dc\u05d1\u05d9\u05df 5 toughness, \u05e8\u05e7 \u05e9\u05db\u05d0\u05df \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d1\u05d4 \u05d1\u05db\u05d5\u05d5\u05e0\u05d4."],[147.0,"\u05e4\u05dc\u05d3\u05d5\u05ea \u05d5\u05d7 \u05de\u05d9\u05d5\u05e2\u05d3\u05d5\u05ea \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05d7\u05d5\u05dd: \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05dc\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d1\u05dc\u05d7\u05e5, \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05d7\u05d9\u05e9\u05d5\u05dc, \u05d5\u05de\u05d1\u05dc\u05d8\u05d9 \u05e9\u05d9\u05d7\u05d5\u05dc."],[154.0,"\u05de\u05ea\u05e8\u05d7\u05d1\u05d9\u05dd \u05d5\u05de\u05ea\u05db\u05d5\u05d5\u05e6\u05d9\u05dd \u05d1\u05db\u05dc \u05de\u05d7\u05d6\u05d5\u05e8. \u05d1\u05e1\u05d5\u05e3 \u05e0\u05d5\u05e6\u05e8\u05ea \u05e8\u05e9\u05ea \u05e9\u05dc \u05e1\u05d3\u05e7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd, \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05ea\u05e8\u05de\u05d9\u05ea."],[166.0,"\u05e9\u05d5\u05de\u05e8\u05ea \u05e2\u05dc \u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc\u05d4 \u05d1\u05d7\u05d5\u05dd, \u05d5\u05e2\u05de\u05d9\u05d3\u05d4 \u05d4\u05d9\u05d8\u05d1 \u05d1\u05e1\u05d3\u05e7\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4."],[175.0,"\u05d5\u05d1\u05d2\u05dc\u05dc \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4 \u05d2\u05dd \u05dc\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05e4\u05dc\u05e1\u05d8\u05d9\u05e7 \u05ea\u05d5\u05d1\u05e2\u05e0\u05d9\u05d5\u05ea."],[185.0,"\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d4\u05d9\u05e8\u05d5\u05ea, \u05db\u05de\u05d5 2\u05d5\u05d0, \u05de\u05db\u05d9\u05dc\u05d5\u05ea \u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df, \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05db\u05e8\u05d5\u05dd \u05d5\u05d5\u05e0\u05d3\u05d9\u05d5\u05dd."],[192.0,"\u05e9\u05dc\u05d4\u05df \u05d1\u05d7\u05d5\u05dd, \u05d2\u05dd \u05db\u05e9\u05e7\u05e6\u05d4 \u05d4\u05db\u05dc\u05d9 \u05de\u05ea\u05d7\u05de\u05dd \u05de\u05d0\u05d5\u05d3 \u05d1\u05d6\u05de\u05df \u05d4\u05d7\u05d9\u05ea\u05d5\u05da."],[199.0,"\u05d4\u05df \u05de\u05d2\u05d9\u05e2\u05d5\u05ea \u05dc\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc 62 \u05e2\u05d3 65 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc 6, \u05d5\u05e9\u05d9\u05de\u05e9\u05d5 \u05d1\u05de\u05e9\u05da \u05e2\u05e9\u05e8\u05d5\u05ea \u05e9\u05e0\u05d9\u05dd \u05dc\u05db\u05dc \u05db\u05dc\u05d9 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da."],[207.0,"\u05de\u05e4\u05d3\u05d3\u05d4. 1 \u05e7\u05e8\u05d1\u05d9\u05d3 \u05e6\u05de\u05e0\u05d8\u05d9 | \u05e7\u05e9\u05d4 \u05d5\u05e2\u05de\u05d9\u05d3 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05d7\u05d5\u05dd, \u05d0\u05d1\u05dc \u05e4\u05e8\u05d9"],[218.0,"\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e2\u05d3\u05d9\u05d9\u05df \u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05d1\u05de\u05e7\u05d3\u05d7\u05d9\u05dd, \u05d1\u05de\u05d1\u05e8\u05d6\u05d9\u05dd, \u05d1\u05db\u05dc\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd, \u05d5\u05d1\u05d7\u05d9\u05ea\u05d5\u05da \u05e2\u05dd \u05de\u05db\u05d5\u05ea."],[226.0,"\u05d2\u05dd \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05e9\u05dc \u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05db\u05dc\u05d9\u05dd \u05e9\u05d5\u05e0\u05d4."],[228.0,"\u05de\u05e2\u05e0\u05d9\u05d9\u05df: \u05d1\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 550 \u05de\u05e2\u05dc\u05d5\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05e2\u05d5\u05dc\u05d4 \u05e9\u05d5\u05d1. \u05d6\u05d5 \u05d4\u05e7\u05e9\u05d9\u05d4 \u05de\u05e9\u05e0\u05d9\u05ea."],[243.0,"\u05d4\u05d9\u05d0 \u05e0\u05d5\u05e6\u05e8\u05ea \u05db\u05e9\u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd \u05e9\u05dc \u05d5\u05e0\u05d3\u05d9\u05d5\u05dd, \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05d5\u05d8\u05d5\u05ea\u05d2\u05e1\u05d8\u05df \u05de\u05e9\u05ea\u05e7\u05e2\u05d9\u05dd \u05de\u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8."],[249.0,"\u05d4\u05e4\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8. \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9 \u05d4\u05d6\u05d4 \u05dc\u05d0 \u05d9\u05e6\u05d9\u05d1, \u05d5\u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05e4\u05d5\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d1\u05d4\u05de\u05e9\u05da \u05d5\u05dc\u05e9\u05e0\u05d5\u05ea \u05de\u05d9\u05d3\u05d5\u05ea."],[262.0,"\u05dc\u05db\u05df \u05de\u05e8\u05e4\u05d9\u05dd \u05e4\u05e2\u05de\u05d9\u05d9\u05dd \u05d0\u05d5 \u05e9\u05dc\u05d5\u05e9, \u05db\u05d3\u05d9 \u05dc\u05d4\u05e4\u05d5\u05da \u05d0\u05ea \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9 \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05d5\u05dc\u05d4\u05e8\u05e4\u05d5\u05ea \u05d2\u05dd \u05d0\u05d5\u05ea\u05d5."],[269.0,"\u05d5\u05d0\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05e2\u05e6\u05de\u05d4 \u05e2\u05d5\u05e9\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd, \u05db\u05d3\u05d9 \u05e9\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05dc\u05d0 \u05d9\u05d0\u05d1\u05d3\u05d5 \u05e4\u05d7\u05de\u05df."],[276.0,"\u05d4\u05d4\u05ea\u05de\u05e6\u05e7\u05d5\u05ea \u05e9\u05dc \u05d4\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d4\u05d2\u05d3\u05d5\u05dc\u05d4. \u05d4\u05dd \u05d2\u05e1\u05d9\u05dd, \u05d5\u05de\u05e1\u05d5\u05d3\u05e8\u05d9\u05dd \u05d1\u05e9\u05d5\u05e8\u05d5\u05ea \u05dc\u05d0\u05d5\u05e8\u05da \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d2\u05dc\u05d2\u05d5\u05dc."],[285.0,"\u05d6\u05e2\u05d9\u05e8\u05d5\u05ea, \u05e9\u05de\u05ea\u05de\u05e6\u05e7\u05d5\u05ea \u05de\u05d4\u05e8 \u05dc\u05d0\u05d1\u05e7\u05d4, \u05d5\u05d0\u05d6 \u05db\u05d5\u05d1\u05e9\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05d1\u05e7\u05d4 \u05d1\u05d7\u05d5\u05dd \u05d5\u05d1\u05dc\u05d7\u05e5 \u05dc\u05d2\u05d5\u05e9 \u05de\u05dc\u05d0."],[296.0,"\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05d1\u05e7\u05d4 \u05d4\u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d5\u05de\u05e4\u05d5\u05d6\u05e8\u05d9\u05dd \u05d1\u05d0\u05d7\u05d9\u05d3\u05d5\u05ea."],[300.0,"\u05d5\u05d0\u05e4\u05e9\u05e8\u05d5\u05ea \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d5\u05e0\u05d3\u05d9\u05d5\u05dd \u05d5\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4 \u05d1\u05dc\u05d9 \u05dc\u05d0\u05d1\u05d3 \u05d0\u05ea \u2026. \u05d4\u05de\u05d7\u05d9\u05e8: \u05d4\u05df \u05d9\u05e7\u05e8\u05d5\u05ea \u05d1\u05d4\u05e8\u05d1\u05d4."],[315.0,"\u05d4\u05d7\u05d5\u05de\u05e8. \u05de\u05e1\u05e4\u05e8\u05d9\u05dd \u05e9\u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05d1-1.2 \u05d4\u05dd \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd, \u05d5\u05d1-1.3 \u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d4\u05d9\u05e8\u05d5\u05ea."],[326.0,"2 \u05d4\u05d9\u05d0 \u05d1\u05e7\u05d9\u05e8\u05d5\u05d1 1.2379. 13\u05d7 \u05d4\u05d9\u05d0 1.2344. A2 \u05d4\u05d9\u05d0 1.2363."],[339.0,"1 \u05d4\u05d9\u05d0 1.2510. 12\u05d0 \u05d4\u05d9\u05d0 1.3343. \u2026 \u05d4\u05d9\u05d0 1.2311."],[352.0,"\u05db\u05d3\u05d0\u05d9 \u05dc\u05d4\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05de\u05e1\u05e4\u05e8\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4, \u05db\u05d9 \u05d1\u05d4\u05d6\u05de\u05e0\u05d5\u05ea \u05d5\u05d1\u05ea\u05e2\u05d5\u05d3\u05d5\u05ea \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4\u05dd \u05dc\u05d0 \u05e4\u05d7\u05d5\u05ea \u05de\u05d1\u05e9\u05de\u05d5\u05ea \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9\u05d9\u05dd."],[359.0,"\u05e9\u05d9\u05de\u05d5 \u05dc\u05d1, \u05d4\u05d4\u05ea\u05d0\u05de\u05d4 \u05dc\u05d0 \u05ea\u05de\u05d9\u05d3 \u05de\u05dc\u05d0\u05d4, \u05d5\u05dc\u05db\u05df \u05d1\u05d7\u05dc\u05e7 \u05e7\u05e8\u05d9\u05d8\u05d9 \u05de\u05e9\u05d5\u05d5\u05d9\u05dd \u05d4\u05e8\u05db\u05d1."],[365.0,"\u05de\u05d4 \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4? \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd \u05de\u05d2\u05d9\u05e2\u05d5\u05ea \u05d1\u05de\u05e6\u05d1 \u05e8\u05da, \u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05db\u05d5\u05da, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 200 \u05e2\u05d3 250 \u05d1\u05e8\u05d9\u05e0\u05dc."],[374.0,"\u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05df \u05d2\u05e1, \u05de\u05e4\u05d9\u05d2\u05d9\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05e2\u05d5\u05d3 \u05de\u05e2\u05d8, \u05d5\u05e9\u05d5\u05dc\u05d7\u05d9\u05dd \u05dc\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd."],[380.0,"\u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05d4\u05d7\u05dc\u05e7 \u05e7\u05e9\u05d4, \u05d5\u05dc\u05db\u05df \u05d0\u05ea \u05d4\u05d2\u05de\u05e8 \u05e2\u05d5\u05e9\u05d9\u05dd \u05d1\u05d4\u05e9\u05d7\u05d6\u05d4, \u05d1-\u05d5\u05d0\u05e1\u05dd, \u05d0\u05d5 \u05d1\u05db\u05e8\u05e1\u05d5\u05dd \u05e7\u05e9\u05d4."],[388.0,"\u05d0\u05d7\u05e8\u05d9 \u05d5\u05d0\u05e1\u05dd \u05db\u05d3\u05d0\u05d9 \u05dc\u05d4\u05e8\u05e4\u05d5\u05ea \u05e9\u05d5\u05d1, \u05db\u05d9 \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e9\u05e0\u05de\u05e1\u05d5 \u05d5\u05e0\u05de\u05e6\u05e7\u05d5 \u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05e4\u05e8\u05d9\u05db\u05d9\u05dd."],[395.0,"\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd, \u05d4\u05e9\u05d7\u05d6\u05d4 \u05e9\u05dc \u05d7\u05d5\u05de\u05e8 \u05e7\u05e9\u05d4 EDM-1 \u05d4\u05dd \u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05d0\u05d9\u05d8\u05d9\u05d9\u05dd \u05d5\u05d9\u05e7\u05e8\u05d9\u05dd."],[406.0,"\u05d5\u05dc\u05db\u05df \u05d7\u05e9\u05d5\u05d1 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d4\u05e4\u05e9\u05d5\u05d8\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e9\u05e2\u05d5\u05e9\u05d4 \u05d0\u05ea \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4, \u05d5\u05dc\u05d0 \u05ea\u05de\u05d9\u05d3 \u05d0\u05ea \u05d4\u05de\u05ea\u05e7\u05d3\u05de\u05ea \u05d1\u05d9\u05d5\u05ea\u05e8."],[413.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4, \u05d4\u05de\u05e9\u05e4\u05d7\u05d4 \u05e9\u05d1\u05d4 \u05d4\u05db\u05e8\u05d5\u05dd \u05db\u05d1\u05e8 \u05dc\u05d0 \u05e8\u05e7 \u05de\u05d7\u05d6\u05e7, \u05d0\u05dc\u05d0 \u05de\u05d2\u05df \u05de\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."]]};
window.MH_TR["\u05e4\u05e8\u05e710_\u05e4\u05dc\u05d3\u05d5\u05ea_\u05d0\u05dc_\u05d7\u05dc\u05d3"]={"t":"\u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05dc \u05d7\u05dc\u05d3","l":[[1.0,"\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d4\u05d9\u05d0 \u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05dc\u05e4\u05d7\u05d5\u05ea \u05e2\u05e9\u05e8\u05d4 \u05d5\u05d7\u05e6\u05d9 \u05d0\u05d7\u05d5\u05d6 \u05db\u05e8\u05d5\u05dd."],[5.0,"\u05d4\u05db\u05e8\u05d5\u05dd \u05de\u05d2\u05d9\u05d1 \u05e2\u05dd \u05d4\u05d7\u05de\u05e6\u05df \u05e9\u05d1\u05d0\u05d5\u05d5\u05d9\u05e8, \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e9\u05db\u05d1\u05d4 \u05e4\u05e1\u05d9\u05d1\u05d9\u05ea \u05e9\u05dc \u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05db\u05e8\u05d5\u05dd."],[12.0,"\u05d4\u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05de\u05d0\u05d5\u05d3, \u05db\u05de\u05d4 \u05e0\u05e0\u05d5\u05de\u05d8\u05e8\u05d9\u05dd \u05d1\u05dc\u05d1\u05d3, \u05d5\u05e9\u05e7\u05d5\u05e4\u05d4, \u05d0\u05d1\u05dc \u05d4\u05d9\u05d0 \u05d0\u05d5\u05d8\u05de\u05ea \u05d0\u05ea \u05d4\u05de\u05ea\u05db\u05ea \u05de\u05e4\u05e0\u05d9 \u05d4\u05e1\u05d1\u05d9\u05d1\u05d4."],[19.0,"\u05d5\u05d4\u05d9\u05ea\u05e8\u05d5\u05df \u05d4\u05d2\u05d3\u05d5\u05dc \u05e9\u05dc\u05d4: \u05db\u05e9\u05d4\u05d9\u05d0 \u05e0\u05e9\u05e8\u05d8\u05ea, \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05e4\u05e1\u05d9\u05d1\u05d9\u05ea \u05e0\u05d5\u05e6\u05e8\u05ea \u05de\u05d7\u05d3\u05e9 \u05de\u05e2\u05e6\u05de\u05d4, \u05db\u05dc \u05e2\u05d5\u05d3 \u05d9\u05e9 \u05d7\u05de\u05e6\u05df."],[26.0,"\u05e2\u05de\u05d9\u05d3\u05d4, \u05d5\u05db\u05de\u05d4 \u05e2\u05de\u05d9\u05d3\u05d4 \u05d4\u05d9\u05d0, \u05d6\u05d4 \u05ea\u05dc\u05d5\u05d9 \u05d1\u05d4\u05e8\u05db\u05d1 \u05e9\u05dc\u05d4 \u05d5\u05d1\u05e1\u05d1\u05d9\u05d1\u05d4."],[36.0,"\u05d9\u05e9 \u05d7\u05de\u05e9 \u05de\u05e9\u05e4\u05d7\u05d5\u05ea \u05e9\u05dc \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4, \u05dc\u05e4\u05d9 \u05d4\u05de\u05d1\u05e0\u05d4 \u05d4\u05d2\u05d1\u05d9\u05e9\u05d5\u05d9 \u05e9\u05dc\u05d4\u05df."],[40.0,"\u05d1\u05dc\u05d1\u05d3, \u05d1\u05de\u05d1\u05e0\u05d4 806. \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8\u05d9\u05ea, \u05e2\u05dd \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d7\u05de\u05df, \u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea."],[52.0,"\u05d3\u05d5\u05e4\u05dc\u05e7\u05e1, \u05e9\u05d4\u05d9\u05d0 \u05d7\u05e6\u05d9 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d5\u05d7\u05e6\u05d9 \u05e4\u05e8\u05d9\u05d8. \u05d5\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05de\u05d5\u05e7\u05e9\u05d5\u05d9\u05ea \u05d1\u05de\u05e9\u05e7\u05e2, \u05e8\u05d4\u05d5\u05e1 \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea."],[60.0,"\u05dc\u05db\u05dc \u05de\u05e9\u05e4\u05d7\u05d4 \u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea \u05dc\u05d2\u05de\u05e8\u05d9, \u05d5\u05dc\u05db\u05df \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05d9\u05d0 \u05d4\u05d2\u05d3\u05e8\u05d4 \u05d7\u05e1\u05e8\u05d4."],[66.0,"\u05d4\u05de\u05e9\u05e4\u05d7\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d9\u05d0 \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05ea, \u05e1\u05d3\u05e8\u05ea 300."],[71.0,"\u05e0\u05d9\u05e7\u05dc. \u05d4\u05d9\u05d0 \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05ea \u05d4\u05d1\u05e1\u05d9\u05e1: \u05e6\u05d9\u05d5\u05d3 \u05de\u05d6\u05d5\u05df, \u05de\u05d8\u05d1\u05d7\u05d9\u05dd, \u05d5\u05de\u05d1\u05e0\u05d9\u05dd \u05db\u05dc\u05dc\u05d9\u05d9\u05dd."],[82.0,"\u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05db\u05dc\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd, \u05db\u05de\u05d5 \u05de\u05d9 \u05d9\u05dd, \u05de\u05dc\u05d7 \u05d5\u05d7\u05d5\u05de\u05e8\u05d9 \u05e0\u05d9\u05e7\u05d5\u05d9."],[92.0,"\u05d4\u05e0\u05d9\u05e7\u05dc \u05e9\u05d5\u05de\u05e8 \u05e2\u05dc \u05de\u05d1\u05e0\u05d4 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9 \u05d2\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8, \u05d5\u05dc\u05db\u05df \u05d4\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d4\u05d6\u05d5 \u05dc\u05d0 \u05e0\u05de\u05e9\u05db\u05ea \u05dc\u05de\u05d2\u05e0\u05d8 \u05d1\u05de\u05e6\u05d1 \u05e8\u05da."],[100.0,"\u05d4\u05d9\u05d0 \u05d2\u05dd \u05dc\u05d0 \u05de\u05ea\u05e7\u05e9\u05d4 \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05e8\u05e7 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8, \u05d5\u05d4\u05d9\u05d0 \u05e9\u05d5\u05de\u05e8\u05ea \u05e2\u05dc toughness \u05de\u05e6\u05d5\u05d9\u05e0\u05ea \u05d2\u05dd \u05d1\u05e7\u05d5\u05e8 \u05e2\u05de\u05d5\u05e7."],[107.0,"\u05d9\u05e9 \u05dc\u05d4 \u05e9\u05ea\u05d9 \u05d2\u05e8\u05e1\u05d0\u05d5\u05ea \u05d7\u05e9\u05d5\u05d5\u05d1\u05d5\u05ea. \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05d4\u05d9\u05d0 \u05d2\u05e8\u05e1\u05ea |, \u05db\u05de\u05d5 304L \u05d5-3161, \u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05de-0.03 \u05d0\u05d7\u05d5\u05d6 \u05e4\u05d7\u05de\u05df."],[119.0,"0 \u05de\u05e2\u05dc\u05d5\u05ea, \u05dc\u05de\u05e9\u05dc \u05dc\u05d9\u05d3 \u05e8\u05d9\u05ea\u05d5\u05da, \u05d4\u05e4\u05d7\u05de\u05df \u05de\u05ea\u05d7\u05d1\u05e8 \u05dc\u05db\u05e8\u05d5\u05dd \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9 \u05db\u05e8\u05d5\u05dd \u05d1\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd."],[132.0,"\u05d4\u05d0\u05d6\u05d5\u05e8 \u05e9\u05dc\u05d9\u05d3 \u05d4\u05d2\u05d1\u05d5\u05dc \u05de\u05d0\u05d1\u05d3 \u05db\u05e8\u05d5\u05dd, \u05d5\u05de\u05ea\u05d7\u05d9\u05dc \u05dc\u05d4\u05d9\u05d0\u05db\u05dc. \u05d6\u05d5 \u05e8\u05d2\u05d9\u05e9\u05d5\u05ea \u05dc\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d1\u05d9\u05df \u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05ea."],[139.0,"\u05d1\u05d2\u05e8\u05e1\u05ea ! \u05d0\u05d9\u05df \u05de\u05e1\u05e4\u05d9\u05e7 \u05e4\u05d7\u05de\u05df \u05db\u05d3\u05d9 \u05e9\u05d6\u05d4 \u05d9\u05e7\u05e8\u05d4, \u05d5\u05dc\u05db\u05df \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4."],[144.0,"\u05de\u05d4\u05d9\u05e8. \u05d4\u05de\u05d7\u05d9\u05d4 \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05e7\u05d5\u05e8\u05d7\u05d9\u05d4, \u05d5\u05e8\u05d9\u05ea\u05d5\u05da \u05d2\u05e8\u05d5\u05e2."],[154.0,"\u05e0\u05db\u05d5\u05e0\u05d9\u05dd. \u05d4\u05d9\u05d0 \u05de\u05ea\u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8, \u05d5\u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05de\u05ea\u05d7\u05ea \u05dc\u05db\u05dc\u05d9 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da."],[163.0,"\u05d0\u05dd \u05d4\u05db\u05dc\u05d9 \u05de\u05e9\u05e4\u05e9\u05e3 \u05d1\u05de\u05e7\u05d5\u05dd \u05dc\u05d7\u05ea\u05d5\u05da, \u05e9\u05db\u05d1\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05ea\u05e7\u05e9\u05d4, \u05d5\u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05d4\u05d1\u05d0 \u05e0\u05e2\u05e9\u05d4 \u05e7\u05e9\u05d4 \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8."],[171.0,"\u05dc\u05d4\u05e9\u05d4\u05d5\u05ea \u05d0\u05ea \u05d4\u05db\u05dc\u05d9 \u05d1\u05de\u05e7\u05d5\u05dd. \u05d4\u05d9\u05d0 \u05d2\u05dd \u05de\u05d5\u05dc\u05d9\u05db\u05d4 \u05d7\u05d5\u05dd \u05d2\u05e8\u05d5\u05e2, \u05db\u05da \u05e9\u05d4\u05d7\u05d5\u05dd \u05de\u05ea\u05e8\u05db\u05d6 \u05d1\u05e7\u05e6\u05d4 \u05d4\u05db\u05dc\u05d9."],[182.0,"\u05d5\u05d1\u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05e9\u05dc \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05e2\u05dc \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d9\u05e9 \u05e1\u05db\u05e0\u05d4 \u05dc\u05d4\u05d9\u05d3\u05d1\u05e7\u05d5\u05ea, galling \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea: \u05d4\u05d1\u05d5\u05e8\u05d2 \u05d5\u05d4\u05d0\u05d5\u05dd \u05e0\u05e6\u05de\u05d3\u05d9\u05dd \u05d5\u05e0\u05ea\u05e7\u05e2\u05d9\u05dd."],[191.0,"\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d7\u05d5\u05de\u05e8 \u05e1\u05d9\u05db\u05d4 \u05de\u05ea\u05d0\u05d9\u05dd, \u05d0\u05d5 \u05d1\u05e9\u05d9\u05dc\u05d5\u05d1 \u05e9\u05dc \u05e1\u05d5\u05d2\u05d9 \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05e9\u05d5\u05e0\u05d9\u05dd."],[196.0,"\u05d4\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d4\u05e4\u05e8\u05d9\u05d8\u05d9\u05ea, \u05db\u05de\u05d5 430, \u05de\u05db\u05d9\u05dc\u05d4 \u05db\u05e8\u05d5\u05dd \u05d1\u05dc\u05d1\u05d3, \u05d1\u05dc\u05d9 \u05e0\u05d9\u05e7\u05dc."],[202.0,"\u05d1\u05e1\u05d3\u05d9\u05e7\u05d4 \u05ea\u05d7\u05ea \u05de\u05d0\u05de\u05e5, \u05d0\u05d1\u05dc \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05dc\u05d4 \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05de\u05d6\u05d5 \u05e9\u05dc 304."],[212.0,"\u05d4\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8\u05d9\u05ea, \u05db\u05de\u05d5 410, 420 \u05d5-4406, \u05de\u05db\u05d9\u05dc\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d7\u05de\u05df, \u05d5\u05dc\u05db\u05df \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e7\u05e9\u05d5\u05d5\u05ea \u05d0\u05d5\u05ea\u05d4."],[222.0,"\u05db\u05d0\u05d7\u05d5\u05d6 \u05e4\u05d7\u05de\u05df, \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc \u05db-58 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc \u05e1, \u05d5\u05de\u05d7\u05e9\u05de\u05e9\u05ea \u05dc\u05de\u05e1\u05d1\u05d9\u05dd \u05d5\u05dc\u05e9\u05e1\u05ea\u05d5\u05de\u05d9\u05dd."],[237.0,"\u05d4\u05de\u05d7\u05d9\u05e8: \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05dc\u05d4 \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05e0\u05de\u05d5\u05db\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05de\u05d1\u05d9\u05df \u05d4\u05de\u05e9\u05e4\u05d7\u05d5\u05ea."],[242.0,"\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d3\u05d5\u05e4\u05dc\u05e7\u05e1, \u05db\u05de\u05d5 2205, \u05de\u05e9\u05dc\u05d1\u05ea \u05d1\u05e2\u05e8\u05da \u05d7\u05e6\u05d9 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d5\u05d7\u05e6\u05d9 \u05e4\u05e8\u05d9\u05d8."],[249.0,"\u05d4\u05e9\u05d9\u05dc\u05d5\u05d1 \u05e0\u05d5\u05ea\u05df \u05d7\u05d5\u05d6\u05e7 \u05db\u05e0\u05d9\u05e2\u05d4 \u05db\u05e4\u05d5\u05dc \u05d1\u05e2\u05e8\u05da \u05de\u05d6\u05d4 \u05e9\u05dc 316, \u05d5\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d8\u05d5\u05d1\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d1\u05e4\u05d9\u05d8\u05d9\u05e0\u05d2 \u05d5\u05d1\u05e1\u05d3\u05d9\u05e7\u05d4 \u05ea\u05d7\u05ea \u05de\u05d0\u05de\u05e5."],[258.0,"\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4 \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4 \u05d4\u05db\u05d9\u05de\u05d9\u05ea, \u05d1\u05e6\u05e0\u05e8\u05ea, \u05d5\u05d1\u05de\u05ea\u05e7\u05e0\u05d9\u05dd \u05d9\u05de\u05d9\u05d9\u05dd."],[263.0,"\u05d4\u05d7\u05d9\u05e1\u05e8\u05d5\u05df: \u05d4\u05d9\u05d0 \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d5\u05dc\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05d4\u05e7\u05e4\u05d3\u05d4 \u05e2\u05dc \u05d4\u05dc\u05d9\u05da \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."],[270.0,"\u05d4\u05e14. \u05d4\u05d9\u05d0 \u05de\u05db\u05d9\u05dc\u05d4 \u05db\u05e8\u05d5\u05dd, \u05e0\u05d9\u05e7\u05dc \u05d5\u05e0\u05d7\u05d5\u05e9\u05ea, \u05d5\u05de\u05ea\u05e7\u05e9\u05d4 \u05d1\u05d4\u05d6\u05d3\u05e7\u05e0\u05d5\u05ea, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 4."],[282.0,"\u05d0, \u05d4\u05e8\u05da, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05d6\u05e7\u05e0\u05d9\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d7\u05e1\u05d9\u05ea, \u05d1\u05dc\u05d9 \u05d8\u05d1\u05d9\u05dc\u05d4, \u05e2\u05dd \u05e9\u05d9\u05e0\u05d5\u05d9 \u05de\u05d9\u05d3\u05d5\u05ea \u05e7\u05d8\u05df \u05de\u05d0\u05d5\u05d3."],[294.0,"\u05d4\u05d7\u05d6\u05e7 \u05d5\u05d4\u05e7\u05e9\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05db-40 \u05e2\u05d3 44 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc 11150 .06 \u05e8\u05da \u05d5\u05e7\u05e9\u05d5\u05d7 \u05d9\u05d5\u05ea\u05e8."],[307.0,"\u05dc\u05db\u05df \u05d4\u05d9\u05d0 \u05e0\u05e4\u05d5\u05e6\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05d1\u05ea\u05e2\u05e2\u05d5\u05d9\u05d9\u05d4 \u05d4\u05d1\u05d9\u05d8\u05d7\u05d5\u05e0\u05d9\u05ea \u05d5\u05d4\u05d0\u05d5\u05d5\u05d9\u05e8\u05d9\u05ea."],[313.0,"\u05d2\u05dd \u05dc\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d9\u05e9 \u05e6\u05d5\u05e8\u05d5\u05ea \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05de\u05e9\u05dc\u05d4."],[316.0,"\u05d1\u05e1\u05d1\u05d9\u05d1\u05d4 \u05e2\u05dd \u05db\u05dc\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd, \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05e4\u05e1\u05d9\u05d1\u05d9\u05ea \u05e0\u05e4\u05e8\u05e6\u05ea \u05d1\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d0\u05d7\u05ea, \u05d5\u05e0\u05d5\u05e6\u05e8 \u05d1\u05d5\u05e8 \u05e7\u05d8\u05df \u05e9\u05d7\u05d5\u05d3\u05e8 \u05e2\u05de\u05d5\u05e7."],[327.0,"\u05d7\u05de\u05e6\u05df, \u05dc\u05de\u05e9\u05dc \u05de\u05ea\u05d7\u05ea \u05dc\u05d0\u05d8\u05dd \u05d0\u05d5 \u05d1\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e6\u05de\u05d5\u05d3, \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05e4\u05e1\u05d9\u05d1\u05d9\u05ea \u05dc\u05d0 \u05e0\u05d1\u05e0\u05d9\u05ea \u05de\u05d7\u05d3\u05e9\u05e9."],[338.0,"\u05d4\u05e9\u05dc\u05d9\u05e9\u05d9\u05ea \u05d4\u05d9\u05d0 \u05e1\u05d3\u05d9\u05e7\u05d4 \u05ea\u05d7\u05ea \u05de\u05d0\u05de\u05e5 \u05d1\u05db\u05dc\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd, \u05d1\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05ea, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05de\u05e2\u05dc \u05db-60 \u05de\u05e2\u05dc\u05d5\u05ea."],[345.0,"\u05d4\u05db\u05e8\u05d5\u05dd, \u05d5\u05e2\u05d5\u05d3 \u05e4\u05d9 \u05e9\u05dc\u05d5\u05e9 \u05d5\u05e9\u05dc\u05d9\u05e9 \u05de\u05d0\u05d7\u05d5\u05d6 \u05d4\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05d5\u05e2\u05d5\u05d3 \u05e1\u05d9 \u05e9\u05e9 \u05e2\u05e9\u05e8\u05d4 \u05de\u05d0\u05d7\u05d5\u05d6 \u05d4\u05d7\u05e0\u05e7\u05df."],[357.0,"\u05dc-304 \u05d4\u05d5\u05d0 \u05db\u05e9\u05de\u05d5\u05e0\u05d4 \u05e2\u05e9\u05e8\u05d4, \u05dc-316 \u05d1\u05e2\u05e9\u05d5\u05e8\u05d9\u05dd \u05d5\u05d7\u05de\u05e9, \u05d5\u05dc-2205 \u05db\u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05d5\u05d7\u05de\u05e9."],[367.0,"\u05d1\u05d0\u05d9\u05e8\u05d5\u05e4\u05d4, \u05dc\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d9\u05e9 \u05de\u05e1\u05e4\u05e8\u05d9\u05dd \u05e9\u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05d1-1.4."],[371.0,"\u05de\u05e1\u05e4\u05e8 \u05d4\u05d7\u05d5\u05de\u05e8 \u05e9\u05dc 304 \u05d4\u05d5\u05d0 1.4301, \u05d5\u05e9\u05dc 3041 \u05d4\u05d5\u05d0 7. 316 \u05d4\u05d9\u05d0 1.4401, \u05d5\u05e8 3161 \u05d4\u05d9\u05d0 1.4404."],[391.0,"3 \u05d4\u05d9\u05d0 1.4305, 430 \u05d4\u05d9\u05d0 1.4016, 2205 \u05d4\u05d9\u05d0 2, \u05d5-\u05d4\u05e117-4 \u05d4\u05d9\u05d0 1.4542."],[411.0,"\u05de\u05d4 \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4? \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d7\u05d6\u05d9\u05e7 \u05d1\u05e0\u05e4\u05e8\u05d3 \u05de\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df."],[417.0,"\u05e9\u05d1\u05d1\u05d9\u05dd, \u05de\u05d1\u05e8\u05e9\u05d5\u05ea \u05d5\u05db\u05dc\u05d9\u05dd \u05e9\u05dc \u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05e2\u05dc\u05d9\u05d4 \u05d1\u05e8\u05d6\u05dc, \u05d5\u05d1\u05de\u05e7\u05d5\u05de\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05d4\u05d9\u05d0 \u05ea\u05d7\u05dc\u05d9\u05d3."],[424.0,"\u05d0\u05ea \u05d4\u05d1\u05e8\u05d6\u05dc \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d5\u05d1\u05d5\u05e0\u05d4 \u05de\u05d7\u05d3\u05e9\u05d5 \u05d0\u05ea \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05e4\u05e1\u05d9\u05d1\u05d9\u05ea."],[433.0,"\u05d5\u05d1\u05e0\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05d5\u05d2 \u05d4\u05de\u05d3\u05d5\u05d9\u05e7, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4."],[436.0,"\u05d5\u05e9\u05ea\u05d9\u05d4\u05df \u05d9\u05e7\u05e8\u05d5\u05ea \u05de-430. \u05d3\u05d5\u05e4\u05dc\u05e7\u05e1 \u2026 \u05d9\u05e7\u05e8\u05d5\u05ea \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8."],[450.0,"\u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d0\u05d9\u05d8\u05d9 \u05de\u05e9\u05dc \u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df, \u05d5\u05e4\u05e1\u05d9\u05d1\u05e6\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05e2\u05d5\u05d3 \u05e9\u05dc\u05d1 \u05d1\u05ea\u05d4\u05dc\u05d9\u05da."],[455.0,"\u05e9\u05dc\u05de\u05d4, \u05d5\u05d1\u05d7\u05d9\u05e8\u05ea \u05d4\u05e1\u05d5\u05d2 \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05ea \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea, \u05d4\u05d7\u05d5\u05d6\u05e7 \u05d5\u05d4\u05e2\u05dc\u05d5\u05ea. \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d9\u05e6\u05d5\u05e7."]]};
window.MH_TR["\u05e4\u05e8\u05e711_\u05d1\u05e8\u05d6\u05dc_\u05d9\u05e6\u05d5\u05e7"]={"t":"\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7","l":[[1.0,"\u05d5\u05d7\u05e6\u05d9 \u05e2\u05d3 \u05d0\u05e8\u05d1\u05e2\u05d4 \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd, \u05d5\u05e2\u05d5\u05d3 \u05d0\u05d7\u05d3 \u05e2\u05d3 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd \u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df."],[10.0,"\u05d1\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05ea \u05d1\u05e8\u05d6\u05dc \u05e4\u05d7\u05de\u05df \u05e9\u05d4\u05db\u05e8\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 3, \u05d4\u05d5\u05d0 \u05e0\u05de\u05e6\u05d0 \u05de\u05d9\u05de\u05d9\u05df \u05dc\u05d2\u05d1\u05d5\u05dc \u05e9\u05dc 2.1 \u05d0\u05d7\u05d5\u05d6, \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d4\u05d0\u05d5\u05d8\u05e7\u05d8\u05d9\u05ea."],[19.0,"\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05e0\u05de\u05e1 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 1,150 \u05e2\u05d3 1,250 \u05de\u05e2\u05dc\u05d5\u05ea, \u05e0\u05de\u05d5\u05da \u05d1\u05db\u05de\u05d4 \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea \u05de\u05e4\u05dc\u05d3\u05d4, \u05d5\u05d6\u05d5\u05e8\u05dd \u05d4\u05d9\u05d8\u05d1 \u05d1\u05ea\u05d1\u05e0\u05d9\u05ea."],[29.0,"\u05db\u05da \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d9\u05e6\u05d5\u05e7 \u05de\u05de\u05e0\u05d5 \u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d5\u05e8\u05db\u05d1\u05d9\u05dd, \u05e2\u05dd \u05d7\u05dc\u05dc\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd, \u05d1\u05d6\u05d5\u05dc."],[34.0,"\u05d1\u05dc\u05d5\u05e7\u05d9\u05dd \u05e9\u05dc \u05de\u05e0\u05d5\u05e2\u05d9\u05dd, \u05d1\u05ea\u05d9 \u05de\u05e9\u05d0\u05d1\u05d5\u05ea, \u05e9\u05d5\u05dc\u05d7\u05e0\u05d5\u05ea \u05e9\u05dc \u05de\u05db\u05d5\u05e0\u05d5\u05ea, \u05d5\u05d3\u05d9\u05e1\u05e7\u05d9\u05d5\u05ea \u05d1\u05dc\u05de\u05d9\u05dd, \u05db\u05d5\u05dc\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7."],[43.0,"\u05d4\u05d4\u05d1\u05d3\u05dc \u05d1\u05d9\u05df \u05e1\u05d5\u05d2\u05d9 \u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d9\u05e6\u05d5\u05e7 \u05dc\u05d0 \u05e0\u05de\u05e6\u05d0 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05d4\u05e8\u05db\u05d1, \u05d0\u05dc\u05d0 \u05d1\u05e6\u05d5\u05e8\u05d4 \u05e9\u05d1\u05d4 \u05d4\u05e4\u05d7\u05de\u05df \u05de\u05d5\u05e4\u05d9\u05e2."],[49.0,"\u05d1\u05e6\u05d5\u05e8\u05ea \u05e4\u05ea\u05d9\u05ea\u05d9\u05dd, \u05d0\u05d5 \u05d1\u05e6\u05d5\u05e8\u05ea \u05db\u05d3\u05d5\u05e8\u05d9\u05d5\u05ea, \u05d4\u05d5\u05d0 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05dc\u05d7\u05dc\u05d5\u05d8\u05d9\u05df."],[59.0,"\u05d1\u05d1\u05e8\u05d6\u05dc \u05d4\u05d0\u05e4\u05d5\u05e8 \u05d4\u05d2\u05e8\u05e4\u05d9\u05d8 \u05d4\u05d5\u05d0 \u05e4\u05ea\u05d9\u05ea\u05d9\u05dd. \u05d1\u05d1\u05e8\u05d6\u05dc \u05d4\u05e0\u05d5\u05d3\u05d5\u05dc\u05e8\u05d9 \u05d4\u05d5\u05d0 \u05db\u05d3\u05d5\u05e8\u05d9\u05d5\u05ea. \u05d1-\u05d560 \u05d4\u05d5\u05d0 \u05d1\u05e6\u05d5\u05e8\u05ea \u05d1\u05d9\u05e0\u05d9\u05d9\u05dd, \u05db\u05de\u05d5 \u05ea\u05d5\u05dc\u05e2\u05d9\u05dd \u05e7\u05e6\u05e8\u05d5\u05ea."],[69.0,"\u05d5\u05d1\u05d1\u05e8\u05d6\u05dc \u05d4\u05dc\u05d1\u05df \u05d0\u05d9\u05df \u05d2\u05e8\u05e4\u05d9\u05d8 \u05d1\u05db\u05dc\u05dc, \u05d5\u05d4\u05e4\u05d7\u05de\u05df \u05e7\u05e9\u05d5\u05e8 \u05d1\u05e6\u05de\u05e0\u05d8\u05d9\u05d8."],[74.0,"\u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d9\u05e6\u05d5\u05e7 \u05d4\u05d0\u05e4\u05d5\u05e8 \u05d4\u05d5\u05d0 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8. \u05d4\u05e9\u05dd \u05d1\u05d0 \u05de\u05e6\u05d1\u05e2 \u05d4\u05e9\u05d1\u05e8 \u05e9\u05dc\u05d5."],[80.0,"\u05d4\u05d0\u05e4\u05d5\u05e8 \u05e4\u05e8\u05d9\u05da, \u05e2\u05dd \u05d4\u05ea\u05d0\u05e8\u05db\u05d5\u05ea \u05e9\u05dc \u05e4\u05d7\u05d5\u05ea \u05de\u05d0\u05d7\u05d5\u05d6, \u05d5\u05d7\u05d5\u05d6\u05e7 \u05de\u05ea\u05d9\u05d7\u05d4 \u05e0\u05de\u05d5\u05da \u05d9\u05d7\u05e1\u05d9\u05ea."],[94.0,"\u05d0\u05d1\u05dc \u05d1\u05dc\u05d7\u05d9\u05e6\u05d4 \u05d4\u05d5\u05d0 \u05d7\u05d6\u05e7 \u05e4\u05d9 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e2\u05d3 \u05d0\u05e8\u05d1\u05e2\u05d4. \u05d5\u05d9\u05e9 \u05dc\u05d5 \u05d9\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea \u05e9\u05d0\u05d9\u05df \u05dc\u05e4\u05dc\u05d3\u05d4."],[100.0,"\u05e9\u05dc \u05de\u05db\u05d5\u05e0\u05d5\u05ea. \u05d4\u05d5\u05d0 \u05de\u05d5\u05dc\u05d9\u05da \u05d7\u05d5\u05dd \u05d4\u05d9\u05d8\u05d1, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d3\u05d9\u05e1\u05e7\u05d9\u05d5\u05ea \u05d1\u05dc\u05de\u05d9\u05dd."],[110.0,"\u05d5\u05d4\u05d2\u05e8\u05e4\u05d9\u05d8 \u05e1\u05da \u05d0\u05ea \u05d4\u05db\u05dc\u05d9 \u05d5\u05e9\u05d5\u05d1\u05e8 \u05d0\u05ea \u05d4\u05e9\u05d1\u05d1, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05e0\u05d5\u05d7 \u05de\u05d0\u05d5\u05d3 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3."],[115.0,"\u05dc\u05e4\u05e0\u05d9 \u05d4\u05d9\u05e6\u05d9\u05e7\u05d4, \u05d4\u05d2\u05e8\u05e4\u05d9\u05d8 \u05de\u05ea\u05e2\u05d2\u05dc \u05d5\u05e0\u05d5\u05e6\u05e8\u05d5\u05ea \u05db\u05d3\u05d5\u05e8\u05d9\u05d5\u05ea \u05d1\u05de\u05e7\u05d5\u05dd \u05e4\u05ea\u05d9\u05ea\u05d9\u05dd."],[125.0,"\u05dc\u05de\u05e9\u05d9\u05da. \u05d6\u05d4 \u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d9\u05e6\u05d5\u05e7 \u05d4\u05e0\u05d5\u05d3\u05d5\u05dc\u05e8\u05d9, \u05e9\u05e0\u05e7\u05e8\u05d0 \u05d2\u05dd \u05d1\u05e8\u05d6\u05dc \u05de\u05e9\u05d9\u05da."],[135.0,"\u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc\u05d5 \u05db\u05e4\u05d5\u05dc \u05d1\u05e2\u05e8\u05da \u05de\u05d6\u05d4 \u05e9\u05dc \u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d0\u05e4\u05d5\u05e8, \u05d5\u05d4\u05d4\u05ea\u05d0\u05e8\u05db\u05d5\u05ea \u05e9\u05dc\u05d5 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05d7\u05de\u05e9 \u05e2\u05e9\u05e8\u05d4 \u05d0\u05d7\u05d5\u05d6 \u05d5\u05d9\u05d5\u05ea\u05e8."],[142.0,"\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05de\u05d7\u05dc\u05d9\u05e3 \u05e4\u05dc\u05d3\u05d4 \u05de\u05d7\u05d5\u05e9\u05dc\u05ea \u05d1\u05d4\u05e8\u05d1\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd: \u05d2\u05dc\u05d9 \u05d0\u05e8\u05db\u05d5\u05d1\u05d4, \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d7\u05dc\u05e7\u05d9 \u05de\u05ea\u05dc\u05d4, \u05d5\u05e6\u05e0\u05e8\u05ea \u05de\u05d9\u05dd."],[151.0,"\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05d6\u05e7 \u05d0\u05ea \u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05e0\u05d5\u05d3\u05d5\u05dc\u05e8\u05d9 \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05de\u05d9\u05d5\u05d7\u05d3 \u05e9\u05e0\u05e7\u05e8\u05d0 \u05d0\u05d5\u05e1\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2. \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05d4\u05d9\u05d0 \u05d1\u05e8\u05d6\u05dc \u05d5\u05e1\\)."],[160.0,"\u05d1\u05e8\u05d6\u05dc\u05d5\u05e1) \u05e2\u05d5\u05d1\u05e8 \u05d0\u05d5\u05e1\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2, \u05d5\u05d7\u05d5\u05d6\u05e7\u05d5 \u05e2\u05d5\u05dc\u05d4 \u05de\u05d0\u05d5\u05d3, \u05dc\u05e8\u05de\u05d4 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d5\u05e9\u05d1\u05d7\u05d5\u05ea."],[167.0,"\u05d9\u05d5\u05ea\u05e8. \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d5 \u05d1\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05dc \u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d7\u05e7\u05dc\u05d0\u05d9\u05d5\u05ea \u05d5\u05db\u05d1\u05d3\u05d5\u05ea."],[177.0,"\u05e7\u05e9\u05d5\u05e8 \u05d1\u05e6\u05de\u05e0\u05d8\u05d9\u05d8. \u05d6\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05db\u05e9\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05de\u05d4\u05e8, \u05d0\u05d5 \u05db\u05e9\u05d9\u05e9 \u05de\u05e2\u05d8 \u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df."],[188.0,"\u05d1\u05e9\u05d7\u05d9\u05e7\u05d4, \u05d0\u05d1\u05dc \u05e4\u05e8\u05d9\u05da \u05de\u05d0\u05d5\u05d3, \u05d5\u05db\u05de\u05e2\u05d8 \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05d1\u05d3 \u05d0\u05d5\u05ea\u05d5 \u05d1\u05db\u05dc\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da, \u05e8\u05e7 \u05d1\u05d4\u05e9\u05d7\u05d6\u05d4."],[198.0,"\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d5 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e0\u05e9\u05d7\u05e7\u05d9\u05dd, \u05db\u05de\u05d5 \u05e6\u05d9\u05e4\u05d5\u05d9\u05d9\u05dd \u05e9\u05dc \u05de\u05d8\u05d7\u05e0\u05d5\u05ea \u05d5\u05de\u05e9\u05d0\u05d1\u05d5\u05ea \u05dc\u05d1\u05d5\u05e5."],[204.0,"\u05de\u05ea\u05e4\u05e8\u05e7 \u05dc\u05d2\u05e8\u05e4\u05d9\u05d8 \u05d1\u05e6\u05d5\u05e8\u05ea \u05d2\u05d5\u05e9\u05d9\u05dd, \u05d5\u05d4\u05d7\u05d5\u05de\u05e8 \u05e0\u05e2\u05e9\u05d4 \u05de\u05e9\u05d9\u05da. \u05d6\u05d4 \u05d1\u05e8\u05d6\u05dc \u2026."],[214.0,"\u05d1\u05e2\u05d1\u05e8 \u05d4\u05d5\u05d0 \u05d4\u05d9\u05d4 \u05e0\u05e4\u05d5\u05e5 \u05d1\u05d0\u05d1\u05d9\u05d6\u05e8\u05d9 \u05e6\u05e0\u05e8\u05ea, \u05d5\u05d4\u05d9\u05d5\u05dd \u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05e0\u05d5\u05d3\u05d5\u05dc\u05e8\u05d9 \u05d4\u05d7\u05dc\u05d9\u05e3 \u05d0\u05d5\u05ea\u05d5 \u05db\u05de\u05e2\u05d8 \u05dc\u05d2\u05de\u05e8\u05d9."],[222.0,"\u05d560 \u05e0\u05de\u05e6\u05d0 \u05d1\u05d0\u05de\u05e6\u05e2, \u05d1\u05d9\u05df \u05d4\u05d0\u05e4\u05d5\u05e8 \u05dc\u05e0\u05d5\u05d3\u05d5\u05dc\u05e8\u05d9."],[226.0,"\u05d4\u05d5\u05d0 \u05d7\u05d6\u05e7 \u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d0\u05e4\u05d5\u05e8, \u05d5\u05e2\u05d3\u05d9\u05d9\u05df \u05e9\u05d5\u05de\u05e8 \u05e2\u05dc \u05de\u05d5\u05dc\u05d9\u05db\u05d5\u05ea \u05d7\u05d5\u05dd \u05d8\u05d5\u05d1\u05d4 \u05d5\u05e2\u05dc \u05e8\u05d9\u05e1\u05d5\u05df \u05e8\u05e2\u05d9\u05d3\u05d5\u05ea."],[232.0,"\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05d4\u05e4\u05da \u05dc\u05d7\u05d5\u05de\u05e8 \u05d4\u05de\u05d5\u05e2\u05d3\u05e3 \u05dc\u05d1\u05dc\u05d5\u05e7\u05d9\u05dd \u05d5\u05dc\u05e8\u05d0\u05e9\u05d9\u05dd \u05e9\u05dc \u05de\u05e0\u05d5\u05e2\u05d9 \u05d3\u05d9\u05d6\u05dc \u05db\u05d1\u05d3\u05d9\u05dd, \u05e9\u05d1\u05d4\u05dd \u05d4\u05dc\u05d7\u05e6\u05d9\u05dd \u05d2\u05d1\u05d5\u05d4\u05d9\u05dd."],[240.0,"\u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05d9\u05e8\u05d5\u05e4\u05d9, \u05d4\u05e9\u05dd \u05e9\u05dc \u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d9\u05e6\u05d5\u05e7 \u05d0\u05d5\u05de\u05e8 \u05de\u05d4 \u05e1\u05d5\u05d2 \u05d4\u05d2\u05e8\u05e4\u05d9\u05d8."],[245.0,"\u05d0\u05e1 \u05d4\u05d5\u05d0 \u05d0\u05e4\u05d5\u05e8, \u05de\u05d2\u05e8\u05e1\u05d9\u05d8 \u05e4\u05ea\u05d9\u05ea\u05d9. GIS \u05d4\u05d5\u05d0 \u05e0\u05d5\u05d3\u05d5\u05dc\u05e8\u05d9, \u05de\u05d2\u05e8\u05e4\u05d9\u05d8 \u05db\u05d3\u05d5\u05e8\u05d9. \u05e6'\u05d8\u05e1 \u05d4\u05d5\u05d0 \u05d560, -\u05d5\u05d0\u05e0\u05e1 \u05d4\u05d5\u05d0 .malleable"],[257.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05d1\u05d0\u05d9\u05dd \u05d4\u05de\u05e1\u05e4\u05e8\u05d9\u05dd. \u05d1\u05d1\u05e8\u05d6\u05dc \u05d0\u05e4\u05d5\u05e8, GJL-250 \u05d0\u05d5\u05de\u05e8 \u05d7\u05d5\u05d6\u05e7 \u05de\u05ea\u05d9\u05d7\u05d4 \u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9 \u05e9\u05dc 250 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc."],[267.0,"\u05d1\u05d1\u05e8\u05d6\u05dc \u05e0\u05d5\u05d3\u05d5\u05dc\u05e8\u05d9 \u05d9\u05e9 \u05e9\u05e0\u05d9 \u05de\u05e1\u05e4\u05e8\u05d9\u05dd: GJS-400-15 \u05d0\u05d5\u05de\u05e8 400 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc, \u05d5\u05d4\u05ea\u05d0\u05e8\u05db\u05d5\u05ea \u05e9\u05dc 15 \u05d0\u05d7\u05d5\u05d6."],[276.0,"\u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e9\u05d9\u05d8\u05d4 \u05d3\u05d5\u05de\u05d4, \u05d0\u05d1\u05dc \u05d1\u05d9\u05d7\u05d9\u05d3\u05d5\u05ea \u05d0\u05d7\u05e8\u05d5\u05ea."],[282.0,"\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9 \u05e9\u05dc \u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7 \u05e9\u05d5\u05e0\u05d4 \u05de\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d4."],[286.0,"\u05d4\u05de\u05e2\u05d1\u05e8 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05e6\u05e8\u05d9\u05da \u05dc\u05d7\u05ea\u05d5\u05da \u05de\u05ea\u05d7\u05ea\u05d9\u05d4, \u05d5\u05dc\u05d0 \u05dc\u05d4\u05d7\u05dc\u05d9\u05e7 \u05e2\u05dc\u05d9\u05d4."],[295.0,"\u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d0\u05e4\u05d5\u05e8 \u05d9\u05d5\u05e6\u05e8 \u05d5 \u05d0\u05d1\u05e7\u05ea \u05d2\u05e8\u05e4\u05d9\u05d8 \u05d5 \u05d1\u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d1\u05d9\u05dd, \u05d5\u05dc\u05db \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d9\u05d1\u05e9, \u05e2\u05dd \u05d9\u05e0\u05d9\u05e7\u05d4."],[303.0,"\u05d1\u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea, \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05de\u05d4\u05d9\u05e8 \u05d1\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d9\u05d5\u05e6\u05e8 \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05e9\u05dc \u05d1\u05e8\u05d6\u05dc \u05dc\u05d1\u05df, \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05e7\u05e9\u05d5\u05ea \u05e9\u05e9\u05d5\u05d1\u05e8\u05d5\u05ea \u05db\u05dc\u05d9\u05dd."],[311.0,"\u05d5\u05e8\u05d9\u05ea\u05d5\u05da \u05e9\u05dc \u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7 \u05e7\u05e9\u05d4: \u05d4\u05d5\u05d0 \u05e4\u05e8\u05d9\u05da, \u05e0\u05e1\u05d3\u05e7 \u05d1\u05e7\u05dc\u05d5\u05ea, \u05d5\u05d3\u05d5\u05e8\u05e9 \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05d5\u05e7\u05d3\u05dd \u05d5\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05e0\u05d9\u05e7\u05dc."],[320.0,"\u05ea\u05d5\u05e1\u05e4\u05d5\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d5\u05e2\u05dd \u05e1\u05d8\u05d9\u05d5\u05ea \u05e9\u05dc \u05d4\u05d9\u05e6\u05d9\u05e7\u05d4, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d0\u05d5\u05ea\u05d5 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3."],[329.0,"\u05d5\u05dc\u05e9\u05d9\u05dd \u05dc\u05d1 \u05dc\u05d7\u05d5\u05e8\u05d9\u05dd \u05d5\u05dc\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05e9\u05e0\u05d7\u05e9\u05e4\u05d9\u05dd \u05d1\u05d6\u05de\u05df \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3."],[333.0,"\u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05d4\u05d9\u05e6\u05d9\u05e7\u05d4 \u05e2\u05e6\u05de\u05d4 \u05d6\u05d5\u05dc\u05d4 \u05dc\u05e7\u05d9\u05dc\u05d5, \u05d0\u05d1\u05dc \u05d3\u05d5\u05e8\u05e9\u05ea \u05ea\u05d1\u05e0\u05d9\u05ea \u05d5\u05d3\u05d2\u05dd, \u05d5\u05de\u05e9\u05ea\u05dc\u05de\u05ea \u05e8\u05e7 \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea."],[341.0,"\u05d3\u05e8\u05d9\u05e9\u05d4 \u05dc\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05dc\u05d0 \u05d4\u05d5\u05e8\u05e1\u05d5\u05ea, \u05dc\u05d1\u05d3\u05d9\u05e7\u05ea \u05e9\u05d9\u05e2\u05d5\u05e8 \u05d4\u05db\u05d3\u05d5\u05e8\u05d9\u05d5\u05ea \u05d1\u05d1\u05e8\u05d6\u05dc \u05e0\u05d5\u05d3\u05d5\u05dc\u05e8\u05d9, \u05d0\u05d5 \u05dc\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05db\u05de\u05d5 \u05d5\u05dd), \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05e2\u05dc\u05d5\u05ea."],[350.0,"\u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d7\u05dc\u05e7 \u05e9\u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05de\u05de\u05d5\u05d8 \u05e4\u05dc\u05d3\u05d4 \u05d1\u05db\u05de\u05d5\u05ea \u05e7\u05d8\u05e0\u05d4 \u05d6\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8 \u05de\u05d9\u05e6\u05d9\u05e7\u05d4."],[356.0,"\u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d9\u05e6\u05d5\u05e7. \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05dc\u05de\u05ea\u05db\u05d5\u05ea \u05d4\u05dc\u05d0 \u05d1\u05e8\u05d6\u05dc\u05d9\u05d5\u05ea, \u05d5\u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd."]]};
window.MH_TR["\u05e4\u05e8\u05e712_\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd"]={"t":"\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd","l":[[1.0,"\u05d5\u05d7\u05e9\u05de\u05dc \u05d4\u05d9\u05d8\u05d1, \u05d5\u05d0\u05d9\u05e0\u05d5 \u05de\u05d7\u05dc\u05d9\u05d3, \u05db\u05d9 \u05e9\u05db\u05d1\u05ea \u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05d3\u05e7\u05d4 \u05d5\u05e7\u05e9\u05d4 \u05e0\u05d5\u05e6\u05e8\u05ea \u05e2\u05dc\u05d9\u05d5 \u05de\u05e2\u05e6\u05de\u05d4."],[11.0,"\u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 1, \u05d4\u05de\u05d1\u05e0\u05d4 \u05e9\u05dc\u05d5 666, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05e0\u05e2\u05e9\u05d4 \u05e4\u05e8\u05d9\u05da \u05d1\u05e7\u05d5\u05e8."],[18.0,"\u05db\u05e9\u05dc\u05d9\u05e9 \u05de\u05d6\u05d4 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d4, \u05d5\u05dc\u05db\u05df \u05d7\u05dc\u05e7 \u05de\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05ea\u05db\u05d5\u05e4\u05e3 \u05d9\u05d5\u05ea\u05e8."],[26.0,"\u05e9\u05dc \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea \u05d1\u05d5\u05d3\u05d3\u05d5\u05ea. \u05d5\u05d0\u05d9\u05df \u05dc\u05d5 \u05d2\u05d1\u05d5\u05dc \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 2."],[37.0,"\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05ea\u05d7\u05dc\u05e7\u05d5\u05ea \u05dc\u05e9\u05d5\u05ea\u05d9 \u05de\u05e9\u05e4\u05d7\u05d5\u05ea, \u05dc\u05e4\u05d9 \u05d4\u05d3\u05e8\u05da \u05e9\u05d1\u05d4 \u05de\u05d7\u05d6\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05df."],[42.0,"\u05d1\u05d4\u05e7\u05e9\u05d7\u05ea \u05de\u05e9\u05e7\u05e2, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 4: \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4, \u05e7\u05d9\u05e8\u05d5\u05d4 \u05d5\u05d4\u05d6\u05d3\u05e7\u05e0\u05d5\u05ea."],[53.0,"\u05d0\u05dc\u05d4 \u05e1\u05d3\u05e8\u05d5\u05ea \u05d0\u05dc\u05e4\u05d9\u05dd, \u05e9\u05e9\u05ea \u05d0\u05dc\u05e4\u05dc\u05d9\u05dd \u05d5\u05e9\u05d1\u05e2\u05ea \u05d0\u05dc\u05e4\u05d9\u05dd."],[57.0,"\u05d0\u05d5\u05ea\u05d4 \u05e8\u05e7 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8. \u05d0\u05dc\u05d4 \u05e1\u05d3\u05e8\u05d5\u05ea \u05d0\u05dc\u05e3, \u05e9\u05dc\u05d5\u05e9\u05ea \u05d0\u05dc\u05e4\u05d9\u05dd \u05d5\u05d7\u05de\u05e9\u05ea \u05d0\u05dc\u05e4\u05d9\u05dd."],[66.0,"\u05d4\u05d4\u05d1\u05d3\u05dc \u05d4\u05d6\u05d4 \u05e7\u05d5\u05d1\u05e2 \u05d4\u05db\u05dc: \u05d0\u05ea \u05d4\u05d8\u05de\u05e4\u05e8, \u05d0\u05ea \u05d4\u05d4\u05ea\u05e0\u05d4\u05d2\u05d5\u05ea \u05d1\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05d0\u05ea \u05de\u05d4 \u05e9\u05e7\u05d5\u05e8\u05d4 \u05dc\u05d7\u05dc\u05e7 \u05db\u05e9\u05d5\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5."],[74.0,"\u05dc\u05db\u05dc \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d9\u05e9 \u05de\u05e1\u05e4\u05e8 \u05e9\u05dc \u05d0\u05e8\u05d1\u05e2 \u05e1\u05e4\u05e8\u05d5\u05ea, \u05d5\u05d4\u05e1\u05e4\u05e8\u05d4 \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05d0\u05d5\u05de\u05e8\u05ea \u05de\u05d4 \u05d4\u05d9\u05e1\u05d5\u05d3 \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9."],[80.0,"\u05e1\u05d3\u05e8\u05ea \u05d0\u05dc\u05e3 \u05d4\u05d9\u05d0 \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d8\u05d4\u05d5\u05e8, \u05de\u05e2\u05dc \u05ea\u05e9\u05e2\u05d9\u05dd \u05d5\u05ea\u05e9\u05e2\u05d4 \u05d0\u05d7\u05d5\u05d6: \u05de\u05d5\u05dc\u05d9\u05da \u05de\u05e6\u05d5\u05d9\u05df \u05d5\u05e2\u05de\u05d9\u05d3 \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05d0\u05d1\u05dc \u05e8\u05da."],[89.0,"\u05e1\u05d3\u05e8\u05ea \u05d0\u05dc\u05e4\u05d9\u05d9\u05dd \u05d4\u05d9\u05d0 \u05e2\u05dd \u05e0\u05d7\u05d5\u05e9\u05ea: \u05d7\u05d6\u05e7\u05d4, \u05e2\u05de\u05d9\u05d3\u05d4 \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea, \u05d0\u05d1\u05dc \u05e8\u05d2\u05d9\u05e9\u05d4 \u05dc\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."],[95.0,"\u05d7\u05d5\u05dd. \u05e1\u05d3\u05e8\u05ea \u05d0\u05e8\u05d1\u05e2\u05ea \u05d0\u05dc\u05e4\u05d9\u05dd \u05d4\u05d9\u05d0 \u05e2\u05dd \u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05d7\u05d5\u05d8\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da."],[105.0,"\u05e1\u05d3\u05e8\u05ea \u05d7\u05de\u05e9\u05ea \u05d0\u05dc\u05dc\u05d9\u05dd \u05d4\u05d9\u05d0 \u05e2\u05dd \u05de\u05d2\u05e0\u05d6\u05d9\u05d5\u05dd: \u05e2\u05de\u05d9\u05d3\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05d5\u05e0\u05d5\u05d7\u05d4 \u05dc\u05e8\u05d9\u05ea\u05d5\u05da."],[111.0,"\u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc\u05d9\u05dd \u05d5\u05dc\u05e2\u05d9\u05d1\u05d5\u05d3. \u05d5\u05e1\u05d3\u05e8\u05ea \u05e9\u05d1\u05e2\u05ea \u05d0\u05dc\u05e4\u05d9\u05dd \u05d4\u05d9\u05d0 \u05e2\u05dd \u05d0\u05d1\u05e5, \u05d4\u05d7\u05d6\u05e7\u05d4 \u05de\u05db\u05d5\u05dc\u05df."],[122.0,"\u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4 \u05d4\u05d9\u05d0 6061 \u05d1\u05de\u05e6\u05d1 16."],[128.0,"\u05d5\u05dc\u05d0\u05e0\u05d5\u05d3\u05d9\u05d6\u05e6\u05d9\u05d4, \u05d5\u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05d7\u05d5\u05d6\u05e7 \u05db\u05e0\u05d9\u05e2\u05d4 \u05e9\u05dc \u05db-276 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc."],[138.0,"\u05d1\u05d0\u05d9\u05e8\u05d5\u05e4\u05d4 \u05d4\u05de\u05e7\u05d1\u05d9\u05dc\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 6082, \u05e9\u05de\u05e9\u05de\u05e9\u05ea \u05dc\u05d0\u05d5\u05ea\u05dd \u05e9\u05d9\u05de\u05d5\u05e9\u05d9\u05dd, \u05d1\u05d7\u05d5\u05d6\u05e7 \u05d3\u05d5\u05de\u05d4 \u05d5\u05d0\u05e3 \u05de\u05e2\u05d8 \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8."],[146.0,"3 \u05e8\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05de\u05e9\u05de\u05e9\u05ea \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc\u05d9\u05dd \u05d0\u05d3\u05e8\u05d9\u05db\u05dc\u05d9\u05d9\u05dd."],[153.0,"\u05db\u05e9\u05e6\u05e8\u05d9\u05da \u05d7\u05d5\u05d6\u05e7 \u05d2\u05d1\u05d5\u05d4 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3, \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05dc\u05e1\u05d3\u05e8\u05d5\u05ea \u05d0\u05dc\u05e4\u05d9\u05dd \u05d5\u05e9\u05d1\u05e2\u05ea \u05d0\u05dc\u05e4\u05d9\u05dd."],[157.0,"5 \u05d1\u05de\u05e6\u05d1 16 \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05d7\u05d5\u05d6\u05e7 \u05db\u05e0\u05d9\u05e2\u05d4 \u05e9\u05dc \u05db-500 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc, \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e4\u05dc\u05d3\u05d4 \u05de\u05d5\u05e9\u05d1\u05d7\u05ea, \u05d5\u05d1\u05e9\u05dc\u05d9\u05e9 \u05de\u05d4\u05de\u05e9\u05e7\u05dc."],[168.0,"\u05d1\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05db\u05e0\u05d9\u05d9\u05dd \u05e2\u05de\u05d5\u05e1\u05d9\u05dd. 2024 \u05e2\u05de\u05d9\u05d3\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea, \u05d5\u05de\u05e9\u05de\u05e9\u05ea \u05d1\u05d2\u05d5\u05e3 \u05d4\u05de\u05d8\u05d5\u05e1."],[181.0,"\u05d5\u05dc\u05db\u05df \u05e4\u05d7\u05d9\u05dd \u05e9\u05dc 2024 \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d1\u05e6\u05d9\u05e4\u05d5\u05d9 \u05e9\u05dc \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d8\u05d4\u05d5\u05e8, Alclad"],[192.0,"\u05db\u05de\u05e2\u05d8 \u05d0\u05d9 \u05d0\u05e4\u05e9\u05d5\u05e8 \u05dc\u05e8\u05ea\u05da \u05d0\u05d5\u05ea\u05df \u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05d9\u05ea\u05d5\u05da. \u05d5-7075 \u05d1\u05de\u05e6\u05d1 6\u05d6 \u05e8\u05d2\u05d9\u05e9\u05d4 \u05dc\u05e1\u05d3\u05d9\u05e7\u05d4 \u05ea\u05d7\u05ea \u05de\u05d0\u05de\u05e5."],[202.0,"\u05d9\u05ea\u05e8 \u05de\u05db\u05d5\u05d5\u05e0\u05ea: \u05d4\u05d5\u05d0 \u05de\u05e2\u05d8 \u05e4\u05d7\u05d5\u05ea \u05d7\u05d6\u05e7, \u05d0\u05d1\u05dc \u05e2\u05de\u05d9\u05d3 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05e1\u05d3\u05d9\u05e7\u05d4."],[213.0,"\u05e1\u05d3\u05e8\u05ea \u05d7\u05de\u05e9\u05ea \u05d0\u05dc\u05e4\u05d9\u05dd \u05d4\u05d9\u05d0 \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05dc\u05e1\u05d1\u05d9\u05d1\u05d4 \u05d9\u05de\u05d9\u05ea \u05d5\u05dc\u05de\u05d1\u05e0\u05d9\u05dd \u05de\u05e8\u05d5\u05ea\u05db\u05d9\u05dd."],[218.0,"3 \u05d5-5754 \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05d0\u05d5\u05d3 \u05d1\u05de\u05d9 \u05d9\u05dd, \u05d5\u05e0\u05e9\u05d0\u05e8\u05d5\u05ea \u05d7\u05d6\u05e7\u05d5\u05ea \u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da, \u05db\u05d9 \u05d4\u05df \u05dc\u05d0 \u05ea\u05dc\u05d5\u05d9\u05d5\u05ea \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd."],[229.0,"\u05d4\u05d8\u05de\u05e4\u05e8 \u05e9\u05dc\u05d4\u05df \u05de\u05e1\u05d5\u05de\u05df \u05d1\u05d0\u05d5\u05ea \u05d5. \u05dc\u05de\u05e9\u05dc, H32 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8 \u05d5\u05d0\u05d7\u05e8\u05d9\u05d5 \u05d9\u05d9\u05e6\u05d5\u05d1, \u05d1\u05e8\u05de\u05d4 \u05e9\u05dc \u05e8\u05d1\u05e2 \u05e7\u05e9\u05d4."],[239.0,"\u05d4\u05d8\u05de\u05e4\u05e8 \u05d4\u05d5\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d4\u05e9\u05dd, \u05d5\u05d1\u05dc\u05e2\u05d3\u05d9\u05d5 \u05d4\u05d4\u05d2\u05d3\u05e8\u05d4 \u05d7\u05e1\u05e8\u05d4."],[244.0,"6 \u05d4\u05d5\u05d0 \u05db\u05de\u05d5 \u05e9\u05d9\u05d5\u05e6\u05e8, \u05d1\u05dc\u05d9 \u05d1\u05e7\u05e8\u05d4. 0 \u05d4\u05d5\u05d0 \u05e8\u05da, \u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05db\u05d5\u05da. \u05d4 \u05d4\u05d5\u05d0 \u05de\u05d5\u05e7\u05e9\u05d4 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8. \u05d5-1 \u05d4\u05d5\u05d0 \u05de\u05d8\u05d5\u05e4\u05dc \u05d1\u05d7\u05d5\u05dd."],[255.0,"\u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4, \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8 \u05d5\u05d4\u05d6\u05d3\u05e7\u05e0\u05d5\u05ea \u05d8\u05d1\u05e2\u05d9\u05ea. 14 \u05d4\u05d5\u05d0 \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4 \u05d5\u05d4\u05d6\u05d3\u05e7\u05e0\u05d5\u05ea \u05d8\u05d1\u05e2\u05d9\u05ea."],[267.0,"\u05d1\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc\u05d9\u05dd. 16 \u05d4\u05d5\u05d0 \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4 \u05d5\u05d4\u05d6\u05d3\u05e7\u05e0\u05d5\u05ea \u05de\u05dc\u05d0\u05db\u05d5\u05ea\u05d9\u05ea. \u05d5-7 \u05d3 \u05d4\u05d5\u05d0 \u05d4\u05d6\u05d3\u05e7\u05e0\u05d5\u05ea \u05d9\u05ea\u05e8 \u05de\u05db\u05d5\u05d5\u05e0\u05ea."],[280.0,"\u05d5\u05e2\u05db\u05e9\u05d9\u05d5 \u05d4\u05d7\u05dc\u05e7 \u05d4\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4: \u05d4\u05e1\u05e4\u05e8\u05d5\u05ea 51 \u05e9\u05d0\u05d7\u05e8\u05d9, \u05db\u05de\u05d5 \u05d1-1651 \u2026."],[291.0,"\u05d4\u05df \u05d0\u05d5\u05de\u05e8\u05d5\u05ea \u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05e0\u05de\u05ea\u05d7 \u05d1\u05d0\u05d7\u05d7\u05d9\u05dd \u05d1\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8, \u05db\u05d3\u05d9 \u05dc\u05e9\u05d7\u05e8\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd."],[297.0,"\u05d5\u05dc\u05db\u05df \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05de\u05d6\u05de\u05d9\u05e0\u05d9\u05dd \u05db\u05de\u05e2\u05d8 \u05ea\u05de\u05d9\u05d3 1651 \u05d5\u05dc\u05d0 6 \u05d1\u05dc\u05d1\u05d3."],[310.0,"\u05d4\u05e8\u05d1\u05d4 \u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df, \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d4\u05d0\u05d5\u05d8\u05e7\u05d8\u05d9\u05ea \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 3."],[318.0,"6 \u05d4\u05d9\u05d0 \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d9\u05e6\u05d9\u05e7\u05d4 \u05e0\u05e4\u05d5\u05e6\u05d4, \u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d8\u05e4\u05dc \u05d1\u05d4 \u05d1\u05d7\u05d5\u05dd \u05dc-16, \u05d5\u05de\u05e9\u05de\u05e9\u05ea \u05dc\u05d7\u05d9\u05e9\u05d5\u05e7\u05d9\u05dd \u05d5\u05dc\u05d1\u05ea\u05d9 \u05e6\u05d9\u05d5\u05d3."],[328.0,"\u05d1\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d1\u05dc\u05d7\u05e5, \u05dc\u05d1\u05ea\u05d9 \u05de\u05db\u05e9\u05d9\u05e8\u05d9\u05dd \u05d5\u05dc\u05d7\u05dc\u05e7\u05d9 \u05e8\u05db\u05d1, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05db\u05de\u05d5 A380."],[335.0,"\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d4\u05d5\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d7\u05d5\u05de\u05e8 \u05e0\u05d5\u05d7 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3, \u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05ea\u05d5\u05da \u05d0\u05d5\u05ea\u05d5 \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05d9\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d5\u05ea \u05de\u05d0\u05d5\u05d3."],[341.0,"\u05e0\u05e4\u05d2\u05e2. \u05dc\u05db\u05df \u05de\u05e2\u05d3\u05d9\u05e4\u05d9\u05dd \u05de\u05e6\u05d1\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05db\u05de\u05d5 16, \u05db\u05dc\u05d9\u05dd \u05d7\u05d3\u05d9\u05dd \u05d5\u05de\u05dc\u05d5\u05d8\u05e9\u05d9\u05dd, \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d8\u05d5\u05d1."],[353.0,"\u05e9\u05e9\u05d5\u05d1\u05e8\u05d5\u05ea \u05d0\u05ea \u05d4\u05e9\u05d1\u05d1. \u05d1\u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05ea\u05e2\u05d5\u05d5\u05ea \u05d1\u05e7\u05dc\u05d5\u05ea, \u05d5\u05e9\u05dd 1651 \u05e2\u05d5\u05e9\u05d4 \u05d0\u05ea \u05d4\u05d4\u05d1\u05d3\u05dc."],[366.0,"\u05de\u05d4\u05d7\u05d5\u05d6\u05e7 \u05dc\u05d9\u05d3 \u05d4\u05ea\u05e4\u05e8, \u05d5\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d7\u05d5\u05d8 \u05e8\u05d9\u05ea\u05d5\u05da 4043 \u05d0\u05d5 6."],[379.0,"\u05e0\u05d0\u05db\u05dc. \u05e0\u05e8\u05d7\u05d9\u05d1 \u05e2\u05dc \u05d6\u05d4 \u05d1\u05e4\u05e8\u05e7 17. \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05d2\u05d9\u05e0\u05d9\u05dd \u05d1\u05d0\u05e0\u05d5\u05d3\u05d7\u05e6\u05d9\u05d4, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e7\u05d5\u05e8\u05e1 \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9\u05d9\u05dd."],[392.0,"\u05de\u05d4 \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4? \u05d1\u05e9\u05d5\u05e8\u05d8\u05d5\u05d8 \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d5\u05d8\u05de\u05e4\u05e8, \u05dc\u05de\u05e9\u05dc 7075 7351\u05da, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd."],[403.0,"\u05d7\u05d9\u05de\u05d5\u05dd, \u05db\u05de\u05d5 \u05e8\u05d9\u05ea\u05d5\u05da, \u05d9\u05d9\u05d1\u05d5\u05e9 \u05e6\u05d1\u05e2 \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d0\u05d5 \u05d0\u05e0\u05d5\u05d3\u05d9\u05d6\u05e6\u05d9\u05d4 \u05e7\u05e9\u05d4, \u05e2\u05dc\u05d5\u05dc \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea."],[415.0,"\u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d9\u05e7\u05e8 \u05de\u05e4\u05dc\u05d3\u05d4 \u05dc\u05e7\u05d9\u05dc\u05d5, \u05d5-7075 \u05d9\u05e7\u05e8\u05d4 \u05de-6061. \u05d7\u05d5\u05de\u05e8 \u05d1\u05d3\u05e8\u05d2\u05d4 \u05d0\u05d5\u05d5\u05d9\u05e8\u05d9\u05ea \u05e2\u05dd \u05ea\u05e2\u05d5\u05d3\u05d5\u05ea \u05d9\u05e7\u05e8 \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8."],[428.0,"\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d4\u05d5\u05d0 \u05de\u05ea\u05e2\u05d1\u05d3 \u05de\u05d4\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05db\u05df \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d4\u05e2\u05dc\u05d5\u05ea \u05d4\u05db\u05d5\u05dc\u05dc\u05ea \u05dc\u05d0 \u05ea\u05de\u05d9\u05d3 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8."],[435.0,"\u05d0\u05d5\u05de\u05e8 \u05de\u05d4 \u05e0\u05e2\u05e9\u05d4 \u05d1\u05d7\u05d5\u05de\u05e8. \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea\u05d9\u05d4."]]};
window.MH_TR["\u05e4\u05e8\u05e713_\u05e0\u05d7\u05d5\u05e9\u05ea_\u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea\u05d9\u05d4"]={"t":"\u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea\u05d9\u05d4","l":[[1.0,"\u05e0\u05d7\u05d5\u05e9\u05ea \u05d4\u05d9\u05d0 \u05d4\u05de\u05d5\u05dc\u05d9\u05db\u05d4 \u05d4\u05d8\u05d5\u05d1\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05db\u05e1\u05e3: \u05d7\u05e9\u05de\u05dc \u05d5\u05d7\u05d5\u05dd."],[6.0,"\u05d4\u05d9\u05d0 \u05de\u05d5\u05dc\u05d9\u05db\u05d4 \u05d7\u05e9\u05de\u05dc \u05d1\u05e2\u05e8\u05da \u05e4\u05d9 \u05e9\u05d9\u05e9\u05d4 \u05de\u05e4\u05dc\u05d3\u05d4, \u05d5\u05e4\u05d9 \u05d0\u05d7\u05d3 \u05d5\u05d7\u05e6\u05d9 \u05de\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd."],[12.0,"\u05dc\u05db\u05df \u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05de\u05d5\u05dc\u05d9\u05da \u05d7\u05e9\u05de\u05dc\u05d9, \u05e4\u05e1 \u05e6\u05d1\u05d9\u05e8\u05d4, \u05de\u05d7\u05dc\u05d9\u05e3 \u05d7\u05d5\u05dd \u05d5\u05e1\u05dc\u05d9\u05dc \u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05e2\u05e9\u05d5\u05d9\u05d9\u05dd \u05de\u05de\u05e0\u05d4."],[18.0,"\u05d4\u05d9\u05d0 \u05e2\u05de\u05d9\u05d3\u05d4 \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05d1\u05de\u05d1\u05e0\u05d4 FCC, \u05de\u05e9\u05d9\u05db\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d5\u05e7\u05dc \u05dc\u05e2\u05e6\u05d1 \u05d0\u05d5\u05ea\u05d4."],[24.0,"\u05d0\u05d1\u05dc \u05d4\u05d9\u05d0 \u05db\u05d1\u05d3\u05d4, \u05e6\u05e4\u05d9\u05e4\u05d5\u05ea\u05d4 \u05db\u05de\u05e2\u05d8 \u05ea\u05e9\u05e2\u05d4 \u05d2\u05e8\u05dd \u05dc\u05e1\u05e0\u05d8\u05d9\u05de\u05d8\u05e8 \u05de\u05e2\u05d5\u05e7\u05d1, \u05d9\u05d5\u05ea\u05e8 \u05de\u05e4\u05dc\u05d3\u05d4, \u05d5\u05d4\u05d9\u05d0 \u05d9\u05e7\u05e8\u05d4."],[31.0,"\u05d9\u05e9 \u05db\u05de\u05d4 \u05e1\u05d5\u05d2\u05d9\u05dd \u05e9\u05dc \u05e0\u05d7\u05d5\u05e9\u05ea \u05d8\u05d4\u05d5\u05e8\u05d4. \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d9\u05d0 \u05e1\u05d6\u05dd, \u05e2\u05dd \u05db\u05de\u05d5\u05ea \u05e7\u05d8\u05e0\u05d4 \u05e9\u05dc \u05d7\u05de\u05e6\u05df."],[39.0,"\u05d1\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05e2\u05dd \u05de\u05d9\u05de\u05df, \u05dc\u05de\u05e9\u05dc \u05d1\u05d4\u05dc\u05d7\u05de\u05d4 \u05e7\u05e9\u05d4, \u05d4\u05d9\u05d0 \u05e2\u05dc\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7."],[47.0,"\u05dc\u05e9\u05d9\u05de\u05d5\u05e9\u05d9\u05dd \u05db\u05d0\u05dc\u05d4, \u05d5\u05dc\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e0\u05d7\u05d5\u05e9\u05ea \u05e0\u05d8\u05d5\u05dc\u05ea \u05d7\u05de\u05e6\u05df, 6\u05d5\u05d60."],[53.0,"\u05d5\u05e6\u05e0\u05e8\u05ea \u05de\u05d9\u05dd \u05d5\u05d2\u05d6 \u05e2\u05e9\u05d5\u05d9\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05e0\u05d7\u05d5\u05e9\u05ea \u05e1\u05d5\u05e1, \u05e9\u05e2\u05d1\u05e8\u05d4 \u05d8\u05d9\u05d4\u05d5\u05e8 \u05d1\u05d6\u05e8\u05d7\u05df."],[60.0,"\u05d0\u05ea \u05d4\u05de\u05d5\u05dc\u05d9\u05db\u05d5\u05ea \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05dc\u05e4\u05d9 \u2026, \u05d5\u05e0\u05d7\u05d5\u05e9\u05ea \u05d8\u05d4\u05d5\u05e8\u05d4 \u05e0\u05de\u05e6\u05d0\u05ea \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05de\u05d0\u05d4 \u05d0\u05d7\u05d5\u05d6."],[67.0,"\u05d0\u05ea \u05d4\u05de\u05d5\u05dc\u05d9\u05db\u05d5\u05ea \u05e9\u05dc\u05d4. \u05dc\u05db\u05df \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05e0\u05d7\u05d5\u05e9\u05ea \u05dc\u05e4\u05d9 \u05d4\u05d0\u05d9\u05d6\u05d5\u05df \u05d1\u05d9\u05df \u05e9\u05ea\u05d9 \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea."],[77.0,"\u05d3\u05d5\u05d2\u05de\u05d4 \u05de\u05d5\u05db\u05e8\u05ea \u05dc\u05db\u05dc \u05de\u05e4\u05e2\u05dc \u05d4\u05d9\u05d0 \u05e0\u05d7\u05d5\u05e9\u05d5\u05ea \u05db\u05e8\u05d5\u05dd \u05d6\u05d9\u05e8\u05e7\u05d5\u05df, \u05e9\u05de\u05de\u05e0\u05d4 \u05e2\u05d5\u05e9\u05d9\u05dd \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05dc\u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05e7\u05d5\u05d3\u05ea\u05d9."],[83.0,"\u05d4\u05d9\u05d0 \u05e9\u05d5\u05de\u05e8\u05ea \u05e2\u05dc \u05db\u05e9\u05d5\u05de\u05d5\u05e0\u05d9\u05dd \u05d0\u05d7\u05d5\u05d6 \u05de\u05d4\u05de\u05d5\u05dc\u05d9\u05db\u05d5\u05ea \u05e9\u05dc \u05e0\u05d7\u05d5\u05e9\u05d5\u05ea \u05d8\u05d4\u05d5\u05e8\u05d4, \u05d5\u05e0\u05e9\u05d0\u05e8\u05ea \u05e7\u05e9\u05d4 \u05d2\u05dd \u05d1\u05d7\u05d5\u05dd \u05e9\u05dc \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."],[90.0,"\u05d4\u05e1\u05e7\u05d0\u05dc\u05d4: \u05d7\u05d6\u05e7\u05d9\u05dd \u05d1\u05d4\u05e8\u05d1\u05d4, \u05d0\u05d1\u05dc \u05e2\u05dd \u05e8\u05d1\u05e2 \u05de\u05d4\u05de\u05d5\u05dc\u05d9\u05db\u05d5\u05ea, \u05d5\u05d0\u05e3 \u05e4\u05d7\u05d5\u05ea."],[99.0,"\u05d2\u05dd \u05d1\u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05d1\u05e4\u05dc\u05d9\u05d6, \u05d4\u05d7\u05d5\u05d6\u05e7 \u05ea\u05dc\u05d5\u05d9 \u05d1\u05de\u05d9\u05d3\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e7\u05e8, \u05d5\u05dc\u05db\u05df \u05d2\u05dd \u05dc\u05d4\u05dd \u05d9\u05e9 \u05d8\u05de\u05e4\u05e8\u05d9\u05dd."],[106.0,"\u05d5\u05e7\u05e9\u05d4. \u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9 \u05d4\u05df \u05de\u05e1\u05d5\u05de\u05e0\u05d5\u05ea \u05d1\u05d0\u05d5\u05ea \u05d5\u05d1\u05de\u05e1\u05e4\u05e8, \u05db\u05de\u05d5 0 \u05dc\u05e8\u05da \u2026 \u05dc\u05d7\u05e6\u05d9 \u05e7\u05e9\u05d4."],[121.0,"\u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05d9\u05e8\u05d5\u05e4\u05d9 \u05d4\u05d8\u05de\u05e4\u05e8 \u05de\u05e1\u05d5\u05de\u05df \u05d1\u05d0\u05d5\u05ea R \u05d5\u05d1\u05d7\u05d5\u05d6\u05e7 \u05d4\u05de\u05ea\u05d9\u05d7\u05d4 \u05d4\u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9, \u05db\u05de\u05d5 R290."],[128.0,"\u05d1\u05d4\u05d6\u05de\u05e0\u05d4 \u05db\u05d3\u05d0\u05d9 \u05dc\u05e6\u05d9\u05d9\u05df \u05d0\u05ea \u05d4\u05d8\u05de\u05e4\u05e8, \u05db\u05d9 \u05de\u05d5\u05d8 \u05e8\u05da \u05d5\u05de\u05d5\u05d8 \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05ea\u05d4 \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05de\u05ea\u05e0\u05d4\u05d2\u05d9\u05dd \u05d0\u05d7\u05e8\u05ea \u05dc\u05d2\u05de\u05e8\u05d9 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d5\u05d1\u05db\u05d9\u05e4\u05d5\u05e3."],[138.0,"\u05e4\u05dc\u05d9\u05d6 \u05d4\u05d5\u05d0 \u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05d0\u05d1\u05e5. \u05db\u05e9\u05d9\u05e9 \u05e2\u05d3 \u05db\u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05d5\u05d7\u05de\u05d9\u05e9\u05d4 \u05d0\u05d7\u05d5\u05d6 \u05d0\u05d1\u05e5, \u05d4\u05de\u05d1\u05e0\u05d4 \u05db\u05d5\u05dc\u05d5 66\u05d7, \u05d5\u05d4\u05e4\u05dc\u05d9\u05d6 \u05de\u05e9\u05d9\u05da \u05de\u05d0\u05d5\u05d3."],[147.0,"\u05e4\u05dc\u05d9\u05d6 70/30, \u05e9\u05d1\u05e2\u05d9\u05dd \u05d0\u05d7\u05d5\u05d6 \u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05d0\u05d7\u05d5\u05d6 \u05d0\u05d1\u05e5, \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05e2\u05d9\u05e6\u05d5\u05d1 \u05e2\u05de\u05d5\u05e7, \u05db\u05de\u05d5 \u05ea\u05e8\u05de\u05d9\u05dc\u05d9\u05dd."],[155.0,"\u05d4\u05e4\u05dc\u05d9\u05d6 \u05d7\u05d6\u05e7 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05e0\u05d5\u05d7 \u05dc\u05d7\u05d9\u05e9\u05d5\u05dc \u05d7\u05dd, \u05d0\u05d1\u05dc \u05e4\u05d7\u05d5\u05ea \u05de\u05e9\u05d9\u05da \u05d1\u05e7\u05d5\u05e8."],[165.0,"\u05d4\u05d0\u05d1\u05e5 \u05d6\u05d5\u05dc \u05de\u05e0\u05d7\u05d5\u05e9\u05ea, \u05d5\u05dc\u05db\u05df \u05d4\u05e4\u05dc\u05d9\u05d6 \u05d6\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8 \u05de\u05e0\u05d7\u05d5\u05e9\u05ea \u05d8\u05d4\u05d5\u05e8\u05d4."],[170.0,"\u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4, \u05d4\u05e4\u05dc\u05d9\u05d6 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d5\u05d0 \u05e4\u05dc\u05d9\u05d6 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05de\u05d4\u05d9\u05e8, 636000, \u05e9\u05d1\u05d0\u05d9\u05e8\u05d5\u05e4\u05d4 \u05e0\u05e7\u05e8\u05d0 CW614N."],[181.0,"\u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05ea\u05d5\u05da \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05d9\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d5\u05ea \u05de\u05d0\u05d5\u05d3 \u05d5\u05dc\u05e7\u05d1\u05dc \u05d2\u05d9\u05de\u05d5\u05e8 \u05de\u05e6\u05d5\u05d9\u05df."],[194.0,"\u05d1\u05de\u05d3\u05d3 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3\u05d9\u05d5\u05ea \u05e9\u05dc \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d4\u05e0\u05d7\u05d5\u05e9\u05ea, \u05d4\u05d5\u05d0 \u05d4\u05d1\u05e1\u05d9\u05e1 \u05d5\u05de\u05e7\u05d1\u05dc \u05de\u05d0\u05d4."],[199.0,"\u05dc\u05e9\u05dd \u05d4\u05e9\u05d5\u05d5\u05d0\u05d4, \u05d1\u05e8\u05d5\u05e0\u05d6\u05d5\u05ea \u05de\u05d9\u05e1\u05d1\u05d9\u05dd \u05e0\u05de\u05e6\u05d0\u05d5\u05ea \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05e9\u05d1\u05e2\u05d9\u05dd, \u05d5\u05e0\u05d7\u05d5\u05e9\u05ea \u05d8\u05d4\u05d5\u05e8\u05d4 \u05e8\u05e7 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05e2\u05e9\u05e8\u05d9\u05dd."],[206.0,"\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05e7\u05dc\u05d0\u05e1\u05d9 \u05dc\u05d1\u05e8\u05d6\u05d9\u05dd, \u05d0\u05d1\u05d9\u05d6\u05e8\u05d9 \u05e6\u05e0\u05e8\u05ea \u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d1\u05de\u05d7\u05e8\u05d8\u05d5\u05ea \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9\u05d5\u05ea."],[212.0,"\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d3\u05e2\u05ea: \u05d1\u05de\u05d2\u05e2 \u05e2\u05dd \u05de\u05d9 \u05e9\u05ea\u05d9\u05d9\u05d4 \u05d9\u05e9 \u05d4\u05d9\u05d5\u05dd \u05d4\u05d2\u05d1\u05dc\u05d5\u05ea \u05e2\u05dc \u05e2\u05d5\u05e4\u05e8\u05ea, \u05d5\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e4\u05dc\u05d9\u05d6 \u05d1\u05dc\u05d9 \u05e2\u05d5\u05e4\u05e8\u05ea."],[220.0,"\u05dc\u05e4\u05dc\u05d9\u05d6\u05d9\u05e9 \u05e9\u05ea\u05d9 \u05d7\u05d5\u05dc\u05e9\u05d5\u05ea."],[223.0,"dezincification \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea. \u05d4\u05d0\u05d1\u05e5 \u05de\u05ea\u05de\u05d5\u05e1\u05e1, \u05d5\u05e0\u05e9\u05d0\u05e8 \u05e9\u05dc\u05d3 \u05e0\u05d7\u05d5\u05e9\u05ea \u05d7\u05dc\u05e9 \u05d5\u05e0\u05e7\u05d1\u05d5\u05d1\u05d9."],[234.0,"\u05dc\u05db\u05df \u05dc\u05d0\u05d1\u05d9\u05d6\u05e8\u05d9 \u05de\u05d9\u05dd \u05d9\u05e9 \u05e4\u05dc\u05d9\u05d6 \u05e2\u05de\u05d9\u05d3 \u05d1\u05ea\u05d5\u05e4\u05e2\u05d4, \u05e9\u05de\u05e1\u05d5\u05de\u05df 78\u05dd."],[240.0,"\u05dc\u05d4\u05d9\u05e1\u05d3\u05e7 \u05d1\u05e0\u05d5\u05db\u05d7\u05d5\u05ea \u05d0\u05de\u05d5\u05e0\u05d9\u05d4. \u05d6\u05d5 \u05e1\u05d3\u05d9\u05e7\u05d4 \u05ea\u05d7\u05ea \u05de\u05d0\u05de\u05e5, \u05e9\u05d1\u05e2\u05d1\u05e8 \u05e0\u05e7\u05e8\u05d0\u05d4 \u05e1\u05d3\u05d9\u05e7\u05ea \u05e2\u05d5\u05e0\u05d4."],[251.0,"\u05d4\u05e4\u05d2\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d1\u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05ea\u05d5\u05df \u05de\u05d5\u05e0\u05e2\u05ea \u05d0\u05d5\u05ea\u05d4."],[255.0,"\u05d1\u05e8\u05d5\u05e0\u05d6\u05d4 \u05d4\u05d9\u05d9\u05ea\u05d4 \u05d1\u05de\u05e7\u05d5\u05e8 \u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05d1\u05d3\u05d9\u05dc, \u05d5\u05d4\u05d9\u05d5\u05dd \u05d4\u05de\u05d9\u05dc\u05d4 \u05de\u05db\u05e1\u05d4 \u05de\u05e9\u05e4\u05d7\u05d4 \u05e8\u05d7\u05d1\u05d4."],[261.0,"\u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea, \u05d5\u05de\u05d7\u05e9\u05de\u05e9\u05ea \u05dc\u05e7\u05e4\u05d9\u05e6\u05d9\u05dd, \u05dc\u05de\u05d2\u05e2\u05d9\u05dd \u05d7\u05e9\u05de\u05dc\u05d9\u05d9\u05dd \u05d5\u05dc\u05ea\u05d5\u05ea\u05d1\u05d9\u05dd."],[271.0,"\u05d1\u05e8\u05d5\u05e0\u05d6\u05d5\u05ea \u05d9\u05e6\u05d9\u05e7\u05d4 \u05e2\u05dd \u05d1\u05d3\u05d9\u05dc \u05d5\u05e2\u05d5\u05e4\u05e8\u05ea \u05d4\u05df \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05e7\u05dc\u05d0\u05e1\u05d9 \u05dc\u05ea\u05d5\u05ea\u05d1\u05d9 \u05de\u05d9\u05e1\u05d1\u05d9\u05dd, \u05db\u05d9 \u05d4\u05df \u05de\u05d7\u05dc\u05d9\u05e7\u05d5\u05ea \u05d4\u05d9\u05d8\u05d1 \u05de\u05d5\u05dc \u05e4\u05dc\u05d3\u05d4."],[278.0,"\u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d9\u05d0 C93200, \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea \u05d2\u05dd 660 5085."],[285.0,"\u05db\u05d7\u05d5\u05de\u05e8 \u05e1\u05d9\u05db\u05d4 \u05db\u05e9\u05d4\u05e9\u05de\u05df \u05e0\u05d2\u05de\u05e8 \u05dc\u05e8\u05d2\u05e2, \u05d5\u05dc\u05db\u05df \u05de\u05d9\u05e1\u05d1 \u05d1\u05e8\u05d5\u05e0\u05d6\u05d4 \u05e1\u05d5\u05d1\u05dc \u05e8\u05d9\u05e6\u05d4 \u05d9\u05d1\u05e9\u05d4 \u05e7\u05e6\u05e8\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d8\u05d5\u05d1 \u05de\u05de\u05d9\u05e1\u05d1 \u05e4\u05dc\u05d3\u05d4."],[298.0,"\u05d5\u05d1\u05e8\u05d5\u05e0\u05d6\u05d4 \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05e2\u05dd \u05db\u05e2\u05e9\u05d5\u05e8\u05d4 \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05de\u05e2\u05d8 \u05d1\u05e8\u05d6\u05dc \u05d5\u05e0\u05d9\u05e7\u05dc, \u05d7\u05d6\u05e7\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d5\u05e2\u05de\u05d9\u05d3\u05d4 \u05d1\u05e9\u05d5\u05d7\u05d9\u05e7\u05d4 \u05d5\u05d1\u05de\u05d9\u05d9\u05dd."],[306.0,"\u05de\u05de\u05e0\u05d4 \u05e2\u05d5\u05e9\u05d9\u05dd \u05de\u05d3\u05d7\u05e4\u05d9 \u05e1\u05e4\u05d9\u05e0\u05d5\u05ea, \u05d7\u05dc\u05e7\u05d9 \u05de\u05e9\u05d0\u05d1\u05d5\u05ea, \u05d5\u05ea\u05d5\u05ea\u05d1\u05d9\u05dd \u05e2\u05de\u05d5\u05e1\u05d9\u05dd."],[311.0,"\u05d1\u05e8\u05d5\u05e0\u05d6\u05d4 \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d9\u05e6\u05d5\u05e7\u05d4, \u05db\u05de\u05d5 695400, \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05d7\u05d5\u05d6\u05e7 \u05de\u05ea\u05d9\u05d7\u05d4 \u05e9\u05dc \u05d9\u05d5\u05ea\u05e8 \u05de\u05d7\u05de\u05e9\u05d5 \u05de\u05d0\u05d5\u05ea \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc."],[321.0,"\u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05de\u05d9\u05d9\u05dd, \u05d5\u05d2\u05dd \u05de\u05d5\u05e0\u05e2\u05ea \u05d4\u05e6\u05d8\u05d1\u05e8\u05d5\u05ea \u05e9\u05dc \u05d0\u05d5\u05e8\u05d2\u05e0\u05d9\u05d6\u05de\u05d9\u05dd \u05d9\u05de\u05d9\u05d9\u05dd."],[330.0,"\u05d1\u05e1\u05e4\u05d9\u05e0\u05d5\u05ea \u05d5\u05d1\u05de\u05ea\u05e7\u05e0\u05d9 \u05d4\u05ea\u05e4\u05dc\u05d4. \u05d5\u05d1\u05d0\u05d5\u05ea\u05d4 \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05de\u05e9\u05d5\u05ea\u05de\u05e9\u05d9\u05dd \u05d2\u05dd \u05d1\u05de\u05d8\u05d1\u05e2\u05d5\u05ea."],[340.0,"\u05e0\u05d7\u05d5\u05e9\u05ea \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d4."],[343.0,"\u05d4\u05d9\u05d0 \u05de\u05db\u05d9\u05dc\u05d4 \u05e4\u05d7\u05d5\u05ea \u05de\u05e9\u05e0\u05d9 \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd, \u05d5\u05de\u05ea\u05d7\u05d6\u05e7\u05ea \u05d1\u05d4\u05e7\u05e9\u05d7\u05ea \u05de\u05e9\u05e7\u05e2, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 4."],[349.0,"\u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05ea, \u05d5\u05d4\u05d9\u05d0 \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc \u05db-40 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc 6, \u05d5\u05dc\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc \u05d9\u05d5\u05ea\u05e8 \u05de-1,200 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc."],[361.0,"\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4 \u05dc\u05e7\u05e4\u05d9\u05e6\u05d9\u05dd \u05d5\u05dc\u05de\u05d2\u05e2\u05d9\u05dd \u05d7\u05e9\u05de\u05dc\u05d9\u05d9\u05dd, \u05d5\u05d2\u05dd \u05dc\u05db\u05dc\u05d9\u05dd \u05e9\u05dc\u05d0 \u05de\u05e2\u05dc\u05d9\u05dd \u05e0\u05d9\u05e6\u05d5\u05e6\u05d5\u05ea, \u05dc\u05de\u05e7\u05d5\u05de\u05d5\u05ea \u05e2\u05dd \u05e1\u05db\u05e0\u05ea \u05e1\u05d9\u05e6\u05d5\u05e5."],[368.0,"\u05d0\u05d1\u05dc \u05d0\u05d1\u05e7 \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd \u05de\u05e1\u05d5\u05db\u05df \u05dc\u05e0\u05e9\u05d9\u05de\u05d4, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05e2\u05dd \u05d9\u05e0\u05d9\u05e7\u05d4, \u05d5\u05dc\u05e4\u05d9 \u05e0\u05d5\u05d4\u05dc\u05d9 \u05d1\u05d8\u05d9\u05d7\u05d5\u05ea."],[375.0,"\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9 \u05e8\u05d2\u05d9\u05dc, \u05e2\u05dd \u05e7\u05d9\u05e8\u05d5\u05e8, \u05e0\u05d7\u05e9\u05d1 \u05d1\u05d8\u05d5\u05d7 \u05d9\u05d5\u05ea\u05e8, \u05d0\u05d1\u05dc \u05e2\u05d3\u05d9\u05d9\u05df \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e7\u05e4\u05d9\u05d3 \u05e2\u05dc \u05d4\u05e0\u05d4\u05dc\u05d9\u05dd."],[382.0,"\u05e0\u05d7\u05d5\u05e9\u05ea \u05de\u05ea\u05d7\u05d1\u05e8\u05ea \u05d1\u05e7\u05dc\u05d5\u05ea \u05d1\u05d4\u05dc\u05d7\u05de\u05d4."],[384.0,"\u05d1\u05d4\u05dc\u05d7\u05de\u05d4 \u05e8\u05db\u05d4, \u05d1\u05d1\u05d3\u05d9\u05dc, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05de\u05d0\u05ea\u05d9\u05d9\u05dd \u05de\u05e2\u05dc\u05d5\u05ea, \u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05e6\u05e0\u05e8\u05ea \u05de\u05d9\u05dd \u05d5\u05e8\u05db\u05d9\u05d1\u05d9\u05dd \u05d7\u05e9\u05d5\u05de\u05dc\u05d9\u05d9\u05dd."],[392.0,"\u05d1\u05d4\u05dc\u05d7\u05de\u05d4 \u05e7\u05e9\u05d4, \u05d1\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05db\u05e1\u05e3 \u05d0\u05d5 \u05e0\u05d7\u05d5\u05e9\u05ea \u05d6\u05e8\u05d7\u05df, \u05d1\u05e9\u05e9\u05d5 \u05de\u05d0\u05d5\u05ea \u05e2\u05d3 \u05ea\u05e9\u05e2 \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea, \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d7\u05d6\u05e7 \u05d1\u05d4\u05e8\u05d1\u05d4."],[400.0,"\u05db\u05e9\u05de\u05dc\u05d7\u05d9\u05de\u05d9\u05dd \u05e0\u05d7\u05d5\u05e9\u05ea \u05dc\u05e0\u05d7\u05d5\u05e9\u05ea, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4\u05df \u05e2\u05dc \u05e4\u05dc\u05d3\u05d4, \u05db\u05d9 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05e0\u05e2\u05e9\u05d4 \u05e4\u05e8\u05d9\u05da."],[411.0,"\u05de\u05d4 \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4? \u05e0\u05d7\u05d5\u05e9\u05d5\u05ea \u05d8\u05d4\u05d5\u05e8\u05d4 \u05e8\u05db\u05d4 \u05d5\u05d3\u05d1\u05d9\u05e7\u05d4, \u05d5\u05e0\u05d3\u05d1\u05e7\u05ea \u05dc\u05db\u05dc\u05d9, \u05d5\u05dc\u05db\u05df \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05e2\u05dd \u05db\u05dc\u05d9\u05dd \u05d7\u05d3\u05d9\u05dd \u05de\u05d0\u05d5\u05d3."],[419.0,"\u05d4\u05e4\u05dc\u05d9\u05d6, \u05dc\u05e2\u05d5\u05de\u05ea\u05d4, \u05d4\u05d5\u05d0 \u05de\u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d4\u05e0\u05d5\u05d7\u05d9\u05dd \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3."],[423.0,"\u05d5\u05d1\u05de\u05d2\u05e2 \u05e2\u05dd \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05d1\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd \u05d7\u05e9\u05de\u05dc\u05d9\u05d9\u05dd, \u05e0\u05d5\u05e6\u05e8\u05ea \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d2\u05dc\u05d5\u05d5\u05e0\u05d9\u05ea."],[437.0,"\u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05d4\u05e0\u05d7\u05d5\u05e9\u05ea \u05e2\u05e6\u05de\u05d4 \u05d9\u05e7\u05e8\u05d4, \u05d5\u05de\u05d7\u05d9\u05e8\u05d4 \u05de\u05e9\u05ea\u05e0\u05d4 \u05e2\u05dd \u05d4\u05e9\u05d5\u05e7. \u05e0\u05d7\u05d5\u05e9\u05ea \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd \u05d9\u05e7\u05e8\u05d4 \u05d1\u05d4\u05e8\u05d1\u05d4."],[444.0,"\u05d1\u05d2\u05e8\u05d9\u05d8\u05d4, \u05d5\u05dc\u05db\u05df \u05db\u05d3\u05d0\u05d9 \u05dc\u05d0\u05e1\u05d5\u05e3 \u05d0\u05d5\u05ea\u05dd \u05d1\u05e0\u05e4\u05e8\u05d3, \u05d5\u05dc\u05d0 \u05dc\u05e2\u05e8\u05d1\u05d1 \u05e2\u05dd \u05e9\u05d1\u05d1\u05d9 \u05e4\u05dc\u05d3\u05d4."],[454.0,"\u05dc\u05d4\u05d7\u05dc\u05e7\u05d4 \u05d5\u05dc\u05de\u05d9\u05d9\u05dd, \u05d5\u05e0\u05d7\u05d5\u05e9\u05ea \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd \u05dc\u05d7\u05d5\u05d6\u05e7. \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd."]]};
window.MH_TR["\u05e4\u05e8\u05e714_\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd"]={"t":"\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd","l":[[1.0,"\u05e9\u05d9\u05e9\u05d9\u05dd \u05d0\u05d7\u05d5\u05d6 \u05de\u05de\u05e9\u05e7\u05dc \u05e4\u05dc\u05d3\u05d4, \u05d0\u05d1\u05dc \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e9\u05dc\u05d5 \u05d7\u05d6\u05e7\u05d5\u05ea \u05db\u05de\u05d5 \u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d5\u05e9\u05d1\u05d7\u05d5\u05ea."],[11.0,"\u05dc\u05db\u05d5\u05d9\u05e9 \u05dc\u05d5 \u05d9\u05d7\u05e1 \u05d7\u05d5\u05d6\u05e7 \u05dc\u05de\u05e9\u05e7\u05dc \u05de\u05d4\u05d8\u05d5\u05d1\u05d9\u05dd \u05e9\u05d9\u05e9, \u05d5\u05d4\u05d5\u05d0 \u05e9\u05d5\u05de\u05e8 \u05e2\u05dc\u05d9\u05d5 \u05e2\u05d3 \u05db-400 \u05de\u05e2\u05dc\u05d5\u05ea."],[18.0,"\u05d4\u05d0\u05d3\u05dd. \u05d0\u05d1\u05dc \u05d9\u05e9 \u05dc\u05d5 \u05d2\u05dd \u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05de\u05e7\u05e9\u05d5\u05ea \u05e2\u05dc \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d0\u05d9\u05ea\u05d5."],[31.0,"\u05d4\u05d7\u05d5\u05dd \u05e9\u05dc\u05d5 \u05e0\u05de\u05d5\u05db\u05d4 \u05de\u05d0\u05d5\u05d3, \u05db\u05e9\u05d1\u05d9\u05e2\u05d9\u05ea \u05de\u05d6\u05d5 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d4. \u05d5\u05d4\u05d5\u05d0 \u05d9\u05e7\u05e8 \u05de\u05d0\u05d5\u05d3, \u05db\u05d9 \u05d4\u05e4\u05e7\u05ea\u05d5 \u05de\u05e1\u05d5\u05d1\u05db\u05ea \u05d5\u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05e8\u05d1\u05d4."],[44.0,"\u05d0\u05d5\u05ea\u05d5 \u05d1\u05de\u05d2\u05e0\u05d6\u05d9\u05d5\u05dd, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05ea\u05d9\u05db\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05e4\u05d5\u05d2 \u05e9\u05de\u05ea\u05e7\u05d1\u05dc \u05e4\u05e2\u05de\u05d9\u05d9\u05dd \u05d0\u05d5 \u05e9\u05dc\u05d5\u05e9 \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd. \u05d6\u05d5 \u05d4\u05e1\u05d9\u05d1\u05d4 \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9\u05ea \u05dc\u05de\u05d7\u05d9\u05e8."],[57.0,"\u05dc\u05db-880 \u05de\u05e2\u05dc\u05d5\u05ea \u05d4\u05d5\u05d0 \u05d1\u05de\u05d1\u05e0\u05d4 \u2026, \u05e9\u05e0\u05e7\u05e8\u05d0 \u05e4\u05d0\u05d6\u05ea \u05d0\u05dc\u05e4\u05d0. \u05de\u05e2\u05dc \u05d6\u05d4 \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d1\u05e8 \u05dc\u05de\u05d1\u05e0\u05d4 BCC, \u05e9\u05e0\u05e7\u05e8\u05d0 \u05e4\u05d0\u05d6\u05ea \u05d1\u05d8\u05d0."],[73.0,"\u05d0\u05dc\u05e4\u05d0, \u05d5\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05db\u05de\u05d5 \u05d5\u05e0\u05d3\u05d9\u05d5\u05dd \u05d5\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05de\u05d9\u05d9\u05e6\u05d1\u05d9\u05dd \u05d0\u05ea \u05e4\u05d0\u05d6\u05ea \u05d1\u05d8\u05d0."],[82.0,"\u05dc\u05e4\u05d9 \u05d4\u05d0\u05d9\u05d6\u05d5\u05df \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd \u05de\u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05dc\u05e9\u05dc\u05d5\u05e9 \u05de\u05e9\u05e4\u05d7\u05d5\u05ea: \u05d0\u05dc\u05e4\u05d0, \u05d0\u05dc\u05e4\u05d0 \u05d1\u05d8\u05d0, \u05d5\u05d1\u05d8\u05d0."],[90.0,"1 \u05d5\u05e2\u05d3 4 Grade. \u05d4\u05d4\u05d1\u05d3\u05dc \u05d1\u05d9\u05e0\u05d9\u05d4\u05df \u05d4\u05d5\u05d0 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05db\u05de\u05d5\u05ea \u05d4\u05d7\u05de\u05e6\u05df: \u05d9\u05d5\u05ea\u05e8 \u05d7\u05de\u05e6\u05df, \u05d9\u05d5\u05ea\u05e8 \u05d7\u05d5\u05d6\u05e7, \u05d5\u05e4\u05d7\u05d5\u05ea \u05de\u05e9\u05d9\u05db\u05d5\u05ea."],[104.0,"\u05d5\u05de\u05e9\u05de\u05e9\u05ea \u05dc\u05de\u05d7\u05dc\u05d9\u05e4\u05d9 \u05d7\u05d5\u05dd, \u05dc\u05e6\u05d9\u05d5\u05d3 \u05db\u05d9\u05de\u05d9, \u05dc\u05de\u05ea\u05e7\u05e0\u05d9 \u05d4\u05ea\u05e4\u05dc\u05d4 \u05d5\u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05de\u05d9\u05d9\u05dd."],[119.0,"\u05db\u05e9\u05e6\u05e8\u05d9\u05da \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05d9\u05e9 \u05d3\u05e8\u05d2\u05d5\u05ea \u05e2\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05e4\u05dc\u05d3\u05d9\u05d5\u05dd, \u05db\u05de\u05d5 7 Grade."],[126.0,"\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d0\u05dc\u05e4\u05d0 \u05d1\u05d8\u05d0, \u05d5\u05d4\u05d9\u05d0 \u05dc\u05d1\u05d3\u05d4 \u05de\u05d4\u05d5\u05d5\u05d4 \u05db\u05de\u05d7\u05e6\u05d9\u05ea \u05de\u05db\u05dc \u05d4\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05e9\u05d1\u05e9\u05d9\u05de\u05d5\u05e9."],[140.0,"2. \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05d6\u05e7 \u05d0\u05d5\u05ea\u05d4 \u05e2\u05d5\u05d3 \u05de\u05e2\u05d8 \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4 \u05d5\u05d4\u05d6\u05d3\u05e7\u05e0\u05d5\u05ea."],[150.0,"\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d2\u05e8\u05e1\u05d4 \u05d8\u05d4\u05d5\u05e8\u05d4 \u05d9\u05d5\u05ea\u05e8, 23 Grade, \u05d1\u05d3\u05e8\u05d2\u05ea |\u05dd, \u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05d7\u05de\u05e6\u05df \u05d5\u05d9\u05d5\u05ea\u05e8 toughness"],[167.0,"\u05d1\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc \u05db-30 \u05e2\u05d3 36 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc 6, \u05d5\u05d1\u05de\u05e6\u05d1 \u05d4\u05d6\u05d4 \u05d4\u05d9\u05d0 \u05db\u05d1\u05e8 \u05d7\u05d6\u05e7\u05d4 \u05db\u05de\u05d5 \u05e4\u05dc\u05d3\u05d4 \u05de\u05d5\u05e9\u05d1\u05d7\u05ea."],[179.0,"\u05d2\u05d1\u05d5\u05d4 \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d6\u05d3\u05e7\u05e0\u05d5\u05ea, \u05d5\u05de\u05e9\u05de\u05e9\u05d5\u05ea \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05db\u05d1\u05d3\u05d9\u05dd \u05db\u05de\u05d5 \u05db\u05e0\u05d9 \u05e0\u05d7\u05d9\u05ea\u05d4 \u05d5\u05e7\u05e4\u05d9\u05e6\u05d9\u05dd."],[190.0,"\u05d5\u05d9\u05e9 \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d0\u05dc\u05e4\u05d0, \u05e9\u05e2\u05d5\u05d1\u05d3\u05d5\u05ea \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8 \u05d1\u05de\u05e0\u05d5\u05e2\u05d9 \u05e1\u05d9\u05dc\u05d5\u05df."],[196.0,"\u05d1\u05e4\u05dc\u05d3\u05d4 \u05e8\u05d5\u05d1 \u05d4\u05d7\u05d5\u05dd \u05d9\u05d5\u05e6\u05d0 \u05e2\u05dd \u05d4\u05e9\u05d5\u05d1\u05d1. \u05d1\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d4\u05e8\u05d1\u05d4 \u05de\u05de\u05e0\u05d5 \u05e0\u05e9\u05d0\u05e8 \u05d1\u05e7\u05e6\u05d4, \u05d5\u05d4\u05db\u05dc\u05d9 \u05e0\u05e9\u05d7\u05e7 \u05de\u05d4\u05e8."],[212.0,"\u05d5\u05e0\u05d3\u05d1\u05e7 \u05d0\u05dc\u05d9\u05d5. \u05d5\u05d1\u05d2\u05dc\u05dc \u05de\u05d5\u05d3\u05d5\u05dc \u05d4\u05d0\u05dc\u05e1\u05d8\u05d9\u05d5\u05ea \u05d4\u05e0\u05de\u05d5\u05da, \u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05e0\u05d3\u05d7\u05e4\u05d5\u05ea \u05de\u05d4\u05db\u05dc\u05d9 \u05d5\u05e8\u05d5\u05e2\u05d3\u05d5\u05ea."],[223.0,"\u05e8\u05d1\u05e2 \u05de\u05e4\u05dc\u05d3\u05d4, \u05d4\u05d6\u05e0\u05d4 \u05dc\u05e9\u05df \u05e0\u05d3\u05d9\u05d1\u05d4, \u05db\u05dc\u05d9\u05dd \u05d7\u05d3\u05d9\u05dd, \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05dc\u05d7\u05e5 \u05d2\u05d1\u05d5\u05d4, \u05d5\u05de\u05d2\u05e2 \u05e8\u05e6\u05d9\u05e3, \u05d1\u05dc\u05d9 \u05dc\u05d4\u05e9\u05d4\u05d5\u05ea \u05d0\u05ea \u05d4\u05db\u05dc\u05d9 \u05d1\u05de\u05e7\u05d5\u05dd."],[237.0,"\u05e9\u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05db\u05dc\u05d9 \u05d1\u05de\u05d2\u05e2 \u05e7\u05d1\u05d5\u05e2, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d7\u05d5\u05dd \u05dc\u05d0 \u05d9\u05e2\u05dc\u05d4 \u05d5\u05d9\u05d9\u05e8\u05d3 \u05d1\u05db\u05dc \u05e1\u05d9\u05d1\u05d5\u05d1."],[251.0,"\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d3\u05e8\u05da \u05d4\u05db\u05dc\u05d9. \u05d5\u05d1\u05d4\u05d1\u05e8\u05d2\u05d4, \u05d4\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05e0\u05e6\u05de\u05d3 \u05dc\u05de\u05d1\u05e8\u05d6, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05d1\u05e8\u05d6\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd \u05d5\u05d1\u05d7\u05d5\u05de\u05e8 \u05e1\u05d9\u05db\u05d4 \u05de\u05ea\u05d0\u05d9\u05dd."],[266.0,"\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d5\u05e9\u05db\u05d1\u05d4 \u05e4\u05d2\u05d5\u05e2\u05d4 \u05d1\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05e9\u05de\u05d5\u05e8\u05d9\u05d3\u05d4 \u05d0\u05ea \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."],[276.0,"\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d0\u05d5\u05d3. \u05dc\u05d0 \u05de\u05db\u05d1\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d1\u05de\u05d9\u05dd, \u05d0\u05dc\u05d0 \u05d1\u05de\u05d8\u05e3 \u05de\u05e1\u05d5\u05d2 \u05dd \u05d0\u05d5 \u05d1\u05d7\u05d5\u05dc \u05d9\u05d1\u05e9."],[290.0,"\u05e9\u05dc \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05dc\u05d1\u05e0\u05d9\u05dd \u05d5\u05d1\u05d5\u05d4\u05e7\u05d9\u05dd, \u05d5\u05d6\u05d5 \u05d2\u05dd \u05d3\u05e8\u05da \u05de\u05d4\u05d9\u05e8\u05d4 \u05dc\u05d6\u05d4\u05d5\u05ea \u05d0\u05d5\u05ea\u05d5."],[304.0,"\u05d1\u05d7\u05d9\u05de\u05d5\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8, \u05de\u05e2\u05dc \u05db-500 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d4\u05d7\u05de\u05e6\u05df \u05d7\u05d5\u05d3\u05e8 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e9\u05db\u05d1\u05d4 \u05e7\u05e9\u05d4 \u05d5\u05e9\u05d1\u05d9\u05e8\u05d4, alpha case \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea."],[314.0,"\u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d0\u05d5 \u05d1\u05d0\u05e8\u05d2\u05d5\u05df. \u05d2\u05dd \u05d1\u05e8\u05d9\u05ea\u05d5\u05da, \u05db\u05dc \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d7\u05dd \u05e6\u05e8\u05d9\u05da \u05d4\u05d2\u05e0\u05d4 \u05e9\u05dc \u05d2\u05d6 \u05d0\u05e6\u05d9\u05dc, \u05de\u05dc\u05e4\u05e0\u05d9\u05dd \u05d5\u05de\u05d0\u05d7\u05d5\u05e8."],[329.0,"\u05e6\u05d1\u05e2 \u05d4\u05ea\u05e4\u05e8 \u05de\u05e1\u05e4\u05e8 \u05d0\u05ea \u05d4\u05e1\u05d9\u05e4\u05d5\u05e8: \u05db\u05e1\u05d5\u05e3 \u05d0\u05d5 \u05d1\u05e6\u05d1\u05e2 \u05e7\u05e9 \u05d1\u05d4\u05d9\u05e8 \u05d4\u05d5\u05d0 \u05ea\u05e7\u05d9\u05df, \u05d5\u05db\u05d7\u05d5\u05dc, \u05d0\u05e4\u05d5\u05e8 \u05d0\u05d5 \u05dc\u05d1\u05df \u05de\u05e2\u05d9\u05d3 \u05e2\u05dc \u05d6\u05d9\u05d4\u05d5\u05dd."],[339.0,"\u05d4\u05d9\u05d3\u05d1\u05e7\u05d5\u05ea. \u05d5\u05d1\u05de\u05d2\u05e2 \u05e2\u05dd \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05d4\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d4\u05d5\u05d0 \u05d4\u05d0\u05e6\u05d9\u05dc\u05d9, \u05d5\u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d4\u05d5\u05d0 \u05e9\u05e0\u05d0\u05db\u05dc."],[354.0,"\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d5\u05dd \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4 \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8\u05d9\u05ea \u05d5\u05d1\u05e9\u05ea\u05dc\u05d9\u05dd, \u05db\u05d9 \u05d4\u05d9\u05d0 \u05d7\u05d5\u05e1\u05db\u05ea \u05d0\u05ea \u05e8\u05d5\u05d1 \u05d4\u05d7\u05d5\u05de\u05e8 \u05e9\u05d4\u05d9\u05d4 \u05d4\u05d5\u05dc\u05da \u05dc\u05e9\u05d1\u05d1\u05d9\u05dd."],[370.0,"\u05d7\u05de\u05d4, \u05e9\u05e1\u05d5\u05d2\u05e8\u05ea \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05e4\u05e0\u05d9\u05de\u05d9\u05d5\u05ea \u05d5\u05de\u05e9\u05e4\u05e8\u05ea \u05d0\u05ea \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."],[379.0,"\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d1\u05d9\u05ea \u05de\u05d0\u05d5\u05d3. \u05db\u05e9\u05d4\u05de\u05e9\u05e7\u05dc \u05d7\u05e9\u05d5\u05d1 \u05d0\u05d1\u05dc \u05d4\u05d7\u05d5\u05d6\u05e7 \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9, \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d6\u05d5\u05dc \u05d1\u05d4\u05e8\u05d1\u05d4."],[393.0,"\u05db\u05e4\u05d5\u05dc. \u05d5\u05db\u05e9\u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e2\u05d5\u05dc\u05d4 \u05de\u05e2\u05dc \u05db\u05d7\u05de\u05e9 \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea, \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05dc\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e0\u05d9\u05e7\u05dc."],[403.0,"8, \u05d5\u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05de\u05e8\u05d0\u05e9, \u05db\u05d5\u05dc\u05dc \u05d4\u05d4\u05d9\u05d3\u05d5\u05e7 \u05d5\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8. \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8?"],[419.0,"\u05d4\u05d7\u05d5\u05de\u05e8 \u05e2\u05e6\u05de\u05d5 \u05d9\u05e7\u05e8 \u05e4\u05d9 \u05e2\u05e9\u05e8\u05d5\u05ea \u05de\u05e4\u05dc\u05d3\u05d4 \u05dc\u05e7\u05d9\u05dc\u05d5, \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d0\u05d9\u05d8\u05d9 \u05e4\u05d9\u05db\u05de\u05d4, \u05d5\u05d4\u05db\u05dc\u05d9\u05dd \u05e0\u05e9\u05d7\u05e7\u05d9\u05dd \u05de\u05d4\u05e8."],[426.0,"\u05d4\u05d7\u05d5\u05de\u05e8, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05dc\u05dd \u05dc\u05d4\u05ea\u05d7\u05d9\u05dc \u05de\u05d7\u05d9\u05e9\u05d5\u05dc \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea, \u05d0\u05d5 \u05de\u05d4\u05d3\u05e4\u05e1\u05d4 \u05d1\u05ea\u05dc\u05ea \u05de\u05de\u05d3."],[437.0,"\u05d5\u05e9\u05d1\u05d1\u05d9\u05dd \u05e0\u05e7\u05d9\u05d9\u05dd \u05e9\u05dc \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05e9\u05d5\u05d5\u05d9\u05dd \u05db\u05e1\u05e3, \u05d5\u05dc\u05db\u05df \u05d0\u05d5\u05e1\u05e4\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d1\u05e0\u05e4\u05e8\u05d6."],[442.0,"\u05d1\u05e2\u05d9\u05d1\u05d5\u05d3, \u05d1\u05d1\u05d8\u05d9\u05d7\u05d5\u05ea \u05d5\u05d1\u05d7\u05d9\u05de\u05d5\u05dd. \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d4\u05e0\u05d9\u05e7\u05dc \u05d5\u05de\u05ea\u05db\u05d5\u05ea \u05de\u05d9\u05d5\u05d7\u05d3\u05d5\u05ea \u05e0\u05d5\u05e1\u05e4\u05d5\u05ea."]]};
window.MH_TR["\u05e4\u05e8\u05e715_\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea_\u05e0\u05d9\u05e7\u05dc_\u05d5\u05de\u05ea\u05db\u05d5\u05ea_\u05de\u05d9\u05d5\u05d7\u05d3\u05d5\u05ea"]={"t":"\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e0\u05d9\u05e7\u05dc \u05d5\u05de\u05ea\u05db\u05d5\u05ea \u05de\u05d9\u05d5\u05d7\u05d3\u05d5\u05ea","l":[[1.0,"\u05e2\u05dd \u05d7\u05d5\u05de\u05e6\u05d4 \u05e8\u05d5\u05ea\u05d7\u05ea. \u05dc\u05e9\u05dd \u05de\u05d2\u05d9\u05e2\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e2\u05dc \u05d1\u05e1\u05d9\u05e1 \u05e0\u05d9\u05e7\u05dc, \u05d5\u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea superalloys"],[15.0,"\u05d4\u05df \u05e9\u05d5\u05de\u05e8\u05d5\u05ea \u05e2\u05dc \u05d7\u05d5\u05d6\u05e7 \u05d5\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05d6\u05d7\u05d9\u05dc\u05d4 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05e9\u05dc \u05e9\u05e9 \u05de\u05d0\u05d5\u05ea \u05e2\u05d3 \u05d0\u05dc\u05e3 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05d7\u05de\u05e6\u05d5\u05df \u05d5\u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."],[24.0,"\u05e1\u05d9\u05dc\u05d5\u05df \u05de\u05d5\u05d3\u05e8\u05e0\u05d9, \u05db\u05de\u05d7\u05e6\u05d9\u05ea \u05de\u05de\u05e9\u05e7\u05dc \u05d4\u05de\u05e0\u05d5\u05e2 \u05e2\u05e9\u05d5\u05d9\u05d4 \u05de\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05db\u05d0\u05dc\u05d4."],[38.0,"\u05e9\u05e0\u05e7\u05e8\u05d0\u05d9\u05dd \u05d2\u05de\u05d0 \u05e4\u05e8\u05d9\u05d9\u05dd, \u05ea\u05e8\u05db\u05d5\u05d1\u05ea \u05e9\u05dc \u05e0\u05d9\u05e7\u05dc \u05e2\u05dd \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd."],[52.0,"\u05de\u05ea\u05e8\u05db\u05db\u05d5\u05ea. \u05d1\u05d7\u05dc\u05e7 \u05de\u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05e0\u05d9\u05d5\u05d1\u05d9\u05d5\u05dd, \u05e9\u05d9\u05d5\u05e6\u05e8 \u05de\u05e9\u05e7\u05e2 \u05d3\u05d5\u05de\u05d4, \u05d5\u05d6\u05d4 \u05d4\u05de\u05e6\u05d1 \u05d1-718 Inconel"],[69.0,"\u05d4\u05d2\u05e8\u05e1\u05d4 \u05d4\u05de\u05d5\u05e7\u05e9\u05d5\u05d9\u05ea \u05d1\u05de\u05e9\u05e7\u05e2 \u05e9\u05dc\u05d4, Monel K-500 \u05de\u05e9\u05de\u05e2\u05d5\u05ea \u05dc\u05e6\u05d9\u05e8\u05d9 \u05de\u05e9\u05d0\u05d1\u05d5\u05ea \u05d5\u05dc\u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05d9\u05de\u05d9\u05d9\u05dd."],[85.0,"\u05d9\u05d7\u05e1\u05d9\u05ea, \u05d5\u05dc\u05db\u05df \u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05e6\u05e0\u05e8\u05ea, \u05d1\u05ea\u05e2\u05e9\u05d5\u05d9\u05d9\u05d4 \u05d4\u05d9\u05de\u05d9\u05ea \u05d5\u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4 \u05d4\u05db\u05d9\u05de\u05d9\u05ea."],[101.0,"\u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc, \u05d5\u05e9\u05d5\u05de\u05e8\u05ea \u05e2\u05dc\u05d9\u05d5 \u05e2\u05d3 \u05db\u05e9\u05d5\u05e9 \u05de\u05d0\u05d5\u05ea \u05d5\u05d7\u05de\u05d9\u05e9\u05d9\u05dd \u05de\u05e2\u05dc\u05d5\u05ea."],[114.0,"\u05d5\u05d1\u05db\u05dc\u05d9\u05dd \u05dc\u05d4\u05e4\u05e7\u05ea \u05e0\u05e4\u05d8 \u05d5\u05d2\u05d6. \u05d5-6-276 Hastelloy, \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05d4\u05d9\u05d0 \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05dc\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05d4\u05db\u05d9\u05de\u05d9\u05d5\u05ea \u05d4\u05e7\u05e9\u05d5\u05ea \u05d1\u05d9\u05d5\u05ea\u05e8."],[129.0,"\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d4\u05d7\u05de\u05d9\u05dd \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e9\u05dc \u05d4\u05de\u05e0\u05d5\u05e2, \u05db\u05de\u05d5 \u05dc\u05d4\u05d1\u05d9 \u05d4\u05d8\u05d5\u05e8\u05d1\u05d9\u05e0\u05d4, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d9\u05e6\u05d9\u05e7\u05d4 \u05de\u05d9\u05d5\u05d7\u05d3\u05d5\u05ea."],[136.0,"\u05d1\u05db\u05dc\u05dc, \u05db\u05d9 \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d4\u05dd \u05d4\u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05de\u05ea\u05d7\u05d9\u05dc\u05d4 \u05d4\u05d6\u05d7\u05d9\u05dc\u05d4."],[145.0,"\u05d1\u05d8\u05de\u05e1\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8, \u05d0\u05d1\u05dc \u05d1\u05d7\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4 \u05d4\u05dd \u05d3\u05d5\u05d5\u05e7\u05d0 \u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05d7\u05d5\u05dc\u05e9\u05d4."],[153.0,"\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9 \u05e9\u05dc \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e0\u05d9\u05e7\u05dc \u05d4\u05d5\u05d0 \u05de\u05d4\u05e7\u05e9\u05d5\u05d9\u05dd \u05e9\u05d9\u05e9, \u05e7\u05e9\u05d4 \u05d0\u05e4\u05d9\u05dc\u05d5 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd."],[159.0,"\u05db\u05da \u05e9\u05d4\u05db\u05dc\u05d9 \u05e4\u05d5\u05d2\u05e9 \u05d7\u05d5\u05de\u05e8 \u05d7\u05d6\u05e7 \u05db\u05dc \u05d4\u05d6\u05de\u05df. \u05d4\u05df \u05d2\u05dd \u05de\u05db\u05d9\u05dc\u05d5\u05ea \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05e9\u05d5\u05d7\u05e7\u05d9\u05dd."],[173.0,"\u05dc\u05db\u05df \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05d9\u05d5\u05ea \u05d7\u05d9\u05ea\u05d5\u05da \u05e0\u05de\u05d5\u05db\u05d5\u05ea \u05de\u05d0\u05d5\u05d3, \u05d1\u05db\u05dc\u05d9\u05dd \u05d7\u05d3\u05d9\u05dd, \u05e2\u05dd \u05d4\u05d6\u05e0\u05d4 \u05e7\u05d1\u05d5\u05e2\u05d4, \u05d5\u05d1\u05dc\u05d9 \u05dc\u05e9\u05e4\u05e9\u05e3 \u05d0\u05e3 \u05e4\u05e2\u05dd."],[180.0,"\u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05ea \u05d4\u05de\u05e0\u05d5\u05e2\u05d9\u05dd \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d2\u05dd \u05d1\u05db\u05dc\u05d9\u05dd \u05e7\u05e8\u05de\u05d9\u05d9\u05dd, \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05d9\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d5\u05ea, \u05dc\u05d4\u05d5\u05e8\u05d3\u05ea \u05d7\u05d5\u05de\u05e8 \u05d2\u05e1."],[196.0,"\u05d5\u05de\u05d9 \u05e9\u05de\u05e2\u05d1\u05d3 718 Inconel \u05e6\u05e8\u05d9\u05da \u05dc\u05d3\u05e2\u05ea \u05d1\u05d0\u05d9\u05d6\u05d4 \u05de\u05e6\u05d1 \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05d2\u05d9\u05e2: \u05de\u05e8\u05d5\u05db\u05da, \u05d0\u05d5 \u05db\u05d1\u05e8 \u05de\u05d5\u05d6\u05e7\u05df \u05d5\u05e7\u05e9\u05d4."],[205.0,"\u05d4\u05d9\u05d0 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05e2\u05e9\u05e8\u05d9\u05dd \u05e2\u05d3 \u05d7\u05de\u05d9\u05e9\u05d9\u05dd \u05de\u05d8\u05e8 \u05dc\u05d3\u05e7\u05d4, \u05d1\u05e2\u05e8\u05da \u05de\u05d7\u05e6\u05d9\u05ea \u05de\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd."],[216.0,"\u05e9\u05d7\u05d9\u05e7\u05ea \u05d4\u05db\u05dc\u05d9\u05dd \u05d4\u05dd \u05d7\u05d5\u05d1\u05d4, \u05db\u05d9 \u05db\u05dc\u05d9 \u05e9\u05d7\u05d5\u05e7 \u05de\u05e7\u05e9\u05d4 \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8."],[225.0,"\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05e2\u05dc\u05d5\u05dc\u05d5\u05ea \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7 \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05e9\u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."],[240.0,"\u05de\u05e0\u05e7\u05d9\u05dd \u05d4\u05d9\u05d8\u05d1 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05dc\u05d0 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05db\u05dc\u05d9\u05dd \u05d0\u05d5 \u05d1\u05de\u05d1\u05e8\u05e9\u05d5\u05ea \u05e9\u05e2\u05d1\u05d3\u05d5 \u05e2\u05dc \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd."],[257.0,"\u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05d5\u05e9\u05d9\u05e9\u05d4 \u05d0\u05d7\u05d5\u05d6 \u05e0\u05d9\u05e7\u05dc, \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05ea\u05e8\u05d7\u05d1 \u05d1\u05d7\u05d5\u05dd, \u05d1\u05e2\u05e8\u05da \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea \u05de\u05e4\u05dc\u05d3\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4."],[267.0,"\u05de\u05ea\u05e8\u05d7\u05d1 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05db\u05de\u05d5 \u05d6\u05db\u05d5\u05db\u05d9\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05dc\u05d6\u05db\u05d5\u05db\u05d9\u05ea \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05d9\u05dd \u05d0\u05d8\u05d5\u05de\u05d9\u05dd."],[282.0,"\u05d0\u05d5\u05ea\u05d5 \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05d2\u05e1, \u05d5\u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d2\u05de\u05e8 \u05d0\u05d7\u05e8 \u05db\u05da."],[292.0,"\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e7\u05d5\u05d1\u05dc\u05d8, \u05db\u05de\u05d5 Stellite, \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05d0\u05d5\u05d3 \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4, \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d5\u05d1\u05d7\u05d5\u05dd."],[298.0,"\u05d0\u05d5\u05ea\u05d4 \u05e2\u05dc \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e0\u05e9\u05d7\u05e7\u05d9\u05dd, \u05db\u05de\u05d5 \u05de\u05d5\u05e9\u05d1\u05d9 \u05e9\u05e1\u05ea\u05d5\u05de\u05d9\u05dd, \u05dc\u05d4\u05d1\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da \u05d5\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05dc \u05de\u05e9\u05d0\u05d1\u05d5\u05ea."],[308.0,"\u05e0\u05de\u05e1 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05de\u05e9\u05dc\u05d5\u05e9\u05ea \u05d0\u05dc\u05e4\u05dc\u05d9\u05dd \u05d5\u05d0\u05e8\u05d1\u05e2 \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05db\u05d1\u05d3 \u05e4\u05d9 \u05e9\u05e0\u05d9\u05d9\u05dd \u05d5\u05d7\u05e6\u05d9 \u05de\u05e4\u05dc\u05d3\u05d4."],[323.0,"\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05de\u05e9\u05de\u05e9 \u05d1\u05d7\u05dc\u05e7\u05d9 \u05ea\u05e0\u05d5\u05e8\u05d9\u05dd, \u05d5\u05d8\u05e0\u05d8\u05dc\u05d5\u05dd \u05d1\u05e6\u05d9\u05d5\u05d3 \u05db\u05d9\u05de\u05d9 \u05d5\u05d1\u05e9\u05ea\u05dc\u05d9\u05dd."],[337.0,"\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d8\u05d4\u05d5\u05e8 \u05e7\u05e9\u05d4 \u05d5\u05e4\u05e8\u05d9\u05da, \u05d5\u05dc\u05db\u05df \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05d4\u05e9\u05d7\u05d6\u05d4 EDM-21"],[344.0,"\u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea 8231 \u05d5-8291 \u05de\u05e9\u05de\u05e9\u05d5\u05ea \u05dc\u05d2\u05d5\u05e4\u05d9 \u05de\u05db\u05e9\u05d9\u05e8\u05d9\u05dd, \u05dc\u05d7\u05dc\u05e7\u05d9 \u05e8\u05db\u05d1 \u05d5\u05dc\u05ea\u05e2\u05d5\u05e4\u05d4."],[361.0,"\u05d3\u05e7\u05d9\u05dd \u05d5\u05d0\u05d1\u05e7\u05d4 \u05e9\u05dc\u05d5 \u05e2\u05dc\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05ea\u05dc\u05e7\u05d7, \u05d5\u05dc\u05d0 \u05de\u05db\u05d1\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d1\u05de\u05d9\u05dd."],[370.0,"\u05d5\u05de\u05d7\u05e9\u05de\u05e9\u05d5\u05ea \u05dc\u05d9\u05e6\u05d9\u05e7\u05d5\u05ea \u05dc\u05d7\u05e5 \u05e7\u05d8\u05e0\u05d5\u05ea \u05d5\u05d6\u05d5\u05dc\u05d5\u05ea, \u05db\u05de\u05d5 \u05d9\u05d3\u05d9\u05d5\u05ea \u05d5\u05de\u05e0\u05e2\u05d5\u05dc\u05d9\u05dd."],[380.0,"\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea, \u05d0\u05ea \u05de\u05e6\u05d1 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05d5\u05d0\u05ea \u05d4\u05ea\u05e7\u05df."],[394.0,"\u05e9\u05d4\u05ea\u05e2\u05e8\u05d1\u05d1 \u05d1\u05de\u05dc\u05d0\u05d9, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05db\u05e9\u05d9\u05e8 ]\u05d4\u05d0 \u05d9\u05d3\u05e0\u05d9, \u05e9\u05de\u05e8\u05d0\u05d4 \u05d0\u05ea \u05d4\u05d4\u05e8\u05db\u05d1 \u05ea\u05d5\u05da \u05e9\u05e0\u05d9\u05d5\u05ea. \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8?"],[410.0,"\u05d1\u05e8\u05de\u05d4 \u05d0\u05d5\u05d5\u05d9\u05e8\u05d9\u05ea. \u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05e9\u05d1\u05d1\u05d9\u05dd \u05e9\u05dc \u05e0\u05d9\u05e7\u05dc \u05d5\u05e7\u05d5\u05d1\u05dc\u05d8 \u05e9\u05d5\u05d5\u05d9\u05dd \u05db\u05e1\u05e3 \u05e8\u05d1, \u05d5\u05dc\u05db\u05df \u05d0\u05d5\u05e1\u05e4\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d1\u05e0\u05e4\u05e8\u05d3."],[423.0,"\u05d4\u05e7\u05e9\u05d9\u05dd \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d5\u05de\u05e1\u05d1\u05d9\u05d1\u05df \u05d9\u05e9 \u05de\u05e9\u05e4\u05d7\u05d4 \u05e9\u05dc \u05de\u05ea\u05db\u05d5\u05ea \u05de\u05d9\u05d5\u05d7\u05d3\u05d5\u05ea, \u05db\u05dc \u05d0\u05d7\u05ea \u05dc\u05d1\u05e2\u05d9\u05d4 \u05de\u05e1\u05d5\u05d9\u05de\u05ea."],[434.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05dc\u05e2\u05d5\u05de\u05e7 \u05de\u05ea\u05db\u05ea \u05d0\u05d7\u05ea \u05de\u05d9\u05d5\u05d7\u05d3\u05ea: \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df."]]};
window.MH_TR["\u05e4\u05e8\u05e716_\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df"]={"t":"\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df","l":[[1.0,"\u05d5\u05d0\u05e8\u05d1\u05e2 \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea. \u05d4\u05e6\u05e4\u05d9\u05e4\u05d5\u05ea \u05e9\u05dc\u05d5 \u05db\u05de\u05d5 \u05e9\u05dc \u05d6\u05d4\u05d1, \u05db\u05de\u05e2\u05d8 \u05e4\u05d9 \u05e9\u05e0\u05d9\u05d9\u05dd \u05d5\u05d7\u05e6\u05d9 \u05de\u05e4\u05dc\u05d3\u05d4."],[15.0,"\u05de\u05d0\u05d5\u05d3. \u05d5\u05d4\u05d5\u05d0 \u05d1\u05d5\u05dc\u05e2 \u05e7\u05e8\u05d9\u05e0\u05d4 \u05d8\u05d5\u05d1 \u05de\u05d0\u05d5\u05d3. \u05d0\u05d1\u05dc \u05d9\u05e9 \u05dc\u05d5 \u05d2\u05dd \u05e9\u05ea\u05d9 \u05d7\u05d5\u05dc\u05e9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea."],[25.0,"\u05ea\u05dc\u05d5\u05d9\u05d4 \u05d1\u05d8\u05d5\u05d4\u05e8 \u05d5\u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05e2\u05d1\u05e8, \u05d5\u05dc\u05db\u05df \u05e9\u05e0\u05d9 \u05de\u05d5\u05d8\u05d5\u05ea \u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05ea\u05e0\u05d4\u05d2 \u05d0\u05d7\u05e8\u05ea \u05dc\u05d2\u05de\u05e8\u05d9."],[41.0,"\u05dc\u05db\u05df \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d5\u05ea \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d1\u05d3 \u05e8\u05e7 \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d0\u05d5 \u05d1\u05d2\u05d6 \u05de\u05d2\u05df."],[50.0,"\u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05db\u05d6\u05d5 \u05d5\u05dc\u05e9\u05dc\u05d5\u05d8 \u05d1\u05d4. \u05d1\u05de\u05e7\u05d5\u05dd \u05d6\u05d4 \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05de\u05d0\u05d1\u05e7\u05d4."],[59.0,"\u05db\u05d5\u05d1\u05e9\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05dc\u05e6\u05d5\u05e8\u05d4, \u05d5\u05de\u05e1\u05e0\u05d8\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d0\u05d5\u05d3, \u05e2\u05d3 \u05e9\u05d4\u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05de\u05ea\u05d7\u05d1\u05e8\u05d9\u05dd."],[69.0,"\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d2\u05d5\u05e9 \u05d1\u05d7\u05d5\u05dd, \u05d1\u05db\u05d1\u05d9\u05e9\u05d4 \u05e1\u05d9\u05d1\u05d5\u05d1\u05d9\u05ea, \u05d1\u05d2\u05dc\u05d2\u05d5\u05dc \u05d5\u05d1\u05de\u05e9\u05d9\u05db\u05d4, \u05dc\u05de\u05d5\u05d8\u05d5\u05ea, \u05dc\u05e4\u05d7\u05d9\u05dd \u05d5\u05dc\u05d7\u05d5\u05d8\u05d9\u05dd."],[77.0,"\u05db\u05da \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d7\u05d5\u05d8\u05d9 \u05dc\u05d4\u05d8, \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05dc\u05e8\u05d9\u05ea\u05d5\u05da 1!6, \u05d2\u05d5\u05e4\u05d9 \u05d7\u05d9\u05de\u05d5\u05dd \u05d1\u05ea\u05e0\u05d5\u05e8\u05d9 \u05d5\u05d0\u05e7\u05d5\u05dd, \u05d5\u05d0\u05e0\u05d5\u05d3\u05d5\u05ea \u05d1\u05de\u05db\u05e9\u05d9\u05e8\u05d9 \u05e8\u05e0\u05d8\u05d2\u05df."],[86.0,"\u05d4\u05ea\u05d5\u05e1\u05e4\u05ea: \u05d9\u05e8\u05d5\u05e7 \u05dc\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d8\u05d4\u05d5\u05e8, \u05d0\u05e4\u05d5\u05e8 \u05dc\u05ea\u05d5\u05e1\u05e4\u05ea \u05e6\u05e8\u05d9\u05d5\u05dd, \u05d5\u05d7\u05d4\u05d1 \u05d0\u05d5 \u05db\u05d7\u05d5\u05dc \u05dc\u05ea\u05d5\u05e1\u05e4\u05ea \u05dc\u05e0\u05ea\u05df."],[99.0,"\u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05d4\u05d0\u05d3\u05d5\u05de\u05d5\u05ea, \u05e2\u05dd \u05ea\u05d5\u05e8\u05d9\u05d5\u05dd, \u05de\u05d5\u05d7\u05dc\u05e4\u05d5\u05ea \u05d4\u05d9\u05d5\u05dd \u05d1\u05d2\u05dc\u05dc \u05d4\u05e7\u05e8\u05d9\u05e0\u05d4 \u05e9\u05dc\u05d4\u05df."],[105.0,"\u05ea\u05e9\u05e2\u05d9\u05dd \u05dc\u05ea\u05e9\u05e2\u05d9\u05dd \u05d5\u05e9\u05d1\u05e2\u05d4 \u05d0\u05d7\u05d5\u05d6 \u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df, \u05d5\u05e2\u05d5\u05d3 \u05de\u05e2\u05d8 \u05e0\u05d9\u05e7\u05dc \u05d5\u05d1\u05e8\u05d6\u05dc, \u05d0\u05d5 \u05e0\u05d9\u05e7\u05dc \u05d5\u05e0\u05d7\u05d5\u05e9\u05ea."],[119.0,"\u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df, \u05db\u05da \u05e9\u05de\u05ea\u05e7\u05d1\u05dc \u05de\u05d1\u05e0\u05d4 \u05e9\u05dc \u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05d1\u05ea\u05d5\u05da \u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05de\u05e9\u05e9\u05d9\u05db\u05d4."],[129.0,"\u05d5\u05d7\u05e6\u05d9, \u05d0\u05d1\u05dc \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05d5\u05e4\u05da \u05dc\u05d7\u05d6\u05e7 \u05d5\u05de\u05e9\u05d9\u05da \u05de\u05e1\u05e4\u05d9\u05e7, \u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05d1\u05d3 \u05d0\u05d5\u05ea\u05d5."],[137.0,"\u05dc\u05d9\u05d3 \u05de\u05db\u05e9\u05d5\u05d5\u05e8 \u05e8\u05d2\u05d9\u05e9. \u05d1\u05ea\u05e7\u05df 8777 ASTM \u05d4\u05df \u05de\u05d7\u05d5\u05dc\u05e7\u05d5\u05ea \u05dc\u05d0\u05e8\u05d1\u05e2 \u05de\u05d7\u05dc\u05e7\u05d5\u05ea, \u05dc\u05e4\u05d9 \u05d0\u05d7\u05d5\u05d6 \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df."],[155.0,"\u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc, \u05d5\u05d4\u05d4\u05ea\u05d0\u05e8\u05db\u05d5\u05ea \u05e0\u05e2\u05d4 \u05de\u05db\u05de\u05d4 \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd \u05d5\u05e2\u05d3 \u05e2\u05e9\u05e8\u05d5\u05ea \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd, \u05dc\u05e4\u05d9 \u05d0\u05d7\u05d5\u05d6 \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05d5\u05dc\u05e4\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05e2\u05d1\u05e8\u05d5."],[167.0,"\u05dc\u05e2\u05e6\u05d5\u05e8 \u05e7\u05e8\u05d9\u05e0\u05d4: \u05de\u05d9\u05d2\u05d5\u05df \u05d5\u05e7\u05d5\u05dc\u05d9\u05de\u05d8\u05d5\u05e8\u05d9\u05dd \u05d1\u05de\u05db\u05e9\u05d5\u05e8 \u05e8\u05e4\u05d5\u05d0\u05d9 \u05d5\u05ea\u05e2\u05e9\u05d9\u05d9\u05ea\u05d9."],[181.0,"\u05d5\u05db\u05e9\u05e6\u05e8\u05d9\u05da \u05e7\u05e9\u05d9\u05d7\u05d5\u05ea: \u05de\u05d5\u05d8\u05d5\u05ea \u05db\u05e8\u05e1\u05d5\u05dd \u05d5\u05e7\u05d9\u05d3\u05d5\u05d7 \u05d0\u05e8\u05d5\u05db\u05d9\u05dd \u05e0\u05d2\u05d3 \u05e8\u05e2\u05d9\u05d3\u05d5\u05ea, \u05db\u05d9 \u05d4\u05de\u05d5\u05d3\u05d5\u05dc \u05d4\u05d2\u05d1\u05d5\u05d4 \u05d5\u05d4\u05de\u05e9\u05e7\u05dc \u05de\u05e8\u05e1\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e8\u05e2\u05d9\u05d3\u05d4."],[191.0,"\u05d1\u05d6\u05d5\u05d5\u05d9\u05ea \u05d7\u05d9\u05ea\u05d5\u05da \u05d7\u05d9\u05d5\u05d1\u05d9\u05ea, \u05d5\u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05d9\u05d5\u05ea \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05d5\u05ea. \u05d4\u05e9\u05d1\u05d1 \u05e7\u05e6\u05e8 \u05d5\u05e9\u05d1\u05d9\u05e8, \u05d5\u05dc\u05e2\u05ea\u05d9\u05dd \u05d0\u05d1\u05e7\u05ea\u05d9."],[207.0,"\u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05d1\u05e2\u05d3\u05d9\u05e0\u05d5\u05ea. \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e7\u05d3\u05d5\u05d7 \u05d5\u05dc\u05d4\u05d1\u05e8\u05d9\u05d2, \u05d0\u05d1\u05dc \u05db\u05e8\u05e1\u05d5\u05dd \u05d4\u05d1\u05e8\u05d2\u05d4 \u05d1\u05d8\u05d5\u05d7 \u05d9\u05d5\u05ea\u05e8 \u05de\u05de\u05d1\u05e8\u05d6."],[221.0,"\u05d7\u05d9\u05ea\u05d5\u05da: \u05d4\u05d5\u05d0 \u05e0\u05e1\u05d3\u05e7 \u05d5\u05de\u05ea\u05e4\u05d5\u05e8\u05e8, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5, \u05d0\u05d5 \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 EDM-2"],[232.0,"\u05d1\u05db\u05dc\u05d9 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05e2\u05e6\u05de\u05dd. \u05e7\u05e8\u05d1\u05d9\u05d3 \u05e6\u05de\u05e0\u05d8\u05d9 \u05d4\u05d5\u05d0 \u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05e9\u05dc \u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df \u05e7\u05e8\u05d1\u05d9\u05d3, \u05de\u05d7\u05d5\u05d1\u05e8\u05d9\u05dd \u05d1\u05e7\u05d5\u05d1\u05dc\u05d8, \u05e9\u05de\u05e1\u05d5\u05e0\u05d8\u05e8\u05d9\u05dd \u05d9\u05d7\u05d3."],[244.0,"\u05d4\u05d0\u05dc\u05e1\u05d8\u05d9\u05d5\u05ea \u05e9\u05dc\u05d5 \u05e4\u05d9 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05de\u05e9\u05dc \u05e4\u05dc\u05d3\u05d4, \u05d5\u05d4\u05d5\u05d0 \u05e2\u05d5\u05de\u05d3 \u05d1\u05dc\u05d7\u05d9\u05e6\u05d4 \u05e2\u05e6\u05d5\u05de\u05d4, \u05d0\u05d1\u05dc \u05e4\u05e8\u05d9\u05da \u05d1\u05de\u05ea\u05d9\u05d7\u05d4 \u05d5\u05d1\u05de\u05db\u05d4."],[255.0,"\u05e2\u05d3\u05d9\u05e0\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05de\u05ea\u05d7\u05ea \u05dc\u05de\u05d9\u05e7\u05e8\u05d5\u05df, \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05d2\u05dd \u05e7\u05e9\u05d9\u05d5\u05ea \u05d5\u05d2\u05dd \u05e7\u05e9\u05d9\u05d7\u05d5\u05ea \u05d8\u05d5\u05d1\u05d4."],[269.0,"\u05d9\u05e6\u05d5\u05e7, \u05d0 \u05dc\u05de\u05ea\u05db\u05d5\u05ea \u05dc\u05d0 \u05d1\u05e8\u05d6\u05dc\u05d9\u05d5\u05ea, 5 \u05dc\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d7\u05d5\u05dd \u05d5\u05dc\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd, H-1 \u05dc\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05de\u05d5\u05e7\u05e9\u05d9\u05dd."],[288.0,"\u05d5\u05dc\u05d7\u05d9\u05ea\u05d5\u05da \u05dc\u05d0 \u05e8\u05e6\u05d9\u05e3. \u05d5\u05e2\u05dc \u05e8\u05d5\u05d1 \u05d4\u05dc\u05d4\u05d1\u05d9\u05dd \u05d9\u05e9 \u05e6\u05d9\u05e4\u05d5\u05d9, CVD \u05d0\u05d5 PVD, \u05e9\u05de\u05d0\u05e8\u05d9\u05da \u05d0\u05ea \u05d7\u05d9\u05d9\u05d4\u05dd."],[305.0,"\u05de\u05d0\u05d5\u05ea\u05d5 \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d2\u05dd \u05d7\u05dc\u05e7\u05d9 \u05d1\u05dc\u05d0\u05d9: \u05de\u05d1\u05dc\u05d8\u05d9\u05dd, \u05d8\u05d1\u05e2\u05d5\u05ea \u05de\u05e9\u05d9\u05db\u05d4, \u05e0\u05d7\u05d9\u05e8\u05d9 \u05d4\u05ea\u05d6\u05d4 \u05d5\u05de\u05d3\u05d9\u05d3\u05d9\u05dd."],[313.0,"\u05d1\u05db\u05d0\u05dc\u05e4\u05d9\u05d9\u05dd \u05e9\u05e9 \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea, \u05e7\u05dc \u05de\u05de\u05e0\u05d5 \u05d1\u05d7\u05e6\u05d9, \u05d5\u05e7\u05dc \u05d9\u05d5\u05ea\u05e8 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3."],[321.0,"\u05d6\u05db\u05d5\u05db\u05d9\u05ea, \u05d5\u05d1\u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd. \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d5\u05d0\u05d517, \u05e2\u05dd \u05de\u05e2\u05d8 \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d5\u05d6\u05d9\u05e8\u05e7\u05d5\u05df, \u05d7\u05d6\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05d7\u05d5\u05dd."],[334.0,"\u05d5\u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 8, \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05d4\u05d5\u05d0 \u05d2\u05dd \u05d9\u05e1\u05d5\u05d3 \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d7\u05e9\u05d5\u05d1 \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea."],[340.0,"\u05d5\u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d0\u05d1\u05e7 \u05de\u05d4\u05e9\u05d7\u05d6\u05d4 \u05e9\u05dc \u05e7\u05e8\u05d1\u05d9\u05d3 \u05e6\u05de\u05e0\u05d8\u05d9, \u05e9\u05de\u05db\u05d9\u05dc \u05e7\u05d5\u05d1\u05dc\u05d8, \u05de\u05d6\u05d9\u05e7\u05d4 \u05de\u05d0\u05d5\u05d3 \u05dc\u05e8\u05d9\u05d0\u05d5\u05ea."],[350.0,"\u05d4\u05d0\u05d1\u05e7 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d3\u05d7\u05d5\u05e1. \u05d5\u05d1\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05db\u05d1\u05d3\u05d5\u05ea, \u05d2\u05dd \u05d7\u05dc\u05e7 \u05e7\u05d8\u05df \u05e9\u05d5\u05e7\u05dc \u05d4\u05e8\u05d1\u05d4, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05dc\u05ea\u05db\u05e0\u05df \u05d0\u05ea \u05d4\u05d4\u05e8\u05de\u05d4 \u05d5\u05d4\u05d4\u05d9\u05d3\u05d5\u05e7."],[364.0,"\u05de\u05e6\u05d9\u05d9\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05d7\u05dc\u05e7\u05d4 \u05dc\u05e4\u05d9 \u05d4\u05ea\u05e7\u05df, \u05dc\u05de\u05e9\u05dc ASTM B777 \u05de\u05d7\u05dc\u05e7\u05d4 3, \u05d5\u05d0\u05dd \u05d4\u05d7\u05dc\u05e7 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05dc\u05d0 \u05de\u05d2\u05e0\u05d8\u05d9."],[379.0,"\u05d1\u05e9\u05e7\u05d9\u05dc\u05d4 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d5\u05d1\u05de\u05d9\u05dd, \u05d5\u05d6\u05d5 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4 \u05d5\u05d0\u05de\u05d9\u05e0\u05d4 \u05dc\u05d0\u05d7\u05d5\u05d6 \u05d4\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df. \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8?"],[390.0,"\u05de\u05d9\u05d5\u05ea\u05e8 \u05e2\u05d5\u05dc\u05d4 \u05db\u05e1\u05e3. \u05d9\u05d9\u05e6\u05d5\u05e8 \u05de\u05d0\u05d1\u05e7\u05d4 \u05dc\u05e6\u05d5\u05e8\u05d4 \u05e7\u05e8\u05d5\u05d1\u05d4 \u05dc\u05e1\u05d5\u05e4\u05d9\u05ea \u05d7\u05d5\u05e1\u05da \u05d7\u05d5\u05de\u05e8 \u05d5\u05e2\u05d9\u05d1\u05d5\u05d3."],[402.0,"\u05e7\u05e8\u05d1\u05d9\u05d3 \u05e9\u05d7\u05d5\u05e7\u05d9\u05dd \u05e0\u05d9\u05ea\u05e0\u05d9\u05dd \u05dc\u05de\u05d7\u05d6\u05d5\u05e8, \u05d5\u05dc\u05db\u05df \u05d0\u05d5\u05e1\u05e4\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d1\u05e0\u05e4\u05e8\u05d6."],[411.0,"\u05d1\u05e0\u05e4\u05d7 \u05e7\u05d8\u05df \u05d5\u05dc\u05de\u05d9\u05d2\u05d5\u05df, \u05d5\u05d4\u05d5\u05d0 \u05d2\u05dd \u05d4\u05d1\u05e1\u05d9\u05e1 \u05dc\u05db\u05dc\u05d9 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05e9\u05d0\u05e0\u05d7\u05e0\u05d5 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4\u05dd \u05db\u05dc \u05d9\u05d5\u05dd."],[422.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05ea\u05d7\u05d9\u05dc \u05dc\u05d3\u05d1\u05e8 \u05e2\u05dc \u05d4\u05ea\u05e0\u05d4\u05d2\u05d5\u05ea \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d1\u05e9\u05d9\u05e8\u05d5\u05ea, \u05d5\u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."]]};
window.MH_TR["\u05e4\u05e8\u05e717_\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4"]={"t":"\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4","l":[[1.0,"\u05d1\u05d8\u05d1\u05e2. \u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d5\u05e4\u05e7 \u05de\u05ea\u05d7\u05de\u05d5\u05e6\u05ea, \u05d5\u05d4\u05d5\u05d0 \u05e9\u05d5\u05d0\u05e3 \u05dc\u05d7\u05d6\u05d5\u05e8 \u05d0\u05dc\u05d9\u05d4. \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05d5\u05d0 \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05db\u05d9\u05de\u05d9, \u05db\u05de\u05d5 \u05e1\u05d5\u05dc\u05dc\u05d4 \u05e7\u05d8\u05e0\u05d4."],[13.0,"\u05d5\u05de\u05ea\u05de\u05d5\u05e1\u05e1\u05ea. \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05d6\u05d5\u05e8\u05de\u05d9\u05dd \u05d3\u05e8\u05da \u05d4\u05de\u05ea\u05db\u05ea \u05d0\u05dc \u05d4\u05e7\u05ea\u05d5\u05d3\u05d4, \u05d5\u05e9\u05dd \u05d4\u05dd \u05de\u05d2\u05d9\u05d1\u05d9\u05dd \u05e2\u05dd \u05d7\u05de\u05e6\u05df \u05d5\u05de\u05d9\u05dd."],[29.0,"\u05d4\u05de\u05e2\u05d2\u05dc. \u05d0\u05dd \u05de\u05d5\u05e6\u05d9\u05d0\u05d9\u05dd \u05d0\u05d7\u05d3 \u05de\u05d0\u05e8\u05d1\u05e2\u05ea \u05d4\u05e8\u05db\u05d9\u05d1\u05d9\u05dd, \u05d4\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05e0\u05e2\u05e6\u05e8\u05ea, \u05d5\u05d6\u05d4 \u05d4\u05d1\u05e1\u05d9\u05e1 \u05dc\u05db\u05dc \u05e9\u05d9\u05d8\u05d5\u05ea \u05d4\u05d4\u05d2\u05e0\u05d4."],[41.0,"\u05db\u05d5\u05dc\u05dd \u05e0\u05d0\u05db\u05dc\u05d9\u05dd \u05d1\u05e7\u05e6\u05d1 \u05d3\u05d5\u05de\u05d4. \u05d4\u05d9\u05d0 \u05d4\u05e6\u05e4\u05d5\u05d9\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d5\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd \u05dc\u05e9\u05e0\u05d4."],[52.0,"\u05d1\u05de\u05d1\u05e0\u05d9\u05dd \u05de\u05e4\u05dc\u05d3\u05d4 \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05e2\u05d5\u05d1\u05d9 \u05ea\u05d5\u05e1\u05e4\u05ea \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05db\u05da \u05e9\u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e9\u05e0\u05d9\u05dd \u05e9\u05dc \u05e9\u05d9\u05e8\u05d5\u05ea \u05d9\u05d9\u05e9\u05d0\u05e8 \u05de\u05e1\u05e4\u05d9\u05e7 \u05d7\u05d5\u05de\u05e8."],[59.0,"\u05e7\u05e6\u05d1 \u05d4\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05ea\u05dc\u05d5\u05d9 \u05de\u05d0\u05d5\u05d3 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d4: \u05d1\u05dc\u05d7\u05d5\u05ea, \u05d1\u05de\u05dc\u05d7\u05d9\u05dd, \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d5\u05d1\u05d7\u05d5\u05de\u05e6\u05d9\u05d5\u05ea."],[75.0,"\u05e4\u05e0\u05d9\u05dd \u05de\u05d1\u05e0\u05d4 \u05d9\u05d1\u05e9, \u05d5\u05e2\u05d3 CX-1 C5, \u05e1\u05d1\u05d9\u05d1\u05d4 \u05d9\u05de\u05d9\u05ea \u05d0\u05d5 \u05ea\u05e2\u05e9\u05d9\u05d9\u05ea\u05d9\u05ea \u05e7\u05e9\u05d4."],[89.0,"\u05d1\u05d3\u05e8\u05d2\u05d5\u05ea \u05d4\u05d2\u05d1\u05d5\u05d4\u05d5\u05ea, \u05d5\u05d7\u05dc\u05e7 \u05de\u05e4\u05dc\u05d3\u05d4 \u05dc\u05d0 \u05de\u05d5\u05d2\u05e0\u05ea \u05d9\u05d7\u05dc\u05d9\u05d3 \u05e9\u05dd \u05de\u05d4\u05e8 \u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05d0\u05e9\u05e8 \u05d1\u05e4\u05e0\u05d9\u05dd \u05d4\u05d0\u05e8\u05e5."],[100.0,"\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d2\u05dc\u05d5\u05d5\u05e0\u05d9\u05ea. \u05d4\u05d8\u05d5\u05e8 \u05d4\u05d2\u05dc\u05d5\u05d5\u05e0\u05d9 \u05de\u05e1\u05d3\u05e8 \u05d0\u05ea \u05d4\u05de\u05ea\u05db\u05d5\u05ea \u05dc\u05e4\u05d9 \u05d4\u05e0\u05d8\u05d9\u05d9\u05d4 \u05e9\u05dc\u05d4\u05df \u05dc\u05d4\u05d9\u05d0\u05db\u05dc."],[115.0,"\u05d0\u05d7\u05e8\u05d9\u05d4\u05dd \u05e4\u05dc\u05d3\u05d4 \u05d5\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7. \u05d0\u05d7\u05e8 \u05db\u05da \u05e0\u05d7\u05d5\u05e9\u05ea \u05d5\u05e4\u05dc\u05d9\u05d6. \u05d5\u05d1\u05e7\u05e6\u05d4 \u05d4\u05d0\u05e6\u05d9\u05dc\u05d9 \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05e4\u05e1\u05d9\u05d1\u05d9\u05ea, \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d5\u05d2\u05e8\u05e4\u05d9\u05d8."],[129.0,"\u05de\u05e0\u05d7\u05d5\u05e9\u05ea \u05d9\u05d9\u05d0\u05db\u05dc \u05de\u05d4\u05e8 \u05de\u05d0\u05d5\u05d3. \u05d1\u05d5\u05e8\u05d2 \u05e7\u05d8\u05df \u05de\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d1\u05e4\u05d7 \u05d2\u05d3\u05d5\u05dc \u05de\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05d9\u05d6\u05d9\u05e7."],[146.0,"\u05d1\u05e9\u05e0\u05d9 \u05d4\u05de\u05e7\u05e8\u05d9\u05dd, \u05d1\u05dc\u05d9 \u05d1\u05d9\u05d3\u05d5\u05d3, \u05d4\u05de\u05ea\u05db\u05ea \u05d4\u05d0\u05e7\u05d8\u05d9\u05d1\u05d9\u05ea \u05e0\u05d0\u05db\u05dc\u05ea \u05dc\u05d9\u05d3 \u05d4\u05d7\u05d9\u05d1\u05d5\u05e8."],[160.0,"\u05de\u05d0\u05d1\u05e5 \u05de\u05d2\u05d9\u05e0\u05d5\u05ea \u05e2\u05dc \u05d2\u05d5\u05e3 \u05d4\u05e1\u05e4\u05d9\u05e0\u05d4: \u05d4\u05d0\u05d1\u05e5 \u05d0\u05e7\u05d8\u05d9\u05d1\u05d9 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05e0\u05d0\u05db\u05dc \u05d1\u05de\u05e7\u05d5\u05dd \u05d4\u05e4\u05dc\u05d3\u05d4, \u05d5\u05de\u05d7\u05dc\u05d9\u05e4\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05de\u05d3\u05d9 \u05e4\u05e2\u05dd."],[173.0,"\u05e7\u05ea\u05d5\u05d3\u05d9\u05ea \u05d1\u05d6\u05e8\u05dd \u05de\u05d5\u05e9\u05e8\u05d4, \u05e9\u05d1\u05d4 \u05e1\u05e4\u05e7 \u05db\u05d5\u05d7 \u05d3\u05d5\u05d7\u05e3 \u05d6\u05e8\u05dd \u05e9\u05d4\u05d5\u05e4\u05da \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05db\u05d5\u05dc\u05d5 \u05dc\u05e7\u05ea\u05d5\u05d3\u05d4."],[189.0,"\u05d1\u05e9\u05d9\u05d9\u05d1\u05d5\u05ea \u05d5\u05d1\u05e9\u05e8\u05d5\u05d5\u05dc\u05d9\u05dd \u05de\u05d1\u05d5\u05d3\u05d3\u05d9\u05dd, \u05d0\u05d5 \u05de\u05e6\u05e4\u05d9\u05dd, \u05d5\u05de\u05e2\u05d3\u05d9\u05e4\u05d9\u05dd \u05dc\u05e6\u05e4\u05d5\u05ea \u05d3\u05d5\u05d5\u05e7\u05d0 \u05d0\u05ea \u05d4\u05e7\u05ea\u05d5\u05d3\u05d4."],[200.0,"\u05e9\u05e8\u05d5\u05d0\u05d9\u05dd \u05d4\u05e8\u05d1\u05d4 \u05de\u05d1\u05d7\u05d5\u05e5. \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05e0\u05e7\u05d5\u05d3\u05ea\u05d9\u05ea, pitting \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea, \u05d9\u05d5\u05e6\u05e8\u05ea \u05d1\u05d5\u05e8\u05d5\u05ea \u05e6\u05e8\u05d9\u05dd \u05d5\u05e2\u05de\u05d5\u05e7\u05d9\u05dd."],[215.0,"\u05dc\u05d0\u05d8\u05de\u05d9\u05dd \u05d5\u05d1\u05d7\u05d9\u05d1\u05d5\u05e8\u05d9\u05dd \u05e6\u05de\u05d5\u05d3\u05d9\u05dd. \u05d5\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d1\u05d9\u05df \u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05ea \u05de\u05ea\u05e7\u05d3\u05de\u05ea \u05dc\u05d0\u05d5\u05e8\u05da \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd."],[226.0,"\u05de\u05ea\u05e7\u05dc\u05e4\u05ea, \u2026 \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea: \u05e9\u05db\u05d1\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05ea\u05e0\u05e4\u05d7\u05d5\u05ea \u05d5\u05e0\u05e4\u05e8\u05d3\u05d5\u05ea \u05d6\u05d5 \u05de\u05d6\u05d5, \u05dc\u05d0\u05d5\u05e8\u05da \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d2\u05dc\u05d2\u05d5\u05dc."],[239.0,"\u05de\u05e1\u05d5\u05d9\u05de\u05ea. \u05d1\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05ea \u05d6\u05d5 \u05e1\u05d1\u05d9\u05d1\u05d4 \u05e9\u05dc \u05db\u05dc\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d7\u05de\u05d9\u05dd. \u05d1\u05e4\u05dc\u05d9\u05d6, \u05d0\u05de\u05d5\u05e0\u05d9\u05d4."],[254.0,"\u05d1\u05de\u05e6\u05d1 6\u05d6, \u05dc\u05d7\u05d5\u05ea \u05d5\u05de\u05dc\u05d7. \u05d4\u05de\u05d0\u05de\u05e5 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05d2\u05dd \u05de\u05d0\u05de\u05e5 \u05e4\u05e0\u05d9\u05de\u05d9, \u05e9\u05e0\u05e9\u05d0\u05e8 \u05de\u05e2\u05d9\u05d1\u05d5\u05d3, \u05de\u05db\u05d9\u05e4\u05d5\u05e3 \u05d0\u05d5 \u05de\u05e8\u05d9\u05ea\u05d5\u05da."],[269.0,"\u05dc\u05db\u05df \u05de\u05d5\u05e0\u05e2\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05d3\u05d9\u05e7\u05d4 \u05d1\u05d1\u05d7\u05d9\u05e8\u05ea \u05d7\u05d5\u05de\u05e8 \u05e2\u05de\u05d9\u05d3, \u05d1\u05d4\u05e4\u05d2\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d0\u05d5 \u05d1\u05e9\u05d9\u05e0\u05d5\u05d9 \u05d4\u05e1\u05d1\u05d9\u05d1\u05d4."],[276.0,"\u05de\u05e6\u05d8\u05d1\u05e8\u05d9\u05dd \u05d1\u05de\u05e7\u05d5\u05de\u05d5\u05ea \u05e9\u05dc \u05de\u05d0\u05de\u05e5, \u05d5\u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05dc\u05e9\u05d1\u05e8 \u05e4\u05e8\u05d9\u05da, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e9\u05e2\u05d5\u05ea \u05d0\u05d5\u05d9\u05de\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e8\u05db\u05d1\u05d4."],[293.0,"\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05dc\u05d9\u05d8\u05d9 \u05e2\u05d5\u05e9\u05d9\u05dd \u05d0\u05e4\u05d9\u05d9\u05d4 \u05dc\u05d4\u05d5\u05e6\u05d0\u05ea \u05d4\u05de\u05d9\u05de\u05df, \u05ea\u05d5\u05da \u05e9\u05e2\u05d5\u05ea \u05e1\u05e4\u05d5\u05e8\u05d5\u05ea, \u05dc\u05e4\u05d9 \u05d4\u05ea\u05e7\u05df."],[307.0,"\u05e9\u05e2\u05d5\u05ea, \u05d5\u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05dc\u05d0 \u05d9\u05d5\u05ea\u05e8 \u05de\u05db\u05de\u05d4 \u05e9\u05e2\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 \u05e1\u05d9\u05d5\u05dd \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9. \u05db\u05db\u05dc \u05e9\u05d4\u05e4\u05dc\u05d3\u05d4 \u05d7\u05d6\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05d0\u05e4\u05d9\u05d9\u05d4 \u05d0\u05e8\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8."],[319.0,"\u05d5\u05d1\u05d1\u05e8\u05d2\u05d9\u05dd \u05d7\u05d6\u05e7\u05d9\u05dd \u05de\u05d0\u05d5\u05d3 \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e6\u05d9\u05e4\u05d5\u05d9 \u05e9\u05dc\u05d0 \u05de\u05db\u05e0\u05d9\u05e1 \u05de\u05d9\u05de\u05df."],[325.0,"\u05de\u05d5\u05e8\u05d9\u05d3\u05d4 \u05d0\u05ea \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05d2\u05dd \u05dc\u05e4\u05dc\u05d3\u05d4 \u05db\u05d1\u05e8 \u05d0\u05d9\u05df \u05d2\u05d1\u05d5\u05dc \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05d1\u05de\u05d9\u05d9\u05dd."],[336.0,"\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4: \u05d6\u05e8\u05d9\u05de\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4 \u05e9\u05dc \u05e0\u05d5\u05d6\u05dc, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05e2\u05dd \u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd, \u05de\u05e1\u05d9\u05e8\u05d4 \u05d0\u05ea \u05d4\u05e9\u05d5\u05db\u05d1\u05d4 \u05d4\u05e4\u05e1\u05d9\u05d1\u05d9\u05ea \u05e9\u05d5\u05d1 \u05d5\u05e9\u05d5\u05d1."],[344.0,"\u05d7\u05dc\u05e7\u05d9\u05dd \u05e6\u05de\u05d5\u05d3\u05d9\u05dd, \u05db\u05de\u05d5 \u05de\u05d9\u05e1\u05d1 \u05e2\u05dc \u05d2\u05dc, \u05d9\u05d5\u05e6\u05e8\u05d5\u05ea \u05d0\u05d1\u05e7\u05ea \u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05d5\u05e4\u05d5\u05d2\u05e2\u05d5\u05ea \u05d1\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."],[355.0,"\u05de\u05d9\u05dd, \u05d3\u05d5\u05d0\u05d2\u05d9\u05dd \u05dc\u05e0\u05d9\u05e7\u05d5\u05d6, \u05d5\u05dc\u05d0 \u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05de\u05ea\u05db\u05d5\u05ea \u05e8\u05d7\u05d5\u05e7\u05d5\u05ea \u05d1\u05d8\u05d5\u05e8 \u05d4\u05d2\u05dc\u05d5\u05d5\u05e0\u05d9 \u05d1\u05dc\u05d9 \u05d1\u05d9\u05d3\u05d5\u05d3."],[370.0,"\u05d5\u05d0\u05d6 \u05e6\u05d9\u05e4\u05d5\u05d9\u05d9\u05dd \u05d5\u05e6\u05d1\u05e2, \u05db\u05de\u05d5 \u05e9\u05dc\u05de\u05d3\u05e0\u05d5 \u05d1\u05e7\u05d5\u05e8\u05e1 \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9\u05d9\u05dd, \u05d4\u05d2\u05e0\u05d4 \u05e7\u05ea\u05d5\u05d3\u05d9\u05ea, \u05d5\u05de\u05e2\u05db\u05d1\u05d9 \u05e7\u05d5\u05e8\u05d7\u05d9\u05d4."],[377.0,"\u05de\u05d7\u05dc\u05d9\u05d3\u05d9\u05dd \u05de\u05d4\u05e8, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05e0\u05d2\u05e2\u05d5 \u05d1\u05d4\u05dd \u05d1\u05d9\u05d3\u05d9\u05d9\u05dd, \u05db\u05d9 \u05d4\u05d6\u05d9\u05e2\u05d4 \u05de\u05db\u05d9\u05dc\u05d4 \u05de\u05dc\u05d7."],[388.0,"\u05dc\u05db\u05df \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05e2\u05dd \u05db\u05e4\u05e4\u05d5\u05ea, \u05de\u05d2\u05d9\u05e0\u05d9\u05dd \u05d1\u05e9\u05de\u05df, \u05d5\u05d0\u05d5\u05e8\u05d6\u05d9\u05dd \u05d1\u05e9\u05e7\u05d9\u05d5\u05ea \u2026, \u05e9\u05de\u05e9\u05d7\u05e8\u05e8\u05d5\u05ea \u05de\u05e2\u05db\u05d1 \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."],[395.0,"\u05dc\u05d7\u05dc\u05d5\u05d3\u05d4 \u05e2\u05dc \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d5\u05e2\u05dc \u05d4\u05de\u05db\u05d5\u05e0\u05d4, \u05d5\u05dc\u05db\u05df \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d0\u05d5\u05e4\u05df \u05e7\u05d1\u05d5\u05e2."],[404.0,"\u05e0\u05d9\u05e7\u05d5\u05d9, \u05d5\u05dc\u05d0 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d0\u05d5\u05ea\u05dd \u05de\u05d3\u05e4\u05d9\u05dd \u05d5\u05d1\u05d0\u05d5\u05ea\u05dd \u05db\u05dc\u05d9\u05dd \u05dc\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d5\u05dc\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df."],[414.0,"\u05dc\u05d4\u05e9\u05d5\u05d5\u05d0\u05d4 \u05d1\u05d9\u05df \u05e6\u05d9\u05e4\u05d5\u05d9\u05d9\u05dd, \u05d0\u05d1\u05dc \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05de\u05e0\u05d1\u05d0 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05db\u05de\u05d4 \u05d6\u05de\u05df \u05d4\u05d7\u05dc\u05e7 \u05d9\u05d7\u05d6\u05d9\u05e7 \u05d1\u05e9\u05d8\u05d7. \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8?"],[428.0,"\u05de\u05ea\u05db\u05d5\u05ea, \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea. \u05d0\u05d1\u05dc \u05db\u05e9\u05dc \u05d1\u05e9\u05d8\u05d7 \u05d1\u05d2\u05dc\u05dc \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d9\u05e7\u05e8 \u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05db\u05dc \u05d0\u05dc\u05d4. \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d1\u05dc\u05d0\u05d9 \u05d5\u05d4\u05d7\u05d9\u05db\u05d5\u05da."]]};
window.MH_TR["\u05e4\u05e8\u05e718_\u05d1\u05dc\u05d0\u05d9_\u05d5\u05d7\u05d9\u05db\u05d5\u05da"]={"t":"\u05d1\u05dc\u05d0\u05d9 \u05d5\u05d7\u05d9\u05db\u05d5\u05da","l":[[1.0,"\u05db\u05d5\u05dc\u05dd \u05de\u05d0\u05d1\u05d3\u05d9\u05dd \u05d7\u05d5\u05de\u05e8 \u05d1\u05d4\u05d3\u05e8\u05d2\u05d4, \u05e2\u05d3 \u05e9\u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d0\u05d5 \u05d4\u05d2\u05d9\u05de\u05d5\u05e8 \u05db\u05d1\u05e8 \u05dc\u05d0 \u05e2\u05d5\u05de\u05d3\u05d9\u05dd \u05d1\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea."],[16.0,"\u05d5\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d1\u05d9\u05df \u05dc\u05de\u05d4 \u05d3\u05d1\u05e8\u05d9\u05dd \u05e0\u05e9\u05d7\u05e7\u05d9\u05dd, \u05d5\u05d0\u05d9\u05da \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc\u05d9 \u05e9\u05d8\u05d7 \u05e9\u05de\u05d0\u05e8\u05d9\u05db\u05d9\u05dd \u05d0\u05ea \u05d7\u05d9\u05d9\u05d4\u05dd."],[29.0,"\u05d5\u05d2\u05e2\u05d9\u05dd \u05e8\u05e7 \u05d1\u05e7\u05e6\u05d5\u05ea \u05d4\u05e4\u05e1\u05d2\u05d5\u05ea, \u05d5\u05e9\u05d8\u05d7 \u05d4\u05de\u05d2\u05e2 \u05d4\u05d0\u05de\u05d9\u05ea\u05d9 \u05e7\u05d8\u05df \u05de\u05d0\u05d5\u05d3, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e4\u05d7\u05d5\u05ea \u05de\u05d0\u05d7\u05d5\u05d6 \u05de\u05d4\u05e9\u05d8\u05d7 \u05d4\u05e0\u05e8\u05d0\u05d4."],[45.0,"\u05e9\u05d5\u05d1 \u05d5\u05e9\u05d5\u05d1. \u05dc\u05db\u05df \u05db\u05d5\u05d7 \u05d4\u05d7\u05d9\u05db\u05d5\u05da \u05ea\u05dc\u05d5\u05d9 \u05d1\u05e2\u05d5\u05de\u05e1, \u05d0\u05d1\u05dc \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05d1\u05e9\u05d8\u05d7 \u05d4\u05e0\u05e8\u05d0\u05d4."],[56.0,"\u05ea\u05d5\u05e4\u05e2\u05d4 \u05e9\u05db\u05dc \u05de\u05d9 \u05e9\u05e2\u05d5\u05d1\u05d3 \u05e2\u05dd \u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05de\u05db\u05d9\u05e8: \u05d4\u05d3\u05d1\u05e7\u05d4 \u05d5\u05d4\u05d7\u05dc\u05e7\u05d4, stick-slip \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea."],[71.0,"\u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d4, \u05d4\u05d7\u05d9\u05db\u05d5\u05da \u05d4\u05e1\u05d8\u05d8\u05d9 \u05d2\u05d1\u05d5\u05d4 \u05de\u05d4\u05d7\u05d9\u05db\u05d5\u05da \u05d1\u05ea\u05e0\u05d5\u05e2\u05d4, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05e0\u05e2 \u05d1\u05e7\u05e4\u05d9\u05e6\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea \u05d1\u05de\u05e7\u05d5\u05dd \u05d1\u05ea\u05e0\u05d5\u05e2\u05d4 \u05d7\u05dc\u05e7\u05d4."],[79.0,"\u05d4\u05d7\u05dc\u05e7\u05d4 \u05e2\u05dc \u05d1\u05e1\u05d9\u05e1 \u05d3\u05e1, \u05e9\u05d4\u05d7\u05d9\u05db\u05d5\u05da \u05d4\u05e1\u05d8\u05d8\u05d9\u05d5\u05d4\u05d3\u05d9\u05e0\u05de\u05d9 \u05e9\u05dc\u05d4\u05dd \u05db\u05de\u05e2\u05d8 \u05e9\u05d5\u05d5\u05d9\u05dd."],[90.0,"\u05de\u05e8\u05d0\u05d4 \u05d0\u05ea \u05e9\u05dc\u05d5\u05e9\u05ea \u05de\u05e9\u05d8\u05e8\u05d9 \u05d4\u05e1\u05d9\u05db\u05d4, \u05dc\u05e4\u05d9 \u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea, \u05d4\u05e6\u05de\u05d9\u05d2\u05d5\u05ea \u05d5\u05d4\u05e2\u05d5\u05de\u05e1."],[99.0,"\u05e2\u05d3\u05d9\u05d9\u05df \u05e0\u05d5\u05d2\u05e2\u05d5\u05ea, \u05d5\u05d4\u05e9\u05de\u05df \u05de\u05d2\u05df \u05e8\u05e7 \u05d1\u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05e9\u05dc \u05ea\u05d5\u05e1\u05e4\u05d9\u05dd. \u05d1\u05e1\u05d9\u05db\u05d4 \u05de\u05e2\u05d5\u05e8\u05d1\u05ea, \u05d7\u05dc\u05e7 \u05de\u05d4\u05e2\u05d5\u05de\u05e1 \u05db\u05d1\u05e8 \u05e0\u05d9\u05e9\u05d0 \u05e2\u05dc \u05d4\u05e9\u05de\u05df."],[112.0,"\u05d1\u05e8\u05d2\u05e2\u05d9 \u05d4\u05d4\u05ea\u05e0\u05e2\u05d4 \u05d5\u05d4\u05e2\u05e6\u05d9\u05e8\u05d4, \u05db\u05e9\u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d4, \u05d5\u05d4\u05e1\u05d9\u05db\u05d4 \u05e2\u05d5\u05d1\u05e8\u05ea \u05dc\u05de\u05e9\u05d8\u05e8 \u05d2\u05d1\u05d5\u05dc\u05d9."],[126.0,"\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e9\u05de\u05e0\u05d9\u05dd \u05e2\u05dd \u05ea\u05d5\u05e1\u05e4\u05d9 \u05dc\u05d7\u05e5 \u05e7\u05d9\u05e6\u05d5\u05e0\u05d9, \u05e9\u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05e9\u05db\u05d1\u05d4 \u05de\u05d2\u05d9\u05e0\u05d4 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05de\u05ea\u05db\u05ea."],[141.0,"\u05d4\u05d9\u05d3\u05d1\u05e7\u05d5\u05ea: \u05d4\u05e4\u05e1\u05d2\u05d5\u05ea \u05e0\u05e6\u05de\u05d3\u05d5\u05ea \u05d6\u05d5 \u05dc\u05d6\u05d5, \u05e0\u05e7\u05e8\u05e2\u05d5\u05ea, \u05d5\u05de\u05e2\u05d1\u05d9\u05e8\u05d5\u05ea \u05d7\u05d5\u05de\u05e8 \u05de\u05de\u05e9\u05d8\u05d7 \u05dc\u05de\u05e9\u05d8\u05d7."],[153.0,"\u05d4\u05d5\u05d0 \u05e9\u05d7\u05d9\u05e7\u05d4 \u05d0\u05d1\u05e8\u05e1\u05d9\u05d1\u05d9\u05ea: \u05d7\u05dc\u05e7\u05d9\u05e7 \u05e7\u05e9\u05d4, \u05d0\u05d5 \u05e4\u05e1\u05d2\u05d4 \u05e7\u05e9\u05e9\u05d4, \u05d7\u05d5\u05e8\u05e9 \u05ea\u05e2\u05dc\u05d5\u05ea \u05d1\u05de\u05e9\u05d5\u05d8\u05d7 \u05d4\u05e8\u05da."],[169.0,"\u05d6\u05d4 \u05d4\u05d1\u05dc\u05d0\u05d9 \u05e9\u05dc \u05d0\u05d1\u05e7, \u05d7\u05d5\u05dc \u05d5\u05e9\u05d1\u05d1\u05d9\u05dd. \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9 \u05d4\u05d5\u05d0 \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05e9\u05d8\u05d7, \u05d1\u05de\u05d2\u05e2 \u05de\u05ea\u05d2\u05dc\u05d2\u05dc, \u05db\u05de\u05d5 \u05d1\u05de\u05d9\u05e1\u05d1\u05d9\u05dd \u05d5\u05d1\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd."],[179.0,"\u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea: \u05d4\u05de\u05d0\u05de\u05e5 \u05d4\u05d2\u05d1\u05d5\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e0\u05de\u05e6\u05d0 \u05e7\u05e6\u05ea \u05de\u05ea\u05d7\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05e1\u05d3\u05e7 \u05e0\u05d5\u05e6\u05e8 \u05e9\u05dd, \u05d5\u05d1\u05e1\u05d5\u05e3 \u05d7\u05ea\u05d9\u05db\u05d4 \u05e0\u05d9\u05ea\u05e7\u05ea."],[192.0,"\u05d5\u05d4\u05e8\u05d1\u05d9\u05e2\u05d9 \u05d4\u05d5\u05d0 \u05d1\u05dc\u05d0\u05d9 \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d1\u05d9, \u05e9\u05d1\u05d5 \u05e9\u05db\u05d1\u05d5\u05ea \u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05e0\u05d5\u05e6\u05e8\u05d5\u05ea \u05d5\u05de\u05d5\u05e1\u05e8\u05d5\u05ea \u05e9\u05d5\u05d1 \u05d5\u05e9\u05d5\u05d1."],[198.0,"\u05d5\u05e7\u05d1\u05d9\u05d8\u05e6\u05d9\u05d4, \u05e9\u05d1\u05d4 \u05d1\u05d5\u05e2\u05d5\u05ea \u05d0\u05d3\u05d9\u05dd \u05e7\u05d5\u05e8\u05e1\u05d5\u05ea \u05dc\u05d9\u05d3 \u05d4\u05de\u05e9\u05d8\u05d7 \u05d5\u05de\u05db\u05d5\u05ea \u05d1\u05d5, \u05db\u05de\u05d5 \u05d1\u05de\u05e9\u05d0\u05d1\u05d5\u05ea \u05d5\u05d1\u05de\u05d3\u05d7\u05e4\u05d9\u05dd."],[210.0,"\u05e9\u05e0\u05e9\u05d7\u05e7\u05ea \u05e2\u05d5\u05dc\u05d4 \u05d1\u05d9\u05d7\u05e1 \u05d9\u05e9\u05e8 \u05dc\u05e2\u05d5\u05de\u05e1 \u05d5\u05dc\u05de\u05e8\u05d7\u05e7 \u05d4\u05d4\u05d7\u05dc\u05e7\u05d4, \u05d5\u05d9\u05d5\u05e8\u05d3\u05ea \u05d1\u05d9\u05d7\u05e1 \u05d4\u05e4\u05d5\u05da \u05dc\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc \u05d4\u05de\u05e9\u05d8\u05d7 \u05e9\u05e0\u05e9\u05d7\u05e7."],[227.0,"2 \u05de\u05d4\u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d4\u05e9\u05d5\u05d7\u05e7\u05d9\u05dd \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05e0\u05e9\u05d7\u05e7. \u05d7\u05d5\u05dc, \u05dc\u05de\u05e9\u05dc, \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e8\u05d5\u05d1 \u05d4\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05de\u05d5\u05e7\u05e9\u05d5\u05ea."],[244.0,"\u05de\u05ea\u05db\u05d5\u05ea \u05d6\u05d4\u05d5\u05ea \u05d5\u05e8\u05db\u05d5\u05ea \u05d6\u05d5 \u05de\u05d5\u05dc \u05d6\u05d5. \u05e4\u05dc\u05d3\u05d4 \u05e2\u05dc \u05e4\u05dc\u05d3\u05d4 \u05d1\u05d9\u05d5\u05d1\u05e9, \u05d0\u05d5 \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05e2\u05dc \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4, \u05e0\u05d5\u05d8\u05d5\u05ea \u05dc\u05d4\u05d9\u05d3\u05d1\u05e7 \u05d5\u05dc\u05d4\u05d9\u05ea\u05e4\u05e1."],[257.0,"\u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 13. \u05ea\u05d5\u05ea\u05d1\u05d9\u05dd \u05de\u05d1\u05e8\u05d5\u05e0\u05d6\u05d4 \u05db\u05d1\u05d5\u05e9\u05d4, \u05e2\u05dd \u05e9\u05de\u05df \u05e1\u05e4\u05dc\u05d5\u05d2 \u05d1\u05ea\u05d5\u05db\u05d4, \u05e1\u05db\u05d9\u05dd \u05d0\u05ea \u05e2\u05e6\u05de\u05dd."],[268.0,"\u05de\u05d9\u05e1\u05d1\u05d9 \u05d4\u05d7\u05dc\u05e7\u05d4 \u05de\u05de\u05ea\u05db\u05ea \u05dc\u05d1\u05e0\u05d4, \u05d5\u05d5\u05dd\u05e188 \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea, \u05e8\u05db\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05d5\u05de\u05e9\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05d9\u05e1\u05d1\u05d9\u05dd \u05d4\u05d9\u05d3\u05e8\u05d5\u05d3\u05d9\u05e0\u05de\u05d9\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd."],[277.0,"\u05ea\u05d5\u05ea\u05d1\u05d9\u05dd \u2026, \u05de-\u05d5\u05d0\u05e1\u05e1 \u2026 \u05de\u05d7\u05dc\u05d9\u05e7\u05d9\u05dd \u05d4\u05d9\u05d8\u05d1 \u05d2\u05dd \u05d1\u05dc\u05d9 \u05e9\u05de\u05df."],[289.0,"\u05d0\u05e4\u05e9\u05e8 \u05d1\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4, \u05d1\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d5\u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4, \u05e9\u05d4\u05db\u05e8\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 7."],[302.0,"\u05d0\u05d5\u05d3 DLC-1, \u05d1\u05d4\u05ea\u05d6\u05d4 \u05ea\u05e8\u05de\u05d9\u05ea \u05e9\u05dc \u05e7\u05e8\u05d1\u05d9\u05d3 \u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df, \u05d0\u05d5 \u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e9\u05dc \u05e9\u05db\u05d1\u05d4 \u05e7\u05e9\u05d4 \u05db\u05de\u05d5 Stellite."],[314.0,"\u05d5\u05d1\u05d7\u05d9\u05e8\u05ea \u05d4\u05d3\u05e8\u05da \u05ea\u05dc\u05d5\u05d9\u05d4 \u05d1\u05e2\u05d5\u05de\u05e1, \u05d1\u05e2\u05d5\u05d1\u05d9 \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05e0\u05d3\u05e8\u05e9, \u05d5\u05d1\u05e0\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05e9\u05d4\u05d7\u05dc\u05e7 \u05d9\u05db\u05d5\u05dc \u05dc\u05e1\u05d1\u05d5\u05dc."],[322.0,"\u05d5\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d5\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e2\u05d3 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd."],[336.0,"\u05d1\u05db\u05de\u05d4 \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05e2\u05dc\u05d5\u05dc\u05d9\u05dd \u05dc\u05e8\u05db\u05da \u05e4\u05dc\u05d3\u05d4 \u05e9\u05e2\u05d1\u05e8\u05d4 \u05d4\u05e8\u05e4\u05d9\u05d4 \u05e0\u05de\u05d5\u05db\u05d4."],[346.0,"\u05e2\u05dc \u05d4\u05d1\u05dc\u05d0\u05d9. \u05de\u05e9\u05d8\u05d7 \u05de\u05d7\u05d5\u05e1\u05e4\u05e1 \u05de\u05d3\u05d9 \u05e9\u05d5\u05d7\u05e7 \u05d0\u05ea \u05d1\u05df \u05d4\u05d6\u05d5\u05d2 \u05e9\u05dc\u05d5 \u05d5\u05e9\u05d5\u05d1\u05e8 \u05d0\u05ea \u05e9\u05db\u05d1\u05ea \u05d4\u05e9\u05de\u05df."],[357.0,"\u05d1\u05e6\u05d9\u05dc\u05d9\u05e0\u05d3\u05e8\u05d9\u05dd \u05e9\u05dc \u05de\u05e0\u05d5\u05e2\u05d9\u05dd \u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05d1\u05db\u05d5\u05d5\u05e0\u05d4 \u05d3\u05d5\u05d2\u05de\u05d4 \u05e9\u05dc \u05d7\u05e8\u05d9\u05e6\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd, \u05e9\u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05e9\u05de\u05df."],[367.0,"\u05d5\u05d1\u05de\u05d2\u05e2 \u05de\u05ea\u05d2\u05dc\u05d2\u05dc, \u05e0\u05d9\u05e7\u05d9\u05d5\u05df \u05d4\u05e4\u05dc\u05d3\u05d4 \u05e7\u05e8\u05d9\u05d8\u05d9: \u05ea\u05db\u05dc\u05d9\u05dc\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05de\u05ea\u05d7\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d4\u05dd \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d4\u05d4\u05ea\u05d7\u05dc\u05d4 \u05e9\u05dc \u05d4\u05e7\u05d9\u05dc\u05d5\u05e3."],[375.0,"\u05dc\u05db\u05df \u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05e1\u05d1\u05d9\u05dd \u05db\u05de\u05d5 52100 \u05de\u05d9\u05d5\u05e6\u05e8\u05d5\u05ea \u05d1\u05e0\u05d9\u05e7\u05d9\u05d5\u05df \u05d2\u05d1\u05d5\u05d4 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3, \u05d5\u05de\u05d5\u05e7\u05e9\u05d5\u05ea \u05dc\u05d9\u05d5\u05ea\u05e8 \u05de-58 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C."],[385.0,"\u05de\u05e6\u05d9\u05d9\u05e0\u05d9\u05dd \u05e7\u05e9\u05d9\u05d5\u05ea \u05dc\u05e9\u05e0\u05d9 \u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd, \u05d7\u05e1\u05e4\u05d5\u05e1, \u05d5\u05d0\u05ea \u05e1\u05d5\u05d2 \u05d4\u05e1\u05d9\u05db\u05d4, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8."],[395.0,"\u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05e8\u05e6\u05d4, \u05d1\u05e2\u05d5\u05de\u05e1 \u05de\u05d5\u05e4\u05d7\u05ea, \u05db\u05d3\u05d9 \u05e9\u05d4\u05e4\u05e1\u05d2\u05d5\u05ea \u05d9\u05ea\u05d9\u05d9\u05e9\u05e8\u05d5 \u05d1\u05e2\u05d3\u05d9\u05e0\u05d5\u05ea."],[409.0,"\u05d4\u05d9\u05d3\u05d1\u05e7\u05d5\u05ea, \u05d5\u05d1\u05d5\u05e8\u05d5\u05ea \u05d5\u05e7\u05d9\u05dc\u05d5\u05e4\u05d9\u05dd \u05de\u05e2\u05d9\u05d3\u05d9\u05dd \u05e2\u05dc \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05e9\u05d8\u05d7. \u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8?"],[424.0,"\u05e1\u05d9\u05db\u05d4 \u05d5\u05d0\u05d9\u05d8\u05d5\u05dd. \u05d0\u05d1\u05dc \u05d4\u05e9\u05d1\u05ea\u05d4 \u05e9\u05dc \u05de\u05db\u05d5\u05e0\u05d4 \u05d1\u05d2\u05dc\u05dc \u05d7\u05dc\u05e7 \u05e9\u05d7\u05d5\u05e7 \u05d9\u05e7\u05e8\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8."],[435.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05dc\u05d7\u05d5\u05de\u05e8 \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8, \u05d5\u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3\u05d9\u05d5\u05ea: \u05dc\u05de\u05d4 \u05d7\u05d5\u05de\u05e8 \u05d0\u05d7\u05d3 \u05de\u05ea\u05e2\u05d1\u05d3 \u05d1\u05e7\u05dc\u05d5\u05ea, \u05d5\u05d0\u05d7\u05e8 \u05e9\u05d5\u05d1\u05e8 \u05db\u05dc\u05d9\u05dd."]]};
window.MH_TR["\u05e4\u05e8\u05e719_\u05e2\u05d9\u05d1\u05d5\u05d3\u05d9\u05d5\u05ea"]={"t":"\u05e2\u05d9\u05d1\u05d5\u05d3\u05d9\u05d5\u05ea","l":[[1.0,"\u05de\u05d7\u05d6\u05d9\u05e7, \u05d0\u05d9\u05d6\u05d4 \u05d2\u05d9\u05de\u05d5\u05e8 \u05de\u05ea\u05e7\u05d1\u05dc, \u05d0\u05d9\u05d6\u05d4 \u05e9\u05d1\u05d1 \u05e0\u05d5\u05e6\u05e8, \u05d5\u05db\u05de\u05d4 \u05db\u05d5\u05d7 \u05d5\u05d4\u05e1\u05e4\u05e7 \u05e6\u05e8\u05d9\u05da."],[16.0,"\u05e2\u05d9\u05d1\u05d5\u05d3\u05d9\u05d5\u05ea \u05d2\u05e8\u05d5\u05e2\u05d4 \u05e2\u05d5\u05e9\u05d4 \u05d0\u05ea \u05d4\u05d4\u05e1\u05da, \u05d1\u05db\u05dc \u05d0\u05d7\u05d3 \u05de\u05d4\u05de\u05d3\u05d3\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4."],[30.0,"\u05db\u05d3\u05d9 \u05dc\u05d4\u05e9\u05d5\u05d5\u05ea, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05d3\u05d3 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3\u05d9\u05d5\u05ea. \u05de\u05d3\u05d3 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3\u05d9\u05d5\u05ea \u05de\u05d5\u05e9\u05d5\u05d5\u05d4 \u05dc\u05e4\u05dc\u05d3\u05d4 1212, \u05e9\u05de\u05e7\u05d1\u05dc\u05ea \u05de\u05d0\u05d4 \u05d0\u05d7\u05d5\u05d6."],[39.0,"\u05d5\u05d7\u05de\u05d9\u05e9\u05d4, 5 Grade \u05e9\u05dc \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05e2\u05e9\u05e8\u05d9\u05dd, \u05d5- 8 Inconel \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05e2\u05e9\u05e8\u05d4."],[61.0,"\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05ea\u05e2\u05d1\u05d3 \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05db\u05dc \u05d4\u05e4\u05dc\u05d3\u05d5\u05ea, \u05d5\u05de\u05e7\u05d1\u05dc \u05de\u05e1\u05e4\u05e8\u05d9\u05dd \u05e9\u05dc \u05de\u05d0\u05d5\u05ea \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd."],[67.0,"\u05de\u05e9\u05dc\u05d4\u05dd, \u05d0\u05d1\u05dc \u05d4\u05d5\u05d0 \u05e0\u05d5\u05ea\u05df \u05e1\u05d3\u05e8 \u05d2\u05d5\u05d3\u05dc \u05d8\u05d5\u05d1, \u05d5\u05d1\u05d4\u05e2\u05e8\u05db\u05ea \u05e2\u05dc\u05d5\u05ea \u05d4\u05d5\u05d0 \u05d0\u05d7\u05d3 \u05d4\u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05d4\u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05d6\u05de\u05df \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3."],[78.0,"\u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05d4\u05e1\u05d2\u05d5\u05dc\u05d9: \u05d4\u05db\u05d5\u05d7 \u05e9\u05e0\u05d3\u05e8\u05e9 \u05dc\u05d7\u05ea\u05d5\u05da \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e8\u05d1\u05d5\u05e2 \u05e9\u05dc \u05e9\u05d1\u05d1."],[87.0,"\u05d0\u05dc\u05e4\u05d9\u05d9\u05dd, \u05d1\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d3\u05d5\u05de\u05d4 \u05dc\u05e4\u05dc\u05d3\u05d4, \u05d5\u05d1\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e0\u05d9\u05e7\u05dc \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05e9\u05dc\u05d5\u05e9\u05ea \u05d0\u05dc\u05e4\u05d9\u05dd."],[101.0,"\u05de\u05d3\u05d9 \u05e9\u05d5\u05d7\u05e7 \u05d0\u05ea \u05d4\u05db\u05dc\u05d9, \u05d0\u05d1\u05dc \u05d2\u05dd \u05d7\u05d5\u05de\u05e8 \u05e8\u05da \u05de\u05d3\u05d9 \u05d4\u05d5\u05d0 \u05d1\u05e2\u05d9\u05d4: \u05d4\u05d5\u05d0 \u05e0\u05de\u05e8\u05d7, \u05e0\u05d3\u05d1\u05e7 \u05dc\u05db\u05dc\u05d9, \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e9\u05d1\u05d1 \u05d0\u05e8\u05d5\u05da \u05d5\u05d2\u05d9\u05de\u05d5\u05e8 \u05e7\u05e8\u05d5\u05e2."],[116.0,"\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05ea \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e0\u05d9\u05e7\u05dc \u05de\u05ea\u05e7\u05e9\u05d5\u05d9\u05dd \u05de\u05ea\u05d7\u05ea \u05dc\u05db\u05dc\u05d9."],[131.0,"\u05e9\u05d5\u05d7\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05db\u05dc\u05d9. \u05d5\u05d4\u05e0\u05d8\u05d9\u05d9\u05d4 \u05d4\u05db\u05d9\u05de\u05d9\u05ea \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8 \u05dc\u05d4\u05d9\u05e6\u05de\u05d3 \u05dc\u05d7\u05d5\u05de\u05e8 \u05d4\u05db\u05dc\u05d9."],[146.0,"\u05d2\u05dd \u05d4\u05de\u05d9\u05e7\u05e8\u05d5 \u05de\u05d1\u05e0\u05d4 \u05de\u05e9\u05e0\u05d4. \u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05e4\u05d7\u05de\u05df \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9, \u05de\u05d1\u05e0\u05d4 \u05e9\u05dc \u05e4\u05e8\u05d9\u05d8 \u05d5\u05e4\u05e8\u05dc\u05d9\u05d8 \u05de\u05ea\u05e2\u05d1\u05d3 \u05d4\u05d9\u05d8\u05d1."],[153.0,"\u05d4\u05e2\u05d9\u05d1\u05d5\u05d3\u05d9\u05d5\u05ea. \u05d5\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05de\u05d5\u05e7\u05e9\u05d4 \u05d4\u05d5\u05d0 \u05db\u05d1\u05e8 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05dc \u05d7\u05d5\u05de\u05e8 \u05e7\u05e9\u05d4."],[166.0,"\u05db\u05d7\u05d5\u05de\u05e8 \u05e1\u05d9\u05db\u05d4 \u05d1\u05e7\u05e6\u05d4. \u05d5\u05ea\u05d7\u05de\u05d5\u05e6\u05d5\u05ea \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05e9\u05d5\u05d7\u05e7\u05d5\u05ea, \u05db\u05d9 \u05d4\u05df \u05e7\u05e9\u05d5\u05ea \u05de\u05d0\u05d5\u05d3, \u05db\u05de\u05e2\u05d8 \u05db\u05de\u05d5 \u05d4\u05db\u05dc\u05d9 \u05e2\u05e6\u05de\u05d5."],[182.0,"\u05d1\u05e4\u05e8\u05e7 5. \u05e1\u05d3\u05e8\u05ea 11, \u05db\u05de\u05d5 1144, \u05de\u05db\u05d9\u05dc\u05d4 \u05d2\u05d5\u05e4\u05e8\u05d9\u05ea. \u05e1\u05d3\u05e8\u05ea 12 \u05de\u05db\u05d9\u05dc\u05d4 \u05d2\u05d5\u05e4\u05e8\u05d9\u05ea \u05d5\u05d6\u05e8\u05d7\u05df."],[195.0,"\u05e4\u05d9\u05e9\u05e0\u05d9\u05d9\u05dd \u05de-1212. \u05d0\u05d5\u05ea\u05d5 \u05e8\u05e2\u05d9\u05d5\u05df \u05e7\u05d9\u05d9\u05dd \u05d2\u05dd \u05d1\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 303, \u05d1\u05e4\u05dc\u05d9\u05d6 \u05e2\u05dd \u05e2\u05d5\u05e4\u05e8\u05ea, \u05d5\u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd 2011."],[211.0,"\u05db\u05de\u05d5 5\u05d5\u05d5\u05e1\u05d4, \u05de\u05d7\u05dc\u05d9\u05e4\u05d9\u05dd \u05d4\u05d9\u05d5\u05dd \u05d0\u05ea \u05d4\u05e2\u05d5\u05e4\u05e8\u05ea \u05d1\u05d1\u05d9\u05e1\u05de\u05d5\u05d8 \u05d0\u05d5 \u05d1\u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df."],[224.0,"\u05d4\u05db\u05dc\u05d9, \u05d5\u05de\u05e4\u05e8\u05d9\u05e2 \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9\u05ea. \u05e9\u05d1\u05d1 \u05de\u05e7\u05d5\u05d8\u05e2 \u05e0\u05d5\u05e6\u05e8 \u05d1\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e4\u05e8\u05d9\u05db\u05d9\u05dd, \u05db\u05de\u05d5 \u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7."],[241.0,"\u05de\u05d5\u05e7\u05e9\u05d9\u05dd. \u05e9\u05d5\u05d1\u05e8 \u05e9\u05d1\u05d1\u05d9\u05dd \u05d1\u05dc\u05d4\u05d1 \u05de\u05db\u05d5\u05e4\u05e3 \u05d0\u05ea \u05d4\u05e9\u05d5\u05d1 \u05e2\u05d3 \u05e9\u05d4\u05d5\u05d0 \u05e0\u05e9\u05d1\u05e8."],[251.0,"\u05d5\u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d4, \u05d4\u05d7\u05d5\u05de\u05e8 \u05e0\u05d3\u05d1\u05e7 \u05dc\u05e7\u05e6\u05d4, \u05e0\u05d1\u05e0\u05d4 \u05e2\u05dc\u05d9\u05d5, \u05d5\u05e0\u05e9\u05d1\u05e8 \u05e9\u05d5\u05d1\u05d5\u05e9\u05d5\u05d1."],[266.0,"\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05db\u05dc\u05d9 \u05d7\u05d3 \u05d9\u05d5\u05ea\u05e8, \u05d0\u05d5 \u05e6\u05d9\u05e4\u05d5\u05d9 \u05de\u05ea\u05d0\u05d9\u05dd."],[275.0,"\u05d0\u05dd6, \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3 \u05d1\u05d5\u05e8\u05d5\u05df \u05e7\u05d5\u05d1\u05d9, \u05d4\u05d5\u05d0 \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05dc\u05e4\u05dc\u05d3\u05d4 \u05de\u05d5\u05e7\u05e9\u05d4 \u05d5\u05dc\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7 \u05e7\u05e9\u05d4."],[292.0,"\u05d4\u05e4\u05d7\u05de\u05df \u05e9\u05dc \u05d4\u05d9\u05d4\u05dc\u05d5\u05dd \u05e2\u05d5\u05d1\u05e8 \u05dc\u05d1\u05e8\u05d6\u05dc, \u05d5\u05d4\u05db\u05dc\u05d9 \u05e0\u05e9\u05d7\u05e7 \u05de\u05d4\u05e8 \u05de\u05d0\u05d5\u05d3."],[306.0,"\u05d1\u05db\u05dc\u05d9 \u05e7\u05e8\u05d1\u05d9\u05d3, \u05d4\u05e2\u05dc\u05d0\u05d4 \u05e9\u05dc \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05d7\u05d9\u05ea\u05d5\u05da \u05d1\u05e2\u05e9\u05d5\u05e8\u05d9\u05dd \u05d0\u05d7\u05d5\u05d6 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05e7\u05e6\u05e8 \u05d0\u05ea \u05d7\u05d9\u05d9 \u05d4\u05db\u05dc\u05d9 \u05d1\u05d7\u05e6\u05d9, \u05d5\u05d0\u05e3 \u05d9\u05d5\u05ea\u05e8."],[318.0,"\u05d9\u05ea\u05d7\u05dc\u05e4\u05d5 \u05db\u05dc \u05d4\u05d6\u05de\u05df. \u05d5\u05d1\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3, \u05d4\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05db\u05dc\u05db\u05dc\u05d9\u05ea \u05e0\u05de\u05d5\u05db\u05d4 \u05d1\u05d4\u05e8\u05d1\u05d4."],[333.0,"\u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05d9\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d5\u05ea \u05d4\u05e1\u05d9\u05db\u05d4 \u05d7\u05e9\u05d5\u05d1\u05d4 \u05d9\u05d5\u05ea\u05d4 \u05d5\u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05d9\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d5\u05ea \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8."],[347.0,"\u05d5\u05d1\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e0\u05d9\u05e7\u05dc, \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05dc\u05d7\u05e5 \u05d2\u05d1\u05d5\u05d4 \u05d3\u05e8\u05da \u05d4\u05db\u05dc\u05d9 \u05e9\u05d5\u05d1\u05e8 \u05d0\u05ea \u05d4\u05e9\u05d1\u05d1 \u05d5\u05de\u05d0\u05e8\u05d9\u05da \u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u05d7\u05d9\u05d9 \u05d4\u05db\u05dc\u05d9."],[360.0,"\u05d4\u05e6\u05e4\u05d4, \u05e9\u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05d7\u05dc\u05e7 \u05de\u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d5\u05d7\u05d5\u05e1\u05db\u05ea \u05d1\u05e0\u05d5\u05d6\u05dc \u05d5\u05d1\u05e0\u05d9\u05e7\u05d5\u05d9."],[370.0,"\u05e0\u05d5\u05e6\u05e8\u05ea \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e9\u05db\u05d1\u05d4 \u05dc\u05d1\u05e0\u05d4, \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05d5\u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05e9\u05dc \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05e9\u05e0\u05d5\u05e6\u05e8 \u05de\u05d7\u05d3\u05e9, \u05e9\u05e2\u05dc\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7."],[386.0,"\u05dc\u05db\u05df \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d2\u05e1, \u05de\u05e4\u05d9\u05d2\u05d9\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d5\u05e8\u05e7 \u05d0\u05d6 \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d2\u05de\u05e8."],[402.0,"\u05de\u05d4 \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4?"],[403.0,"\u05de\u05d5\u05dc \u05de\u05e8\u05d5\u05db\u05db\u05ea \u05e2\u05dd \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d0\u05d7\u05e8\u05d9, \u05d0\u05d5 \u05e4\u05dc\u05d3\u05d4 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05dc, \u05db\u05e9\u05d4\u05d9\u05d0 \u05de\u05d5\u05ea\u05e8\u05ea."],[422.0,"\u05d5\u05dc\u05d4\u05e4\u05d2\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd. \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05d0\u05ea \u05de\u05d4 \u05e9\u05d4\u05d7\u05d5\u05dd \u05e9\u05dc \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e2\u05d5\u05e9\u05d4 \u05dc\u05d7\u05d5\u05de\u05e8."]]};
window.MH_TR["\u05e4\u05e8\u05e720_\u05e8\u05d9\u05ea\u05d5\u05da_\u05d5\u05d4\u05e9\u05e4\u05e2\u05ea\u05d5_\u05e2\u05dc_\u05d4\u05d7\u05d5\u05de\u05e8"]={"t":"\u05e8\u05d9\u05ea\u05d5\u05da \u05d5\u05d4\u05e9\u05e4\u05e2\u05ea\u05d5 \u05e2\u05dc \u05d4\u05d7\u05d5\u05de\u05e8","l":[[1.0,"\u05e8\u05d2\u05e2. \u05d1\u05de\u05e8\u05db\u05d6, \u05d1\u05ea\u05e4\u05e8, \u05d4\u05de\u05ea\u05db\u05ea \u05e0\u05de\u05e1\u05d4 \u05d5\u05de\u05ea\u05de\u05e6\u05e7\u05ea \u05de\u05d7\u05d3\u05e2\u05d5, \u05e2\u05dd \u05de\u05d1\u05e0\u05d4 \u05e9\u05dc \u05d9\u05e6\u05d9\u05e7\u05d4."],[12.0,"\u05d7\u05d9\u05de\u05d5\u05dd \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8\u05d9\u05dd \u05de\u05d0\u05d5\u05d3. \u05d5\u05de\u05e2\u05d1\u05e8 \u05dc\u05d5, \u05d7\u05d5\u05de\u05e8 \u05d4\u05d1\u05e1\u05d9\u05e1, \u05e9\u05dc\u05d0 \u05d4\u05e9\u05ea\u05e0\u05d4."],[22.0,"\u05e9\u05dc\u05d5\u05e9\u05d4 \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd, \u05d1\u05ea\u05d5\u05da \u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3. \u05d5\u05e8\u05d5\u05d1 \u05d4\u05d1\u05e2\u05d9\u05d5\u05ea \u05e9\u05dc \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05e0\u05de\u05e6\u05d0\u05d5\u05ea \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05de\u05d5\u05e9\u05e4\u05e2 \u05de\u05d7\u05d5\u05dd."],[34.0,"\u05d9\u05d5\u05ea\u05e8 \u05d7\u05d5\u05dd \u05e0\u05d5\u05ea\u05df \u05d0\u05d6\u05d5\u05e8 \u05de\u05d5\u05e9\u05e4\u05e2 \u05e8\u05d7\u05d1 \u05d9\u05d5\u05ea\u05d4 \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9\u05d9\u05d5\u05ea\u05e8 \u05d5\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d2\u05e1\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."],[51.0,"\u05e4\u05d7\u05d5\u05ea \u05d7\u05d5\u05dd \u05e0\u05d5\u05ea\u05df \u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05dc\u05db\u05df \u05de\u05d1\u05e0\u05d4 \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8."],[57.0,"\u05e9\u05d4\u05db\u05e8\u05e0\u05d5, \u05d1\u05e9\u05e0\u05d9\u05d5\u05ea. \u05dc\u05d9\u05d3 \u05e7\u05d5 \u05d4\u05d4\u05ea\u05db\u05d4 \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d2\u05d3\u05dc\u05d9\u05dd \u05de\u05d0\u05d5\u05d3. \u05e7\u05e6\u05ea \u05e8\u05d7\u05d5\u05e7 \u05d9\u05d5\u05ea\u05e8 \u05d4\u05dd \u05de\u05ea\u05e2\u05d3\u05e0\u05d9\u05dd."],[69.0,"\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05de\u05d4\u05d9\u05e8 \u05d4\u05d5\u05e4\u05da \u05d0\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d6\u05d4 \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05e7\u05e9\u05d4 \u05d5\u05e4\u05e8\u05d9\u05da. \u05db\u05d0\u05df \u05e0\u05d5\u05e6\u05e8\u05ea \u05d4\u05d1\u05e2\u05d9\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05d4 \u05e1\u05d3\u05d9\u05e7\u05d4 \u05e7\u05e8\u05d4."],[81.0,"\u05d4\u05d9\u05d0 \u05e6\u05e8\u05d9\u05db\u05d4 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05d3\u05d1\u05e8\u05d9\u05dd \u05d1\u05d9\u05d7\u05d3: \u05de\u05d1\u05e0\u05d4 \u05e7\u05e9\u05d5\u05d4, \u05de\u05d9\u05de\u05df, \u05d5\u05de\u05d0\u05de\u05e5."],[87.0,"\u05d5\u05dc\u05db\u05df \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05dc\u05d0 \u05d4\u05d5\u05e8\u05e1\u05d5\u05ea \u05e9\u05dc \u05e8\u05d9\u05ea\u05d5\u05db\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd \u05e2\u05d5\u05e9\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e8\u05e7 \u05d0\u05d7\u05e8\u05d9 \u05e9\u05e2\u05d1\u05e8 \u05d6\u05de\u05df."],[98.0,"\u05e8\u05ea\u05d9\u05db\u05d4 \u05d1\u05e7\u05dc\u05d5\u05ea. \u05d1\u05d9\u05df \u05d0\u05e4\u05e1 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d0\u05e8\u05d1\u05e2 \u05dc\u05d0\u05e4\u05e1 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05e9\u05d5, \u05e6\u05e8\u05d9\u05da \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05d5\u05e7\u05d3\u05dd."],[112.0,"\u05e2\u05d3 \u05e9\u05dc\u05d5\u05e9 \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea, \u05de\u05d0\u05d8 \u05d0\u05ea \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8, \u05de\u05d5\u05e0\u05e2 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05e7\u05e9\u05d4, \u05d5\u05e0\u05d5\u05ea\u05df \u05dc\u05de\u05d9\u05de\u05df \u05d6\u05de\u05df \u05dc\u05e6\u05d0\u05ea."],[128.0,"\u05d1\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05d3\u05dc\u05d5\u05ea \u05de\u05d9\u05de\u05df, \u05db\u05de\u05d5 7018\u05dd, \u05e9\u05de\u05d0\u05d7\u05e1\u05e0\u05d9\u05dd \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d9\u05d9\u05d1\u05d5\u05e9, \u05db\u05d9 \u05dc\u05d7\u05d5\u05ea \u05d4\u05d9\u05d0 \u05de\u05e7\u05d5\u05e8 \u05de\u05d9\u05de\u05df."],[140.0,"\u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05d0\u05e4\u05e1 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05dc\u05d5\u05e9 \u05d5\u05d7\u05e6\u05d9, \u05d5\u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05dc\u05d9 \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05d5\u05e7\u05d3\u05dd."],[151.0,"\u05dc\u05d7\u05de\u05dd \u05d0\u05d5\u05ea\u05d4 \u05dc\u05de\u05d0\u05ea\u05d9\u05d9\u05dd \u05d5\u05d7\u05de\u05d9\u05e9\u05d9\u05dd \u05e2\u05d3 \u05e9\u05dc\u05d5\u05e9 \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05dc\u05d8\u05e4\u05dc \u05d1\u05d4 \u05d1\u05d7\u05d5\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da."],[162.0,"\u05d3\u05d1\u05e8\u05d9\u05dd: \u05d4\u05d5\u05d0 \u05de\u05e8\u05e4\u05d4 \u05d0\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05de\u05d5\u05e9\u05e4\u05e2 \u05de\u05d7\u05d5\u05dd, \u05d5\u05de\u05e9\u05d7\u05e8\u05e8 \u05d0\u05ea \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd \u05e9\u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d4\u05e9\u05d0\u05d9\u05e8."],[174.0,"\u05e9\u05e9 \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05ea\u05e7\u05e0\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05de\u05e2\u05dc \u05e2\u05d5\u05d1\u05d9 \u05de\u05e1\u05d5\u05d9\u05dd."],[182.0,"\u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05e2\u05d5\u05d1\u05e8\u05ea \u05d0\u05ea \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d4\u05de\u05e7\u05d5\u05e8\u05d9\u05ea, \u05d4\u05e4\u05dc\u05d3\u05d4 \u05de\u05ea\u05e8\u05db\u05db\u05ea."],[191.0,"\u05e0\u05d5\u05d6\u05dc\u05d9\u05d9\u05dd \u05d1\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd, \u05d5\u05ea\u05e4\u05e8 \u05e2\u05de\u05d5\u05e7 \u05d5\u05e6\u05e8, \u05d1\u05e8\u05d9\u05e1\u05d5\u05df \u05d2\u05d1\u05d5\u05d4, \u05e0\u05e7\u05e8\u05e2 \u05e2\u05d5\u05d3 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05ea\u05de\u05e6\u05e7."],[207.0,"\u05dc\u05db\u05df \u05e4\u05dc\u05d3\u05d5\u05ea \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05dc, \u05e2\u05dd \u05d2\u05d5\u05e4\u05e8\u05d9\u05ea \u05d0\u05d5 \u05e2\u05d5\u05e4\u05e8\u05ea, \u05db\u05de\u05e2\u05d8 \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05ea\u05da, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 19."],[215.0,"\u05dc\u05d4\u05d9\u05d6\u05d4\u05e8 \u05de\u05e8\u05d2\u05d9\u05e9\u05d5\u05ea \u05dc\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d1\u05d9\u05df \u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d2\u05e8\u05e1\u05d0\u05d5\u05ea L, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 10."],[226.0,"\u05db\u05de\u05d5 308L \u05d5- 3091 \u05de\u05ea\u05d5\u05db\u05e0\u05e0\u05d9\u05dd \u05db\u05da \u05e9\u05d1\u05ea\u05e4\u05e8 \u05d9\u05d9\u05e9\u05d0\u05e8 \u05de\u05e2\u05d8 \u05e4\u05e8\u05d9\u05d8 \u05d3\u05dc\u05ea\u05d0."],[242.0,"\u05d0\u05d7\u05e8\u05d9, \u05d5\u05d1\u05d3\u05d5\u05e4\u05dc\u05e7\u05e1 \u05e6\u05e8\u05d9\u05da \u05dc\u05e9\u05de\u05d5\u05e8 \u05e2\u05dc \u05db\u05de\u05d5\u05ea \u05d7\u05d5\u05dd \u05de\u05d1\u05d5\u05e7\u05e8\u05ea, \u05db\u05d3\u05d9 \u05dc\u05e9\u05de\u05d5\u05e8 \u05e2\u05dc \u05d4\u05d0\u05d9\u05d6\u05d5\u05df \u05d1\u05d9\u05df \u05e9\u05ea\u05d9 \u05d4\u05e4\u05d0\u05d6\u05d5\u05ea."],[258.0,"\u05e4\u05d9 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05de\u05d4\u05de\u05ea\u05db\u05ea \u05e2\u05e6\u05de\u05d4, \u05d5\u05dc\u05db\u05df \u05de\u05e0\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05de\u05e8\u05ea\u05db\u05d9\u05dd \u05d1\u05ea\u05d4\u05dc\u05d9\u05db\u05d9\u05dd \u05e9\u05de\u05e4\u05e8\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4."],[270.0,"\u05de\u05d9\u05de\u05df \u05de\u05dc\u05d7\u05d5\u05ea \u05d9\u05d5\u05e6\u05e8 \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05d4\u05e0\u05d9\u05e7\u05d9\u05d5\u05df \u05d5\u05d9\u05d9\u05d1\u05d5\u05e9 \u05d4\u05d7\u05d5\u05d8 \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd."],[275.0,"6, \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05de\u05d5\u05e9\u05e4\u05e2 \u05de\u05d7\u05d5\u05dd \u05de\u05d0\u05d1\u05d3 \u05d7\u05dc\u05e7 \u05d2\u05d3\u05d5\u05dc \u05de\u05d4\u05d7\u05d5\u05d6\u05e7, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7\u05d9\u05dd 4 \u05d5-12."],[287.0,"\u2026] \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea: \u05db\u05dc\u05d9 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05de\u05d7\u05de\u05dd \u05d5\u05de\u05e2\u05e8\u05d1\u05d1 \u05d0\u05ea \u05d4\u05de\u05ea\u05db\u05ea \u05d1\u05de\u05e6\u05d1 \u05de\u05d5\u05e6\u05e7, \u05d1\u05dc\u05d9 \u05dc\u05d4\u05ea\u05d9\u05da \u05d0\u05d5\u05ea\u05d4, \u05d5\u05d4\u05d7\u05d9\u05d1\u05d5\u05e8 \u05d7\u05d6\u05e7 \u05d1\u05d4\u05e8\u05d1\u05d4."],[306.0,"\u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05d2\u05dd \u05de\u05e2\u05d5\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7. \u05d4\u05ea\u05e4\u05e8 \u05de\u05ea\u05db\u05d5\u05d5\u05e5 \u05db\u05e9\u05d4\u05d5\u05d0 \u05de\u05ea\u05e7\u05e8\u05e8, \u05d5\u05de\u05d5\u05e9\u05da \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d0\u05d7\u05e8\u05d9\u05d5."],[313.0,"\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05ea\u05e7\u05e0\u05d9\u05dd, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05d8\u05d9\u05dd \u05de\u05e8\u05d0\u05e9 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05db\u05da \u05e9\u05d9\u05ea\u05d9\u05d9\u05e9\u05e8\u05d5 \u05d1\u05e7\u05d9\u05e8\u05d5\u05e8."],[324.0,"\u05d4\u05db\u05e0\u05d9\u05e2\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8. \u05db\u05e9\u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d7\u05dc\u05e7 \u05de\u05e8\u05d5\u05ea\u05da, \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05de\u05e9\u05ea\u05d7\u05e8\u05e8\u05d9\u05dd, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d6\u05d6."],[335.0,"\u05dc\u05db\u05df \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05de\u05e8\u05ea\u05db\u05d9\u05dd, \u05de\u05e4\u05d9\u05d2\u05d9\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d5\u05e8\u05e7 \u05d0\u05d6 \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d2\u05de\u05e8."],[342.0,"\u05d1\u05e4\u05e8\u05e7\u05d9\u05dd \u05e9\u05dc\u05d4\u05dd. \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d3\u05d5\u05e8\u05e9 \u05d4\u05d2\u05e0\u05d4 \u05de\u05dc\u05d0\u05d4 \u05e9\u05dc \u05d2\u05d6 \u05d0\u05e6\u05d9\u05dc \u05e2\u05dc \u05db\u05dc\u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d7\u05dd. \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e0\u05d9\u05e7\u05dc \u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05e0\u05d9\u05e7\u05d9\u05d5\u05df \u05e7\u05e4\u05d3\u05e0\u05d9."],[355.0,"\u05e0\u05d7\u05d5\u05e9\u05ea \u05de\u05d5\u05dc\u05d9\u05db\u05d4 \u05d0\u05ea \u05d4\u05d7\u05d5\u05dd \u05d4\u05e8\u05d7\u05e7 \u05de\u05d4\u05ea\u05e4\u05e8, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05db\u05d4 \u05d7\u05d5\u05dd \u05e8\u05d1. \u05d5\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7 \u05d3\u05d5\u05e8\u05e9 \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05d5\u05e7\u05d3\u05dd \u05d5\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05d3\u05d5\u05ea \u05e0\u05d9\u05e7\u05dc."],[364.0,"\u05d4\u05d4\u05d1\u05d3\u05dc \u05d1\u05d4\u05ea\u05e4\u05e9\u05d8\u05d5\u05ea \u05d4\u05ea\u05e8\u05de\u05d9\u05ea, \u05e2\u05dc \u05d4\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d4\u05d2\u05dc\u05d5\u05d5\u05e0\u05d9\u05ea \u05d1\u05d9\u05e0\u05d9\u05d4\u05df, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e2\u05dc \u05e9\u05db\u05d1\u05ea \u05d1\u05d9\u05e0\u05d9\u05d9\u05dd."],[374.0,"\u05dc\u05e1\u05d9 \u05ea\u05e7\u05df \u05db\u05de\u05d515614 ISO \u05d0\u05d5 1.1\u05dd \u2026, \u05d5\u05d2\u05dd \u05e8\u05ea\u05da \u05de\u05d5\u05e1\u05de\u05da."],[394.0,"\u05d4\u05e7\u05d1\u05dc\u05d4 \u05e9\u05dc \u05e4\u05d2\u05de\u05d9\u05dd \u05d1\u05ea\u05e4\u05e8 \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05dc\u05e4\u05d9 \u05ea\u05e7\u05df, \u05db\u05de\u05d5 50! 7, \u05e2\u05dd \u05e8\u05de\u05d5\u05ea \u05d0\u05d9\u05db\u05d5\u05ea C ,8 \u05d5-\u05dd."],[413.0,"\u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05d5\u05e7\u05d3\u05dd, \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d0\u05d7\u05e8\u05d9, \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05dc\u05d0 \u05d4\u05d5\u05e8\u05e1\u05d5\u05ea, \u05d4\u05e1\u05de\u05db\u05d5\u05ea, \u05d5\u05ea\u05d9\u05e7\u05d5\u05df \u05e2\u05d9\u05d5\u05d5\u05ea\u05d9\u05dd."],[421.0,"\u05d1\u05db\u05dc\u05dc, \u05d0\u05d5 \u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05d1\u05e8 \u05d1\u05d1\u05e8\u05d2\u05d9\u05dd, \u05d1\u05d4\u05dc\u05d7\u05de\u05d4 \u05e7\u05e9\u05d4, \u05d0\u05d5 \u05dc\u05e2\u05d1\u05d3 \u05de\u05d2\u05d5\u05e9 \u05d0\u05d7\u05d3."],[432.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05e6\u05d5\u05e8\u05d5\u05ea \u05d4\u05d0\u05e1\u05e4\u05e7\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8, \u05d5\u05d0\u05d9\u05da \u05d4\u05df \u05de\u05e9\u05e4\u05d9\u05e2\u05d5\u05ea \u05e2\u05dc \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d5\u05e2\u05dc \u05d4\u05e2\u05dc\u05d5\u05ea."]]};
window.MH_TR["\u05e4\u05e8\u05e721_\u05e6\u05d5\u05e8\u05d5\u05ea_\u05d0\u05e1\u05e4\u05e7\u05d4"]={"t":"\u05e6\u05d5\u05e8\u05d5\u05ea \u05d0\u05e1\u05e4\u05e7\u05d4","l":[[1.0,"\u05de\u05e9\u05e0\u05d4 \u05dc\u05d0 \u05e8\u05e7 \u05d0\u05ea \u05d4\u05de\u05d7\u05d9\u05e8 \u05d5\u05d0\u05ea \u05db\u05de\u05d5\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3, \u05d0\u05dc\u05d0 \u05d2\u05dd \u05d0\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e2\u05e6\u05de\u05df."],[16.0,"\u05e9\u05d5\u05e0\u05d9\u05dd. \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05e6\u05d5\u05e8\u05d5\u05ea \u05d4\u05d0\u05e1\u05e4\u05e7\u05d4, \u05d5\u05d0\u05d9\u05da \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d1\u05d9\u05e0\u05d9\u05d4\u05df."],[28.0,"\u05d1\u05d7\u05d5\u05dd \u05de\u05d2\u05d9\u05e2\u05d4 \u05e2\u05dd \u05e9\u05db\u05d1\u05ea \u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05e9\u05d7\u05d5\u05e8\u05d4, mill scale \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea, \u05d5\u05dc\u05e2\u05ea\u05d9\u05dd \u05d2\u05dd \u05e2\u05dd \u05e9\u05db\u05d1\u05d4 \u05e9\u05d0\u05d9\u05d1\u05d3\u05d4 \u05e4\u05d7\u05de\u05df."],[40.0,"\u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd. \u05de\u05d5\u05d8\u05d5\u05ea \u05de\u05e9\u05d5\u05db\u05d9\u05dd \u05d1\u05e7\u05d5\u05e8 \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05de\u05d1\u05e8\u05d9\u05e7\u05d9\u05dd, \u05d1\u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05e6\u05e8\u05d5\u05ea, \u05d5\u05e2\u05dd \u05d7\u05d5\u05d6\u05e7 \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05d6\u05db\u05d5\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e7\u05e8."],[52.0,"\u05d0\u05d1\u05dc \u05d9\u05e9 \u05d1\u05d4\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d7\u05dc\u05e7 \u05dc\u05d0 \u05e1\u05d9\u05de\u05d8\u05e8\u05d9 \u05e9\u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05de\u05d4\u05dd \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05ea\u05e2\u05d5\u05d5\u05ea."],[59.0,"\u05d5\u05d0\u05e3 \u05d9\u05d5\u05ea\u05e8, \u05e9\u05d4\u05e7\u05dc\u05d9\u05e4\u05d4 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea \u05d4\u05d5\u05e1\u05e8\u05d4 \u05de\u05d4\u05dd, \u05d9\u05d7\u05d3 \u05e2\u05dd \u05d4\u05e9\u05db\u05d1\u05d4 \u05e9\u05d0\u05d9\u05d1\u05d3\u05d4 \u05e4\u05d7\u05de\u05df."],[69.0,"\u05d1\u05e7\u05d5\u05d8\u05e8 \u05d4\u05d9\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e2\u05d3 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d5\u05d9\u05d5\u05ea\u05e8, \u05dc\u05e4\u05d9 \u05d4\u05d2\u05d5\u05d3\u05dc."],[79.0,"\u05d1\u05de\u05d5\u05d8 \u05de\u05e9\u05d5\u05da \u05d1\u05e7\u05d5\u05e8 \u05d4\u05d9\u05d0 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 11\u05d7, \u05d5\u05d1\u05de\u05d5\u05d8 \u05de\u05d5\u05e9\u05d7\u05d6 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc-8\u05d7 \u05d5\u05d0\u05e3 7\u05d7."],[88.0,"\u05de\u05d2\u05d9\u05e2 \u05e2\u05dd \u05e9\u05db\u05d1\u05ea \u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05d5\u05e2\u05dd \u05d2\u05dc\u05d9\u05dd, \u05d5\u05e4\u05d7 \u05de\u05d2\u05d5\u05dc\u05d2\u05dc \u05d1\u05e7\u05d5\u05e8 \u05d7\u05dc\u05e7 \u05d5\u05e9\u05d8\u05d5\u05d7 \u05d9\u05d5\u05ea\u05e8."],[99.0,"\u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 12, \u05e4\u05d7 \u05d1\u05de\u05e6\u05d1 1651 \u05e0\u05de\u05ea\u05d7 \u05db\u05d3\u05d9 \u05dc\u05e9\u05d7\u05e8\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd."],[108.0,"\u05de\u05d2\u05d5\u05dc\u05d2\u05dc, \u05d0\u05d1\u05dc \u05db\u05de\u05e2\u05d8 \u05d7\u05e1\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d5\u05e0\u05e9\u05d0\u05e8 \u05e9\u05d8\u05d5\u05d7 \u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05db\u05d1\u05d3."],[122.0,"\u05d5\u05d1\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d9\u05d5\u05e6\u05e8 \u05d1\u05e7\u05e6\u05d4 \u05d0\u05d6\u05d5\u05e8 \u05de\u05d5\u05e9\u05e4\u05e2 \u05de\u05d7\u05d5\u05dd, \u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05d4\u05e7\u05e6\u05d4 \u05d4\u05d6\u05d4 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3."],[139.0,"\u05e9\u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05de\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05de\u05e8\u05d0\u05e9, \u05de\u05d5\u05e9\u05d7\u05d6\u05d9\u05dd \u05d5\u05e9\u05d8\u05d5\u05d7\u05d9\u05dd, \u05d5\u05d7\u05d5\u05e1\u05db\u05d9\u05dd \u05d0\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df."],[153.0,"\u05e0\u05de\u05ea\u05d7\u05d9\u05dd \u05dc\u05d0\u05d5\u05e8\u05da \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d2\u05dc\u05d2\u05d5\u05dc, \u05db\u05de\u05d5 \u05e1\u05d9\u05d1\u05d9\u05dd \u05d1\u05e2\u05e5. \u05dc\u05db\u05df \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea \u05d1\u05db\u05d9\u05d5\u05d5\u05e0\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd, \u05d5\u05d6\u05d5 \u05d0\u05e0\u05d9\u05d6\u05d5\u05d8\u05e8\u05d5\u05e4\u05d9\u05d4."],[166.0,"\u05d4\u05d2\u05dc\u05d2\u05d5\u05dc, \u05d5\u05e4\u05d7\u05d5\u05ea \u05d8\u05d5\u05d1\u05d9\u05dd \u05dc\u05e8\u05d5\u05d7\u05d1. \u05d5\u05d4\u05db\u05d9 \u05d7\u05dc\u05e9 \u05d4\u05d5\u05d0 \u05d4\u05db\u05d9\u05d5\u05d5\u05df \u05dc\u05e2\u05d5\u05de\u05e7 \u05d4\u05e4\u05d7."],[176.0,"\u05d4\u05d5\u05d0 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05e7\u05e8\u05e2 \u05d1\u05e9\u05db\u05d1\u05d5\u05ea. \u05d6\u05d5 \u05e7\u05e8\u05d9\u05e2\u05d4 \u05d1\u05e9\u05db\u05d1\u05d5\u05ea, \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea. lamellar tearing"],[187.0,"\u05dc\u05db\u05df \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05de\u05d5\u05e1\u05d9\u05dd \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05ea \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d2\u05dc\u05d2\u05d5\u05dc, \u05d5\u05de\u05de\u05e7\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05e4\u05d7 \u05d1\u05d4\u05ea\u05d0\u05dd."],[195.0,"\u05d4\u05db\u05ea\u05e4\u05d9\u05d9\u05dd \u05d5\u05d4\u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd, \u05d1\u05de\u05e7\u05d5\u05dd \u05dc\u05d4\u05d9\u05d7\u05ea\u05da \u05d1\u05d4\u05dd, \u05db\u05de\u05d5 \u05e9\u05e7\u05d5\u05e8\u05d4 \u05d1\u05d7\u05dc\u05e7 \u05e9\u05e2\u05d5\u05d1\u05d3 \u05de\u05de\u05d5\u05d8."],[209.0,"\u05d1\u05ea\u05d1\u05e0\u05d9\u05ea \u05e1\u05d2\u05d5\u05e8\u05d4, \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d5\u05e8\u05db\u05d1\u05d9\u05dd \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea, \u05e7\u05e8\u05d5\u05d1 \u05de\u05d0\u05d5\u05d3 \u05dc\u05e6\u05d5\u05e8\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea."],[223.0,"\u05d4\u05d7\u05d9\u05e1\u05e8\u05d5\u05da: \u05d4\u05ea\u05d1\u05e0\u05d9\u05ea \u05d9\u05e7\u05e8\u05d4, \u05d7\u05de\u05df \u05d4\u05d4\u05db\u05e0\u05d4 \u05d0\u05e8\u05d5\u05df."],[228.0,"\u05d9\u05e6\u05d9\u05e7\u05d4 \u05de\u05d0\u05e4\u05e9\u05e8\u05ea \u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d5\u05ea \u05d4\u05de\u05d5\u05e8\u05db\u05d1\u05d5\u05ea \u05d1\u05d9\u05d5\u05ea\u05d4 \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7\u05d9\u05dd 11 \u05d5-12, \u05d5\u05d1\u05e7\u05d5\u05e8\u05e1 \u05d4\u05d8\u05db\u05e0\u05d5\u05dc\u05d5\u05d2\u05d9\u05d5\u05ea."],[236.0,"\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d2\u05e1\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8, \u05d5\u05de\u05e9\u05d9\u05db\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d7\u05d5\u05de\u05e8 \u05de\u05d7\u05d5\u05e9\u05dc."],[245.0,"\u05dc\u05db\u05df \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd \u05de\u05d7\u05de\u05d9\u05e8\u05d9\u05dd \u05e2\u05dd \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05db\u05d1\u05d9\u05e9\u05d4 \u05d0\u05d9\u05d6\u05d5\u05e1\u05d8\u05d8\u05d9\u05ea \u05d7\u05de\u05d4, \u05db\u05d3\u05d9 \u05dc\u05e1\u05d2\u05d5\u05e8 \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea."],[254.0,"\u05e0\u05e4\u05d5\u05e6\u05d4 \u05de\u05d0\u05d5\u05d3. \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e7\u05d1\u05dc \u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05d7\u05ea\u05da, \u05e2\u05dd \u05d7\u05dc\u05dc\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd, \u05d5\u05d1\u05de\u05e6\u05d1 5\u05d3\u05d0\u05d516."],[265.0,"\u05e9\u05de\u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05de\u05d2\u05d5\u05e9 \u05de\u05dc\u05d0, \u05d5\u05e6\u05d9\u05e0\u05d5\u05e8\u05d5\u05ea \u05de\u05e8\u05d5\u05ea\u05db\u05d9\u05dd, \u05e9\u05de\u05d2\u05d5\u05dc\u05d2\u05dc\u05d9\u05dd \u05de\u05e4\u05d7\u05d5\u05de\u05e8\u05d5\u05ea\u05db\u05d9\u05dd \u05dc\u05d0\u05d5\u05e8\u05db\u05dd."],[276.0,"\u05d5\u05de\u05d3\u05d5\u05d9\u05e7 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05e2\u05d5\u05d1\u05d9 \u05d4\u05d3\u05d5\u05e4\u05df. \u05d5\u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d7\u05dc\u05d5\u05dc\u05d9\u05dd \u05d9\u05e9 \u05d2\u05dd \u05de\u05d5\u05d8\u05d5\u05ea \u05d7\u05dc\u05d5\u05dc\u05d9\u05dd, \u05e9\u05d7\u05d5\u05e1\u05db\u05d9\u05dd \u05e7\u05d9\u05d3\u05d5\u05d7 \u05d0\u05e8\u05d5\u05da."],[289.0,"\u05d7\u05dc\u05e7 \u05db\u05de\u05e2\u05d8 \u05e1\u05d5\u05e4\u05d9, \u05e2\u05dd \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea \u05de\u05d1\u05d5\u05e7\u05e8\u05ea, \u05db\u05de\u05d5 \u05d1\u05ea\u05d5\u05ea\u05d1\u05d9\u05dd \u05e1\u05e4\u05d5\u05d2\u05d9 \u05e9\u05de\u05df."],[302.0,"\u05d4\u05d6\u05e8\u05e7\u05ea \u05d0\u05d1\u05e7\u05ea \u05de\u05ea\u05db\u05ea, \u05d5\u05d0\u05d5\u05d5\u05d0 \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea, \u05de\u05d0\u05e4\u05e9\u05d5\u05e8\u05ea \u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d5\u05de\u05d5\u05e8\u05db\u05d1\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05d1\u05e6\u05e4\u05d9\u05e4\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4."],[310.0,"\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df, \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea \u05d5\u05dc\u05e6\u05d5\u05e8\u05d5\u05ea \u05e9\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d9\u05d9\u05e6\u05e8 \u05d0\u05d7\u05e8\u05ea."],[319.0,"\u05d2\u05dd \u05db\u05d0\u05df, \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d9\u05db\u05d5\u05dc\u05d5\u05ea \u05dc\u05d4\u05d9\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea \u05d1\u05db\u05d9\u05d5\u05d5\u05e0\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd, \u05dc\u05e4\u05d9 \u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d4\u05d3\u05e4\u05e1\u05d4."],[325.0,"\u05d5\u05d0\u05ea \u05d4\u05e9\u05db\u05d1\u05d4 \u05e9\u05d0\u05d9\u05d1\u05d3\u05d4 \u05e4\u05d7\u05de\u05df, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d5\u05d9\u05d5\u05ea\u05e8 \u05dc\u05db\u05dc \u05e6\u05d3, \u05ea\u05dc\u05d5\u05d9 \u05d1\u05d2\u05d5\u05d3\u05dc."],[339.0,"\u05dc\u05d0 \u05dc\u05e2\u05d1\u05d3 \u05d1\u05db\u05dc\u05dc \u05d0\u05ea \u05d4\u05e7\u05d5\u05d8\u05e8 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9. \u05d5\u05d1\u05d7\u05d9\u05e9\u05d5\u05dc \u05d5\u05d1\u05d9\u05e6\u05d9\u05e7\u05d4, \u05d4\u05ea\u05d5\u05e1\u05e4\u05ea \u05e0\u05e7\u05d1\u05e2\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d4\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d0\u05d5 \u05d4\u05d7\u05d9\u05e9\u05d5\u05dc."],[351.0,"\u05d4\u05d5\u05d0 \u05e2\u05e9\u05e8\u05d4 \u05dc\u05d0\u05d7\u05d3, \u05ea\u05e9\u05e2\u05d9\u05dd \u05d0\u05d7\u05d5\u05d6 \u05de\u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05d9\u05e7\u05e8 \u05d4\u05d5\u05dc\u05db\u05d9\u05dd \u05dc\u05e9\u05d1\u05d1\u05d9\u05dd."],[366.0,"\u05e9\u05e7\u05dc \u05dc\u05d4\u05e9\u05d9\u05d2, \u05d5\u05e9\u05de\u05d9\u05dd \u05dc\u05d1 \u05d0\u05dd \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05d2\u05d9\u05e2 \u05d1\u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05d8\u05e8\u05d9\u05d5\u05ea \u05d0\u05d5 \u05d1\u05d0\u05d9\u05e0\u05e6'\u05d9\u05dd, \u05db\u05d9 \u05e2\u05e8\u05d1\u05d5\u05d1 \u05d1\u05d9\u05df \u05d4\u05e9\u05d9\u05d8\u05d5\u05ea \u05d2\u05d5\u05e8\u05dd \u05dc\u05d1\u05d6\u05d1\u05d5\u05d6."],[378.0,"\u05e2\u05dd \u05de\u05e2\u05d8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d0\u05d5 \u05de\u05e4\u05d9\u05d2\u05d9\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05d2\u05e1."],[390.0,"\u05de\u05d5\u05d8 \u05de\u05d5\u05e9\u05d7\u05d6 \u05d9\u05e7\u05e8 \u05de\u05de\u05d5\u05d8 \u05de\u05d2\u05d5\u05dc\u05d2\u05dc \u05d1\u05d7\u05d5\u05dd, \u05d7\u05d9\u05e9\u05d5\u05dc \u05d3\u05d5\u05e8\u05e9\u05d5 \u05ea\u05d1\u05e0\u05d9\u05ea, \u05d5\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d3\u05d5\u05e8\u05e9\u05ea \u05d3\u05d2\u05dd \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea."],[403.0,"\u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3. \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05dc\u05de\u05d3 \u05d0\u05d9\u05da \u05de\u05d6\u05de\u05d9\u05e0\u05d9\u05dd \u05d7\u05d5\u05de\u05e8 \u05e0\u05db\u05d5\u05df: \u05ea\u05e7\u05e0\u05d9\u05dd, \u05ea\u05e2\u05d5\u05d3\u05d5\u05ea \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e7\u05d1\u05dc\u05d4."]]};
window.MH_TR["\u05e4\u05e8\u05e722_\u05ea\u05e7\u05e0\u05d9\u05dd_\u05ea\u05e2\u05d5\u05d3\u05d5\u05ea_\u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea_\u05e7\u05d1\u05dc\u05d4"]={"t":"\u05ea\u05e7\u05e0\u05d9\u05dd \u05ea\u05e2\u05d5\u05d3\u05d5\u05ea \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e7\u05d1\u05dc\u05d4","l":[[1.0,"\u05d5\u05d1\u05d0\u05d9\u05d6\u05d5 \u05e1\u05d1\u05d5\u05dc\u05ea, \u05e2\u05dd \u05d0\u05d9\u05d6\u05d5 \u05ea\u05e2\u05d5\u05d3\u05d4, \u05d5\u05d0\u05dd \u05d9\u05e9 \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05de\u05d9\u05d5\u05d7\u05d3\u05d5\u05ea."],[17.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05dc\u05de\u05d3 \u05d0\u05d9\u05da \u05de\u05d6\u05de\u05d9\u05e0\u05d9\u05dd \u05d7\u05d5\u05de\u05e8, \u05d0\u05d9\u05da \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05ea\u05e2\u05d5\u05d3\u05d4, \u05d5\u05de\u05d4 \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05db\u05e9\u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05d2\u05d9\u05e2."],[33.0,"3 \u05dd. \u05d4\u05de\u05e6\u05d1: \u05de\u05e8\u05d5\u05db\u05da, \u05de\u05d5\u05e9\u05d1\u05d7 \u05dc\u05e7\u05e9\u05d9\u05d5\u05ea \u05de\u05e1\u05d5\u05d9\u05de\u05ea, \u05d0\u05d5 \u05d8\u05de\u05e4\u05e8\u05db\u05de\u05d51651."],[58.0,"\u05d0\u05d5\u05dc\u05d8\u05e8\u05e1\u05d5\u05e0\u05d9\u05ea, \u05d2\u05d5\u05d3\u05dc \u05d2\u05e8\u05e2\u05d9\u05df, \u05e0\u05d9\u05e7\u05d9\u05d5\u05df, \u05d0\u05d5 \u05d1\u05d3\u05d9\u05e7\u05ea \u05d4\u05dc\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4."],[74.0,"\u05d5\u05d1\u05e1\u05d5\u05e3, \u05e1\u05d5\u05d2 \u05d4\u05ea\u05e2\u05d5\u05d3\u05d4 \u05d4\u05e0\u05d3\u05e8\u05e9, \u05d5\u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05dc\u05e1\u05d9\u05de\u05d5\u05df \u05d5\u05dc\u05e2\u05e7\u05d9\u05d1\u05d5\u05ea."],[79.0,"\u05d5\u05e9\u05de\u05d5\u05e0\u05d4 \u05e2\u05d3 \u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05d5\u05e9\u05ea\u05d9\u05d9\u05dd \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc \u05e1, \u05de\u05e9\u05d5\u05da \u05d1\u05e7\u05d5\u05e8, \u05d0\u05e8\u05d1\u05e2\u05d4 \u05de\u05d8\u05e8\u05d9\u05dd, \u05e2\u05dd \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d0\u05d5\u05dc\u05d8\u05e8\u05e1\u05d5\u05e0\u05d9\u05ea \u05d5\u05ea\u05e2\u05d5\u05d3\u05d4 3.1."],[101.0,"\u05dc\u05d0 \u05ea\u05de\u05d9\u05d3 \u05d0\u05d5\u05ea\u05d5 \u05d7\u05d5\u05de\u05e8. 4140 \u05d5-4207%104 \u05e7\u05e8\u05d5\u05d1\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05d0\u05d1\u05dc \u05d8\u05d5\u05d5\u05d7\u05d9 \u05d4\u05d4\u05e8\u05db\u05d1 \u05d5\u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05dc\u05d0 \u05d6\u05d4\u05d9\u05dd \u05dc\u05d2\u05de\u05e8\u05d9."],[116.0,"\u05d1\u05d4\u05d6\u05de\u05e0\u05d4, \u05d5\u05dc\u05d0 \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05dc\u05e1\u05e4\u05e7 \u05dc\u05d4\u05d7\u05dc\u05d9\u05d8. \u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd, \u05de\u05e9\u05d5\u05d5\u05d9\u05dd \u05d0\u05ea \u05d4\u05d4\u05e8\u05db\u05d1 \u05d5\u05d0\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d1\u05e4\u05d5\u05e2\u05dc."],[128.0,"\u05d1\u05dc\u05d9 \u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05d1\u05d3\u05d9\u05e7\u05d4. \u05ea\u05e2\u05d5\u05d3\u05d4 2.2 \u05db\u05d5\u05dc\u05dc\u05ea \u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05d1\u05d3\u05d9\u05e7\u05d4 \u05db\u05dc\u05dc\u05d9\u05d5\u05ea, \u05de\u05d4\u05d9\u05d9\u05e6\u05d5\u05e8 \u05d4\u05e9\u05d5\u05d8\u05e3."],[146.0,"\u05d4\u05e1\u05e4\u05e6\u05d9\u05e4\u05d9\u05ea, \u05d5\u05d7\u05ea\u05d5\u05de\u05d4 \u05d1\u05d9\u05d3\u05d9 \u05e0\u05e6\u05d9\u05d2 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05e9\u05dc \u05d4\u05d9\u05e6\u05e8\u05df, \u05e9\u05d0\u05d9\u05e0\u05d5 \u05ea\u05dc\u05d5\u05d9 \u05d1\u05de\u05d7\u05dc\u05e7\u05ea \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8."],[157.0,"\u05d1\u05d5\u05d3\u05e7 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05d0\u05d9\u05e9\u05e8 \u05d0\u05d5\u05ea\u05d4. \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4 \u05d4\u05d1\u05d9\u05d8\u05d7\u05d5\u05e0\u05d9\u05ea \u05d5\u05d4\u05d0\u05d5\u05d5\u05d9\u05e8\u05d9\u05ea \u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05e4\u05d7\u05d5\u05ea 3.1."],[170.0,"\u05d4\u05ea\u05e7\u05df, 50049 \u05d0\u05d5\u05e1, \u05d5\u05ea\u05e2\u05d5\u05d3\u05d4 \u05de\u05e1\u05d5\u05d2 3.18. \u05d6\u05d5 \u05d0\u05d5\u05ea\u05d4 \u05ea\u05e2\u05d5\u05d3\u05d4 \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea \u05d4\u05d9\u05d5\u05dd 3.1."],[185.0,"\u05d5\u05d1\u05d0\u05e8\u05e6\u05d5\u05ea \u05d4\u05d1\u05e8\u05d9\u05ea \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05ea\u05e2\u05d5\u05d3\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u20aa \u05d3\u05d5\u05d0, \u05d3\u05d5\u05d7 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05e9\u05dc \u05de\u05e4\u05e2\u05dc \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8."],[191.0,"\u05dc\u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05e9\u05e2\u05dc \u05d4\u05e0\u05d9\u05d9\u05e8. \u05d0\u05d7\u05e8 \u05db\u05da, \u05d4\u05d4\u05e8\u05db\u05d1 \u05d4\u05db\u05d9\u05de\u05d9: \u05de\u05e9\u05d5\u05d5\u05d9\u05dd \u05db\u05dc \u05d9\u05e1\u05d5\u05d3 \u05dc\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05e9\u05d1\u05ea\u05e7\u05df."],[207.0,"\u05d4\u05dc\u05dd. \u05d0\u05d7\u05e8 \u05db\u05da, \u05de\u05e6\u05d1 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd, \u05d5\u05d4\u05ea\u05e7\u05df \u05e9\u05dc\u05e4\u05d9\u05d5 \u05e0\u05d1\u05d3\u05e7. \u05d5\u05d1\u05e1\u05d5\u05e3, \u05d7\u05ea\u05d9\u05de\u05d4 \u05d5\u05d7\u05d5\u05ea\u05de\u05ea."],[225.0,"\u05db\u05dc \u05e9\u05d5\u05e8\u05d4 \u05e9\u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05d4\u05d6\u05de\u05e0\u05d4 \u05d4\u05d9\u05d0 \u05e1\u05d9\u05d1\u05d4 \u05dc\u05e2\u05e6\u05d5\u05e8."],[229.0,"\u05e0\u05d9\u05e7\u05d7 \u05d3\u05d5\u05d2\u05de\u05d4: \u05ea\u05e2\u05d5\u05d3\u05d4 \u05e9\u05dc \u05de\u05d5\u05d8 4140 \u05de\u05d5\u05e9\u05d1\u05d7. \u05de\u05e1\u05e4\u05e8 \u05d4\u05de\u05e0\u05d4 \u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05e8\u05d0\u05e9 \u05d4\u05ea\u05e2\u05d5\u05d3\u05d4, \u05d5\u05d7\u05e8\u05d5\u05d8 \u05d2\u05dd \u05e2\u05dc \u05e7\u05e6\u05d4 \u05d4\u05de\u05d5\u05d8."],[239.0,"\u05d4\u05db\u05e8\u05d5\u05dd \u05d5\u05d4\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05d1\u05ea\u05d7\u05d5\u05dd. \u05d7\u05d5\u05d6\u05e7 \u05d4\u05db\u05e0\u05d9\u05e2\u05d4, \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d5\u05d4\u05d4\u05ea\u05d0\u05e8\u05db\u05d5\u05ea \u05e2\u05d5\u05de\u05d3\u05d9\u05dd \u05d1\u05d3\u05e8\u05d9\u05e9\u05d4."],[253.0,"\u05d5\u05d4\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e0\u05e2\u05e9\u05d5 \u05dc\u05e4\u05d9 A370 \u05d5\u05d0 ASTM. \u05de\u05d4 \u05de\u05d3\u05dc\u05d9\u05e7 \u05e0\u05d5\u05e8\u05d4 \u05d0\u05d3\u05d5\u05de\u05d4?"],[260.0,"\u05e2\u05dc \u05d4\u05d2\u05d1\u05d5\u05dc \u05d1\u05db\u05dc \u05d4\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea, \u05d1\u05d3\u05d9\u05e7\u05d4 \u05e9\u05e0\u05d3\u05e8\u05e9\u05d4 \u05d5\u05d7\u05e1\u05e8\u05d4, \u05ea\u05e7\u05df \u05d0\u05d7\u05e8 \u05de\u05de\u05d4 \u05e9\u05d4\u05d5\u05d6\u05de\u05df, \u05d0\u05d5 \u05ea\u05e2\u05d5\u05d3\u05d4 \u05d1\u05dc\u05d9 \u05d7\u05ea\u05d9\u05de\u05d4."],[273.0,"\u05d7\u05dc\u05d5\u05d3\u05d4 \u05d5\u05e4\u05d2\u05de\u05d9\u05dd. \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05de\u05d9\u05d3\u05d5\u05ea. \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e9\u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05e2\u05dc \u05d4\u05d7\u05d5\u05de\u05e8 \u05ea\u05d5\u05d0\u05dd \u05dc\u05de\u05e1\u05e4\u05e8 \u05d4\u05de\u05e0\u05d4 \u05e9\u05d1\u05ea\u05e2\u05d5\u05d3\u05d4."],[289.0,"\u05d1\u05d1\u05d3\u05d9\u05e7\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05e0\u05d9\u05d9\u05d3\u05ea, \u05d5\u05d1\u05d1\u05d3\u05d9\u05e7\u05ea \u05d5\u05d5\u05d0\u05e1, \u05e9\u05d1\u05d4 \u05de\u05db\u05e9\u05d9\u05e8 \u05d6\u05d7\u05d0 \u05d9\u05d3\u05e0\u05d9 \u05d9\u05de\u05e8\u05d0\u05d4 \u05d0\u05ea \u05d4\u05d4\u05e8\u05db\u05d1."],[300.0,"\u05d7\u05d5\u05de\u05e8 \u05e9\u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05dd \u05e2\u05d5\u05d1\u05e8 \u05dc\u05d4\u05e1\u05d2\u05e8, \u05d5\u05dc\u05d0 \u05e0\u05db\u05e0\u05e1 \u05dc\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e2\u05d3 \u05e9\u05de\u05d7\u05dc\u05d9\u05d8\u05d9\u05dd \u05de\u05d4 \u05dc\u05e2\u05e9\u05d5\u05ea \u05d1\u05d5."],[306.0,"\u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4: \u05de\u05d2\u05e0\u05d8 \u05de\u05d1\u05d3\u05d9\u05dc \u05d1\u05d9\u05df \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05ea \u05dc\u05e4\u05dc\u05d3\u05d4, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05d1\u05d9\u05df \u05e1\u05d5\u05d2\u05d9 \u05e4\u05dc\u05d3\u05d5\u05ea."],[316.0,"\u05d5\u05d1\u05d3\u05d9\u05e7\u05ea \u05e0\u05d9\u05e6\u05d5\u05e6\u05d5\u05ea \u05d1\u05de\u05e9\u05d7\u05d6\u05ea \u05e0\u05d5\u05ea\u05e0\u05ea \u05e8\u05de\u05d6 \u05dc\u05db\u05de\u05d5\u05ea \u05d4\u05e4\u05d7\u05de\u05df, \u05d0\u05d1\u05dc \u05d4\u05d9\u05d0 \u05dc\u05d0 \u05de\u05d7\u05dc\u05d9\u05e4\u05d4 \u05d1\u05d3\u05d9\u05e7\u05ea \u05d4\u05e8\u05db\u05d1."],[323.0,"\u05de\u05d5\u05d8, \u05de\u05e2\u05d1\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05dc\u05db\u05dc \u05d7\u05ea\u05d9\u05db\u05d4. \u05e9\u05d0\u05e8\u05d9\u05d5\u05ea \u05de\u05e1\u05de\u05e0\u05d9\u05dd, \u05d5\u05dc\u05d0 \u05d6\u05d5\u05e8\u05e7\u05d9\u05dd \u05dc\u05de\u05d3\u05e3 \u05de\u05e9\u05d5\u05ea\u05e3."],[334.0,"\u05d4\u05de\u05d3\u05d1\u05e7\u05d4. \u05d5\u05e7\u05d5\u05e0\u05d9\u05dd \u05de\u05e1\u05e4\u05e7\u05d9\u05dd \u05de\u05d0\u05d5\u05e9\u05e8\u05d9\u05dd \u05d1\u05dc\u05d1\u05d3, \u05db\u05d9 \u05d7\u05d5\u05de\u05e8 \u05de\u05d6\u05d5\u05d9\u05e3 \u05d5\u05ea\u05e2\u05d5\u05d3\u05d5\u05ea \u05de\u05d6\u05d5\u05d9\u05e4\u05d5\u05ea \u05d4\u05dd \u05e1\u05d9\u05db\u05d5\u05df \u05d0\u05de\u05d9\u05ea\u05d9."],[350.0,"\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e9\u05dc\u05d5\u05d7 \u05d3\u05d2\u05d9\u05de\u05d4 \u05dc\u05de\u05e2\u05d1\u05d3\u05d4 \u05de\u05d5\u05e1\u05de\u05db\u05ea, \u05dc\u05d1\u05d3\u05d9\u05e7\u05ea \u05d4\u05e8\u05db\u05d1 \u05d5\u05ea\u05db\u05d5\u05e0\u05d5\u05ea, \u05d0\u05d1\u05dc\u05d6\u05d4\u05d9\u05e7\u05e8\u05d5\u05dc\u05d5\u05e7\u05d7 \u05d6\u05de\u05df."],[361.0,"\u05d5\u05d0\u05dd \u05d0\u05d9\u05df \u05d0\u05d9\u05e9\u05d5\u05e8, \u05d4\u05d7\u05d5\u05de\u05e8 \u05e0\u05d3\u05d7\u05d4. \u05d4\u05d7\u05dc\u05d8\u05d4 \u05d1\u05e2\u05dc \u05e4\u05d4, \u05dc\u05d9\u05d3 \u05d4\u05de\u05db\u05d5\u05e0\u05d4, \u05d4\u05d9\u05d0 \u05d4\u05de\u05e7\u05d5\u05e8 \u05dc\u05e8\u05d5\u05d1 \u05d4\u05d1\u05e2\u05d9\u05d5\u05ea."],[377.0,"\u05ea\u05e7\u05e0\u05d9 AMS \u05d5- MIL-1 \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05dc\u05d0 \u05e8\u05e7 \u05d0\u05ea \u05d4\u05d4\u05e8\u05db\u05d1, \u05d0\u05dc\u05d0 \u05d2\u05dd \u05d0\u05ea \u05e9\u05d9\u05d8\u05ea \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8, \u05d0\u05ea \u05d4\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d5\u05d0\u05ea \u05e8\u05de\u05ea \u05d4\u05e0\u05d9\u05e7\u05d9\u05d5\u05df."],[390.0,"\u05d5\u05e9\u05e8\u05e9\u05e8\u05ea \u05e2\u05e7\u05d9\u05d1\u05d5\u05ea \u05de\u05dc\u05d0\u05d4, \u05de\u05d4\u05d9\u05e6\u05d9\u05e7\u05d4 \u05d5\u05e2\u05d3 \u05d4\u05d7\u05dc\u05e7 \u05d4\u05d2\u05de\u05d5\u05e8, \u05d4\u05d9\u05d0 \u05d7\u05dc\u05e7 \u05de\u05d4\u05de\u05d5\u05e6\u05e8 \u05e2\u05e6\u05de\u05d5."],[400.0,"\u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05ea\u05e2\u05d5\u05d3\u05d4 3.2 \u05d9\u05e7\u05e8\u05d4 \u05de-3.1, \u05db\u05d9 \u05d4\u05d9\u05d0 \u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05d1\u05d5\u05d3\u05e7 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9."],[416.0,"\u05de\u05d5\u05e1\u05d9\u05e4\u05d5\u05ea \u05de\u05d7\u05d9\u05e8 \u05d5\u05d6\u05de\u05df. \u05d7\u05d5\u05de\u05e8 \u05d1\u05d3\u05e8\u05d2\u05d4 \u05d0\u05d5\u05d5\u05d9\u05e8\u05d9\u05ea \u05d9\u05e7\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d9\u05e9 \u05db\u05de\u05d5\u05ea \u05de\u05d9\u05e0\u05d9\u05de\u05d5\u05dd \u05dc\u05d4\u05d6\u05de\u05e0\u05d4."],[428.0,"\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0, \u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05d1\u05e7\u05d5\u05e8\u05e1, \u05e0\u05d7\u05d1\u05e8 \u05d0\u05ea \u05d4\u05db\u05dc: \u05d0\u05d9\u05da \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d7\u05d5\u05de\u05d5."]]};
window.MH_TR["\u05e4\u05e8\u05e723_\u05d1\u05d7\u05d9\u05e8\u05ea_\u05d7\u05d5\u05de\u05e8"]={"t":"\u05d1\u05d7\u05d9\u05e8\u05ea \u05d7\u05d5\u05de\u05e8","l":[[1.0,"\u05e0\u05d7\u05d1\u05e8 \u05d0\u05ea \u05d4\u05db\u05dc, \u05d5\u05e0\u05e2\u05e0\u05d4 \u05e2\u05dc \u05d4\u05e9\u05d0\u05dc\u05d4 \u05e9\u05e2\u05d5\u05de\u05d3\u05ea \u05de\u05d0\u05d7\u05d5\u05e8\u05d9 \u05db\u05dc \u05e9\u05e8\u05d8\u05d5\u05d8: \u05d0\u05d9\u05da \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d7\u05d5\u05de\u05e8."],[12.0,"\u05e9\u05dc \u05d4\u05d6\u05d5\u05dc \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d0\u05dc\u05d0 \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8 \u05e9\u05e2\u05d5\u05e9\u05d4 \u05d0\u05ea \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05e2\u05dc\u05d5\u05ea \u05d4\u05db\u05d5\u05dc\u05dc\u05ea \u05d4\u05e0\u05de\u05d5\u05db\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d5\u05d1\u05e1\u05d9\u05db\u05d5\u05df \u05e1\u05d1\u05d9\u05e8."],[23.0,"\u05d4\u05de\u05d5\u05e2\u05de\u05d3\u05d9\u05dd, \u05d5\u05de\u05e1\u05e0\u05e0\u05d9\u05dd \u05d0\u05ea \u05de\u05d9 \u05e9\u05dc\u05d0 \u05e2\u05d5\u05de\u05d3 \u05d1\u05d3\u05e8\u05d9\u05e9\u05d4 \u05d4\u05db\u05e8\u05d7\u05d9\u05ea \u05d0\u05d7\u05ea."],[35.0,"\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4: \u05d1\u05d7\u05d9\u05e9\u05d5\u05d1, \u05d1\u05d0\u05d1 \u05d8\u05d9\u05e4\u05d5\u05e1, \u05d0\u05d5 \u05d1\u05e0\u05d9\u05e1\u05d9\u05d5\u05df \u05e7\u05d5\u05d3\u05dd."],[46.0,"\u05d9\u05db\u05d5\u05dc \u05dc\u05e9\u05e7\u05d5\u05dc. \u05d1\u05d0\u05d9\u05d6\u05d5 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d1\u05d3, \u05d5\u05d1\u05d0\u05d9\u05d6\u05d5 \u05e1\u05d1\u05d9\u05d1\u05d4: \u05dc\u05d7\u05d5\u05ea, \u05de\u05d9 \u05d9\u05dd, \u05db\u05d9\u05de\u05d9\u05e7\u05dc\u05d9\u05dd."],[63.0,"\u05dc\u05d0\u05d5\u05e8\u05da \u05d6\u05de\u05df. \u05d5\u05db\u05de\u05d4 \u05d9\u05d7\u05d9\u05d3\u05d5\u05ea, \u05d1\u05d0\u05d9\u05d6\u05d4 \u05de\u05d7\u05d9\u05e8, \u05d5\u05e2\u05dd \u05d0\u05d9\u05dc\u05d5 \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05e9\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7 \u05d5\u05d4\u05ea\u05e7\u05df."],[81.0,"\u05e8\u05e6\u05d5\u05d9\u05d5\u05ea. \u05d3\u05e8\u05d9\u05e9\u05d4 \u05d4\u05db\u05e8\u05d7\u05d9\u05ea, \u05db\u05de\u05d5 \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05de\u05d9 \u05d9\u05dd \u05d0\u05d5 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e9\u05dc \u05e9\u05e9 \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea, \u05e4\u05d5\u05e1\u05dc\u05ea \u05d7\u05d5\u05de\u05e8 \u05de\u05d9\u05d3."],[92.0,"\u05d3\u05e8\u05d9\u05e9\u05d4 \u05e8\u05e6\u05d5\u05d9\u05d4, \u05db\u05de\u05d5 \u05de\u05e9\u05e7\u05dc \u05e0\u05de\u05d5\u05da \u05d0\u05d5 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05dc, \u05d4\u05d9\u05d0 \u05e9\u05d9\u05e7\u05d5\u05dc \u05d1\u05d3\u05d9\u05e8\u05d5\u05d2."],[98.0,"\u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e9\u05dc Ashby \u05de\u05e6\u05d9\u05d2\u05d5\u05ea \u05d7\u05d5\u05d6\u05e7 \u05de\u05d5\u05dc \u05e6\u05e4\u05d9\u05e4\u05d5\u05ea, \u05d0\u05d5 \u05e7\u05e9\u05d9\u05d7\u05d5\u05ea \u05de\u05d5\u05dc \u05e6\u05e4\u05d9\u05e4\u05d5\u05ea, \u05dc\u05db\u05dc \u05de\u05e9\u05e4\u05d7\u05d5\u05ea \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d9\u05d7\u05d3."],[109.0,"\u05d5\u05e7\u05dc\u05d4, \u05dc\u05de\u05e9\u05dc, \u05de\u05d4 \u05e9\u05e7\u05d5\u05d1\u05e2 \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05d4\u05de\u05d5\u05d3\u05d5\u05dc \u05dc\u05d1\u05d3, \u05d0\u05dc\u05d0 \u05d4\u05d9\u05d7\u05e1 \u05d1\u05d9\u05df \u05e9\u05d5\u05e8\u05e9 \u05d4\u05de\u05d5\u05d3\u05d5\u05dc \u05dc\u05e6\u05e4\u05d9\u05e4\u05d5\u05ea."],[121.0,"\u05d0\u05e3 \u05e9\u05d4\u05de\u05d5\u05d3\u05d5\u05dc \u05e9\u05dc\u05d5 \u05e0\u05de\u05d5\u05da \u05e4\u05d9 \u05e9\u05dc\u05d5\u05e9\u05d4. \u05d5\u05d1\u05de\u05d5\u05d8 \u05de\u05ea\u05d9\u05d7\u05d4, \u05e9\u05d1\u05d5 \u05e7\u05d5\u05d1\u05e2 \u05d4\u05d9\u05d7\u05e1 \u05d1\u05d9\u05df \u05d4\u05de\u05d5\u05d3\u05d5\u05dc \u05dc\u05e6\u05e4\u05d9\u05e4\u05d5\u05ea, \u05d4\u05df \u05db\u05de\u05e2\u05d8 \u05e9\u05d5\u05d5\u05ea."],[134.0,"\u05db\u05e9\u05d9\u05e9 \u05db\u05de\u05d4 \u05de\u05d5\u05e2\u05de\u05d3\u05d9\u05dd \u05d8\u05d5\u05d1\u05d9\u05dd, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05d8\u05e8\u05d9\u05e6\u05ea \u05d4\u05d7\u05dc\u05d8\u05d4."],[137.0,"\u05e2\u05e9\u05e8\u05d9\u05dd, \u05e2\u05dc\u05d5\u05ea \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d7\u05de\u05d9\u05e9\u05d4, \u05e2\u05d9\u05d1\u05d5\u05d3\u05d9\u05d5\u05ea \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d6\u05de\u05d9\u05e0\u05d5\u05ea \u05e2\u05e9\u05e8\u05d4, \u05d5\u05de\u05d3\u05e8\u05d2\u05d9\u05dd \u05db\u05dc \u05d7\u05d5\u05de\u05e8 \u05de\u05d0\u05d7\u05ea \u05e2\u05d3 \u05d7\u05de\u05e9\u05d5 \u05d1\u05db\u05dc \u05e7\u05e8\u05d9\u05d8\u05e8\u05d9\u05d5\u05df."],[156.0,"\u05d5\u05d1\u05e2\u05d9\u05d1\u05d5\u05d3\u05d9\u05d5\u05ea, \u05d3\u05d5\u05e4\u05dc\u05e7\u05e1 \u05d1\u05d7\u05d5\u05d6\u05e7 \u05d5\u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05d5\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d5\u05d1\u05de\u05e9\u05e7\u05dc, \u05d0\u05d1\u05dc \u05e6\u05d9\u05d5\u05df \u05e0\u05de\u05d5\u05da \u05d1\u05e2\u05dc\u05d5\u05ea."],[169.0,"\u05d4\u05e6\u05d9\u05d5\u05df \u05d4\u05db\u05d5\u05dc\u05dc \u05dc\u05d0 \u05de\u05d7\u05dc\u05d9\u05d8 \u05d1\u05de\u05e7\u05d5\u05de\u05e0\u05d5, \u05d0\u05d1\u05dc \u05d4\u05d5\u05d0 \u05de\u05e8\u05d0\u05d4 \u05d1\u05d1\u05d9\u05e8\u05d5\u05e8 \u05e2\u05dc \u05de\u05d4 \u05d0\u05e0\u05d7\u05e0\u05d5 \u05de\u05d5\u05d5\u05ea\u05e8\u05d9\u05dd \u05d1\u05db\u05dc \u05d1\u05d7\u05d9\u05e8\u05d4."],[177.0,"\u05d4\u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05e2\u05e6\u05de\u05dd: \u05e4\u05dc\u05d3\u05d5\u05ea \u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05db\u05de\u05d5 8620 \u2026, \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 7."],[199.0,"\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d1\u05d9, 5 Grade \u05e9\u05dc \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd. \u05d0\u05d1\u05d9\u05d6\u05e8 \u05d9\u05de\u05d9: 3161, \u05d3\u05d5\u05e4\u05dc\u05e7\u05e1, \u05d1\u05e8\u05d5\u05e0\u05d6\u05d4 \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05d0\u05d5 \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd 2 Grade."],[218.0,"\u05db\u05e9\u05d4\u05e9\u05d8\u05d9\u05d7\u05d5\u05ea \u05e7\u05e8\u05d9\u05d8\u05d9\u05ea. \u05de\u05d1\u05dc\u05d8 \u05dc\u05d7\u05d9\u05ea\u05d5\u05da: 82 ,2\u05e1, \u05d0\u05d5 \u05e4\u05dc\u05d3\u05ea \u05d0\u05d1\u05e7\u05d4 \u05db\u05e9\u05d4\u05e2\u05d5\u05de\u05e1 \u05d2\u05d1\u05d5\u05d4 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3."],[242.0,"\u05d5\u05de\u05e2\u05dc \u05d6\u05d4, 625 Inconel \u05d0\u05d5 718. \u05d5\u05ea\u05d5\u05ea\u05d1 \u05e9\u05de\u05d7\u05dc\u05d9\u05e7 \u05e2\u05dc \u05d2\u05dc: \u05d1\u05e8\u05d5\u05e0\u05d6\u05d4, \u05d0\u05d5 \u05e4\u05d5\u05dc\u05d9\u05de\u05e8 \u05db\u05de\u05d5 \u05d5\u05d0\u05e1\u05e1 PEEK-1"],[261.0,"\u05dc\u05de\u05e9\u05d0\u05d1\u05ea \u05de\u05d9\u05d9\u05dd. \u05d4\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05d4\u05d4\u05db\u05e8\u05d7\u05d9\u05d5\u05ea: \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05de\u05d9 \u05d9\u05dd, \u05d5\u05d7\u05d5\u05d6\u05e7 \u05de\u05e1\u05e4\u05d9\u05e7 \u05dc\u05e4\u05d9\u05ea\u05d5\u05dc \u05d5\u05dc\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."],[273.0,"\u05d5-4140 .\u05d7\u05e117-4 \u05e0\u05e4\u05e1\u05dc, \u05db\u05d9 \u05e9\u05e8\u05d9\u05d8\u05d4 \u05d0\u05d7\u05ea \u05d1\u05e6\u05d9\u05e4\u05d5\u05d9 \u05de\u05ea\u05d7\u05d9\u05dc\u05d4 \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4. 316 \u05e2\u05de\u05d9\u05d3, \u05d0\u05d1\u05dc \u05d7\u05dc\u05e9 \u05de\u05d3\u05d9 \u05dc\u05e2\u05d5\u05de\u05e1 \u05d4\u05d6\u05d4."],[292.0,"\u05dc\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d1\u05d7\u05e8\u05d9\u05e6\u05d9\u05dd \u05d1\u05de\u05d9\u05dd \u05e2\u05d5\u05de\u05d3\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d7\u05e9\u05d5\u05d1 \u05dc\u05d3\u05e2\u05ea \u05d0\u05dd \u05d4\u05de\u05e9\u05d0\u05d1\u05d4 \u05e2\u05d5\u05de\u05d3\u05ea \u05dc\u05ea\u05e7\u05d5\u05e4\u05d5\u05ea \u05d0\u05e8\u05d5\u05db\u05d5\u05ea."],[309.0,"\u05d5\u05d1\u05d9\u05df \u05e9\u05e0\u05d9\u05d4\u05dd \u05de\u05db\u05e8\u05d9\u05e2\u05d9\u05dd \u05dc\u05e4\u05d9 \u05d4\u05e2\u05dc\u05d5\u05ea, \u05d4\u05d6\u05de\u05d9\u05e0\u05d5\u05ea, \u05d5\u05d4\u05e7\u05dc\u05d5\u05ea \u05dc\u05e2\u05d1\u05d3 \u05d0\u05d5\u05ea\u05dd \u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05d9\u05e9 \u05dc\u05e0\u05d5."],[316.0,"\u05d1\u05d9\u05d5\u05ea\u05e8, \u05db\u05e9\u05d4\u05d5\u05d0 \u05dc\u05d0 \u05e0\u05d3\u05e8\u05e9\u05d5, \u05d5\u05de\u05d7\u05d9\u05e8\u05d5 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d5\u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4. \u05d3\u05e8\u05d9\u05e9\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d1\u05dc\u05d9 \u05dc\u05d7\u05e9\u05d5\u05d1 \u05e2\u05dc toughness"],[329.0,"\u05d1\u05d7\u05d5\u05de\u05e8 \u05d0\u05e7\u05d6\u05d5\u05d8\u05d9 \u05e9\u05d0\u05d9\u05df \u05d1\u05de\u05dc\u05d0\u05d9. \u05d5\u05d0\u05d9 \u05d9\u05d3\u05d9\u05e2\u05d4 \u05de\u05d4 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d0\u05d5 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd, \u05d9\u05e2\u05e9\u05d5 \u05dc\u05d7\u05d5\u05de\u05e8."],[345.0,"\u05d6\u05de\u05df \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3, \u05e9\u05ea\u05dc\u05d5\u05d9 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3\u05d9\u05d5\u05ea, \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd, \u05d4\u05e6\u05d9\u05e4\u05d5\u05d9, \u05d4\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea, \u05d5\u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e4\u05e1\u05d9\u05dc\u05d5\u05ea."],[361.0,"\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d1\u05de\u05e7\u05d5\u05dd \u05e4\u05dc\u05d3\u05d4, \u05d7\u05d5\u05e1\u05db\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05de\u05de\u05d4 \u05e9\u05d4\u05dd \u05e2\u05d5\u05dc\u05d9\u05dd \u05d1\u05d7\u05d5\u05de\u05e8."],[373.0,"\u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d7\u05d5\u05de\u05e8 \u05d9\u05e7\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05e7\u05d9\u05dc\u05d5, \u05e9\u05de\u05d2\u05d9\u05e2 \u05de\u05d5\u05e7\u05e9\u05d5\u05d4 \u05de\u05e8\u05d0\u05e9\u05d5, \u05d7\u05d5\u05e1\u05da \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05de\u05e2\u05d1\u05e8 \u05d4\u05e9\u05d7\u05d6\u05d4."],[381.0,"\u05e2\u05d3 \u05e9\u05e9, \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05e2\u05e9\u05e8\u05d9\u05dd \u05d5\u05d9\u05d5\u05ea\u05e8, \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e0\u05d9\u05e7\u05dc \u05e9\u05dc\u05d5\u05e9\u05d9\u05dd \u05d5\u05d9\u05d5\u05ea\u05e8."],[400.0,"\u05d0\u05d1\u05dc \u05d6\u05db\u05e8\u05d5 \u05e9\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05e9\u05d5\u05e7\u05dc \u05e9\u05dc\u05d9\u05e9 \u05de\u05e4\u05dc\u05d3\u05d4, \u05d5\u05dc\u05db\u05df \u05dc\u05e4\u05d9 \u05e0\u05e4\u05d7 \u05d4\u05d5\u05d0 \u05d6\u05d5\u05dc \u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05de\u05d4 \u05e9\u05e0\u05e8\u05d0\u05d4 \u05dc\u05e4\u05d9 \u05e7\u05d9\u05dc\u05d5."],[408.0,"\u05e0\u05e4\u05d5\u05e5, \u05d1\u05de\u05d9\u05d3\u05d5\u05ea \u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9\u05d5\u05ea, \u05de\u05d2\u05d9\u05e2 \u05de\u05d4\u05e8 \u05d5\u05d6\u05d5\u05dc. \u05d7\u05d5\u05de\u05e8 \u05e0\u05d3\u05d9\u05e8, \u05d0\u05d5 \u05de\u05d9\u05d3\u05d4 \u05dc\u05d0 \u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9\u05ea, \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05e9\u05d1\u05d5\u05e2\u05d5\u05ea \u05d5\u05de\u05d7\u05d9\u05e8."],[422.0,"\u05dc\u05db\u05df \u05db\u05d3\u05d0\u05d9 \u05dc\u05d4\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05de\u05dc\u05d0\u05d9 \u05e9\u05dc \u05e1\u05e4\u05e7\u05d9 \u05d4\u05d7\u05d5\u05de\u05e8, \u05d5\u05dc\u05e9\u05d0\u05d5\u05dc \u05d0\u05d5\u05ea\u05dd \u05dc\u05e4\u05e0\u05d9 \u05e9\u05de\u05d7\u05dc\u05d9\u05d8\u05d9\u05dd."],[428.0,"\u05d5\u05d4\u05d1\u05e8\u05d6\u05dc \u05d4\u05d9\u05e6\u05d5\u05e7, \u05d4\u05de\u05ea\u05db\u05d5\u05ea \u05d4\u05dc\u05d0 \u05d1\u05e8\u05d6\u05dc\u05d9\u05d5\u05ea, \u05d4\u05d4\u05ea\u05e0\u05d4\u05d2\u05d5\u05ea \u05d1\u05e9\u05d9\u05e8\u05d5\u05ea, \u05d4\u05d7\u05d5\u05de\u05e8 \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8, \u05d5\u05d4\u05d4\u05d6\u05de\u05e0\u05d4."],[440.0,"\u05e9\u05db\u05d3\u05d0\u05d9 \u05dc\u05e9\u05d0\u05d5\u05dc \u05e2\u05dc \u05db\u05dc \u05d7\u05d5\u05de\u05e8: \u05de\u05d4 \u05d4\u05d7\u05dc\u05e7 \u05e6\u05e8\u05d9\u05da, \u05de\u05d4 \u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e6\u05e8\u05d9\u05da, \u05d5\u05db\u05de\u05d4 \u05d6\u05d4 \u05e2\u05d5\u05dc\u05d4 \u05d1\u05e1\u05d5\u05e3."],[451.0,"\u05d4\u05de\u05e7\u05e8\u05d9\u05dd. \u05ea\u05d5\u05d3\u05d4 \u05e9\u05d4\u05d9\u05d9\u05ea\u05dd \u05d0\u05d9\u05ea\u05e0\u05d5 \u05d1\u05e7\u05d5\u05e8\u05e1 \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d5\u05de\u05d8\u05dc\u05d5\u05e8\u05d2\u05d9\u05d4 \u05e9\u05dc \u05dd\u05d8\u05d4 \u2026."]]};
